insert into private.study_guides (guide, chunks, sha256) values ('study_guide_fin_cm209', 75, '6bfba20b90cc3e1ee03a339eaf12ea1ecfa68872953be91cd2c6e62ec49505ab');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 1, $study_guide${"guide":"study_guide_fin_cm209","code":"FIN-CM209","courseId":"58f61fa3-cc23-5d99-bde7-5581043985ed","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"e69da723-3cec-5330-9289-8c479bef175c","create":true,"after":{"title":"Elements of Banking","body":"Every topic is examinable.","outcomes":["Explain what banks do, how they create credit, and how the Nigerian financial system is organised.","Describe the evolution, functions and forms of money.","Trace the history of banking in Nigeria, from the colonial banks to today's recapitalisation.","Explain the role, functions and monetary policy tools of the Central Bank of Nigeria.","Describe the types of banks and other financial institutions in Nigeria, and the role of the NDIC.","Explain the money market, its institutions and instruments, and work simple money market calculations.","Describe how a clearing bank is organised and how cheques are cleared.","Explain bills of exchange, cheques and the main methods of payment, including electronic payments.","State the rights and duties of banker and customer.","Explain the banking services for exporters and importers.","Apply the principles of lending and explain the forms of security.","Read a bank's balance sheet and interpret a customer's accounts.","Explain how banks balance liquidity, profitability and safety.","Describe the work of the Chartered Institute of Bankers of Nigeria."],"assessment":["Expect objective questions: definitions, lists, features and functions, dates and Nigerian institutions, plus some short calculations."]}},"retire":[],"notes":[{"kind":"note","itemId":"a6e2c271-306d-5de6-9480-6bc557208ee7","sourceKey":"guide-topic:1","position":1,"payload":{"title":"The Business of Banking and the Financial System","body":"What banking is and how it evolved; the functions, income, risks and regulation of commercial banks; credit creation and the money multiplier (with computations); the financial system, its components, functions and objectives; financial intermediation; non-bank financial institutions; financial markets; financial inclusion, innovation and globalisation.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What banking is and how it evolved; the functions, income, risks and regulation of commercial banks; credit creation and the money multiplier (with computations); the financial system, its components, functions and objectives; financial intermediation; non-bank financial institutions; financial markets; financial inclusion, innovation and globalisation."}],"lessons":[{"number":"1.1","title":"Banking, its origin and the types of banks","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Banking:","bold":true},{"text":" the business of accepting deposits from the public and lending or investing those funds (and providing payment and other financial services). Banks are intermediaries between savers (surplus units) and borrowers (deficit units)."}]},{"text":[{"text":"Bank:","bold":true},{"text":" an institution whose main business is accepting deposits from the public and using them to grant loans and advances. Not a stock exchange, insurer or pension fund administrator."}]},{"text":[{"text":"\"Bank\"","bold":true},{"text":" comes from the Italian "},{"text":"banco","bold":true},{"text":": the "},{"text":"bench or table","bold":true},{"text":" on which money changers did their business. Italians were the first bankers."}]}]},{"type":"paragraph","text":[{"text":"Stages in the evolution of banking:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Valuables (gold) kept for safety in "},{"text":"temples and places of worship","bold":true},{"text":" (ancient Rome, Greece, Mesopotamia, China, Japan)."}]},{"text":[{"text":"Money lending by merchants and money changers","bold":true},{"text":" (exchanged coins, later took deposits and gave loans)."}]},{"text":[{"text":"Goldsmiths","bold":true},{"text":" (17th-century England) accepting gold on deposit and issuing receipts."}]},{"text":[{"text":"Commercial (joint-stock) banking."}]},{"text":[{"text":"Central banking","bold":true},{"text":" (issue of notes centralised, e.g. the Bank of England)."}]}]},{"type":"paragraph","text":[{"text":"Barter replacing money is "},{"text":"not","bold":true},{"text":" a stage (money replaced barter)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Goldsmiths:","bold":true},{"text":" charged fees and gave receipts. They noticed that "},{"text":"depositors rarely withdrew all their gold at the same time","bold":true},{"text":", so idle balances could be lent out at interest. They then paid interest on deposits to attract more. Their receipts circulated as payment and became "},{"text":"goldsmiths' notes","bold":true},{"text":", the forerunners of "},{"text":"bank notes","bold":true},{"text":"."}]},{"text":[{"text":"IOU (\"I owe you\"):","bold":true},{"text":" an "},{"text":"informal written acknowledgement of a debt","bold":true},{"text":"; "},{"text":"not negotiable","bold":true},{"text":" (cannot be assigned, sold or traded). A "},{"text":"promissory note","bold":true},{"text":" is a "},{"text":"negotiable","bold":true},{"text":" instrument. Contents of an IOU: parties, payment information, signatures, termination date, (ideally) a lawyer's involvement."}]}]},{"type":"paragraph","text":[{"text":"Types of banks","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Key feature"}]],"rows":[[[{"text":"Central bank"}],[{"text":"Government-owned; regulates the banking system; does not serve the public (CBN)"}]],[[{"text":"Commercial bank"}],[{"text":"Accepts deposits, grants loans; income mainly the interest spread"}]],[[{"text":"Investment (merchant) bank"}],[{"text":"Capital-market work: underwriting, M&A advice, asset management, trading, research; income from "},{"text":"fees, commissions and profits on own investments","bold":true}]],[[{"text":"Credit union"}],[{"text":"Member-owned, not-for-$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 2, $study_guide$profit cooperative","bold":true},{"text":"; members are owners and customers; better savings rates, lower fees"}]],[[{"text":"Savings and loan association"}],[{"text":"Savings deposits and mortgage loans"}]],[[{"text":"Development bank"}],[{"text":"Government-sponsored long-term finance for development"}]],[[{"text":"Microfinance bank"}],[{"text":"Small loans and savings for "},{"text":"low-income people and small businesses","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lending existed before goldsmiths; goldsmiths did not invent lending, but lending out part of deposited gold laid the foundation of modern banking. So it is fair to say goldsmiths \"brought lending into banking\"."}]},{"text":[{"text":"Underwriting:","bold":true},{"text":" the investment bank buys a whole new issue at an agreed price and resells it, bearing the risk of unsold shares."}]},{"text":[{"text":"Mama Ngozi, an unbanked Onitsha trader who opens a small savings account and later borrows ₦50,000, is a typical microfinance bank customer."}]},{"text":[{"text":"Bank of Industry (BOI) was formed in "},{"text":"2001","bold":true},{"text":" by merging the "},{"text":"Nigerian Industrial Development Bank (NIDB)","bold":true},{"text":", the Nigerian Bank for Commerce and Industry (NBCI) and NERFUND."}]},{"text":[{"text":"Today banking in Nigeria is governed by the "},{"text":"Banks and Other Financial Institutions Act (BOFIA) 2020","bold":true},{"text":", which replaced BOFIA 1991, and the "},{"text":"CBN Act 2007","bold":true},{"text":". The CBN Governor is "},{"text":"Olayemi Cardoso","bold":true},{"text":" (since 2023). The 2024 recapitalisation set minimum capital of ₦500 billion (international), ₦200 billion (national), ₦50 billion (regional and merchant) and ₦20 billion / ₦10 billion (non-interest national / regional), with a deadline of "},{"text":"31 March 2026","bold":true},{"text":"."}]}]}]},{"number":"1.2","title":"What commercial banks do, how they earn, and their risks","mustKnow":[{"type":"paragraph","text":[{"text":"Two principal functions:","bold":true},{"text":" (1) "},{"text":"accepting deposits","bold":true},{"text":" from the public; (2) "},{"text":"granting loans and advances","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Deposits:","bold":true},{"text":" "},{"text":"current (demand)","bold":true},{"text":" (withdraw any time by cheque, little or no interest); "},{"text":"savings","bold":true},{"text":" (interest, limited withdrawals); "},{"text":"fixed (time)","bold":true},{"text":" (fixed period and rate agreed at the start; early withdrawal loses interest; higher rate the longer the term)."}]},{"text":[{"text":"Advances:","bold":true},{"text":" loans, "},{"text":"overdrafts","bold":true},{"text":" (draw beyond your balance up to a limit; interest only on the overdrawn amount) and "},{"text":"bills discounting","bold":true},{"text":" (buying a bill before maturity for less than face value, collecting the full value at maturity)."}]}]},{"type":"paragraph","text":[{"text":"Ancillary functions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Agency:","bold":true},{"text":" collecting cheques, "},{"text":"dividends and interest","bold":true},{"text":"; paying insurance premiums and standing orders; buying and selling shares; remittances."}]},{"text":[{"text":"Acting as "},{"text":"executor, trustee or attorney","bold":true},{"text":" for customers' estates."}]},{"text":[{"text":"Safe custody","bold":true},{"text":" of wills, jewellery and documents."}]},{"text":[{"text":"Other credit services: "},{"text":"debt factoring","bold":true},{"text":", "},{"text":"loan syndication","bold":true},{"text":", equipment leasing, direct credit, foreign exchange, advisory services."}]}]},{"type":"paragraph","text":[{"text":"Not commercial-bank functions: "},{"text":"issuing legal tender currency","bold":true},{"text":", lender of last resort (both CBN), "},{"text":"writing wills","bold":true},{"text":" (lawyers write wills; banks only keep them or act as executors)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Debt factoring:","bold":true},{"text":" the bank "},{"text":"buys a customer's book debts at an agreed discount","bold":true},{"text":" and collects from the debtors."}]},{"text":[{"text":"Loan syndication:","bold":true},{"text":" a "},{"text":"lead bank","bold":true},{"text":" brings several banks together to finance a large project no single bank could conveniently fund."}]},{"text":[{"text":"Income:","bold":true},{"text":" mainly "},{"text":"net interest income","bold":true},{"text":" = interest on loans minus interest on deposits (the spread); plus fees and investment income."}]},{"text":[{"text":"Goals of deposit money banks:","bold":true},{"text":" "},{"text":"profitability, liquidity, solvency","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Risks","bold":true}]},{"type":"table","header":[[{"text":"Risk"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Credit"}],[{"text":"Borrowers fail to repay"}],[{"text":"Floods ruin farmers who borrowed"}]],[[{"text":"Liquidity"}],[{"text":"Not enough cash for withdrawals"}],[{"text":"Funds locked in long mortgages; many withdraw at once"}]],[[{"text":"Interest rate"}],[{"text":"Rate changes hurt profit"}],[]],[[{"text":"Operational"}],[{"text":"Failed processes, people, fraud, systems"}],[{"text":"Cashier and fraudsters; computer fails to flag transfers"}]],[[{"text":"Market"}],[{"text":"Losses from price, exchange-rate moves"}],[]]]},{"type":"paragraph","text":[{"text":"Regulation:","bold":true},{"text":" "},{"text":"prudential","bold":true},{"text":" (safety of each bank: capital, asset quality, liquidity); "},{"text":"consumer protection","bold":true},{"text":" (disclosure of charges, complaints resolution); "},{"text":"monetary policy regulation","bold":true},{"text":" (reserve ratios, rates). "$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 3, $study_guide$},{"text":"Capital adequacy","bold":true},{"text":" = minimum capital "},{"text":"relative to risk-weighted assets","bold":true},{"text":". "},{"text":"Deposit insurance","bold":true},{"text":" (NDIC) protects depositors up to a limit if a bank fails, preventing runs and keeping confidence."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (net interest income):","bold":true},{"text":" loans ₦800m at 20%, deposits ₦1,000m at 8%. Interest earned = 20% × ₦800m = ₦160m. Interest paid = 8% × ₦1,000m = ₦80m. Net interest income = ₦160m − ₦80m = "},{"text":"₦80m","bold":true},{"text":". (₦96m and ₦240m are traps.)"}]},{"text":[{"text":"Worked example (overdraft):","bold":true},{"text":" Bisi has ₦100,000 credit and a ₦500,000 overdraft limit; she withdraws ₦400,000. Overdrawn amount = ₦400,000 − ₦100,000 = "},{"text":"₦300,000","bold":true},{"text":"; interest is charged only on this. At 24% a year simple interest for 3 months: ₦300,000 × 0.24 × 3/12 = "},{"text":"₦18,000","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (bill discounting):","bold":true},{"text":" a ₦1,000,000 three-month bill is bought for ₦950,000. The bank's discount (income) = ₦1,000,000 − ₦950,000 = "},{"text":"₦50,000","bold":true},{"text":"."}]},{"text":[{"text":"Spread:","bold":true},{"text":" paying 3% on savings and charging 8% on loans gives a margin of 5%."}]},{"text":[{"text":"NDIC cover now (since 2024):","bold":true},{"text":" "},{"text":"₦5 million","bold":true},{"text":" per depositor in deposit money banks (also payment service banks and mobile-money pass-through), "},{"text":"₦2 million","bold":true},{"text":" in microfinance and primary mortgage banks (formerly ₦500,000 and ₦200,000)."}]},{"text":[{"text":"CBN core functions","bold":true},{"text":" (so you can reject them as commercial-bank work): issuing legal tender, banker and adviser to government, banker to banks and "},{"text":"lender of last resort","bold":true},{"text":" (emergency cash to a sound bank facing a run), managing external reserves, monetary policy, supervision. The CBN does "},{"text":"not","bold":true},{"text":" take deposits from or lend to the public."}]},{"text":[{"text":"Direct monetary controls","bold":true},{"text":" (used before Nigeria moved to market-based management in 1993): credit ceilings, administered (fixed) interest rates, selective credit controls. "},{"text":"Open market operations","bold":true},{"text":" in treasury bills are "},{"text":"indirect","bold":true},{"text":" (market-based)."}]}]}]},{"number":"1.3","title":"Credit creation and the money multiplier","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Banks create money "},{"text":"by lending","bold":true},{"text":": each new loan creates a new "},{"text":"demand deposit","bold":true},{"text":". They do "},{"text":"not","bold":true},{"text":" print notes or coins (only the CBN issues currency)."}]},{"text":[{"text":"Borrowing from banks abroad does not create money either: it only moves existing money from one holder to another. New money (deposits) arises only when a bank lends."}]},{"text":[{"text":"Assumptions:","bold":true},{"text":" (1) an initial "},{"text":"primary deposit in cash","bold":true},{"text":"; (2) only a "},{"text":"fraction","bold":true},{"text":" of each deposit is needed by depositors soon; (3) a fraction must by law be kept as "},{"text":"reserve","bold":true},{"text":"; (4) the rest, the "},{"text":"excess reserve","bold":true},{"text":", is lent out; (5) credit can be created to a multiple of the initial deposit; (6) the multiple depends on the reserve ratio. Also: loans are redeposited in banks and there is no cash drain."}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true},{"text":" (r = cash reserve ratio as a decimal):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Required reserve = r × deposit"}]},{"text":[{"text":"Excess reserve (amount lent at first stage) = deposit − required reserve = deposit × (1 − r)"}]},{"text":[{"text":"Money (deposit, credit) multiplier: k = 1 / r"}]},{"text":[{"text":"Total deposits created (including the initial deposit) = initial deposit × k = initial deposit / r"}]},{"text":[{"text":"New (derived) deposits = total deposits − initial deposit"}]},{"text":[{"text":"Reserve ratio from totals: r = initial deposit / total deposits; multiplier k = total / initial"}]},{"text":[{"text":"The multiplier is the "},{"text":"inverse","bold":true},{"text":" (reciprocal) of the reserve ratio. Reserve ratio and total credit (and the multiplier) are "},{"text":"inversely","bold":true},{"text":" related."}]},{"text":[{"text":"Limits to credit creation:","bold":true},{"text":" (1) "},{"text":"size of the initial cash deposit","bold":true},{"text":"; (2) "},{"text":"reserve ratio","bold":true},{"text":"; (3) "},{"text":"leakages","bold":true},{"text":" (cash kept outside banks). Also: shortage of creditworthy borrowers or lack of collateral, the public's preference for holding cash, fear of cash drain, and "},{"text":"central bank contractionary policy","bold":true},{"text":". Borrowers "},{"text":"redepositing","bold":true},{"text":" loans in other banks does "},{"text":"not","bold":true},{"text":" limit creation; it keeps it going."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Process, ₦1,000m at 25%:","bold":true},{"text":" Bank X keeps ₦250m, lends "},{"text":"₦750m","bold":true},{"text":". Bank Y receives ₦750m, keeps ₦187.5m, lends ₦562.5m. Bank Z receives ₦562.5m, keeps ₦140.625m, lends ₦421.875m. Total deposits = ₦1,000m × 1/0.25 = "},{"text":"₦4,000m","bold":true},{"text":". At 40%: ₦1,000m ÷ 0.40 = "},{"text":"₦2,500m","bold":true},{"text":". At 10%: ₦10,000m."}]},{"text":[{"text":"₦2,000,000 at 20%:","bold":true},{"text":" total = 2,000,000 ÷ 0.20 = "},{"text":"₦10,000,000","bold":true},{"text":" (new deposits ₦8,000,000 is the trap)."}]},{"text":[{"text":"₦5,000 at 25%:","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 4, $study_guide$ld":true},{"text":" k = 1 ÷ 0.25 = "},{"text":"4","bold":true},{"text":"; total = 5,000 × 4 = "},{"text":"₦20,000","bold":true},{"text":"."}]},{"text":[{"text":"₦500 at 15%:","bold":true},{"text":" k = 1 ÷ 0.15 = "},{"text":"6.67","bold":true},{"text":" (2 d.p.); total = 500 ÷ 0.15 = "},{"text":"₦3,333.33","bold":true},{"text":"; required reserve = 0.15 × 500 = ₦75; excess reserve = 500 − 75 = "},{"text":"₦425","bold":true},{"text":"."}]},{"text":[{"text":"₦1,000 at 15%:","bold":true},{"text":" 1,000 ÷ 0.15 = ₦6,666.67, about "},{"text":"₦6,667","bold":true},{"text":"."}]},{"text":[{"text":"Finding r:","bold":true},{"text":" ₦15m creates ₦240m: k = 240 ÷ 15 = 16, r = 1 ÷ 16 = "},{"text":"6.25%","bold":true},{"text":". ₦35m creates ₦280m: r = 35 ÷ 280 = "},{"text":"12.5%","bold":true},{"text":". ₦50m creates ₦500m: k = "},{"text":"10","bold":true},{"text":", r = 10%."}]},{"text":[{"text":"Percentage changes (trap):","bold":true},{"text":" \"increased by 100%\" means "},{"text":"doubled","bold":true},{"text":"; \"increased by 50%\" means × 1.5 (10% becomes 15%, not 60%); \"reduced by 50%\" means halved; \"decreased by 25%\" means × 0.75; \"increased by 25%\" means × 1.25; \"increased by 40%\" means × 1.4."}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"New r"}],[{"text":"New initial deposit"}],[{"text":"Total created"}]],"rows":[[[{"text":"₦15m, 6.25% doubled"}],[{"text":"12.5%"}],[{"text":"₦15m"}],[{"text":"15 ÷ 0.125 = ₦120m"}]],[[{"text":"₦15m down 25%, 6.25%"}],[{"text":"6.25%"}],[{"text":"₦11.25m"}],[{"text":"11.25 ÷ 0.0625 = ₦180m"}]],[[{"text":"₦15m down 25%, r doubled"}],[{"text":"12.5%"}],[{"text":"₦11.25m"}],[{"text":"11.25 ÷ 0.125 = ₦90m"}]],[[{"text":"₦35m, 12.5% doubled"}],[{"text":"25%"}],[{"text":"₦35m"}],[{"text":"35 ÷ 0.25 = ₦140m"}]],[[{"text":"₦35m up 25%, 12.5%"}],[{"text":"12.5%"}],[{"text":"₦43.75m"}],[{"text":"43.75 ÷ 0.125 = ₦350m"}]],[[{"text":"₦35m down 25%, r doubled"}],[{"text":"25%"}],[{"text":"₦26.25m"}],[{"text":"26.25 ÷ 0.25 = ₦105m"}]],[[{"text":"₦10m at 10%"}],[{"text":"10%"}],[{"text":"₦10m"}],[{"text":"10 ÷ 0.10 = ₦100m"}]],[[{"text":"₦10m, 10% up 50%"}],[{"text":"15%"}],[{"text":"₦10m"}],[{"text":"10 ÷ 0.15 = ₦66.67m"}]],[[{"text":"₦10m, 10% down 50%"}],[{"text":"5%"}],[{"text":"₦10m"}],[{"text":"10 ÷ 0.05 = ₦200m"}]],[[{"text":"₦50m up 40%, 10% doubled"}],[{"text":"20%"}],[{"text":"₦70m"}],[{"text":"70 ÷ 0.20 = ₦350m"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"To create more money banks must "},{"text":"lend out more","bold":true},{"text":" of their deposits; raising their cash ratio with the CBN reduces creation."}]}]}]},{"number":"1.4","title":"The financial system and financial intermediation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial system:","bold":true},{"text":" the network of "},{"text":"financial institutions, markets, instruments and regulations","bold":true},{"text":" that "},{"text":"channels funds from surplus units (savers) to deficit units (borrowers)","bold":true},{"text":". The 1976 Committee on the Nigerian Financial System called it \"the congeries of financial institutions and arrangements which serve the needs of an economy\". It operates at firm, national and global levels."}]},{"text":[{"text":"4 components:","bold":true},{"text":" financial "},{"text":"institutions","bold":true},{"text":", financial "},{"text":"markets","bold":true},{"text":", financial "},{"text":"instruments","bold":true},{"text":", financial "},{"text":"services","bold":true},{"text":"."}]},{"text":[{"text":"Instruments:","bold":true},{"text":" "},{"text":"equity","bold":true},{"text":" (shares), "},{"text":"debt","bold":true},{"text":" (bonds, debentures, loans), "},{"text":"derivative","bold":true},{"text":" (options, futures, forwards, swaps), "},{"text":"hybrid","bold":true},{"text":" ("},{"text":"convertible bonds","bold":true},{"text":", preference shares)."}]},{"text":[{"text":"3 basic types of institutions:","bold":true},{"text":" "},{"text":"bank financial institutions","bold":true},{"text":" (BFIs), "},{"text":"non-bank financial institutions","bold":true},{"text":" (NBFIs), "},{"text":"regulatory and supervisory institutions","bold":true},{"text":"."}]},{"text":[{"text":"Regulators:","bold":true},{"text":" CBN, Federal Ministry of Finance, "},{"text":"NDIC","bold":true},{"text":", "},{"text":"SEC","bold":true},{"text":" (capital market), "},{"text":"NAICOM","bold":true},{"text":" (insurance), "},{"text":"PenCom","bold":true},{"text":" (pensions), FMBN (formerly mortgage institutions), FSRCC (coordinates regulators). NDIC and the "},{"text":"Debt Management Office","bold":true},{"text":" are "},{"text":"not","bold":true},{"text":" NBFIs."}]}]},{"type":"paragraph","text":[{"text":"Functions of the financial system (8):","bold":true},{"text":" mobilisation of savings; efficient capital allocation; "},{"text":"liquidity provision","bold":true},{"text":" (turning assets into cash quickly without significant loss of value); risk management and transfer; price discovery and information; payment and settlement; monetary policy transmission; promoting financial inclusion. The seven functions of financial markets (Lesson 1.6: savings mobilisation, storage of wealth, liquidity, credit, payments, protection against risk, monetary policy) are also functions of the financial system. Fixing the prices of goods and services is "},{"text":"not","bold":true},{"text":" a function."}]},{"type":"paragraph","text":[{"text":"Objectives of the Nigerian financial system (8):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provide "},{"text":"non-inflationary","bold":true},{"text":" support to the economy."}]},{"text":[{"text":"Facilitate effective management of the economy."}]},{"text":[{"text":"Assist in transforming the "},{"text":"rural community","bold":true},{"text":"."}]},{"text":[{"text":"Achieve greater "},{"text":"mobilisation of savings","bold":true},{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 5, $study_guide$ and channel them efficiently."}]},{"text":[{"text":"Ensure that "},{"text":"no viable project is frustrated simply for lack of funds","bold":true},{"text":"."}]},{"text":[{"text":"Protect the economy from the vicissitudes of the international economy."}]},{"text":[{"text":"Sustain indigenisation and management of the economy."}]},{"text":[{"text":"Achieve greater integration and linkage in agriculture."}]}]},{"type":"paragraph","text":[{"text":"Services:","bold":true},{"text":" intermediation, resource mobilisation, resource allocation, efficient payments, foreign exchange for trade."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct finance:","bold":true},{"text":" borrower raises funds straight from savers in the financial market (e.g. a company selling ₦5 billion of bonds to households). "},{"text":"Indirect finance (financial intermediation):","bold":true},{"text":" through an intermediary; the main route."}]},{"text":[{"text":"Financial intermediaries:","bold":true},{"text":" the general name for institutions that move funds from surplus to deficit units (BFIs and NBFIs both do this)."}]},{"text":[{"text":"Weaknesses of direct financing:","bold":true},{"text":" much "},{"text":"time and effort","bold":true},{"text":" to find a lender; "},{"text":"high cost","bold":true},{"text":" (price) of funds; "},{"text":"short period","bold":true},{"text":"; "},{"text":"high risk","bold":true},{"text":" to the lender."}]},{"text":[{"text":"Advantages of intermediaries:","bold":true},{"text":" access to "},{"text":"bulky sums","bold":true},{"text":" (consortium if needed); "},{"text":"lower risk","bold":true},{"text":" per saver (pooling); "},{"text":"lower cost","bold":true},{"text":"; "},{"text":"longer term","bold":true},{"text":"."}]},{"text":[{"text":"How intermediaries promote savings, investment and capital formation:","bold":true},{"text":" by "},{"text":"pooling funds from surplus units and channelling them into productive investment","bold":true},{"text":" by deficit units; reducing risk, mobilising idle funds, giving liquidity and income to savers, and allocating funds expertly."}]},{"text":[{"text":"Why savers trust intermediaries:","bold":true},{"text":" they "},{"text":"pay interest","bold":true},{"text":", have a "},{"text":"reputation to protect","bold":true},{"text":", and let savers "},{"text":"withdraw when needed","bold":true},{"text":" (safety plus liquidity)."}]},{"text":[{"text":"Success factors:","bold":true},{"text":" (1) "},{"text":"trust and confidence","bold":true},{"text":"; (2) "},{"text":"convenience","bold":true},{"text":" (little bureaucracy, nearness); (3) "},{"text":"price","bold":true},{"text":" (interest, fees). Loss of trust leads to "},{"text":"financial disintermediation","bold":true},{"text":" (mass withdrawal of funds)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maturity (securities) transformation:","bold":true},{"text":" banks lend for five years though most depositors leave money for months; they "},{"text":"bridge the different maturity (capital lock-up) periods","bold":true},{"text":". NBFIs do it by buying long-term primary securities and issuing their own indirect securities with different maturities. Other NBFI services: "},{"text":"aggregation","bold":true},{"text":", accessibility, specialisation, risk reduction."}]},{"text":[{"text":"Bank vs NBFI:","bold":true},{"text":" bank "},{"text":"liabilities (demand deposits withdrawable by cheque) are spendable as money","bold":true},{"text":", so banks can create credit; NBFI liabilities are not. Both mobilise surplus funds for deficit units."}]},{"text":[{"text":"Demand-following hypothesis:","bold":true},{"text":" finance grows "},{"text":"in response to demand","bold":true},{"text":" from a growing real economy (colonial Nigeria, dominated by expatriate banks financing export trade). "},{"text":"Supply-leading:","bold":true},{"text":" institutions are "},{"text":"set up ahead of demand","bold":true},{"text":" to mobilise savings and stimulate growth (Patrick, 1966). Do not confuse either with financial repression (rates fixed below market, credit rationed)."}]},{"text":[{"text":"Factors in the development of Nigeria's system:","bold":true},{"text":" independence, the CBN (1958), civil war, oil boom, government financing needs, monetary policy changes, regulation and deregulation, the 1976 Financial System Review Committee, the 1972 Indigenisation Decree, SAP (1986), NDIC, EFCC, 2004 bank consolidation, 2009 reform."}]}]}]},{"number":"1.5","title":"Non-bank financial institutions","mustKnow":[{"type":"paragraph","text":[{"text":"NBFIs are "},{"text":"heterogeneous","bold":true},{"text":": many different kinds, each with its own functions: insurers, pension funds and PFAs, finance companies, primary mortgage institutions, bureaux de change, discount houses, unit trusts, cooperatives."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Insurance:","bold":true},{"text":" two major types, "},{"text":"life","bold":true},{"text":" and "},{"text":"non-life","bold":true},{"text":". Two functions: "},{"text":"risk transfer","bold":true},{"text":" and "},{"text":"financial intermediation","bold":true},{"text":". Life covers loss from "},{"text":"death, disability or old age","bold":true},{"text":"; long-term; variants: "},{"text":"whole life","bold":true},{"text":" (paid on death) and "},{"text":"endowment assurance","bold":true},{"text":" (paid at the end of the term if alive, or to beneficiaries on earlier death). Non-life ("},{"text":"property","bold":true},{"text":": fire, theft, marine; "},{"text":"liability","bold":true},{"text":": negligence) is usually "},{"text":"yearly","bold":true},{"text":", so non-life funds go into short-term assets and life funds into long-term assets. Regulator: "},{"text":"NAICOM","bold":true},{"text":" (since 1997)."}]},{"text":[{"text":"NPF/NSITF:","bold":true},{"text":" the "},{"text":"National Provident Fu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 6, $study_guide$nd (1961)","bold":true},{"text":", for private-sector workers, was replaced by the "},{"text":"Nigeria Social Insurance Trust Fund (NSITF) in 1993 by Decree No. 73","bold":true},{"text":", because of "},{"text":"poor performance","bold":true},{"text":" (poor records, employers not remitting contributions). NSITF's "},{"text":"7 areas:","bold":true},{"text":" retirement pension, retirement grant, invalidity pension, invalidity grant, survivors' pension, survivors' grant, funeral grant."}]},{"text":[{"text":"Pension Reform Act 2004:","bold":true},{"text":" created the "},{"text":"National Pension Commission (PenCom)","bold":true},{"text":", plus "},{"text":"Pension Fund Administrators (PFAs)","bold":true},{"text":" and "},{"text":"Pension Fund Custodians (PFCs)","bold":true},{"text":". Each worker opens a "},{"text":"Retirement Savings Account (RSA) with a PFA of his choice","bold":true},{"text":"; the PFA invests, the "},{"text":"PFC keeps the assets in custody","bold":true},{"text":". PenCom "},{"text":"licenses and supervises PFAs and PFCs","bold":true},{"text":"."}]},{"text":[{"text":"Defined contribution:","bold":true},{"text":" benefit depends on "},{"text":"contributions plus investment returns","bold":true},{"text":" in the RSA (worker bears investment risk). "},{"text":"Defined benefit:","bold":true},{"text":" benefit "},{"text":"fixed in advance by formula","bold":true},{"text":" (final salary, years of service, rank)."}]},{"text":[{"text":"Primary mortgage institutions:","bold":true},{"text":" set up under "},{"text":"Decree No. 53 of 1989","bold":true},{"text":" to mobilise savings and give housing loans; first regulated by the "},{"text":"Federal Mortgage Bank of Nigeria (FMBN)","bold":true},{"text":"; the CBN took over in the late 1990s. Now called primary mortgage banks, regulated by the CBN."}]},{"text":[{"text":"Finance houses/companies:","bold":true},{"text":" borrow "},{"text":"placements","bold":true},{"text":" and lend at higher rates; services include "},{"text":"LPO financing","bold":true},{"text":", leasing, project financing, debt factoring; under CBN oversight since 1991 (CBN Decree 24, BOFI Decree 25); may not take public deposits."}]},{"text":[{"text":"Bureaux de change (1989):","bold":true},{"text":" deal in foreign exchange for "},{"text":"small users","bold":true},{"text":". Purposes: cater for small users; bring the "},{"text":"parallel (black) market","bold":true},{"text":" under official purview and regulate it; eliminate the parallel-market premium by merging the rates. Also: give legal recognition to small dealers, free access for small buyers, better forex statistics, less pressure on the official market. Not for big corporate allocations, deposits or overdrafts. CBN oversight since 1997."}]},{"text":[{"text":"Discount houses (1993):","bold":true},{"text":" dealt mainly in "},{"text":"short-term government securities","bold":true},{"text":" in the money market, between banks and the CBN."}]},{"text":[{"text":"Unit trusts:","bold":true},{"text":" pool many small savers' funds into a "},{"text":"diversified portfolio","bold":true},{"text":", with an independent trustee."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current position:","bold":true},{"text":" the "},{"text":"Pension Reform Act 2014","bold":true},{"text":" replaced the 2004 Act (minimum contributions 10% employer, 8% employee; the 2004 Act had 7.5% each). NSITF now runs the employees' compensation scheme. Discount houses were phased out in the mid-2010s, several becoming merchant banks."}]},{"text":[{"text":"Finance houses failed in the mid-1990s from speculation, rates up to 60%, loans without collateral and fund mismatch (short placements in fixed assets)."}]}]}]},{"number":"1.6","title":"Financial markets; inclusion, innovation and globalisation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial market:","bold":true},{"text":" institutional arrangements that "},{"text":"mobilise funds from surplus units and channel them to deficit units","bold":true},{"text":". "},{"text":"7 functions:","bold":true},{"text":" savings mobilisation, storage of wealth, liquidity, credit, payments system, "},{"text":"protection against risk","bold":true},{"text":", executing monetary policy. Not: fixing prices or issuing currency."}]}]},{"type":"table","header":[[{"text":"Money market"}],[{"text":"Capital market"}]],"rows":[[[{"text":"Short-term funds (up to one year)"}],[{"text":"Medium- to long-term funds"}]],[[{"text":"Treasury bills, commercial paper, bankers' acceptances, call money"}],[{"text":"Shares (equities), bonds, "},{"text":"debentures","bold":true}]],[[{"text":"Liquidity, working capital"}],[{"text":"Expansion, factories (e.g. 15-year funds)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary market:","bold":true},{"text":" "},{"text":"new issues","bold":true},{"text":"; the "},{"text":"only segment where capital formation occurs","bold":true},{"text":". "},{"text":"Secondary market:","bold":true},{"text":" trading of "},{"text":"existing","bold":true},{"text":" securities."}]},{"text":[{"text":"Capital market:","bold":true},{"text":" market for raising medium- to long-term funds for investment. Principal institutions: "},{"text":"SEC","bold":true},{"text":" (apex regulator) and the stock exchange. Participants include issuing houses, stockbrokers, "},{"text":"underwriters","bold":true},{"text":", registrars; finance houses are "},{"text":"not","bold":true},{"text":" capital-market participants."}]},{"text":[{"text":"Benefit of a capital market to Nigeria:","bold":true},{"text":" it "},{"text":"channels medium- to long-term funds to firms and governments","bold":true},{"text":" for expansion and development projects."}]},{"text":[{"text":"Financial dualism:","bold":true},{"text":" organised and unorganised (informal: esusu, ajo, moneylenders) markets existing side by side."}]},{"text":[{"text":"Bond prices move "}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 7, $study_guide$,{"text":"inversely","bold":true},{"text":" with interest rates: a rise in the price of fixed-interest securities means the market rate has "},{"text":"fallen","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current names:","bold":true},{"text":" the Nigerian Stock Exchange (NSE) demutualised in "},{"text":"2021","bold":true},{"text":" into "},{"text":"Nigerian Exchange Group","bold":true},{"text":", with "},{"text":"Nigerian Exchange Limited (NGX)","bold":true},{"text":" as the exchange. SEC now operates under the "},{"text":"Investments and Securities Act 2025","bold":true},{"text":" (replaced ISA 2007)."}]},{"text":[{"text":"Financial inclusion:","bold":true},{"text":" all sections of society, especially low-income and vulnerable groups, have "},{"text":"access to appropriate, affordable financial services","bold":true},{"text":". Helped by "},{"text":"agent banking, mobile money and simple low-cost accounts","bold":true},{"text":" in underserved areas (Nigeria's National Financial Inclusion Strategy dates from 2012). Collateral for savings accounts or closing rural branches does the opposite."}]},{"text":[{"text":"Financial innovation:","bold":true},{"text":" new financial products, services or processes. "},{"text":"Globalisation:","bold":true},{"text":" growing interconnection of countries through flows of goods, services, finance, people and ideas."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Banking = taking deposits and lending; \"bank\" from Italian banco (bench); goldsmiths brought lending in; receipts became bank notes."}]},{"text":[{"text":"Principal functions: deposits and advances; agency (collect dividends); safe custody; no currency issue, no will writing."}]},{"text":[{"text":"Net interest income = interest earned − interest paid; overdraft interest only on the overdrawn amount."}]},{"text":[{"text":"Risks: credit, liquidity, interest rate, operational, market."}]},{"text":[{"text":"k = 1/r; total deposits = initial ÷ r; excess reserve = deposit × (1 − r); \"increased by 100%\" = doubled."}]},{"text":[{"text":"Limits: initial deposit, reserve ratio, leakages."}]},{"text":[{"text":"Financial system = institutions, markets, instruments, services; 3 institution types: BFIs, NBFIs, regulators."}]},{"text":[{"text":"Intermediation succeeds on trust, convenience, price; loss of trust = disintermediation."}]},{"text":[{"text":"NPF 1961 → NSITF 1993 (Decree 73); PRA 2004 → PenCom, PFAs, PFCs; PMIs 1989 under FMBN."}]},{"text":[{"text":"Money market short-term, capital market long-term; primary market = capital formation; SEC is the capital-market apex regulator."}]}]}],"theory":{"itemId":"dbe954f3-3729-5b02-be2c-8358c1436612","question":[{"type":"paragraph","text":[{"text":"A bank receives a fresh cash deposit of ₦4,000,000. The cash reserve ratio is 20%. Find (a) the excess reserve of the first bank, (b) the money multiplier, (c) the total deposits the banking system can create, and (d) the total if the reserve ratio is increased by 25%."}]}]},"practice":[{"topic":"The Business of Banking and the Financial System","named":false}]}},{"kind":"note","itemId":"4be90ce0-943d-57d4-8f48-184bc229b1bc","sourceKey":"guide-topic:2","position":2,"payload":{"title":"The Development of Money","body":"Barter, its features, advantages and limitations; definitions of money and the schools of thought; the functions and characteristics of money; the types of money and how money evolved from barter to the eNaira; the money stock (M1, M2, M3), near money and the value of money; how banks create credit and what limits it.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Barter, its features, advantages and limitations; definitions of money and the schools of thought; the functions and characteristics of money; the types of money and how money evolved from barter to the eNaira; the money stock (M1, M2, M3), near money and the value of money; how banks create credit and what limits it."}],"lessons":[{"number":"2.1","title":"Barter and why money came","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Barter (trade by barter):","bold":true},{"text":" the direct exchange of goods and services for other goods and services without the use of money. In short, exchange of commodity for commodity (goods for goods)."}]},{"text":[{"text":"Barter economy:","bold":true},{"text":" a simple economic system where production is limited, so surplus output is limited, and trade takes place only by exchanging commodities for commodities. It is an economy where money is not in use. Barter existed before the money economy."}]},{"text":[{"text":"3 basic features of a barter economy:","bold":true},{"text":" (1) a producer produces almost all his needs himself; (2) the level of surplus is limited; (3) a producer directly exchanges his products for other people's products."}]},{"text":[{"text":"Barter vs money economy:","bold":true},{"text":" barter = goods exchanged directly for goods; money economy = goods and services exchanged for money."}]}]},{"type":"paragraph","text":[{"text":"Limitations of barter:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Double coincidence of wants","bold":true},{"text":" (the main limitation): each party must have what the other wants "},{"text":"and","bold":true},{"text":" want what the other has, at the same time."}]},{"text":[{"text":"Lack of a common measure of value","bold":true},{"text":" (no unit of account): too many relative prices to know; the problem of fixing exchange rates between goods."}]},{"text":[{"text":"Indivisibility","bold":true},{"text":" of goods (a cow cannot be split for a few bags of salt)."}]},{"text":[{"text":"Difficulty of storing value","bold":true},{"text":" (no means of storing wealth; goods perish)."}]},{"text":[{"text":"Difficulty of deferred payment","bold":true},{"text":" (no standard for debts and credit)."$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 8, $study_guide$}]},{"text":[{"text":"Transport difficulties","bold":true},{"text":" (bulky goods carried long distances in search of a partner)."}]},{"text":[{"text":"Lack of specialisation","bold":true},{"text":" (everyone a \"jack of all trades, master of none\")."}]},{"text":[{"text":"Waste of time and cost of information","bold":true},{"text":" (failure to expedite transactions)."}]},{"text":[{"text":"Waiting cost and storage cost:","bold":true},{"text":" stockpiling output while waiting for a partner creates two fresh costs: the "},{"text":"waiting (opportunity) cost","bold":true},{"text":" of satisfaction forgone, and the "},{"text":"storage cost","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Relative prices under barter:","bold":true},{"text":" with n goods, number of relative prices = n(n − 1) / 2. A money economy needs only one money price per good."}]},{"text":[{"text":"Two major advantages of a money economy over barter:","bold":true},{"text":" money is a good "},{"text":"store of value","bold":true},{"text":" (barter goods are often perishable), and money is "},{"text":"divisible","bold":true},{"text":" into small units, so small purchases are possible."}]}]},{"type":"paragraph","text":[{"text":"Advantages of barter (5):","bold":true},{"text":" simplicity and directness; no need for money; flexibility in valuing goods; "},{"text":"freedom from inflation, currency devaluation and over-issue of money","bold":true},{"text":"; promotion of self-sufficiency."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Barter is traced to about 6000 BC in Mesopotamia (modern Iraq)."}]},{"text":[{"text":"Trap: \"direct exchange of goods for goods\" is what barter "},{"text":"is","bold":true},{"text":", not a drawback; \"inflation from over-issue of currency\" is a problem of money, not of barter."}]},{"text":[{"text":"Double coincidence example: a yam farmer wants cloth, but the only weaver wants fish, not yams. No trade. Indivisibility example: a cattle owner wants salt worth far less than one cow."}]},{"text":[{"text":"Worked example (relative prices): with 1,000 goods, 1,000 × 999 / 2 = 499,500, about "},{"text":"500,000","bold":true},{"text":" relative prices. With 50 goods: 50 × 49 / 2 = 1,225."}]},{"text":[{"text":"Modern barter","bold":true},{"text":" survives as "},{"text":"countertrade","bold":true},{"text":" (two countries swap, say, crude oil for machinery with no money changing hands), barter exchanges, and in crises such as Zimbabwe's hyperinflation."}]},{"text":[{"text":"Money is a "},{"text":"social invention that evolved gradually","bold":true},{"text":" because barter's shortcomings made a "},{"text":"generally acceptable","bold":true},{"text":" medium of exchange necessary. It was not created by one decree, and it came long before commercial banks."}]}]}]},{"number":"2.2","title":"Meaning and definitions of money","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money (general definition):","bold":true},{"text":" anything that is generally acceptable as a means of payment for goods and services and in settlement of debts. Put simply, money is a "},{"text":"medium of exchange","bold":true},{"text":"."}]},{"text":[{"text":"Coulborn:","bold":true},{"text":" \"a means of valuation and of payment, as both the unit of account and the generally acceptable medium of exchange\"."}]},{"text":[{"text":"Pierce and Shaw (1974):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Abstract definition:","bold":true},{"text":" money is a "},{"text":"unit of account","bold":true},{"text":", the common denominator in which the exchange value of all goods and services is expressed."}]},{"text":[{"text":"Tangible (concrete) definition:","bold":true},{"text":" money is a medium of exchange whose ownership is capable of changing hands."}]}]}]},{"text":[{"text":"3 modern classifications:","bold":true},{"text":" (1) general, (2) legal, (3) functional."}]}]},{"type":"paragraph","text":[{"text":"3 schools of thought under the general definition:","bold":true}]},{"type":"table","header":[[{"text":"School"}],[{"text":"View"}]],"rows":[[[{"text":"Currency school"}],[{"text":"Money = legal tender currency (naira and kobo, pounds, dollars)"}]],[[{"text":"Banking school"}],[{"text":"Agrees, but says cheques must count: \"cheque is money and money is cheque\", since most bank transactions use cheques"}]],[[{"text":"Monetarist (Chicago) view, "},{"text":"Milton Friedman","bold":true}],[{"text":"Money is "},{"text":"anything that serves as a temporary abode of purchasing power","bold":true},{"text":" (includes cheques, drafts, promissory notes, bills of exchange)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal definition:","bold":true},{"text":" money is what the law says it is."}]},{"text":[{"text":"Functional definition:","bold":true},{"text":" money is measured by aggregates "},{"text":"M1, M2, M3","bold":true},{"text":" set by each central bank (Lesson 2.5)."}]},{"text":[{"text":"Hicks (1967):","bold":true},{"text":" \"money is defined by its functions; anything is money which is used as money; "},{"text":"money is what money does","bold":true},{"text":".\""}]},{"text":[{"text":"Numismatics:","bold":true},{"text":" the study of money, especially coins and paper currency."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A law declaring something legal tender does not on its own make it money; people must actually accept it."}]},{"text":[{"text":"Without money, the "},{"text":"price mechanism","bold":true},{"text":" and the "},{"text":"resource allocation system","bold":true},{"text":" would both be inoperative: in a market economy, money prices signal where resources should move and who gets what."}]},{"text":[{"text":"Money promotes "},{"text":"specialisation and division of labour","bold":true},{"text":", removes the need for a double coincidence of$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 9, $study_guide$ wants, and encourages "},{"text":"savings and investment","bold":true},{"text":". It does the opposite of forcing each household to produce all it needs."}]}]}]},{"number":"2.3","title":"Functions and characteristics of money","mustKnow":[{"type":"paragraph","text":[{"text":"Functions of money","bold":true},{"text":" (Jevons, 1875, gave four; a fifth is often added):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Medium of exchange:","bold":true},{"text":" the intermediary in trade; removes the double coincidence of wants. The most fundamental function."}]},{"text":[{"text":"Unit of account (measure of value, standard of value, common denominator of value):","bold":true},{"text":" all prices expressed in one unit (the naira), so for each good you know how many units of money it costs, as the metre measures distance."}]},{"text":[{"text":"Store of value (store of wealth):","bold":true},{"text":" holding purchasing power for future use, e.g. saving for old age or a \"rainy day\"."}]},{"text":[{"text":"Standard of deferred payment:","bold":true},{"text":" debts contracted now and settled in money later (loans, bonds, credit sales)."}]},{"text":[{"text":"Transfer of value:","bold":true},{"text":" moving value from person to person and place to place."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary functions:","bold":true},{"text":" medium of exchange and measure of value (unit of account). "},{"text":"Secondary:","bold":true},{"text":" store of value and standard of deferred payment."}]},{"text":[{"text":"Not functions:","bold":true},{"text":" settling disputes, creating employment, earning interest, keeping prices constant at all times."}]}]},{"type":"paragraph","text":[{"text":"Characteristics (qualities) of good money (8):","bold":true}]},{"type":"table","header":[[{"text":"Quality"}],[{"text":"Meaning"}]],"rows":[[[{"text":"General acceptability"}],[{"text":"Accepted by all, by custom or by law. "},{"text":"The most important","bold":true},{"text":"; the one quality near money lacks"}]],[[{"text":"Scarcity"}],[{"text":"Relatively scarce, not as abundant as sand, but not too rare"}]],[[{"text":"Durability"}],[{"text":"Lasts through repeated use; needed for store of value"}]],[[{"text":"Homogeneity (uniformity)"}],[{"text":"Every unit identical: ₦1 in Abuja = ₦1 in Ibadan"}]],[[{"text":"Divisibility"}],[{"text":"Divisible into small units so transactions of any size can be made (₦1 = 100 kobo)"}]],[[{"text":"Portability"}],[{"text":"Easy to carry about"}]],[[{"text":"Recognisability (cognisability)"}],[{"text":"Recognised as genuine at once, without technical aid"}]],[[{"text":"Stability"}],[{"text":"Stable in value over time"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the example to the function. Prices of goods quoted in naira = "},{"text":"unit of account","bold":true},{"text":". Repaying a loan in fixed naira over five years, borrowing ₦500,000 now to repay ₦550,000 in two years, buying now and paying in three months, or a bond paying naira interest and principal at set dates = "},{"text":"standard of deferred payment","bold":true},{"text":". Saving for old age = "},{"text":"store of value","bold":true},{"text":". Emeka in Lagos sending ₦30,000 monthly to his parents in Kano = "},{"text":"transfer of value","bold":true},{"text":"."}]},{"text":[{"text":"To serve as a "},{"text":"store of value and standard of deferred payment","bold":true},{"text":", money must be "},{"text":"stable in value","bold":true},{"text":". Money is a poor store of value during "},{"text":"inflation","bold":true},{"text":". "},{"text":"Inflation","bold":true},{"text":" = a persistent rise in the general price level over a period; "},{"text":"deflation","bold":true},{"text":" = a persistent fall; "},{"text":"stagflation","bold":true},{"text":" = inflation with stagnant output and high unemployment."}]},{"text":[{"text":"\"Measure of value\" is a function, not a quality. \"Durable money\" is not a type of money. \"Abundance\" is not a quality (money must be scarce)."}]},{"text":[{"text":"Money with legal tender status is "},{"text":"legal money","bold":true},{"text":"; money accepted only by custom is "},{"text":"customary money","bold":true},{"text":"."}]}]}]},{"number":"2.4","title":"Types of money and how money evolved","mustKnow":[{"type":"paragraph","text":[{"text":"Order of evolution:","bold":true},{"text":" barter → commodity money → metallic money (coins) → paper money → bank deposit money → electronic and digital money."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Commodity money:","bold":true},{"text":" has intrinsic value of its own apart from its use as money (cowries, salt, cattle, grain, gold, tobacco). It may be used "},{"text":"without a distinguishing mark","bold":true},{"text":" or "},{"text":"with a design or symbol","bold":true},{"text":" (minted coins). Commodity money has largely gone out of use."}]},{"text":[{"text":"Standard (full-bodied) money:","bold":true},{"text":" money whose intrinsic (metal) value "},{"text":"equals","bold":true},{"text":" its face value."}]},{"text":[{"text":"Token money:","bold":true},{"text":" has no commodity value; its value comes entirely from being generally acceptable (paper money, bank deposits). Includes:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Representative (convertible) token money:","bold":true},{"text":" paper money convertible into a commodity such as gold "},{"text":"on demand","bold":true},{"text":"."}]},{"text":[{"text":"Inconvertible token money (fiduciary issue):","bold":true},{"text":" not backed by gold or any commodity; its supply is limited only by "},{"text":"law","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Fiduciary issue:","bold":true},{"text":" bank notes not backed by gold but by government securities. "},{"text":"Fiduciary money","bold":true},{"text":" is accepted because of "},{"text":"trust"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 10, $study_guide$,"bold":true},{"text":" in the issuer."}]},{"text":[{"text":"Fiat money:","bold":true},{"text":" money declared "},{"text":"legal tender","bold":true},{"text":" by government decree; no intrinsic value, not backed by a commodity. \"Fiat\" is Latin for "},{"text":"\"let it be done\"","bold":true},{"text":". Today's naira is fiat money."}]},{"text":[{"text":"Legal tender:","bold":true},{"text":" money that the law says must be accepted in settlement of debts. In Nigeria: "},{"text":"naira notes and coins issued by the CBN","bold":true},{"text":". Cheques, postal orders and treasury bills are not legal tender."}]},{"text":[{"text":"Bank deposit money:","bold":true},{"text":" deposits withdrawable by cheque or transfer. A cheque is not money itself; it transfers the deposit, which is money."}]}]},{"type":"paragraph","text":[{"text":"Limitations of commodity money (5):","bold":true},{"text":" perishability; "},{"text":"variability in quality","bold":true},{"text":" (two cows of one breed, one fat, one thin); transport difficulty; "},{"text":"supply fluctuations","bold":true},{"text":" (a bumper grain harvest crashes grain's value); difficulty in making small transactions."}]},{"type":"paragraph","text":[{"text":"Why gold and silver were preferred (7):","bold":true},{"text":" durability (no rust or decay), uniformity, divisibility, portability (high value for weight), scarcity, intrinsic value, universal acceptability."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lydia","bold":true},{"text":" (Asia Minor, modern Turkey) minted the first standardised coins about 600 BC from "},{"text":"electrum","bold":true},{"text":", a natural alloy of gold and silver. Before coins, Rome used "},{"text":"aes rude","italic":true},{"text":" (rough bronze), then "},{"text":"aes signatum","italic":true},{"text":" (marked bars)."}]},{"text":[{"text":"Debasement:","bold":true},{"text":" a ruler cuts the gold or silver content of coins (e.g. mixing in copper) but keeps the face value, earning a profit called "},{"text":"seigniorage","bold":true},{"text":". Results: inflation, loss of public trust, rejection of debased coins for full-value or foreign coins. It "},{"text":"lowers","bold":true},{"text":", never raises, each coin's purchasing power."}]},{"text":[{"text":"Worked example: a ruler holds 60 kg of silver. Full coins hold 25 g. 60 kg = 60,000 g. Full coins: 60,000 / 25 = 2,400. Debased to 20 g: 60,000 / 20 = 3,000. Extra coins = 3,000 − 2,400 = "},{"text":"600","bold":true},{"text":". (Same method: 120 kg at 20 g gives 6,000 coins; at 15 g gives 8,000; so 2,000 more.)"}]},{"text":[{"text":"Paper money:","bold":true},{"text":" began in China (Tang dynasty, about 807 AD; Song dynasty "},{"text":"jiaozi","italic":true},{"text":"). Europe's first banknotes: Stockholms Banco, 1661; Bank of England founded 1694. Early problems: "},{"text":"counterfeiting","bold":true},{"text":" (answered with watermarks, intricate designs, special paper, several signatures), trust, overissue, wear."}]},{"text":[{"text":"Goldsmiths (17th-century England):","bold":true},{"text":" their receipts for gold deposited circulated as "},{"text":"goldsmiths' notes","bold":true},{"text":", forerunners of bank notes. Since depositors did not all collect at once, they issued notes worth more than the gold held: the start of "},{"text":"fractional reserve banking","bold":true},{"text":". Early notes had to be "},{"text":"convertible","bold":true},{"text":" because people accepted them only believing they could get gold or silver on demand. The "},{"text":"Bank Charter Act 1844","bold":true},{"text":" let the Bank of England make a fiduciary issue of £14 million."}]},{"text":[{"text":"Gold standard:","bold":true},{"text":" currencies defined as a fixed weight of gold; notes exchangeable for gold; fixed exchange rates; money supply limited by gold reserves (no free expansion). The link ended in "},{"text":"1971","bold":true},{"text":" when the USA suspended convertibility of the dollar into gold."}]},{"text":[{"text":"Electronic money:","bold":true},{"text":" cards, online banking, mobile money such as "},{"text":"M-Pesa","bold":true},{"text":" in Kenya (promotes "},{"text":"financial inclusion","bold":true},{"text":" of the unbanked)."}]},{"text":[{"text":"Cryptocurrency (e.g. Bitcoin, 2009):","bold":true},{"text":" decentralised digital currency on "},{"text":"blockchain","bold":true},{"text":", not issued or controlled by any government or central bank; very volatile; "},{"text":"not legal tender","bold":true},{"text":"."}]},{"text":[{"text":"CBDC:","bold":true},{"text":" electronic central bank money for payments and storing value; legal tender. Nigeria's "},{"text":"eNaira","bold":true},{"text":" was launched on "},{"text":"25 October 2021","bold":true},{"text":", the first CBDC in Africa (the world's first nationwide CBDC was the Bahamas' Sand Dollar, 2020). It has the "},{"text":"same value as the cash naira","bold":true},{"text":" (1:1), "},{"text":"complements, not replaces","bold":true},{"text":", cash, is open to people without bank accounts, and pays "},{"text":"no interest","bold":true},{"text":". Expected benefits: lower cost of printing and handling cash, financial inclusion, better monetary policy data, safer payments, cheaper cross-border trade. Uptake has been low; the CBN now positions it more as payments infrastructure."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"CBDC (eNaira)"}],[{"text":"Cryptocurrency"}]],"rows":[[[{"text":"Issuer"}],[{"text":"Central bank"}],[{"text":"Users / private network"}]],[[{"text":"Legal tender"}],[{"text":"Yes"}],[{"text":"No"}]],[[{"text":"Volatility"}],[{"text":"Low"}],[{"text":"High"}]],[[{"text":"Backing"}],[{"text":"State-backed by law"}],[{"text":"Not backed by law"}]]]}]},{"number":"2.5","title":"The money stock, near money and the value of money","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money supply (money stock,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 11, $study_guide$ stock of money):","bold":true},{"text":" the total stock of money held by the public in an economy at a point in time: currency (notes and coins) held by the public "},{"text":"plus","bold":true},{"text":" bank deposits."}]},{"text":[{"text":"Demand (sight) deposits:","bold":true},{"text":" current account, withdrawable on demand by cheque. "},{"text":"Time deposits:","bold":true},{"text":" fixed period; "},{"text":"savings deposits:","bold":true},{"text":" withdrawal conditions; both earn interest."}]},{"text":[{"text":"Quasi-money (near money) in Nigeria's aggregates:","bold":true},{"text":" time deposits + savings deposits held by the public with banks."}]}]},{"type":"paragraph","text":[{"text":"Formulas (Nigeria):","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"M1 (narrow money) = currency outside banks + demand deposits"}]},{"text":[{"text":"QM (quasi-money) = savings deposits + time deposits"}]},{"text":[{"text":"M2 (broad money) = M1 + QM = currency + demand + savings + time deposits"}]},{"text":[{"text":"M3 = M2 + deposits with non-bank financial institutions (NBFIs)"}]},{"text":[{"text":"Near money (quasi-money):","bold":true},{"text":" financial assets that can be converted into cash quickly with little or no loss, but are "},{"text":"not generally accepted as a medium of exchange","bold":true},{"text":". They store value but must first be converted before spending. Examples: "},{"text":"treasury bills","bold":true},{"text":", treasury certificates, time and savings (fixed) deposits, bills of exchange, bonds, debentures, insurance policies, postal orders, stocks and shares."}]},{"text":[{"text":"Demand deposits on current account are money (part of M1), not near money.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Money vs near money (6 differences):","bold":true}]},{"type":"table","header":[[{"text":"Basis"}],[{"text":"Money"}],[{"text":"Near money"}]],"rows":[[[{"text":"Legality"}],[{"text":"Legal tender"}],[{"text":"No legal tender status"}]],[[{"text":"Liquidity"}],[{"text":"Spent directly"}],[{"text":"Must be converted first"}]],[[{"text":"Acceptability"}],[{"text":"Generally accepted"}],[{"text":"Not generally accepted"}]],[[{"text":"Yield"}],[{"text":"Cash earns no yield"}],[{"text":"Earns a yield"}]],[[{"text":"Conversion"}],[{"text":"None needed"}],[{"text":"Short delay and some cost"}]],[[{"text":"Safety"}],[{"text":"Cash can be lost or stolen"}],[{"text":"Safer, so often preferred"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Value of money:","bold":true},{"text":" its "},{"text":"purchasing power","bold":true},{"text":", the quantity of goods and services a given amount of money can buy. It varies "},{"text":"inversely","bold":true},{"text":" with the general price level and is measured with a "},{"text":"price index","bold":true},{"text":" (index number method)."}]},{"text":[{"text":"Value of money = 1 / P. New value as % of old = (old price index / new price index) × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (M aggregates):","bold":true},{"text":" currency ₦600bn, demand deposits ₦1,400bn, savings and time ₦1,100bn. M1 = 600 + 1,400 = "},{"text":"₦2,000bn","bold":true},{"text":" (savings and time are left out of M1)."}]},{"text":[{"text":"Worked example (table, ₦ billion):","bold":true}],"blocks":[{"type":"table","header":[[{"text":"Year"}],[{"text":"Currency"}],[{"text":"Demand"}],[{"text":"Savings"}],[{"text":"Time"}],[{"text":"M1"}],[{"text":"QM"}],[{"text":"M2"}]],"rows":[[[{"text":"2007"}],[{"text":"500"}],[{"text":"1,000"}],[{"text":"780"}],[{"text":"680"}],[{"text":"1,500"}],[{"text":"1,460"}],[{"text":"2,960"}]],[[{"text":"2008"}],[{"text":"750"}],[{"text":"1,550"}],[{"text":"950"}],[{"text":"800"}],[{"text":"2,300"}],[{"text":"1,750"}],[{"text":"4,050"}]],[[{"text":"2009"}],[{"text":"1,000"}],[{"text":"2,000"}],[{"text":"1,450"}],[{"text":"1,250"}],[{"text":"3,000"}],[{"text":"2,700"}],[{"text":"5,700"}]],[[{"text":"2010"}],[{"text":"1,125"}],[{"text":"2,500"}],[{"text":"1,800"}],[{"text":"1,600"}],[{"text":"3,625"}],[{"text":"3,400"}],[{"text":"7,025"}]],[[{"text":"2011"}],[{"text":"1,125"}],[{"text":"2,500"}],[{"text":"1,800"}],[{"text":"1,600"}],[{"text":"3,625"}],[{"text":"3,400"}],[{"text":"7,025"}]]]},{"type":"paragraph","text":[{"text":"Check 2010 M2: 1,125 + 2,500 + 1,800 + 1,600 = ₦7,025bn."}]}]},{"text":[{"text":"Worked example (M1, M2, M3):","bold":true},{"text":" currency 80, demand 320, savings 300, time 50, NBFI deposits 400 (₦bn). M1 = 80 + 320 = 400. M2 = 400 + 300 + 50 = 750. M3 = 750 + 400 = "},{"text":"₦1,150bn","bold":true},{"text":". Another year: currency 150, demand 400 gives M1 = "},{"text":"₦550bn","bold":true},{"text":"; currency 100, demand 300, savings 280, time 80 gives M2 = "},{"text":"₦760bn","bold":true},{"text":"."}]},{"text":[{"text":"Friedman's M2 = currency + demand + time deposits; the broadest M3 is linked with "},{"text":"Gurley and Shaw","bold":true},{"text":". M1 shows the medium of exchange role; M2 and M3 add store of value."}]},{"text":[{"text":"Each component of the money stock is money "},{"text":"to the extent that it performs some of the functions of money","bold":true},{"text":". Currency and demand deposits (M1) are the most liquid and most generally accepted, so they are \"most qualified\" to be called money (M1 is sometimes called high-powered money; strictly, high-powered money is currency plus banks' reserves with the central bank)."}]},{"text":[{"text":"A "},{"text":"falling share of cash","bold":true},{"text":" in the money stock shows more public confidence in banks "},{"text":"and","bold":true},{"text":" a more sophisticated financial system (in Nigeria's early-1990s bank distress the cash share rose)."}]},{"text":[{"text":"Worked example (value of money, one index):","bold":true},{"text":" price index rises from 100 to 250. New value = 100 / 250 × 100 = "},{"text":"40%","bold":true},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 12, $study_guide$xt":" of the old value (a 60% fall)."}]},{"text":[{"text":"Worked example (weighted basket):","bold":true},{"text":" weights gari 0.3, yam 0.3, rice 0.4 (weights sum to 1). First-year prices ₦500, ₦800, ₦1,000: P1 = 0.3×500 + 0.3×800 + 0.4×1,000 = 150 + 240 + 400 = 790. Second-year prices ₦700, ₦1,000, ₦1,300: P2 = 210 + 300 + 520 = 1,030. Value = 790 / 1,030 × 100 = "},{"text":"76.70%","bold":true},{"text":" (to 2 d.p.) of its first-year value. This assumes the income shares stay fixed."}]},{"text":[{"text":"Velocity of money","bold":true},{"text":" = times a unit of money changes hands in a period (Fisher: "},{"text":"MV = PQ","bold":true},{"text":"). Demand for money: Cambridge "},{"text":"Md = kPY","bold":true},{"text":"; Keynes's three motives (transactions, precautionary, speculative); Friedman's modern quantity theory."}]}]}]},{"number":"2.6","title":"Credit creation and the supply of money","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit creation:","bold":true},{"text":" banks create money (deposits) by granting loans and overdrafts from deposits, keeping only a fraction as reserves (fractional reserve banking)."}]},{"text":[{"text":"Assumptions:","bold":true},{"text":" a primary cash deposit starts it; a legal fraction is kept as reserve; the rest (excess reserve) is lent; loans are redeposited in the same or another bank; no cash drain."}]},{"text":[{"text":"Formulas:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit (money) multiplier k = 1 / r, where r = cash reserve ratio"}]},{"text":[{"text":"Total deposits created = initial deposit / r = initial deposit × k"}]},{"text":[{"text":"Credit creation multiplier = total deposits created / original deposit"}]},{"text":[{"text":"Total loans = total deposits − initial deposit"}]}]}]},{"text":[{"text":"The "},{"text":"higher","bold":true},{"text":" the reserve ratio, the "},{"text":"lower","bold":true},{"text":" the multiplier and the credit created."}]}]},{"type":"paragraph","text":[{"text":"Limitations to credit creation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Size of the legal "},{"text":"cash reserve ratio","bold":true},{"text":"."}]},{"text":[{"text":"Amount of the initial cash deposit (level of cash reserves)."}]},{"text":[{"text":"Leakages","bold":true},{"text":": cash kept outside banks (\"under the pillow\")."}]},{"text":[{"text":"Fear of "},{"text":"cash drain","bold":true},{"text":" to other banks."}]},{"text":[{"text":"Lack of acceptable "},{"text":"collateral security","bold":true},{"text":"."}]},{"text":[{"text":"Actions of the monetary authorities."}]}]},{"type":"paragraph","text":[{"text":"Determinants of money supply:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Exogenous","bold":true},{"text":" (set by the central bank): the "},{"text":"minimum cash reserve ratio","bold":true},{"text":", the level of bank reserves (open market operations)."}]},{"text":[{"text":"Endogenous","bold":true},{"text":" (from the economy): the public's desire to hold cash rather than deposits, business activity, demand for loans, interest rates."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (10% ratio):","bold":true},{"text":" ₦1,000 deposited."}],"blocks":[{"type":"table","header":[[{"text":"Round"}],[{"text":"Deposit (₦)"}],[{"text":"Reserve 10% (₦)"}],[{"text":"Loan 90% (₦)"}]],"rows":[[[{"text":"Original"}],[{"text":"1,000"}],[{"text":"100"}],[{"text":"900"}]],[[{"text":"1st redeposit"}],[{"text":"900"}],[{"text":"90"}],[{"text":"810"}]],[[{"text":"2nd redeposit"}],[{"text":"810"}],[{"text":"81"}],[{"text":"729"}]],[[{"text":"All banks"}],[{"text":"10,000"}],[{"text":"1,000"}],[{"text":"9,000"}]]]},{"type":"paragraph","text":[{"text":"k = 1 / 0.10 = 10; total deposits = 1,000 × 10 = ₦10,000; loans = 10,000 − 1,000 = ₦9,000."}]}]},{"text":[{"text":"At 20%: ₦2,000 / 0.20 = "},{"text":"₦10,000","bold":true},{"text":". At 12.5%: k = 1 / 0.125 = "},{"text":"8","bold":true},{"text":". At 25%: ₦1,000m × 4 = ₦4,000m. At 40%: k = 2.5, so ₦1,000m gives ₦2,500m."}]},{"text":[{"text":"Leakage: if the public also keeps cash equal to 10% of deposits with r = 10%, the deposit multiplier falls to 1 / (0.10 + 0.10) = 5."}]},{"text":[{"text":"More cash deposited by the public "},{"text":"expands","bold":true},{"text":", never limits, credit creation."}]},{"text":[{"text":"Raises money supply:","bold":true},{"text":" a cut in the cash reserve ratio; CBN buying securities. "},{"text":"Reduces it:","bold":true},{"text":" a rise in the reserve ratio; CBN "},{"text":"selling","bold":true},{"text":" treasury bills to banks in open market operations; a greater public preference for cash."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Barter = goods for goods; main problem: double coincidence of wants; extra costs: waiting and storage; n goods need n(n − 1)/2 relative prices."}]},{"text":[{"text":"Money = anything generally acceptable in payment. Friedman: temporary abode of purchasing power. Hicks: money is what money does."}]},{"text":[{"text":"Functions: medium of exchange and unit of account (primary); store of value, deferred payment (secondary); transfer of value."}]},{"text":[{"text":"Qualities: acceptability (most important), scarcity, durability, homogeneity, divisibility, portability, recognisability, stability."}]},{"text":[{"text":"Evolution: barter → commodity → coins → paper → deposits → electronic. Fiat = \"let it be done\"; gold link ended 1971; eNaira launched 25 October 2021."}]},{"text":[{"text":"M1 = currency + demand deposits; M2 = M1 + savings + time; M3 = M2 + NBFI deposits."}]},{"text":[{"text":"Value of money = purchasing power, inverse to the price level, measured by a price index."}]},{"text":[{"text":"Credit multiplier k = 1/r; total deposits = initial deposit / r."}]}]}],"theory":{"itemId":"e3c86c07-6a9b-5074-9b35-8a1$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 13, $study_guide$44da2c912","question":[{"type":"paragraph","text":[{"text":"An economy's banks create total deposits of ₦500 million from an initial deposit of ₦50 million. (a) Find the money multiplier and the reserve ratio. (b) The reserve requirement is then raised by 100% and the initial deposit by 40%. Find the new total deposits."}]}]},"practice":[{"topic":"The Development of Money","named":false}]}},{"kind":"note","itemId":"f270c43a-54d7-59dd-850f-77a22d2f7bdd","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Historical Development of Banking in Nigeria","body":"The colonial (expatriate) banks and the West African Currency Board; the indigenous banks, the boom and doom and why they failed; Paton, the 1952 Ordinance, the 1958 law, the CBN and the 1969 Decree; indigenisation, development banks and merchant banks; SAP, distress and its cures; the 2004-2005 consolidation, the 2009 crisis, AMCON, universal banking and the current (2024-2026) recapitalisation.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The colonial (expatriate) banks and the West African Currency Board; the indigenous banks, the boom and doom and why they failed; Paton, the 1952 Ordinance, the 1958 law, the CBN and the 1969 Decree; indigenisation, development banks and merchant banks; SAP, distress and its cures; the 2004-2005 consolidation, the 2009 crisis, AMCON, universal banking and the current (2024-2026) recapitalisation."}],"lessons":[{"number":"3.1","title":"The colonial banks and the West African Currency Board","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First bank:","bold":true},{"text":" the "},{"text":"African Banking Corporation (ABC), 1892","bold":true},{"text":", Lagos. It distributed British (Bank of England) currency. It marked the start of commercial banking in Nigeria."}]},{"text":[{"text":"Bank of British West Africa (BBWA), 1894:","bold":true},{"text":" took over ABC's Lagos business in 1894; first surviving bank; near-monopoly for over 30 years; banker to the colonial government. Today "},{"text":"First Bank of Nigeria","bold":true},{"text":" (name from 1979)."}]},{"text":[{"text":"Colonial Bank","bold":true},{"text":" (1916/1917) merged with Barclays, the Anglo-Egyptian Bank and the National Bank of South Africa to form "},{"text":"Barclays Bank DCO","bold":true},{"text":" (1925). Today "},{"text":"Union Bank of Nigeria","bold":true},{"text":"."}]},{"text":[{"text":"British and French Bank (for Commerce and Industry), 1949.","bold":true},{"text":" Today "},{"text":"United Bank for Africa (UBA)","bold":true},{"text":"."}]},{"text":[{"text":"These "},{"text":"three expatriate banks","bold":true},{"text":" (BBWA, Barclays DCO, British and French) dominated banking before independence. They are called the "},{"text":"first-generation banks","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Old name"}],[{"text":"Present name"}]],"rows":[[[{"text":"Bank of British West Africa (later Standard Bank)"}],[{"text":"First Bank"}]],[[{"text":"Colonial Bank / Barclays DCO"}],[{"text":"Union Bank"}]],[[{"text":"British and French Bank"}],[{"text":"UBA"}]],[[{"text":"Agbonmagbe Bank"}],[{"text":"Wema Bank"}]],[[{"text":"International Bank for West Africa"}],[{"text":"Afribank (later Mainstreet, now part of Polaris)"}]]]},{"type":"paragraph","text":[{"text":"Characteristics of the colonial banks:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Foreign-owned and managed; "},{"text":"registered, headquartered and controlled from London","bold":true},{"text":", so they fell under "},{"text":"London's","bold":true},{"text":" regulatory jurisdiction."}]},{"text":[{"text":"Served colonial government and "},{"text":"British/foreign trade","bold":true},{"text":" (palm oil, cocoa, groundnuts)."}]},{"text":[{"text":"Discriminatory lending:","bold":true},{"text":" they took African deposits but refused Africans credit."}]},{"text":[{"text":"Conservative lending with heavy collateral."}]},{"text":[{"text":"Branches only in "},{"text":"cities and coastal towns","bold":true},{"text":" where British trade was, not rural credit for peasant farmers."}]}]},{"type":"paragraph","text":[{"text":"West African Currency Board (WACB), 1912:","bold":true},{"text":" issued and distributed currency in the British West African colonies before central banks. The "},{"text":"West African pound","bold":true},{"text":" was fixed at par with sterling and "},{"text":"100% backed by sterling","bold":true},{"text":" reserves. "},{"text":"BBWA was its agent","bold":true},{"text":" for custody and distribution of the currency."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages:","bold":true},{"text":" unified currency accepted by the people; relieved government of currency management; no inflation or foreign exchange crisis; eased acceptance of new currencies at independence."}]},{"text":[{"text":"Criticisms:","bold":true},{"text":" (1) money supply was "},{"text":"tied to the balance of trade","bold":true},{"text":" (export earnings); (2) "},{"text":"no independence or discretion","bold":true},{"text":" for Nigeria's own monetary policy; (3) "},{"text":"hindered the growth of Nigeria's own financial system","bold":true},{"text":" (reserves invested abroad, no local investment); (4) failed to "},{"text":"train Africans","bold":true},{"text":" in monetary management; (5) one currency for colonies gaining independence at different dates."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Convertibility into sterling was a "},{"text":"feature","bold":true},{"text":" of the WACB system, not one of the criticisms listed against it."}]},{"text":[{"text":"Trap: in some older questions ABC is dated 1882. The correct year is "},{"text":"1892","bold":true},{"text":"; choose the \"1892, African Banking Corporation\" option."}]},{"text":[{"text":"The 1940 Lagos trader whose loan is refused while a British firm gets credit illu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 14, $study_guide$strates "},{"text":"discriminatory lending by the expatriate banks","bold":true},{"text":", not any later CBN rule."}]}]}]},{"number":"3.2","title":"Indigenous banks, the boom and the doom (free banking era)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Free (laissez-faire) banking era (about 1891-1951):","bold":true},{"text":" anyone could open a bank with "},{"text":"no licence, no minimum capital and no regulation","bold":true},{"text":". It ended in 1952."}]},{"text":[{"text":"Why indigenous banks emerged (2 reasons):","bold":true},{"text":" (1) the "},{"text":"expansion of African businessmen","bold":true},{"text":"; (2) the "},{"text":"discriminatory lending of the expatriate banks","bold":true},{"text":". Nationalism added fuel."}]},{"text":[{"text":"Early indigenous banks:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Industrial and Commercial Bank, 1929","bold":true},{"text":": the first indigenous bank; failed in 1930."}]},{"text":[{"text":"Nigerian Mercantile Bank, 1931","bold":true},{"text":": failed."}]},{"text":[{"text":"National Bank of Nigeria, 1933","bold":true},{"text":": first successful indigenous bank."}]},{"text":[{"text":"Agbonmagbe Bank, 1945","bold":true},{"text":" (founded by Okupe): today "},{"text":"Wema Bank","bold":true},{"text":"."}]},{"text":[{"text":"African Continental Bank (ACB), 1947","bold":true},{"text":": associated with Dr Nnamdi Azikiwe."}]}]}]},{"text":[{"text":"Banking boom and banking doom (1945-1955):","bold":true},{"text":" many banks registered (about 145 banking companies in 1947 by one count), then most collapsed. By end-1954 "},{"text":"only three","bold":true},{"text":" indigenous banks survived: "},{"text":"National Bank, ACB and Agbonmagbe","bold":true},{"text":", all rescued by their "},{"text":"regional governments","bold":true},{"text":". Afribank was "},{"text":"not","bold":true},{"text":" one of them."}]}]},{"type":"paragraph","text":[{"text":"Causes of the collapse (learn the list):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inadequate capital (undercapitalisation, weak capital base)."}]},{"text":[{"text":"Untrained, inexperienced staff and bad management."}]},{"text":[{"text":"Fraud and stealing; insider abuse."}]},{"text":[{"text":"Indiscriminate branch expansion (over-expansion)."}]},{"text":[{"text":"Crude accounting and poor record keeping."}]},{"text":[{"text":"No regulatory framework","bold":true},{"text":" or supervisor."}]},{"text":[{"text":"Competition from the stronger foreign banks and the discriminating attitude of the colonial authorities."}]},{"text":[{"text":"Lack of government patronage; political and ethnic ties."}]},{"text":[{"text":"The 1952 Ordinance's capital rules, which many could not meet."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"NOT a cause\" traps: "},{"text":"excessive CBN regulation","bold":true},{"text":" or "},{"text":"strict CBN cash reserve rules","bold":true},{"text":" (the CBN did not exist yet); "},{"text":"holding too much capital","bold":true},{"text":"; "},{"text":"foreign merchants' patronage and encouragement","bold":true},{"text":"; margin loans to stockbrokers or failing ₦25 billion (those are 2000s events). In \"EXCEPT\" items where every option (poor management, aggressive competition, no regulator) is a real cause, choose "},{"text":"none of the above","bold":true},{"text":"."}]},{"text":[{"text":"\"All of the above\" is right when the options are weak capital, untrained managers and fraud."}]}]}]},{"number":"3.3","title":"Regulation begins: Paton, 1952, the CBN and the 1969 Decree","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paton Commission (1948):","bold":true},{"text":" led by "},{"text":"G. D. Paton","bold":true},{"text":"; enquired into banking business in Nigeria and "},{"text":"recommended the form and extent of control","bold":true},{"text":" to introduce."}]},{"text":[{"text":"Banking Ordinance 1952:","bold":true},{"text":" Nigeria's "},{"text":"first banking law","bold":true},{"text":", based on the Paton Report, passed because of the "},{"text":"widespread failure of indigenous banks","bold":true},{"text":" in the free banking era. Provisions:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"licence","bold":true},{"text":" (from the Financial Secretary) before banking business."}]},{"text":[{"text":"Minimum paid-up capital","bold":true},{"text":": £12,500 (₦25,000) for banks incorporated in Nigeria; £100,000 (₦200,000) for banks incorporated abroad, so "},{"text":"lower for Nigerian banks","bold":true},{"text":"."}]},{"text":[{"text":"Reserve fund","bold":true},{"text":" from profits."}]},{"text":[{"text":"Examination","bold":true},{"text":" of banks and periodic returns."}]},{"text":[{"text":"Assistance to indigenous banks; "},{"text":"3-year grace period","bold":true},{"text":" to comply."}]}]}]},{"text":[{"text":"It did "},{"text":"not","bold":true},{"text":" create deposit insurance (NDIC came in 1988). Its lasting significance: it "},{"text":"ended free banking and set up the principle of government regulation","bold":true},{"text":"."}]},{"text":[{"text":"After 1952 many more banks failed","bold":true},{"text":" because (all of these): they could not meet the minimum capital; there was "},{"text":"no supervisory agency","bold":true},{"text":" to give direction; they lacked government patronage."}]},{"text":[{"text":"1958 law","bold":true},{"text":" (Banking Ordinance/Act 1958, with the CBN Act): expatriate capital raised to ₦400,000; indigenous unchanged at ₦25,000; licensing power passed to the Minister of Finance after consulting the CBN."}]},{"text":[{"text":"Road to the CBN:","bold":true},{"text":" Mbadiwe's motion (1952); "},{"text":"Fisher Report (1953)","bold":true},{"text":" said it was too early; IBRD mission (1953); "},{"text":"J. B. Loynes report$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 15, $study_guide$ (1957)","bold":true},{"text":" favoured a central bank. "},{"text":"CBN Act 1958","bold":true},{"text":"; operations began "},{"text":"1 July 1959","bold":true},{"text":"."}]},{"text":[{"text":"First Governor:","bold":true},{"text":" "},{"text":"Roy Pentelow Fenton","bold":true},{"text":" (British, 1958-1963). First Nigerian Governor: "},{"text":"Aliyu Mai-Bornu","bold":true},{"text":" (1963-1967). Current Governor (2026): "},{"text":"Olayemi Cardoso","bold":true},{"text":" (since September 2023)."}]},{"text":[{"text":"Early CBN steps:","bold":true},{"text":" own currency (1959); "},{"text":"treasury bills (April 1960)","bold":true},{"text":", which began the money market; "},{"text":"Lagos Bankers' Clearing House (1961)","bold":true},{"text":" to settle cheques drawn on one bank and paid into another; support for the Lagos Stock Exchange (1961)."}]},{"text":[{"text":"Significance:","bold":true},{"text":" Nigeria gained "},{"text":"control of its own currency and monetary policy","bold":true},{"text":"."}]},{"text":[{"text":"Banking Decree 1969:","bold":true},{"text":" "},{"text":"more comprehensive","bold":true},{"text":"; added to the CBN's control tools; extended monetary control to "},{"text":"most banking institutions other than commercial banks","bold":true},{"text":". Minimum paid-up capital "},{"text":"₦600,000 indigenous, ₦1.5 million expatriate","bold":true},{"text":". Repealed by "},{"text":"BOFID No. 25 of 1991","bold":true},{"text":" (with CBN Decree No. 24 of 1991)."}]}]},{"type":"paragraph","text":[{"text":"Regulatory milestones in order:","bold":true},{"text":" free banking (to 1951) · Banking Ordinance 1952 · CBN Act 1958 · Banking Decree 1969 · NDIC Decree 1988 · BOFID 1991 · Failed Banks Decree 1994 · CBN Act 2007 · BOFIA 2020 (current)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1952 versus 1969: the 1952 Ordinance ended free banking under colonial rule; the 1969 Decree gave the CBN a much wider range of controls."}]},{"text":[{"text":"You may also see the 1952 requirement quoted as ₦50,000 authorised capital. Either way, the point is that many small banks could not meet it."}]},{"text":[{"text":"A tiny Lagos bank closing in 1953 within the grace period is a victim of the "},{"text":"1952 licensing and minimum capital rules","bold":true},{"text":"."}]}]}]},{"number":"3.4","title":"After independence: indigenisation, development and merchant banks","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Indigenisation:","bold":true},{"text":" transferring ownership and control of enterprises, banks included, "},{"text":"from foreigners to Nigerians","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian Enterprises Promotion (Indigenisation) Decree 1972:","bold":true},{"text":" the Federal Government took "},{"text":"40%","bold":true},{"text":" in the "},{"text":"three largest foreign banks","bold":true},{"text":" (First, Union, UBA). The 1976-1977 amendments raised it: banking had to be "},{"text":"at least 60% Nigerian-owned","bold":true},{"text":"."}]},{"text":[{"text":"Outcomes:","bold":true},{"text":" Nigerians moved into "},{"text":"top management and directorships","bold":true},{"text":"; banking skills grew; new indigenous and state-owned banks were set up."}]},{"text":[{"text":"Development finance institutions:","bold":true}]}]},{"type":"table","header":[[{"text":"Institution"}],[{"text":"Purpose"}]],"rows":[[[{"text":"Nigerian Industrial Development Bank (NIDB)"}],[{"text":"long-term finance for industrial projects"}]],[[{"text":"Nigerian Bank for Commerce and Industry (NBCI)"}],[{"text":"lending to Nigerian businessmen, including to buy shares in foreign firms"}]],[[{"text":"Nigerian Agricultural and Cooperative Bank (NACB)"}],[{"text":"agriculture and rural cooperatives"}]],[[{"text":"Federal Mortgage Bank of Nigeria"}],[{"text":"long-term housing (mortgage) finance"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Merchant banking","bold":true},{"text":" began in "},{"text":"1960","bold":true},{"text":" with "},{"text":"Nigerian Acceptances Limited (NAL)","bold":true},{"text":" and "},{"text":"Philip Hill (Nigeria) Limited","bold":true},{"text":"; they merged in "},{"text":"1969","bold":true},{"text":" as "},{"text":"NAL Merchant Bank","bold":true},{"text":", Nigeria's first merchant bank."}]},{"text":[{"text":"Merchant banks vs commercial banks:","bold":true},{"text":" merchant banks are "},{"text":"wholesale","bold":true},{"text":" (large firms, institutions, medium- to long-term corporate finance, issuing house, leasing, acceptances, few branches); commercial banks are "},{"text":"retail","bold":true},{"text":" (current and savings accounts, short-term loans, wide branches)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A 10-year loan for a textile factory in the 1970s points to "},{"text":"NIDB","bold":true},{"text":". NIDB and NBCI were merged into the "},{"text":"Bank of Industry","bold":true},{"text":" (2001); NACB became today's "},{"text":"Bank of Agriculture","bold":true},{"text":"."}]},{"text":[{"text":"The rural banking scheme (1977) and community banks (1990, now microfinance banks) took banking beyond the cities."}]}]}]},{"number":"3.5","title":"SAP deregulation, distress and the response","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Deregulation era (1986 to the mid-1990s):","bold":true},{"text":" the "},{"text":"Structural Adjustment Programme (SAP)","bold":true},{"text":" from 1986. Reforms:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Deregulation of "},{"text":"interest rates","bold":true},{"text":"."}]},{"text":[{"text":"Removal of "},{"text":"credit ceilings","bold":true},{"text":"."}]},{"text":[{"text":"Liberalised bank licensing","bold":true},{"text":", so banks proliferated (about 40 commercial and 15 merchant banks before 1986 to about 125 commercial and merchant banks by 1994$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 16, $study_guide$)."}]},{"text":[{"text":"Foreign exchange liberalisation: "},{"text":"Second-tier Foreign Exchange Market (SFEM), 1986","bold":true},{"text":", rate set by market forces."}]},{"text":[{"text":"Privatisation of government stakes."}]}]}]},{"text":[{"text":"SAP did "},{"text":"not","bold":true},{"text":" increase Federal Government deposits in banks: in 1989 public sector deposits were "},{"text":"withdrawn","bold":true},{"text":" from banks to the CBN. Raising capital to ₦25 billion is 2004, not SAP."}]},{"text":[{"text":"Bank distress:","bold":true},{"text":" a bank suffers severe "},{"text":"financial, operational and managerial weakness","bold":true},{"text":" that makes it "},{"text":"unable to meet its obligations to customers, owners and the economy as and when due","bold":true},{"text":"."}]},{"text":[{"text":"CAMEL (5):","bold":true},{"text":" "},{"text":"C","bold":true},{"text":"apital adequacy, "},{"text":"A","bold":true},{"text":"sset quality, "},{"text":"M","bold":true},{"text":"anagement, "},{"text":"E","bold":true},{"text":"arnings, "},{"text":"L","bold":true},{"text":"iquidity. Market share is not one."}]},{"text":[{"text":"Symptoms (5):","bold":true},{"text":" boardroom squabbles; customer complaints of unpaid maturing obligations; "},{"text":"desperate borrowing","bold":true},{"text":" above market rates; window dressing; "},{"text":"persistent adverse clearing position and overdraft with the CBN","bold":true},{"text":"."}]},{"text":[{"text":"Causes:","bold":true},{"text":" internal: weak management, inadequate capital, fraud and insider abuse, poor asset and liability management. External: "},{"text":"macroeconomic instability","bold":true},{"text":" (inflation, recession), weak legal framework, delayed supervisory action, external shocks and balance of payments problems, political interference."}]},{"text":[{"text":"Responses:","bold":true},{"text":" "},{"text":"NDIC (1988)","bold":true},{"text":", from a 1983 CBN committee proposal for a "},{"text":"depositors protection fund","bold":true},{"text":"; "},{"text":"Failed Banks (Recovery of Debts) and Financial Malpractices in Banks Decree 1994","bold":true},{"text":": tribunals that recovered debts owed to failed banks "},{"text":"and","bold":true},{"text":" tried their directors; liquidations, the largest being "},{"text":"26 banks on 16 January 1998","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A bank that is a regular "},{"text":"net placer","bold":true},{"text":" of surplus funds in the interbank market is healthy, not distressed."}]},{"text":[{"text":"Cures for distress: a stable economy, sound regulation, good management, liquidity and funds management, fraud control."}]}]}]},{"number":"3.6","title":"Consolidation, the 2009 crisis and banking today","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Consolidation:","bold":true},{"text":" reducing the number of banks and other deposit-taking institutions while "},{"text":"increasing the size and concentration","bold":true},{"text":" of those that remain."}]},{"text":[{"text":"2004 programme:","bold":true},{"text":" announced by "},{"text":"CBN Governor Charles Soludo","bold":true},{"text":" at a special Bankers' Committee meeting on "},{"text":"6 July 2004","bold":true},{"text":". Minimum capital base rose from "},{"text":"₦2 billion to ₦25 billion","bold":true},{"text":" by "},{"text":"31 December 2005","bold":true},{"text":" (18 months)."}]},{"text":[{"text":"Definitions:","bold":true},{"text":" capital base = "},{"text":"paid-up capital and reserves unimpaired by losses","bold":true},{"text":"; paid-up capital = ordinary shares plus non-redeemable preference shares."}]},{"text":[{"text":"Allowed modes:","bold":true},{"text":" "},{"text":"only mergers and outright acquisitions","bold":true},{"text":". A mere "},{"text":"group arrangement","bold":true},{"text":" (a holding company keeping separate banks) was "},{"text":"not","bold":true},{"text":" accepted."}]},{"text":[{"text":"Incentives:","bold":true},{"text":" authority to deal in "},{"text":"foreign exchange","bold":true},{"text":"; "},{"text":"public sector deposits","bold":true},{"text":"; recommendation to collect public revenue; prospect of managing part of the "},{"text":"external reserves","bold":true},{"text":"; tax incentives; lower transaction costs. "},{"text":"Not","bold":true},{"text":" an incentive: exemption from CBN supervision."}]},{"text":[{"text":"Result:","bold":true},{"text":" "},{"text":"89 banks became 25","bold":true},{"text":" (75 banks merged into groups); 14 failed and were liquidated. Stanbic and IBTC then merged, leaving 24. "},{"text":"Wema Bank merged with National Bank of Nigeria.","bold":true}]},{"text":[{"text":"2009 crisis:","bold":true},{"text":" governor "},{"text":"Sanusi Lamido Sanusi","bold":true},{"text":"; a "},{"text":"joint CBN and NDIC","bold":true},{"text":" special examination. In "},{"text":"August 2009","bold":true},{"text":" the CEOs of "},{"text":"five","bold":true},{"text":" banks were removed: "},{"text":"Afribank, Finbank, Intercontinental, Oceanic, Union","bold":true},{"text":". Then three more: "},{"text":"Bank PHB, Equatorial Trust Bank, Spring Bank","bold":true},{"text":". Causes: "},{"text":"margin loans and oil and gas exposure, weak risk management and corporate governance","bold":true},{"text":", insider abuse. Constant borrowing at the "},{"text":"Expanded Discount Window","bold":true},{"text":" showed the banks were "},{"text":"illiquid","bold":true},{"text":". The CBN injected about ₦620 billion."}]},{"text":[{"text":"AMCON (2010):","bold":true},{"text":" buys "},{"text":"non-performing loans","bold":true},{"text":" from banks, takes over the collateral and helps recapitalise them."}]},{"text":[{"text":"Universal banking (2001):","bold":true},{"text":" one licence for commercial, merchant (investment) and other financial services. "},{"text":"Reviewed in 2010:","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 17, $study_guide$e},{"text":" banks had to "},{"text":"divest non-core businesses or use a holding company","bold":true},{"text":", under "},{"text":"commercial, merchant or specialised","bold":true},{"text":" licences."}]},{"text":[{"text":"2010 commercial bank capital:","bold":true},{"text":" "},{"text":"regional ₦10 billion, national ₦25 billion, international ₦50 billion","bold":true},{"text":" (merchant ₦15 billion)."}]},{"text":[{"text":"Current position:","bold":true},{"text":" "},{"text":"BOFIA 2020","bold":true},{"text":" replaced BOFIA 1991; the "},{"text":"CBN Act 2007","bold":true},{"text":" governs the CBN. In "},{"text":"March 2024","bold":true},{"text":" the CBN set new minimum capital: "},{"text":"international ₦500 billion, national ₦200 billion, regional ₦50 billion, merchant ₦50 billion, non-interest national ₦20 billion and regional ₦10 billion","bold":true},{"text":", deadline "},{"text":"31 March 2026","bold":true},{"text":". In April 2026 the CBN confirmed that "},{"text":"33 banks","bold":true},{"text":" had met it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The March 2004 review rated 62 banks sound, 14 marginal, 11 unsound, and 2 had not sent returns (62 + 14 + 11 + 2 = 89)."}]},{"text":[{"text":"Why consolidate? The 89 banks were small and fragile; one South African bank (ABSA) had more assets than all of them together."}]},{"text":[{"text":"The 2004 governor was "},{"text":"Soludo","bold":true},{"text":", not Sanusi (2009) or Cardoso (2024)."}]}]},{"type":"paragraph","text":[{"text":"Development of the financial system:","bold":true},{"text":" it grew through rising savings and investment, the establishment of the CBN, and technology such as electronic banking. A return to barter, closing banks or removing regulation would hold it back."}]},{"type":"paragraph","text":[{"text":"Periods to name:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Pre-independence free banking (before 1959; colonial era 1892-1960)."}]},{"text":[{"text":"Regulated banking (1960-1985)."}]},{"text":[{"text":"SAP deregulation (1986 to 1993/95)."}]},{"text":[{"text":"Consolidation (July 2004 to December 2005), followed by post-2009 reform and today's digital era."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ABC 1892 first; BBWA 1894 (First Bank); Colonial Bank/Barclays DCO (Union); British and French 1949 (UBA)."}]},{"text":[{"text":"WACB 1912: sterling-backed West African pound, BBWA as agent; no monetary independence."}]},{"text":[{"text":"Indigenous: ICB 1929 (first), National Bank 1933, Agbonmagbe 1945 (Wema), ACB 1947; only National Bank, ACB and Agbonmagbe survived the 1945-1955 boom and doom."}]},{"text":[{"text":"Paton Report led to the Banking Ordinance 1952: licence, minimum capital, reserves, examination; ended free banking."}]},{"text":[{"text":"CBN Act 1958, operations 1 July 1959, Fenton first governor; Loynes 1957."}]},{"text":[{"text":"Banking Decree 1969: ₦600,000 indigenous, ₦1.5 million expatriate; replaced by BOFID 1991, now BOFIA 2020."}]},{"text":[{"text":"Indigenisation 1972 (40%), 1976-1977 (60%); NAL plus Philip Hill gave NAL Merchant Bank (1969)."}]},{"text":[{"text":"SAP 1986: deregulation, SFEM; distress measured by CAMEL; NDIC 1988; 26 banks liquidated in 1998."}]},{"text":[{"text":"Soludo, 6 July 2004: ₦2 billion to ₦25 billion; 89 to 25 banks; mergers and acquisitions only."}]},{"text":[{"text":"2009: five plus three CEOs removed; AMCON 2010; 2024 recapitalisation (₦500 billion international) with a 31 March 2026 deadline."}]}]}],"theory":{"itemId":"b51b3be2-8fb2-5fba-b04b-741e9d970e39","question":[{"type":"paragraph","text":[{"text":"In the 2004 consolidation, a bank had a capital base of ₦2 billion. (a) How much extra capital did it need, how many times did the requirement rise, and by what percentage? (b) By what percentage did the number of banks fall when 89 became 25?"}]}]},"practice":[{"topic":"Historical Development of Banking in Nigeria","named":false}]}},{"kind":"note","itemId":"9b891e1e-95e3-59f2-a764-32ecca5fcbe0","sourceKey":"guide-topic:4","position":4,"payload":{"title":"The Central Bank of Nigeria","body":"What a central bank is and its canons; the WACB and the road to the CBN (1958 Act, 1 July 1959); the CBN Act 2007, Board, Governor, Deputy Governors and MPC; traditional and developmental functions; monetary policy, its objectives and instruments with simple computations; the CBN-led reforms of 2004, 2009, 2010 and 2024.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What a central bank is and its canons; the WACB and the road to the CBN (1958 Act, 1 July 1959); the CBN Act 2007, Board, Governor, Deputy Governors and MPC; traditional and developmental functions; monetary policy, its objectives and instruments with simple computations; the CBN-led reforms of 2004, 2009, 2010 and 2024."}],"lessons":[{"number":"4.1","title":"Central banking, its canons and the birth of the CBN","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Central bank:","bold":true},{"text":" the apex monetary authority of a country, with the sole right to issue currency and responsibility for regulating the banking and monetary system. It is the government's bank and the bankers' bank; it deals mainly with government and banks, not the public."}]},{"text":[{"text":"In Nigeria the apex monetary authority is the "},{"text":"Central Bank of Nigeria (CBN)","bold":true},{"text":", headquartered in Abuja."}]}]},{"type":"paragraph","text":[{"text":"Canons (principles) of central banking:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It must be the "},{"text":"sole bank of issue","bold":true},{"text":"."}]},{"text":[{"text":"It must "},{"text":"not do ordinary commercial banking or compete with commercial banks","bold":true},{"text":" (no profit-seeking deposits from the public); it is a bankers' bank and the government's bank.$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 18, $study_guide$"}]},{"text":[{"text":"It controls financial institutions with "},{"text":"monetary tools","bold":true},{"text":" (bank rate, open market operations and others)."}]},{"text":[{"text":"It keeps "},{"text":"some assets in liquid form","bold":true},{"text":" so it can discount short-term commercial and government bills."}]},{"text":[{"text":"It should be "},{"text":"free from government interference","bold":true},{"text":" (independent)."}]}]},{"type":"paragraph","text":[{"text":"Also accepted as central banking principles: acting as "},{"text":"lender of last resort","bold":true},{"text":" and being responsible for the "},{"text":"stability of the financial system","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"West African Currency Board (WACB):","bold":true},{"text":" set up in "},{"text":"1912","bold":true},{"text":" (after the "},{"text":"Lord Emmott","bold":true},{"text":" committee of 1911) to issue sterling-backed currency for four British colonies: Nigeria, Gold Coast (Ghana), Sierra Leone, The Gambia. Based in London; the "},{"text":"Bank of British West Africa","bold":true},{"text":" was its currency distributor in Nigeria. Before the CBN, the WACB issued Nigeria's legal tender."}]},{"type":"table","header":[[{"text":"Advantages of the WACB"}],[{"text":"Disadvantages of the WACB"}]],"rows":[[[{"text":"A unified currency standard accepted by the people"}],[{"text":"One currency for four colonies caused problems as they became independent at different dates"}]],[[{"text":"Relieved colonial governments of currency management"}],[{"text":"100% sterling backing invested abroad deprived the colonies of earning assets at home"}]],[[{"text":"Removed inflation and foreign exchange crises"}],[{"text":"Failed to train Africans in monetary management"}]],[[{"text":"Paved the way for easy acceptance of new currencies at independence"}],[{"text":"No independent monetary policy: Nigeria's money supply simply moved with its sterling (trade) earnings"}]]]},{"type":"paragraph","text":[{"text":"Road to the CBN (the three missions):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"1952:","bold":true},{"text":" K. O. Mbadiwe's motion in the House of Representatives asked for a central bank."}]},{"text":[{"text":"Fisher Report, 1953","bold":true},{"text":" (J. L. Fisher, Bank of England adviser): against a central bank then. \"The financial environment hardly exists in Nigeria for the establishment of a Central Bank.\" Reasons: the financial system was "},{"text":"too underdeveloped/narrow","bold":true},{"text":" for a central bank to control the money supply, and "},{"text":"trained staff were lacking","bold":true},{"text":"."}]},{"text":[{"text":"World Bank (IBRD) Mission","bold":true},{"text":" (report 1955): too early for a full central bank; recommended a "},{"text":"State Bank of Nigeria","bold":true},{"text":" that could later become a central bank."}]},{"text":[{"text":"Loynes Report, 1957","bold":true},{"text":" (J. B. Loynes, Bank of England): "},{"text":"favoured","bold":true},{"text":" a central bank; its recommendations formed the draft bill presented to the House in "},{"text":"March 1958","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"There was "},{"text":"no \"Johnson's Commission 1954\"","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CBN Act (No. 24) of 1958","bold":true},{"text":" established the CBN. It "},{"text":"commenced operations on 1 July 1959","bold":true},{"text":"."}]},{"text":[{"text":"First Governor: "},{"text":"Roy Pentelow Fenton","bold":true},{"text":" (1958-1963). First Nigerian Governor: "},{"text":"Aliyu Mai-Bornu","bold":true},{"text":" (1963-1967), followed by "},{"text":"Clement Isong","bold":true},{"text":" (1967-1975). Current Governor (2026): "},{"text":"Olayemi Cardoso","bold":true},{"text":", appointed 2023."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"By 1956 (self-rule) the government was persuaded a central bank was needed to "},{"text":"harness the financial resources of the economy, give leadership and direction to banks and other financial institutions, and create institutions, instruments and markets","bold":true},{"text":" for the growth of the financial system. If asked which of these, the answer is \"all of the above\"."}]},{"text":[{"text":"Watch the dates: "},{"text":"Act 1958, operations 1959","bold":true},{"text":". Options like 1 October 1960 (independence) or 1 July 1958 are traps."}]}]}]},{"number":"4.2","title":"Legal framework, objects and organisational structure","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Laws:","bold":true},{"text":" CBN Act 1958, replaced by CBN Decree No. 24 of 1991, amended 1993, 1997, 1998, 1999, now the "},{"text":"CBN Act 2007","bold":true},{"text":" (in force). The CBN also administers the "},{"text":"Banks and Other Financial Institutions Act (BOFIA) 2020","bold":true},{"text":", which replaced BOFIA 1991."}]}]},{"type":"paragraph","text":[{"text":"Principal objects under the CBN Act 2007 (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ensure "},{"text":"monetary and price stability","bold":true},{"text":" (the first and primary object)."}]},{"text":[{"text":"Issue "},{"text":"legal tender currency","bold":true},{"text":" in Nigeria."}]},{"text":[{"text":"Maintain "},{"text":"external reserves","bold":true},{"text":" to safeguard the international value of the currency."}]},{"text":[{"text":"Promote a "},{"text":"sound financial system","bold":true},{"text":" in Nigeria."}]},{"text":[{"text":"Act as "},{"text":"banker and provide economic and financial advice to the Federal Government","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Board of Directors (apex of the structure):","bold":true},{"text":" chaired by the "},{"text":"Governor","bold":true},{"text":"; members are the Governor$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 19, $study_guide$, the "},{"text":"4 Deputy Governors","bold":true},{"text":", "},{"text":"5 non-executive directors","bold":true},{"text":", the "},{"text":"Permanent Secretary of the Federal Ministry of Finance","bold":true},{"text":" and the "},{"text":"Accountant-General of the Federation","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Governor","bold":true},{"text":" (and Deputy Governors): appointed by the "},{"text":"President, subject to Senate confirmation","bold":true},{"text":", for "},{"text":"5 years in the first instance, renewable once","bold":true},{"text":" for not more than 5 years."}]},{"text":[{"text":"4 Deputy Governors (2007 Act):","bold":true}]}]},{"type":"table","header":[[{"text":"Deputy Governor"}],[{"text":"Departments include"}]],"rows":[[[{"text":"Economic Policy"}],[{"text":"Monetary Policy, Research, Statistics, Financial Markets"}]],[[{"text":"Financial System Stability"}],[{"text":"Banking Supervision","bold":true},{"text":", Other Financial Institutions Supervision"}]],[[{"text":"Operations"}],[{"text":"Banking Services, Currency Operations, Reserve Management, Payments System Management"}]],[[{"text":"Corporate Services"}],[{"text":"Human Resources, Finance"}]]]},{"type":"paragraph","text":[{"text":"Monetary Policy Committee (MPC):","bold":true},{"text":" formulates "},{"text":"monetary and credit policy","bold":true},{"text":". Set up formally by the CBN Act 2007."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Members ("},{"text":"12","bold":true},{"text":"): Governor (Chairman) 1 + Deputy Governors 4 + Board members 2 + President's appointees 3 + Governor's appointees 2 = "},{"text":"12","bold":true},{"text":"."}]},{"text":[{"text":"Must meet "},{"text":"at least four times a year","bold":true},{"text":"; in practice it meets about every two months."}]}]},{"type":"paragraph","text":[{"text":"Licensing under BOFIA:","bold":true},{"text":" to carry on banking business you must apply "},{"text":"in writing to the Governor of the CBN","bold":true},{"text":" for a licence. A bank may open or close a branch only with the "},{"text":"prior written consent of the CBN","bold":true},{"text":". Mergers and acquisitions also need the Governor's prior approval."}]},{"type":"paragraph","text":[{"text":"Why banks are heavily regulated (8):","bold":true},{"text":" protect depositors; protect customers from unfair dealing; promote monetary stability (control cost, volume and availability of credit); win public confidence; keep banks solvent; prevent crises that would damage the economy; safety of deposits; develop an integrated, efficient financial system. Regulation does "},{"text":"not","bold":true},{"text":" guarantee every bank a profit."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The 2007 Act gave the CBN greater autonomy."}]},{"text":[{"text":"You may see the MPC described as \"2 CBN appointees and 5 presidential appointees\"; that split is not the Act's, but the total is still 12. The 2007 Act wording is 2 Board members, 3 presidential and 2 Governor's appointees."}]},{"text":[{"text":"The NDIC (1988, operations 1989) shares bank oversight but is a separate body."}]}]}]},{"number":"4.3","title":"Traditional functions of the CBN","mustKnow":[{"type":"paragraph","text":[{"text":"The CBN's functions fall into three groups: "},{"text":"traditional","bold":true},{"text":", "},{"text":"regulatory (supervisory)","bold":true},{"text":" and "},{"text":"developmental","bold":true},{"text":" (Lesson 4.5)."}]},{"type":"paragraph","text":[{"text":"Five major functions under the 1958 Act:","bold":true},{"text":" (1) issue currency notes and coins (legal tender); (2) banker to the government; (3) banker to other banks; (4) manage the country's external reserves; (5) manage domestic monetary policy. Today you also add "},{"text":"regulation and supervision","bold":true},{"text":" of banks and other financial institutions, and "},{"text":"financial adviser to government","bold":true},{"text":"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Issue of legal tender:","bold":true},{"text":" sole issuer of the naira. The CBN "},{"text":"issues","bold":true},{"text":" currency; "},{"text":"Nigerian Security Printing and Minting Plc prints and mints","bold":true},{"text":" it."}]},{"text":[{"text":"Banker to government:","bold":true},{"text":" keeps federal, state and local government accounts; "},{"text":"manages the public debt","bold":true},{"text":" (issues Treasury Bills, Treasury Certificates, development stocks); grants "},{"text":"Ways and Means advances","bold":true},{"text":" (temporary direct advances to the FG to cover revenue shortfalls); runs the "},{"text":"Treasury Single Account (TSA)","bold":true},{"text":": all MDAs close separate bank accounts and pay receipts into one consolidated account at the CBN."}]},{"text":[{"text":"Banker to banks:","bold":true},{"text":" keeps banks' current/reserve accounts, provides "},{"text":"clearing","bold":true},{"text":" facilities, rediscounts their bills, and is "},{"text":"lender of last resort","bold":true},{"text":": emergency funds to a "},{"text":"solvent but temporarily illiquid","bold":true},{"text":" bank."}]},{"text":[{"text":"External reserves:","bold":true},{"text":" holds gold and convertible currencies to safeguard the naira's international value."}]},{"text":[{"text":"Monetary stability and a sound financial system:","bold":true},{"text":" monetary policy plus licensing, examination (on-site and off-site) and enforcement."}]}]},{"type":"paragraph","text":[{"text":"Things the CBN does NOT do:","bold":true},{"text":" accept deposits from or lend to individuals, households or businessmen; insure deposits or pay depositors of failed banks ("},{"text":"NDIC","bold":true},{"text":"); register stockbrokers or list shares ("},{"text":"SEC","bold":true},{"text":" and the Exchange); register companies ("},{"text":"CAC","bold":true},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 20, $study_guide${"text":"); collect taxes; examine and qualify bankers ("},{"text":"CIBN","bold":true},{"text":"). A central bank is "},{"text":"not","bold":true},{"text":" a merchant bank."}]},{"type":"table","header":[[{"text":"Central bank"}],[{"text":"Commercial bank"}]],"rows":[[[{"text":"One per country; apex of the system"}],[{"text":"Many in one country"}]],[[{"text":"Monopoly of currency issue"}],[{"text":"Cannot issue currency"}]],[[{"text":"Not profit-driven"}],[{"text":"Main objective is profit"}]],[[{"text":"Deals with government and banks"}],[{"text":"Deals with the public"}]],[[{"text":"Controls","bold":true},{"text":" credit"}],[{"text":"Creates","bold":true},{"text":" credit"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Currency history:","bold":true},{"text":" Nigerian pound issued "},{"text":"1959","bold":true},{"text":"; "},{"text":"1 January 1973","bold":true},{"text":" decimalisation: the "},{"text":"naira and kobo","bold":true},{"text":", at "},{"text":"₦2 = £1","bold":true},{"text":"; "},{"text":"₦20 note 1977","bold":true},{"text":" honouring "},{"text":"General Murtala Mohammed","bold":true},{"text":"; ₦1,000 note 2005."}]},{"text":[{"text":"Reserves history:","bold":true},{"text":" sterling backing received from the WACB in 1959; from "},{"text":"1973","bold":true},{"text":" held in as many traded currencies as possible (not only US dollars and pounds) to "},{"text":"earn new income and reduce losses","bold":true},{"text":" from a fall in any one currency."}]},{"text":[{"text":"Domiciliary accounts:","bold":true},{"text":" since deregulation, exporters and others may keep foreign exchange in domiciliary accounts with banks. Two types: "},{"text":"Export Domiciliary Account","bold":true},{"text":" and "},{"text":"Ordinary Domiciliary Account","bold":true},{"text":"."}]},{"text":[{"text":"Ways and Means limit:","bold":true},{"text":" the CBN Act 2007 caps outstanding advances at "},{"text":"5% of the FG's previous year's actual revenue","bold":true},{"text":" (the 1991 Decree said 12.5% of estimated recurrent revenue). Example: previous year's revenue ₦10 trillion; limit = 5% × ₦10,000 billion = ₦500 billion. Heavy deficit financing by the CBN pumps money into the economy and weakens its control of prices: this is "},{"text":"fiscal dominance","bold":true},{"text":"."}]}]}]},{"number":"4.4","title":"Monetary policy and its instruments","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monetary policy:","bold":true},{"text":" the use of the central bank's control over the "},{"text":"quantity, availability and cost of money and credit","bold":true},{"text":" to achieve general economic objectives. Not fiscal policy, which uses "},{"text":"taxation, government expenditure and public debt","bold":true},{"text":" (Federal Ministry of Finance)."}]},{"text":[{"text":"Monetary and fiscal policy are both "},{"text":"economic stabilisation policies","bold":true},{"text":"."}]},{"text":[{"text":"Four objectives:","bold":true},{"text":" (1) "},{"text":"stable prices","bold":true},{"text":", (2) "},{"text":"high growth rate of output","bold":true},{"text":", (3) "},{"text":"full employment","bold":true},{"text":", (4) "},{"text":"balance of payments equilibrium","bold":true},{"text":". Secondary: stable exchange rate, income redistribution. Population growth and bank profits are "},{"text":"not","bold":true},{"text":" objectives. In practice the CBN's primary focus is "},{"text":"price stability","bold":true},{"text":"."}]},{"text":[{"text":"Stable prices:","bold":true},{"text":" the general price level avoids wide fluctuations and changes only gradually (not frozen prices)."}]},{"text":[{"text":"Full employment:","bold":true},{"text":" all able and willing to work find jobs; some frictional and seasonal unemployment remains."}]},{"text":[{"text":"Types:","bold":true},{"text":" "},{"text":"expansionary","bold":true},{"text":" (more money and credit; for recession) and "},{"text":"contractionary","bold":true},{"text":" (less; for inflation)."}]}]},{"type":"paragraph","text":[{"text":"Instruments","bold":true}]},{"type":"table","header":[[{"text":"Quantitative (general, traditional)"}],[{"text":"Qualitative (selective)"}]],"rows":[[[{"text":"Open market operations (OMO)"}],[{"text":"Moral suasion"}]],[[{"text":"Discount rate / bank rate (now MPR)"}],[{"text":"Selective credit control"}]],[[{"text":"Reserve requirements (cash reserve ratio, liquidity ratio)"}],[{"text":"Margin requirement"}]],[[{"text":"Special deposits"}],[{"text":"Loan (credit) ceiling"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"OMO:","bold":true},{"text":" buying and selling government (or CBN) securities to change bank reserves and money supply. "},{"text":"Sell","bold":true},{"text":" = withdraw money (contract). "},{"text":"Buy","bold":true},{"text":" = inject money (expand). Main "},{"text":"indirect, market-based","bold":true},{"text":" tool since "},{"text":"June 1993","bold":true},{"text":". Uses Nigerian Treasury Bills, bonds and "},{"text":"CBN Bills","bold":true},{"text":" (issued by the CBN itself to mop up liquidity)."}]},{"text":[{"text":"Repo:","bold":true},{"text":" CBN sells and agrees to buy back = "},{"text":"temporarily withdraws","bold":true},{"text":" liquidity. "},{"text":"Reverse repo:","bold":true},{"text":" temporarily injects."}]},{"text":[{"text":"Discount rate = bank rate:","bold":true},{"text":" the rate at which the central bank lends to banks or rediscounts their eligible bills. Lower it to expand credit; raise it to contract. In Nigeria the "},{"text":"Minimum Rediscount Rate (MRR)","bold":true},{"text":" was replaced in "},{"text":"December 2006","bold":true},{"text":" by the "},{"text":"Monetary Policy Rate (MPR)","bold":true},{"text":", the signalling rate."}]},{"text":[{"text":"Standing facilities corridor:","bold":true},{"text":" "},{"text":"SLF","bold":true},{"text":" (Standing Lending Facility) = overnight borrow$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 21, $study_guide$ing from the CBN against collateral, "},{"text":"above","bold":true},{"text":" MPR. "},{"text":"SDF","bold":true},{"text":" (Standing Deposit Facility) = overnight deposit with the CBN, "},{"text":"below","bold":true},{"text":" MPR. Formulas: SLF rate = MPR + upper band; SDF rate = MPR − lower band (100 basis points = 1%)."}]},{"text":[{"text":"Cash reserve ratio (CRR):","bold":true},{"text":" minimum % of deposits a bank must keep "},{"text":"with the CBN","bold":true},{"text":". "},{"text":"Liquidity ratio:","bold":true},{"text":" minimum % of deposit liabilities held in "},{"text":"liquid assets","bold":true},{"text":" (cash in vault, balances with the CBN, Treasury Bills). Raise either: excess reserves fall, lending and money supply contract."}]},{"text":[{"text":"Simple deposit multiplier = 1 ÷ reserve ratio.","bold":true},{"text":" Maximum lendable from new deposits = deposits × (1 − CRR). Liquidity shortfall = (liquidity ratio × deposits) − liquid assets held."}]},{"text":[{"text":"Special deposits:","bold":true},{"text":" cash kept with the central bank "},{"text":"over and above","bold":true},{"text":" required reserves, "},{"text":"not counted","bold":true},{"text":" toward them."}]},{"text":[{"text":"Moral suasion:","bold":true},{"text":" persuasion or friendly appeal to banks to act in the national interest, "},{"text":"without legal compulsion","bold":true},{"text":". It is the classic "},{"text":"non-market","bold":true},{"text":" instrument."}]},{"text":[{"text":"Selective credit control:","bold":true},{"text":" administrative guidelines directing credit to sectors in set amounts at set rates (pre-"},{"text":"1986 SAP","bold":true},{"text":", to agriculture and manufacturing)."}]},{"text":[{"text":"Margin requirement:","bold":true},{"text":" fixes how much security is needed for advances, to stop lending against commodities hoarded for speculation. "},{"text":"Loan ceiling:","bold":true},{"text":" total advances may not rise above the level reached on a date the CBN names."}]},{"text":[{"text":"Direct controls of bank liquidity:","bold":true},{"text":" supplementary reserves, variable cash ratio, variable liquidity ratio."}]}]},{"type":"paragraph","text":[{"text":"Current position (September 2026 MPC):","bold":true},{"text":" MPR "},{"text":"23%","bold":true},{"text":"; corridor "},{"text":"+50/−300","bold":true},{"text":" basis points; CRR "},{"text":"45%","bold":true},{"text":" for deposit money banks, "},{"text":"16%","bold":true},{"text":" merchant banks, "},{"text":"75%","bold":true},{"text":" on non-TSA public sector deposits; liquidity ratio "},{"text":"30%","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interest rates and spending move oppositely: "},{"text":"higher rates lead to lower spending; lower rates to higher spending","bold":true},{"text":". To pump money in, the CBN "},{"text":"reduces","bold":true},{"text":" the discount rate or MPR, "},{"text":"buys","bold":true},{"text":" securities, or "},{"text":"cuts","bold":true},{"text":" reserve ratios. To fight inflation it "},{"text":"sells","bold":true},{"text":" securities (OMO), "},{"text":"raises","bold":true},{"text":" MPR or reserve ratios, uses selective credit control; a "},{"text":"surplus budget","bold":true},{"text":" is a fiscal anti-inflation tool. "},{"text":"Cutting the MPR is not","bold":true},{"text":" an anti-inflation tool. Taxation and budgeting are fiscal, not monetary."}]},{"text":[{"text":"Reserve requirements change the "},{"text":"multiplier","bold":true},{"text":"; OMO changes the "},{"text":"monetary base","bold":true},{"text":"."}]},{"text":[{"text":"Direct controls (1959-1986):","bold":true},{"text":" credit ceilings, sectoral allocation, fixed interest rates. "},{"text":"Market-based era","bold":true},{"text":" from SAP (1986), OMO from 1993."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1 (multiplier):","bold":true},{"text":" CRR 10%: multiplier = 1 ÷ 0.10 = 10, so ₦10,000 of new cash supports ₦10,000 × 10 = ₦100,000 of deposits. If the CRR rises to 20%: multiplier = 1 ÷ 0.20 = 5, supporting ₦10,000 × 5 = ₦50,000. Raising the CRR from 10% to 20% cuts the multiplier from 10 to 5."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (CRR):","bold":true},{"text":" CRR 40%, new deposits ₦250 billion. Required reserve = 40% × ₦250bn = ₦100bn. Maximum lending = ₦250bn − ₦100bn = "},{"text":"₦150bn","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (liquidity ratio):","bold":true},{"text":" Ekiti Trust Bank: deposits ₦600bn, liquid assets ₦150bn, liquidity ratio 30%. Required = 30% × ₦600bn = ₦180bn. Shortfall = ₦180bn − ₦150bn = "},{"text":"₦30bn","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (corridor):","bold":true},{"text":" MPR 20%, corridor +500/−100 bps. SLF = 20% + 5% = "},{"text":"25%","bold":true},{"text":"; SDF = 20% − 1% = "},{"text":"19%","bold":true},{"text":". September 2026: SLF = 23% + 0.5% = 23.5%; SDF = 23% − 3% = 20%."}]}]},{"number":"4.5","title":"Developmental functions of the CBN","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Developmental functions:","bold":true},{"text":" roles beyond the traditional ones, suited to a developing economy, to build the financial system and finance key sectors. Example: special financing schemes for agriculture and industry."}]}]},{"type":"paragraph","text":[{"text":"Three major developmental functions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provision of financial infrastructure:","bold":true},{"text":" creating "},{"text":"markets and instruments","bold":true},{"text":": Treasury Bills (1960), call money fund scheme (1962), Treasury Certificates (1968), certificates of deposit, bankers' acceptances, discount houses (1993); encouraged the "},{"text":"Lagos Stock Exchange (1961)","bold":true},{"text":"; helped found NIDB, the NDI$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 22, $study_guide$C and SEC."}]},{"text":[{"text":"Provision of special funds and schemes","bold":true},{"text":" (see below)."}]},{"text":[{"text":"Provision of information and training:","bold":true},{"text":" publications ("},{"text":"Statistical Bulletin, Annual Report, CBN Briefs, Economic and Financial Review","bold":true},{"text":", Bullion), seminars, surveys and the "},{"text":"Monetary Policy Forum","bold":true},{"text":" (from 2000); manpower development."}]}]},{"type":"paragraph","text":[{"text":"Special funds and schemes:","bold":true}]},{"type":"table","header":[[{"text":"Scheme"}],[{"text":"Key facts"}]],"rows":[[[{"text":"Rural Banking Scheme","bold":true},{"text":" (1977, 4 phases to 1993)"}],[{"text":"Commercial banks "},{"text":"directed to open branches in rural areas","bold":true},{"text":" to mobilise rural savings"}]],[[{"text":"Agricultural Credit Guarantee Scheme Fund (ACGSF)","bold":true},{"text":" (1977)"}],[{"text":"Guarantees "},{"text":"75% of the net amount in default","bold":true},{"text":" on agricultural loans; share capital subscribed 60% Federal Government, 40% CBN"}]],[[{"text":"NERFUND","bold":true},{"text":" (National Economic "},{"text":"Reconstruction","bold":true},{"text":" Fund)"}],[{"text":"Medium/long-term funds, partly in foreign exchange; merged into Bank of Industry (2001)"}]],[[{"text":"SMIEIS","bold":true},{"text":" (Small and Medium Industries Equity Investment Scheme)"}],[{"text":"CBN initiative via the "},{"text":"Bankers' Committee","bold":true},{"text":": banks set aside "},{"text":"10% of profit before tax","bold":true},{"text":" for equity in small and medium industries"}]],[[{"text":"Rediscounting and Refinancing Facility (RRF)","bold":true},{"text":" (1987)"}],[{"text":"Lets banks rediscount or refinance "},{"text":"export","bold":true},{"text":" credit"}]],[[{"text":"Foreign Input Facility (FIF)","bold":true},{"text":" (1989)"}],[{"text":"Helps producers get foreign exchange to "},{"text":"import capital goods and raw materials","bold":true}]],[[{"text":"Anchor Borrowers' Programme","bold":true},{"text":" (2015) and others (Real Sector Support Facility, MSMEDF)"}],[{"text":"Development finance interventions for farmers and the real sector"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"RRF and FIF passed to "},{"text":"NEXIM","bold":true},{"text":" in 1991. There is "},{"text":"no","bold":true},{"text":" \"National Economic Rejuvenation Fund\"."}]},{"text":[{"text":"Community banking (1990)","bold":true},{"text":" replaced rural banking and later became "},{"text":"microfinance banking","bold":true},{"text":"."}]},{"text":[{"text":"The CBN helped set up development banks: NIDB 1964 (now Bank of Industry), NACB 1973 (now Bank of Agriculture), Federal Mortgage Bank 1977."}]},{"text":[{"text":"Manpower:","bold":true},{"text":" the CBN chairs the Bankers' Committee and supports the "},{"text":"CIBN","bold":true},{"text":" and the "},{"text":"Financial Institutions Training Centre (FITC)","bold":true},{"text":", seconds staff and runs its own training programmes."}]},{"text":[{"text":"Payments:","bold":true},{"text":" cashless policy (2012); "},{"text":"Bank Verification Number (BVN)","bold":true},{"text":", launched with the Bankers' Committee in "},{"text":"February 2014","bold":true},{"text":", gives each customer one biometric identity across all banks."}]},{"text":[{"text":"Since 2023-2024 the CBN under Cardoso has scaled back its intervention lending to concentrate on price stability."}]},{"text":[{"text":"Paying insured depositors of failed banks is the "},{"text":"NDIC's","bold":true},{"text":" work, not a CBN achievement."}]}]}]},{"number":"4.6","title":"CBN-led banking reforms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Consolidation:","bold":true},{"text":" a reduction in the number of banks, with the remaining banks becoming "},{"text":"larger and more concentrated","bold":true},{"text":"."}]},{"text":[{"text":"2004-2005 consolidation:","bold":true},{"text":" announced "},{"text":"6 July 2004","bold":true},{"text":" by Governor "},{"text":"Charles Soludo","bold":true},{"text":" to the Bankers' Committee. Minimum capital raised from "},{"text":"₦2 billion to ₦25 billion","bold":true},{"text":", deadline "},{"text":"31 December 2005","bold":true},{"text":" (18 months). Reason: banks were "},{"text":"small, fragile, poorly developed, with a weak capital base","bold":true},{"text":" compared with their expected role. Allowed modes: "},{"text":"mergers and outright acquisitions/takeovers","bold":true},{"text":" (plus fresh capital); a "},{"text":"mere group arrangement was not acceptable","bold":true},{"text":". Result: "},{"text":"89 banks fell to 25","bold":true},{"text":"; "},{"text":"14","bold":true},{"text":" failed and were liquidated."}]}]},{"type":"table","header":[[{"text":"For consolidation"}],[{"text":"Against consolidation"}]],"rows":[[[{"text":"Revenue and cost efficiency gains"}],[{"text":"More risk-taking through leverage and off-balance-sheet activity"}]],[[{"text":"Removes weak banks"}],[{"text":"Very large banks are complex and costly to manage"}]],[[{"text":"Better diversification of risk"}],[{"text":"Scale economies are not unlimited"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"2009 crisis:","bold":true},{"text":" caused by "},{"text":"heavy lending concentrated in the capital market (margin loans) and oil and gas","bold":true},{"text":", plus "},{"text":"weak risk management and corporate governance","bold":true},{"text":". A "},{"text":"joint CBN-NDIC special examination","bold":true},{"text":" (Governor "},{"text":"Sanusi Lamido Sanusi","bold":true},{"text":", August 2009) found "},{"text":"very high non-performing loans","bold":true},{"text":" and "},{"text":"illiquid","bold":true},{"text":" banks depending on CBN support (Expanded Discount Window) and interbank borrowing. Five, then three more, banks had their managements removed and received $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 23, $study_guide$CBN capital injections; "},{"text":"AMCON","bold":true},{"text":" (2010) bought their bad loans."}]},{"text":[{"text":"2010 licensing regime","bold":true},{"text":" (universal banking ended): commercial bank with "},{"text":"international","bold":true},{"text":" authorisation "},{"text":"₦50 billion","bold":true},{"text":"; "},{"text":"national","bold":true},{"text":" ₦25 billion; "},{"text":"regional","bold":true},{"text":" ₦10 billion; merchant bank ₦15 billion."}]},{"text":[{"text":"Current (2024 recapitalisation, deadline 31 March 2026):","bold":true},{"text":" international commercial "},{"text":"₦500 billion","bold":true},{"text":"; national ₦200 billion; regional ₦50 billion; merchant ₦50 billion; non-interest national ₦20 billion, regional ₦10 billion."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Before 2004, existing banks needed ₦1 billion and new banks ₦2 billion; one South African bank (ABSA) had more assets than all 89 Nigerian banks."}]},{"text":[{"text":"The five banks first examined in 2009 (Afribank, Finbank, Intercontinental, Oceanic, Union) had liquidity ratios "},{"text":"below","bold":true},{"text":" the 25% minimum then."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Central bank = apex monetary authority; sole issuer; bankers' bank; government's bank; does not compete with commercial banks."}]},{"text":[{"text":"WACB 1912; Fisher 1953 (against), World Bank 1955 (State Bank), Loynes 1957 (for); CBN Act 1958; operations 1 July 1959."}]},{"text":[{"text":"CBN Act 2007: first object is monetary and price stability; Board chaired by the Governor; 4 Deputy Governors; Governor appointed by the President with Senate confirmation for 5 years, renewable once."}]},{"text":[{"text":"MPC: 12 members, meets at least 4 times a year; MPR replaced MRR (2006)."}]},{"text":[{"text":"Quantitative tools: OMO, bank rate, reserve requirements, special deposits; qualitative: moral suasion, selective credit control, margin requirement, loan ceiling."}]},{"text":[{"text":"Sell securities or raise CRR to contract; buy securities or cut rates to expand. Multiplier = 1 ÷ reserve ratio."}]},{"text":[{"text":"Developmental: infrastructure, special funds and schemes (ACGSF 75%, SMIEIS 10% of PBT, RRF exports, FIF imports, rural banking), information and training."}]},{"text":[{"text":"2004: ₦25 billion, 89 to 25 banks; 2010: international ₦50 billion; 2024: international ₦500 billion by 31 March 2026."}]}]}],"theory":{"itemId":"04394be6-b73b-50c1-b2b9-761e7cb01a71","question":[{"type":"paragraph","text":[{"text":"Lekki Bank has deposit liabilities of ₦800 billion. The CRR is 45% and the liquidity ratio 30%. (a) How much must it keep with the CBN as cash reserve? (b) What minimum liquid assets must it hold? (c) If the CBN cuts the CRR to 40%, how much is released for lending?"}]}]},"practice":[{"topic":"The Central Bank of Nigeria","named":false}]}},{"kind":"note","itemId":"9adc1855-7b73-5002-9fb1-8ed211865a89","sourceKey":"guide-topic:5","position":5,"payload":{"title":"The Nigerian Banking Structure, Savings and Investment","body":"The parts of the financial system and how intermediaries turn savings into investment; commercial, merchant and non-interest banks, the licence regime and every recapitalisation; the development finance institutions and their mergers; Peoples Bank, community banks and microfinance banks; the NDIC and distress resolution; the other regulators and non-bank institutions; simple interest, real rate, NHF and NDIC computations.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The parts of the financial system and how intermediaries turn savings into investment; commercial, merchant and non-interest banks, the licence regime and every recapitalisation; the development finance institutions and their mergers; Peoples Bank, community banks and microfinance banks; the NDIC and distress resolution; the other regulators and non-bank institutions; simple interest, real rate, NHF and NDIC computations."}],"lessons":[{"number":"5.1","title":"The financial system, savings and investment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 basic types of financial institutions:","bold":true},{"text":" (1) "},{"text":"bank financial institutions (BFIs)","bold":true},{"text":": deposit money banks and specialised banks; (2) "},{"text":"non-bank financial institutions (NBFIs)","bold":true},{"text":": insurance companies, pension funds, finance houses, unit trusts, mutual funds, savings and loans; (3) "},{"text":"regulatory and supervisory institutions","bold":true},{"text":". BFI liabilities (demand deposits) are spendable as money; NBFI liabilities are not."}]},{"text":[{"text":"4 components of the system:","bold":true},{"text":" institutions, markets (money and capital), instruments, regulators."}]},{"text":[{"text":"Formal sector:","bold":true},{"text":" licensed and regulated (banks, insurers, pension funds, capital market operators). "},{"text":"Informal sector:","bold":true},{"text":" unlicensed and unsupervised: "},{"text":"esusu, ajo, isusu","bold":true},{"text":" (rotating contributions), moneylenders, daily savings collectors."}]},{"text":[{"text":"Financial intermediation:","bold":true},{"text":" channelling funds from "},{"text":"surplus units","bold":true},{"text":" (savers) to "},{"text":"deficit units","bold":true},{"text":" (investors). Intermediaries promote the savings-investment process and so "},{"text":"capital formation","bold":true},{"text":" (acquiring capital assets to raise productivity) and growth."}]},{"text":[{"text":"Why intermediaries beat direct lending:","bold":true},{"text":" they pool small savings into bulky sums; spread risk (lower risk per saver, so lower cost of funds); give longer terms ("},{"text":"maturity transformation","bold":true},{"text":": short-term deposits funding long-term loans); assess borrowers expertly; cut transaction costs; give savers liqu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 24, $study_guide$idity and income. Direct sourcing means high cost, short term and high risk."}]},{"text":[{"text":"Factors for successful intermediation:","bold":true},{"text":" trust and confidence; convenience; price (interest and fees); nearness to market. Loss of confidence causes "},{"text":"disintermediation","bold":true},{"text":"."}]},{"text":[{"text":"3 goals of a DMB:","bold":true},{"text":" "},{"text":"profitability, liquidity, solvency.","bold":true},{"text":" Loans earn most but reduce liquidity; cash is liquid but earns nothing."}]},{"text":[{"text":"Savings products:","bold":true},{"text":" savings account, target savings, fixed (time) deposits, digital savings. "},{"text":"Channels of bank investment:","bold":true},{"text":" direct lending, securities (Treasury Bills, bonds), equity (within limits), trade finance."}]},{"text":[{"text":"Challenges to saving:","bold":true},{"text":" low income, inflation, financial exclusion, distrust after bank failures, competing assets (property, dollars, crypto)."}]},{"text":[{"text":"Formulas:","bold":true},{"text":" Simple interest = P × R × T (T in years). Amount = P + interest. Real interest rate ≈ nominal rate − inflation rate."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Twenty Oshodi traders each paying ₦5,000 weekly, one collecting the pool in turn, with no licence or regulator: "},{"text":"informal","bold":true},{"text":" sector."}]},{"text":[{"text":"A bank using thousands of withdrawable savings to fund a ten-year cement-factory loan shows "},{"text":"maturity transformation","bold":true},{"text":"."}]},{"text":[{"text":"Fixed deposit:","bold":true},{"text":" ₦1,000,000 for 3 months at 12% simple. Interest = 1,000,000 × 0.12 × 3/12 = ₦30,000. Amount paid = 1,000,000 + 30,000 = "},{"text":"₦1,030,000","bold":true},{"text":". (₦30,000 alone is the interest, not the payment.)"}]},{"text":[{"text":"Savings:","bold":true},{"text":" Chidinma's ₦800,000 at 6% for 9 months: 800,000 × 0.06 × 9/12 = "},{"text":"₦36,000","bold":true},{"text":" interest."}]},{"text":[{"text":"Real rate:","bold":true},{"text":" savings pay 12%, inflation is 21%: 12 − 21 = "},{"text":"−9%","bold":true},{"text":". The saver loses purchasing power; this is why inflation discourages saving."}]}]}]},{"number":"5.2","title":"Deposit money banks: commercial, merchant, non-interest","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Deposit money banks (DMBs)","bold":true},{"text":" = "},{"text":"commercial banks and merchant banks","bold":true},{"text":". Nigeria runs "},{"text":"branch banking","bold":true},{"text":": one bank, many offices nationwide, one serving as head office."}]},{"text":[{"text":"Commercial bank functions:","bold":true},{"text":" (1) accept deposits: current (demand), savings, fixed/time; (2) grant advances: loans, overdrafts, bill discounting; ancillary: agency (payments, remittances), executor and trustee, "},{"text":"safe-keeping of wills, jewellery and documents","bold":true},{"text":", payment services, foreign exchange."}]},{"text":[{"text":"Merchant bank:","bold":true},{"text":" engaged in wholesale banking, medium- and long-term finance, equipment leasing, debt factoring, investment management, issue and acceptance of bills, unit trusts. Started 1960 (Philip Hill Nigeria and Nigerian Acceptances Ltd, merged 1969 as NAL Merchant Bank)."}]},{"text":[{"text":"Merchant bank services:","bold":true},{"text":" "},{"text":"banking:","italic":true},{"text":" "},{"text":"acceptances","bold":true},{"text":" (the "},{"text":"traditional","bold":true},{"text":" function that marks them out: accepting bills of exchange to finance the trade of others), loans and advances including "},{"text":"bridging loans","bold":true},{"text":", deposits (fixed/call, current for corporates, "},{"text":"NCDs","bold":true},{"text":"), "},{"text":"equipment leasing","bold":true},{"text":", foreign exchange (letters of credit). "},{"text":"Corporate finance:","italic":true},{"text":" project financing and loan syndication, "},{"text":"issuing house","bold":true},{"text":", investment and financial advisory (mergers, acquisitions)."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Merchant bank"}],[{"text":"Commercial bank"}]],"rows":[[[{"text":"Type"}],[{"text":"Wholesale banker"}],[{"text":"Retail banker"}]],[[{"text":"Customers"}],[{"text":"Firms and institutions, large sums"}],[{"text":"Everyone: individuals, households, firms, government"}]],[[{"text":"Deposits"}],[{"text":"Mainly fixed"}],[{"text":"Demand, savings and fixed"}]],[[{"text":"Branches"}],[{"text":"Few, urban"}],[{"text":"Many, urban and rural"}]],[[{"text":"Clearing house"}],[{"text":"Traditionally not members"}],[{"text":"Members"}]],[[{"text":"Loans"}],[{"text":"Bulkier, medium term"}],[{"text":"Mostly short term"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Universal banking (2001 to 2010):","bold":true},{"text":" one bank could do commercial and merchant banking plus insurance and stockbroking. Advantages: removed the commercial/merchant dichotomy, created a "},{"text":"level playing field","bold":true},{"text":", raised competition. Ended by the CBN's "},{"text":"Regulation on the Scope of Banking Activities (2010)","bold":true},{"text":", which created licence types and confined banks to core banking (no insurance underwriting, no real estate except own premises, no non-permitted equity investment, no issuing currency) without CBN authorisation."}]},{"text":[{"text":"Licence categories:","bold":true},{"text":" commercial ("},{"text":"international, national, regional","bold":true},{"text":" authorisation), merchant, non-interest (national, regional). International = all states plus branches or subsidiaries abroad; national = all states, no offshore; regional = a limited set of states."}]},{"text":[{"text":"Non-interest (Islamic) banking:","bold":true},{"text":" no interest ("},{"text":"riba","bold":true},{"text":"); works $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 25, $study_guide$on "},{"text":"profit-and-loss sharing","bold":true},{"text":". Demand deposits earn nothing; investment (time) deposits get a "},{"text":"share of profit","bold":true},{"text":" at a ratio agreed in advance. Contracts: "},{"text":"Murabaha","bold":true},{"text":" (cost-plus sale with disclosed mark-up), "},{"text":"Ijarah","bold":true},{"text":" (leasing), "},{"text":"Mudarabah","bold":true},{"text":" (profit-sharing). "},{"text":"Jaiz Bank","bold":true},{"text":" is the pioneer; TAJ Bank and Lotus Bank followed."}]},{"text":[{"text":"Minimum capital history:","bold":true},{"text":" 1991 BOFID ₦50m commercial, ₦40m merchant; 1997 ₦500m both; 2001 universal ₦1bn (old) / ₦2bn (new); 2004 ₦2bn; "},{"text":"July 2004 consolidation: ₦25bn shareholders' funds by 31 December 2005","bold":true},{"text":"; 2010: regional ₦10bn, merchant ₦15bn, national ₦25bn, international ₦50bn."}]},{"text":[{"text":"Current (March 2024 programme, deadline 31 March 2026):","bold":true},{"text":" international commercial "},{"text":"₦500bn","bold":true},{"text":", national "},{"text":"₦200bn","bold":true},{"text":", regional "},{"text":"₦50bn","bold":true},{"text":", merchant "},{"text":"₦50bn","bold":true},{"text":", non-interest national "},{"text":"₦20bn","bold":true},{"text":", regional "},{"text":"₦10bn","bold":true},{"text":"."}]},{"text":[{"text":"Present-day structure:","bold":true},{"text":" CBN at the apex; commercial, merchant and non-interest banks; MFBs; DFIs; primary mortgage institutions; other institutions. The "},{"text":"West African Currency Board","bold":true},{"text":" (Nigeria's currency issuer before the CBN, 1912 to 1959) is history, not part of today's structure."}]},{"text":[{"text":"Law:","bold":true},{"text":" "},{"text":"BOFIA 2020","bold":true},{"text":" (Banks and Other Financial Institutions Act) replaced BOFIA 1991."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Consolidation","bold":true},{"text":" = banks merging, acquiring one another and raising fresh capital to meet a higher minimum. In 2004-2005, 89 banks became 25. Recapitalisation gives banks a "},{"text":"very strong capital base","bold":true},{"text":". By the 2026 deadline the CBN reported 33 banks compliant, with a few still in regulatory or court processes."}]},{"text":[{"text":"Musa's ₦4m van sold to him at ₦4.6m with the ₦600,000 mark-up disclosed (600,000 ÷ 4,000,000 × 100 = 15%), paid in instalments: "},{"text":"Murabaha","bold":true},{"text":"."}]},{"text":[{"text":"Delta Foods needs cash now, to be repaid from a share issue in four months: "},{"text":"bridging loan","bold":true},{"text":". A bank buying a machine and renting it to a firm: "},{"text":"equipment leasing","bold":true},{"text":". Selling a client's new shares to the public: "},{"text":"issuing house","bold":true},{"text":". "},{"text":"NCDs","bold":true},{"text":": interbank instruments of "},{"text":"3 to 36 months","bold":true},{"text":" channelling commercial banks' surplus funds into merchant banks."}]},{"text":[{"text":"Merchant banks are wholesale because they mobilise large funds from firms and institutions, not because they sell goods. Examples today: FBN Merchant Bank, Coronation Merchant Bank. International-licence examples: Access, Zenith, First Bank, UBA, GTBank."}]},{"text":[{"text":"Indigenisation:","bold":true},{"text":" in 1973 the Federal Government took "},{"text":"40%","bold":true},{"text":" of the three big expatriate banks (now First Bank, Union Bank, UBA), raised to "},{"text":"60% in 1976","bold":true},{"text":"."}]}]}]},{"number":"5.3","title":"Development finance institutions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Development banks (DFIs, specialised banks):","bold":true},{"text":" government-owned, set up "},{"text":"jointly by the Federal Government and the CBN","bold":true},{"text":", to give "},{"text":"long-term finance to priority sectors","bold":true},{"text":" whose projects are too large or slow-maturing for conventional banks."}]},{"text":[{"text":"4 rationales:","bold":true},{"text":" (1) DMBs lend short because their deposits are short, leaving a "},{"text":"long-term finance gap","bold":true},{"text":"; (2) fund "},{"text":"socially desirable but commercially unprofitable","bold":true},{"text":" projects (housing, hence FMBN); (3) bridge the "},{"text":"information gap","bold":true},{"text":", on-lending funds from the World Bank and African Development Bank; (4) push catalyst sectors (agriculture, industry) with big long-run multiplier effects."}]}]},{"type":"table","header":[[{"text":"Institution"}],[{"text":"Year"}],[{"text":"Purpose"}]],"rows":[[[{"text":"NIDB"}],[{"text":"1964 (from ICON, 1959)"}],[{"text":"Long-term loans and equity to "},{"text":"medium and large","bold":true},{"text":" industry"}]],[[{"text":"NBCI"}],[{"text":"1973"}],[{"text":"Help Nigerians buy shares under the "},{"text":"Indigenisation (Enterprises Promotion) Decree 1972","bold":true},{"text":"; SMEs"}]],[[{"text":"NACB"}],[{"text":"1973 as NAB, NACB 1978"}],[{"text":"Agriculture and cooperatives"}]],[[{"text":"FMBN"}],[{"text":"1977 (from Nigerian Building Society, 1956)"}],[{"text":"Housing finance; apex mortgage bank"}]],[[{"text":"NERFUND"}],[{"text":"1989"}],[{"text":"Foreign-currency funds for SMEs, on-lent through banks; a fund, not a bank"}]],[[{"text":"NEXIM (Nigerian Export-Import Bank)"}],[{"text":"1991 (Act 38)"}],[{"text":"Export credit, "},{"text":"export credit insurance and guarantees","bold":true}]],[[{"text":"UDBN"}],[{"text":"1992 (Decree 51)"}],[{"text":"Urban infrastructure","bold":true},{"text":": markets, motor parks, mass transit, drainage, public toilets; now the Infrastructure Bank"}]],[[{"text":"BOI"}],[{"text":"2001"}],[{"text":"NIDB + NBCI + NERFUND"}]],[[{"text":"NACRDB, now "},{"text":"Bank of Agriculture","bold":true}],[{"text":"2000-2001"}],[{"text":"NACB + Peoples Bank + FEAP"}]],[[{"text":"DBN"}],[{"text":"2017"}],[{"text":"Wholesale $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 26, $study_guide$MSME funding through "},{"text":"participating financial institutions","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"NIDB functions:","bold":true},{"text":" identify and promote high value-added projects; mobilise funds and skills at home and abroad; long-term loans and equity. Services: loans to medium and large firms, equity stakes, World Bank funds for on-lending, information to foreign investors, technical help. It took "},{"text":"no current-account deposits","bold":true},{"text":"."}]},{"text":[{"text":"NBCI terms:","bold":true},{"text":" equity only if promoters provide "},{"text":"at least 30%","bold":true},{"text":"; loans repayable over "},{"text":"12 to 15 years","bold":true},{"text":"."}]},{"text":[{"text":"NACB aims:","bold":true},{"text":" food self-sufficiency, raw materials for industry, export crops for foreign exchange (all three)."}]},{"text":[{"text":"BOI purposes:","bold":true},{"text":" empower SMEs, revitalise ailing industries with fresh funds and ideas, modernise and diversify enterprises not yet moribund. It is "},{"text":"not","bold":true},{"text":" a lender of last resort."}]},{"text":[{"text":"Mortgage system:","bold":true},{"text":" Mortgage Institutions Decree "},{"text":"53 of 1989","bold":true},{"text":" created a "},{"text":"two-tier","bold":true},{"text":" market: "},{"text":"FMBN apex","bold":true},{"text":" (wholesale funds, oversight), "},{"text":"primary mortgage institutions","bold":true},{"text":" second tier (take deposits, lend to people to buy, build or improve homes). FMBN's "},{"text":"regulatory role passed to the CBN","bold":true},{"text":" (1998); CBN now licenses and supervises PMIs. FMBN still "},{"text":"manages the National Housing Fund","bold":true},{"text":"."}]},{"text":[{"text":"NHF (Decree 3 of 1992):","bold":true},{"text":" workers contribute "},{"text":"2.5% of monthly basic salary","bold":true},{"text":"."}]},{"text":[{"text":"Mortgage problems:","bold":true},{"text":" title documents, weak capital, no long-term funds, low incomes, ignorance, poor manpower, poverty."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why the mergers:","bold":true},{"text":" the 1990s crises brought loan defaults and distress. A "},{"text":"2000 World Bank review","bold":true},{"text":" blamed non-commercial governance, "},{"text":"politicised lending","bold":true},{"text":", poor credit discipline, poor internal direction, no diversification, "},{"text":"lack of quality staff","bold":true},{"text":", inappropriate funding vehicles; 78% of loans were non-performing."}]},{"text":[{"text":"NIDB = large industry; NBCI = small and medium firms and indigenisation."}]},{"text":[{"text":"NHF:","bold":true},{"text":" basic salary ₦180,000. Monthly = 180,000 × 2.5% = ₦4,500. Yearly = 4,500 × 12 = "},{"text":"₦54,000","bold":true},{"text":"."}]},{"text":[{"text":"A cashew exporter fearing a European buyer's default goes to "},{"text":"NEXIM","bold":true},{"text":". Funmi's bakery gets DBN money "},{"text":"through her commercial or microfinance bank","bold":true},{"text":"."}]},{"text":[{"text":"African Continental Bank was a regional-government commercial bank, not a development bank."}]}]}]},{"number":"5.4","title":"Peoples Bank, community banks and microfinance banks","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Specialised banks","bold":true},{"text":" for the urban poor and rural masses, giving funds in very small amounts."}]},{"text":[{"text":"Peoples Bank of Nigeria (1989):","bold":true},{"text":" loans "},{"text":"without collateral and without interest","bold":true},{"text":" (only a service charge), because the poor could not afford collateral or DMB interest rates. Repayment enforced by lending to members of "},{"text":"recognised trade groups","bold":true},{"text":" (peer pressure). "},{"text":"Challenges:","bold":true},{"text":" few skilled managers, high cost of many small loans, dependence on government funds, defaults, loss of funds placed with failed DMBs. Merged into NACRDB."}]},{"text":[{"text":"Community banks:","bold":true},{"text":" "},{"text":"Decree No. 46 of 1992","bold":true},{"text":". Capital "},{"text":"₦250,000","bold":true},{"text":" (1992), raised to "},{"text":"₦5,000,000","bold":true},{"text":" (2003). Supervised by the "},{"text":"National Board for Community Banks (NBCB)","bold":true},{"text":", which kept a fund for them to borrow in crisis. Same functions as commercial banks (deposits: savings, time, target; debentures; collections; ancillary services; credit) "},{"text":"except","bold":true},{"text":" (1) limited to their "},{"text":"own community","bold":true},{"text":", (2) "},{"text":"no foreign exchange","bold":true},{"text":" without CBN approval, (3) "},{"text":"not in the clearing house","bold":true},{"text":". Collapse causes: inflation, high costs, loan defaults, funds lost in distressed DMBs (not too much capital)."}]},{"text":[{"text":"Microfinance Policy, December 2005 (launched 15 December):","bold":true},{"text":" community banks to "},{"text":"convert to microfinance banks within 24 months","bold":true},{"text":" by meeting new capital. Elements: states and LGAs set aside "},{"text":"at least 1% of annual budgets","bold":true},{"text":"; Microfinance Development Fund; "},{"text":"deposit insurance for MFBs","bold":true},{"text":"; consultative committee; accreditation; MFI database."}]},{"text":[{"text":"2005 categories:","bold":true},{"text":" "},{"text":"unit MFB (₦20m)","bold":true},{"text":" and "},{"text":"state MFB (₦1bn)","bold":true},{"text":"."}]},{"text":[{"text":"Goals of MFBs:","bold":true},{"text":" diversified, affordable, dependable services to the "},{"text":"economically active poor","bold":true},{"text":"; mobilise savings; create jobs and raise household income; channel government micro-credit; pay salaries, gratuities and pensions for government."}]},{"text":[{"text":"Objectives of the policy:","bold":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 27, $study_guide$true},{"text":" access for the excluded; mainstream the informal sector; serve MSMEs; rural transformation; "},{"text":"linkages","bold":true},{"text":" between universal/development banks and MFBs. CBN supervision also "},{"text":"enhances monetary stability","bold":true},{"text":"."}]},{"text":[{"text":"Revised tiers (2019):","bold":true},{"text":" Tier 1 unit ₦200m (urban), Tier 2 unit ₦50m (rural), state ₦1bn, national ₦5bn."}]},{"text":[{"text":"MFB prohibitions:","bold":true},{"text":" "},{"text":"foreign exchange","bold":true},{"text":", real estate except own office, public-sector deposits (except for micro-credit programmes and payments)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MFBs do not finance multinationals' large projects or deal in dollars and domiciliary accounts; an Ibadan MFB selling US dollars is "},{"text":"not allowed","bold":true},{"text":"."}]},{"text":[{"text":"History is tested: ₦250,000 (1992) to ₦5,000,000 (before conversion); December 2005; unit and state."}]}]}]},{"number":"5.5","title":"The NDIC and bank distress","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NDIC:","bold":true},{"text":" set up by "},{"text":"Decree No. 22 of 1988","bold":true},{"text":", began operations "},{"text":"1989","bold":true},{"text":"; law now the NDIC Act 2023 (replacing the 2006 Act). Linked to "},{"text":"SAP deregulation","bold":true},{"text":", which swelled bank numbers (about 40 in 1986 to about 120 by the early 1990s)."}]},{"text":[{"text":"Rationale:","bold":true},{"text":" (1) complement CBN supervision as banks multiplied; (2) protect depositors, "},{"text":"especially small ones","bold":true},{"text":"; (3) prevent bank failure and loss of confidence; (4) ensure "},{"text":"orderly exit","bold":true},{"text":" of failing banks, reducing disruption. "},{"text":"Not","bold":true},{"text":" to protect shareholders or government deposits."}]},{"text":[{"text":"Functions:","bold":true},{"text":" insure deposit liabilities; assist banks in difficulty (loans, guarantees, take over management, arrange mergers); guarantee payment to depositors; act as "},{"text":"liquidator","bold":true},{"text":" (after the CBN revokes the licence: pays insured depositors, then shares asset proceeds among depositors and creditors); help monetary authorities with banking policy. It does "},{"text":"not","bold":true},{"text":" issue currency or control money supply."}]},{"text":[{"text":"Premium:","bold":true},{"text":" "},{"text":"15/16 of 1%","bold":true},{"text":" of total deposit liabilities a year (flat rate, 1988; the 2006 Act capped it at 15/16 of 1%)."}]},{"text":[{"text":"Cover per depositor:","bold":true},{"text":" ₦50,000 (1989) → ₦200,000 (2006) → "},{"text":"₦500,000 (2010)","bold":true},{"text":" → "},{"text":"₦5,000,000 for DMBs (2024)","bold":true},{"text":"; ₦2,000,000 for MFBs and primary mortgage banks. Balance above the cover is paid "},{"text":"pro rata as liquidation dividends","bold":true},{"text":"."}]},{"text":[{"text":"Subrogation:","bold":true},{"text":" once paid, the depositor's claim passes to the NDIC to that extent."}]},{"text":[{"text":"Sick bank:","bold":true},{"text":" cannot meet obligations to depositors/creditors as due, "},{"text":"or","bold":true},{"text":" losses have eroded or threaten shareholders' funds."}]},{"text":[{"text":"Supervision:","bold":true},{"text":" three concerns: "},{"text":"capital adequacy, loan concentration, liquidity ratio","bold":true},{"text":". Capital adequacy 1:10 = "},{"text":"₦1 of capital supports at most ₦10 of loans","bold":true},{"text":". "},{"text":"Off-site","bold":true},{"text":" = analysing periodic returns; "},{"text":"on-site","bold":true},{"text":" = examining books at the bank. NDIC and CBN examine jointly and share reports; under the 1988 Decree the CBN Governor chaired the NDIC Board (today the Board has its own chairman)."}]},{"text":[{"text":"Distress:","bold":true},{"text":" severe financial, operational and managerial weakness leaving a bank unable to meet obligations as due. "},{"text":"CAMEL:","bold":true},{"text":" Capital adequacy, Asset quality, Management, Earnings, Liquidity."}]},{"text":[{"text":"Symptoms:","bold":true},{"text":" boardroom squabbles, customer complaints, borrowing above market rates, window dressing, "},{"text":"persistent adverse clearing positions","bold":true},{"text":"."}]},{"text":[{"text":"Causes:","bold":true},{"text":" "},{"text":"internal:","italic":true},{"text":" weak management, insider abuse, fraud, inadequate capital, poor asset-liability management. "},{"text":"External:","italic":true},{"text":" macroeconomic instability, political interference, weak laws, oil shocks."}]},{"text":[{"text":"Cures:","bold":true},{"text":" better management and internal controls, adequate capital, stable macro policy, good regulation, fraud reduction."}]},{"text":[{"text":"Resolution = rehabilitation or liquidation.","bold":true},{"text":" Options: (1) "},{"text":"moral suasion","bold":true},{"text":" (dialogue and persuasion); (2) "},{"text":"holding actions","bold":true},{"text":" (stop advertising for deposits, stop new loans, aggressive debt recovery, inject fresh capital, no new capital projects); (3) "},{"text":"change of management","bold":true},{"text":" (interim board); (4) "},{"text":"NDIC assumes control and management","bold":true},{"text":" (runs it through an interim board, restructures, sells or liquidates if a turnaround costs too much); (5) comprehensive supervisory intervention; (6) "},{"text":"purchase and assumption","bold":true},{"text":" (healthy bank buys assets and takes over deposits); (7) "},{"text":"bridge banks","bold":true},{"text":"; (8) "},{"text":"liquidation","bold":true},{"text":", the "},{"text":"last option","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Premium:","bold":true},{"text":" deposits ₦64bn. 64,000,000,000 × 15/16 × 1/1$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 28, $study_guide$00 = "},{"text":"₦600,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Payout:","bold":true},{"text":" deposit ₦7.2m, cover ₦5m. Insured payment = ₦5,000,000; remainder 7,200,000 − 5,000,000 = "},{"text":"₦2,200,000","bold":true},{"text":" claimed from liquidation dividends as assets are sold."}]},{"text":[{"text":"Capital adequacy:","bold":true},{"text":" ₦2bn capital at 1:10 supports at most 2bn × 10 = ₦20bn of loans."}]},{"text":[{"text":"Bridge banks (August 2011):","bold":true},{"text":" Mainstreet, Enterprise and Keystone took over Afribank, Spring Bank and Bank PHB."}]},{"text":[{"text":"Criticisms and replies:","bold":true},{"text":" premium too heavy and should be "},{"text":"risk-based","bold":true},{"text":" (reply: higher rates would crush weak banks the scheme protects); ₦50,000 too small (reply: comparable abroad, plus pro-rata dividends); exclude government securities (reply: they are "},{"text":"assets","bold":true},{"text":", never insured deposits); scheme should be voluntary for big banks (reply: big banks fail too and their premiums "},{"text":"subsidise small banks","bold":true},{"text":"). Lack of offices in every state was "},{"text":"not","bold":true},{"text":" a criticism."}]},{"text":[{"text":"Achievements:","bold":true},{"text":" orderly resolution through rescues, sales, mergers and insured payouts. It never ended bank failure."}]}]}]},{"number":"5.6","title":"Other regulators and non-bank institutions","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Regulates"}]],"rows":[[[{"text":"CBN"}],[{"text":"Banks, MFBs, PMIs, BDCs, finance companies"}]],[[{"text":"NDIC"}],[{"text":"Deposit insurance"}]],[[{"text":"SEC","bold":true}],[{"text":"Apex capital market regulator","bold":true},{"text":": registers securities and operators, supervises exchanges, protects investors"}]],[[{"text":"NAICOM","bold":true}],[{"text":"Insurance companies, brokers, loss adjusters"}]],[[{"text":"PenCom","bold":true}],[{"text":"Pensions: licenses and oversees PFAs and custodians"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Pensions:","bold":true},{"text":" before 2004, civil service pensions were an "},{"text":"unfunded defined benefit","bold":true},{"text":" scheme paid from annual revenue. "},{"text":"Pension Reform Act 2004","bold":true},{"text":" created the "},{"text":"contributory","bold":true},{"text":" scheme (7.5% + 7.5%); "},{"text":"2014 Act","bold":true},{"text":": "},{"text":"employer 10%, employee 8%","bold":true},{"text":". Features: contributory; individual "},{"text":"retirement savings account (RSA)","bold":true},{"text":"; fully funded; managed by "},{"text":"PFAs","bold":true},{"text":", assets held by "},{"text":"custodians (PFCs)","bold":true},{"text":"."}]},{"text":[{"text":"Finance companies:","bold":true},{"text":" leasing, hire purchase, factoring, LPO finance; licensed by CBN."}]},{"text":[{"text":"Bureaux de change (1989):","bold":true},{"text":" retail forex to small users; originally only "},{"text":"foreign bank notes, coins and buying travellers' cheques","bold":true},{"text":"."}]},{"text":[{"text":"Discount houses (from 1992, FSDH first):","bold":true},{"text":" "},{"text":"intermediaries between the CBN and banks","bold":true},{"text":", trading in and holding Treasury Bills, commercial bills and short-term securities. Most later became merchant banks."}]},{"text":[{"text":"Unit trusts:","bold":true},{"text":" pool small savers' funds for diversified investment."}]},{"text":[{"text":"Insurance:","bold":true},{"text":" risk transfer plus financial intermediation; life and non-life."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos PFA seeking approval goes to "},{"text":"PenCom","bold":true},{"text":", not SEC or NAICOM. FDI = "},{"text":"Foreign Direct Investment","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Intermediaries move savings to investment: pooling, maturity transformation, lower risk and cost."}]},{"text":[{"text":"DMBs = commercial (retail) + merchant (wholesale; acceptances are their traditional function)."}]},{"text":[{"text":"Universal banking 2001-2010; then licence types. Capital: ₦25bn (2005); ₦500bn/₦200bn/₦50bn (2026). BOFIA 2020."}]},{"text":[{"text":"BOI = NIDB + NBCI + NERFUND; Bank of Agriculture = NACB + Peoples Bank + FEAP."}]},{"text":[{"text":"FMBN apex, PMIs second tier; NHF 2.5% of basic salary."}]},{"text":[{"text":"Community banks (Decree 46, 1992) became MFBs (December 2005)."}]},{"text":[{"text":"NDIC 1988: premium 15/16 of 1%; cover ₦50,000 → ₦500,000 → ₦5m."}]},{"text":[{"text":"Liquidation is the last resort; moral suasion is dialogue."}]},{"text":[{"text":"SEC, NAICOM, PenCom regulate capital market, insurance, pensions."}]}]}],"theory":{"itemId":"b7457b9f-2007-595e-b06a-17c072779a6e","question":[{"type":"paragraph","text":[{"text":"A deposit money bank had total deposit liabilities of ₦48 billion. (a) What annual premium did it pay at 15/16 of 1%? (b) It later fails. A depositor holds ₦9 million. Using the ₦5 million cover, how is she paid?"}]}]},"practice":[{"topic":"The Nigerian Banking Structure, Savings and Investment","named":false}]}},{"kind":"note","itemId":"8f86e2a0-f7a8-5bc9-b549-559655739f8a","sourceKey":"guide-topic:6","position":6,"payload":{"title":"The Nigerian Money Market","body":"What a money market is and how it differs from the capital market; why Nigeria set one up; its structure and operators; every instrument with its date; discount houses and the lines of defence; growth factors, appraisal and challenges; Treasury bill, call money and repo computations.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What a money market is and how it differs from the capital market; why Nigeria set one up; its structure and operators; every instrument with its date; discount houses and the lines of defence; growth factors, appraisal and challenges; Treasury bill, ca$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 29, $study_guide$ll money and repo computations."}],"lessons":[{"number":"6.1","title":"Meaning and features of the money market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money market:","bold":true},{"text":" a market for buying and selling "},{"text":"short-term financial instruments or investible funds","bold":true},{"text":", usually with maturities of "},{"text":"up to one year","bold":true},{"text":". Money is bought and sold like any other commodity. What is traded are "},{"text":"money market instruments","bold":true},{"text":"."}]},{"text":[{"text":"Capital market:","bold":true},{"text":" the market for buying and selling "},{"text":"medium- to long-term","bold":true},{"text":" instruments (2 years to 30 or more; equity is perpetual)."}]},{"text":[{"text":"Features of the money market:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Short-term instruments (up to one year)."}]},{"text":[{"text":"Highly liquid: quickly turned into cash."}]},{"text":[{"text":"Low risk: issuers are creditworthy (government, big banks, blue-chip firms)."}]},{"text":[{"text":"Wholesale and professional:","bold":true},{"text":" large deals dominated by institutions with specialised knowledge."}]},{"text":[{"text":"No single trading floor: deals are done by telephone and electronic platforms."}]}]}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Money market"}],[{"text":"Capital market"}]],"rows":[[[{"text":"Term"}],[{"text":"Short (up to 1 year)"}],[{"text":"Medium to long"}]],[[{"text":"Main purpose"}],[{"text":"Short-term "},{"text":"liquidity adjustment","bold":true}],[{"text":"Turning savings into "},{"text":"long-term investment","bold":true}]],[[{"text":"Apex regulator"}],[{"text":"CBN","bold":true}],[{"text":"SEC","bold":true},{"text":" (Securities and Exchange Commission)"}]],[[{"text":"Dominant institutions"}],[{"text":"Deposit money banks","bold":true}],[{"text":"Non-bank financial institutions","bold":true}]],[[{"text":"Instruments"}],[{"text":"TBs, CPs, CDs, BAs, call money"}],[{"text":"Shares (equities), bonds, debentures, mortgages"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"abiding (most basic) distinction","bold":true},{"text":" is the "},{"text":"term and liquidity","bold":true},{"text":" of the instruments."}]},{"text":[{"text":"Both markets have a "},{"text":"primary market","bold":true},{"text":" (new issues, raising new funds) and a "},{"text":"secondary market","bold":true},{"text":" (resale of existing securities)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: shares, equities, debentures, bonds and mortgages are "},{"text":"capital market","bold":true},{"text":" instruments, never money market ones."}]},{"text":[{"text":"Today most Nigerian money market trading (Treasury bills, commercial paper) is done over the counter on the FMDQ Securities Exchange platform, not on a stock exchange floor."}]}]}]},{"number":"6.2","title":"Why Nigeria needed a money market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Before the CBN (1958/59) Nigeria had no money market.","bold":true},{"text":" 4 consequences:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Businessmen and industrialists had no local market to raise funds."}]},{"text":[{"text":"Surplus funds were "},{"text":"sent abroad to the London money market","bold":true},{"text":"."}]},{"text":[{"text":"Government had no machinery for mobilising resources as independence approached."}]},{"text":[{"text":"Monetary policy was futile while foreign banks, run on conditions abroad, dominated finance."}]}]}]},{"text":[{"text":"Rationale (reasons for establishing it):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Government's need to "},{"text":"bridge the gap between expenditure needs and expected revenue","bold":true},{"text":" (Treasury bills even out seasonal revenue)."}]},{"text":[{"text":"Nigerianisation of the credit base:","bold":true},{"text":" keep funds in Nigeria for local credit needs instead of letting them flow overseas."}]},{"text":[{"text":"Firms' need for "},{"text":"working capital","bold":true},{"text":" and traders' need to "},{"text":"finance trade","bold":true},{"text":" (sometimes overnight)."}]},{"text":[{"text":"Machinery for government's short-term financing."}]},{"text":[{"text":"A step to independent nationhood ("},{"text":"monetary autonomy","bold":true},{"text":")."}]},{"text":[{"text":"Perform all traditional money market functions. Banks also gain a way to "},{"text":"economise on cash and adjust liquidity","bold":true},{"text":", and the CBN a basis for "},{"text":"effective monetary policy","bold":true},{"text":"."}]}]}]},{"text":[{"text":"On the supply side, banks and multinationals hold "},{"text":"excess funds","bold":true},{"text":" they want to invest short-term and safely."}]},{"text":[{"text":"4 prerequisites for a money market:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Short-term funds whose owners are willing to invest them."}]},{"text":[{"text":"A "},{"text":"continuous and sufficient flow of assets of varying maturities","bold":true},{"text":"."}]},{"text":[{"text":"Intermediaries","bold":true},{"text":" to pool funds and invest them in short-term bills."}]},{"text":[{"text":"A "},{"text":"lender of last resort","bold":true},{"text":" (the central bank) to guarantee the liquidity of the assets."}]}]}]},{"text":[{"text":"4 functions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A basis for effective "},{"text":"monetary policy","bold":true},{"text":" and macroeconomic stability."}]},{"text":[{"text":"Deficit institutions borrow and surplus institutions invest "},{"text":"temporarily","bold":true},{"text":"; less idle cash."}]},{"text":[{"text":"Institutions hold par$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 30, $study_guide$t of their funds in liquid assets convertible to cash quickly."}]},{"text":[{"text":"The CBN can "},{"text":"gauge scarcity or surplus of funds through movements in money market interest rates","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Benefits:","bold":true},{"text":" (a) reduces "},{"text":"idle, barren cash","bold":true},{"text":": people earn income yet stay liquid; (b) banks hold less idle cash and invest secondary reserves; (c) ready gauge of fund scarcity for the CBN; (d) efficient execution of monetary policy."}]},{"text":[{"text":"Price discovery:","bold":true},{"text":" the money market sets benchmark short-term interest rates that serve as reference rates for other instruments."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"All of the above\" is the answer when options list government's revenue gap, firms' working capital and traders' finance: all three create the need."}]},{"text":[{"text":"A requirement that instruments be listed on the stock exchange is "},{"text":"not","bold":true},{"text":" a prerequisite."}]},{"text":[{"text":"How the money market helps monetary policy: the CBN "},{"text":"buys or sells short-term government securities (open market operations)","bold":true},{"text":" to inject or withdraw liquidity. It does not remove reserve requirements or fix prices of goods."}]}]}]},{"number":"6.3","title":"Structure and operators","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Apex institution:","bold":true},{"text":" the "},{"text":"CBN","bold":true},{"text":" (current Governor: Olayemi Cardoso, since 2023)."}]},{"text":[{"text":"Structure:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Formal (organised) market:","bold":true},{"text":" CBN open market operations, CBN standing facilities, the "},{"text":"interbank market","bold":true},{"text":", the discount market, primary and secondary markets in Treasury bills and other instruments."}]},{"text":[{"text":"Informal market:","bold":true},{"text":" esusu, ajo, isusu and other rotating contribution clubs, thrift collectors and money lenders."}]}]}]},{"text":[{"text":"Interbank market:","bold":true},{"text":" banks "},{"text":"lend to and borrow from each other","bold":true},{"text":" (often overnight) to manage daily liquidity, at rates set by supply and demand."}]},{"text":[{"text":"Standing facilities (CBN):","bold":true},{"text":" "},{"text":"Standing Lending Facility (SLF):","bold":true},{"text":" a bank short of funds borrows "},{"text":"overnight from the CBN","bold":true},{"text":" against eligible securities. "},{"text":"Standing Deposit Facility (SDF):","bold":true},{"text":" a bank with surplus places it overnight with the CBN."}]},{"text":[{"text":"Operators:","bold":true},{"text":" CBN; discount houses (historically); Federal and state governments; commercial, merchant, universal and (today) non-interest and other deposit money banks; specialised banks (community, now microfinance, banks; People's Bank); savings-type institutions; statutory boards and corporations; NSITF; mortgage and finance houses; insurance companies; pension funds; large corporations; individuals; local governments."}]},{"text":[{"text":"Lines of defence for a bank short of cash:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"First line:","bold":true},{"text":" "},{"text":"call money / interbank borrowing","bold":true},{"text":"."}]},{"text":[{"text":"Second line:","bold":true},{"text":" "},{"text":"discounting bills","bold":true},{"text":" (e.g. Treasury bills) for cash."}]}]}]},{"text":[{"text":"Discount house:","bold":true},{"text":" a non-bank institution \"trading in and holding Treasury bills, commercial bills and other securities\", acting as "},{"text":"intermediary between the CBN and licensed banks","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Structure: "},{"text":"oligopolistic","bold":true},{"text":", dominated (apart from government) by a few large banks, long the \"big three\" (First Bank, Union Bank, UBA). It is not perfectly competitive or a CBN monopoly."}]},{"text":[{"text":"Stockbrokers, registrars, issuing houses, the stock exchange and the SEC are "},{"text":"capital market","bold":true},{"text":" operators. A group of \"CBN, deposit money banks, Federal Government, large corporations\" is wholly money market."}]},{"text":[{"text":"An ajo scheme in Balogun Market, where traders pay ₦2,000 a day and each collects the pool in turn, is the "},{"text":"informal","bold":true},{"text":" money market."}]},{"text":[{"text":"A merchant bank buying 182-day Treasury bills at the CBN auction is in the "},{"text":"primary","bold":true},{"text":" market; reselling them to a pension fund two weeks later is the "},{"text":"secondary","bold":true},{"text":" market."}]},{"text":[{"text":"Discount houses history:","bold":true},{"text":" first suggested in the 1960s but dropped for lack of business. "},{"text":"First Securities Discount House (FSDH)","bold":true},{"text":" was set up in "},{"text":"1992","bold":true},{"text":", the first. Later came others such as Kakawa, Consolidated, Express and Associated Discount Houses. They bought government securities from the CBN, warehoused and sold them (so government got its full funds), took call loans from banks, and gave banks a place to "},{"text":"invest surplus short-term funds and get them back quickly","bold":true},{"text":". By about 2015 the leading ones had converted into "},{"text":"merchant banks","bold":true},{"text":" (FSDH Merchant Bank, Coronation Merchant Bank from Associated, FBNQuest Merchant Bank from Kakawa). Treasury bill auctions now run through banks acting as primary dealers."}]},{"text":[{"text":"OMO sale","bold":true},{"text":" of Treasury bills by the CBN "},{"text":"reduces banks' reserves and withdraws liquidity","bold":true},{"text":"; an OMO pur$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 31, $study_guide$chase injects liquidity."}]}]}]},{"number":"6.4","title":"Money market instruments","mustKnow":[{"type":"table","header":[[{"text":"Instrument"}],[{"text":"Key facts"}]],"rows":[[[{"text":"Treasury bill (TB)","bold":true}],[{"text":"Short-term "},{"text":"FG","bold":true},{"text":" debt issued by the "},{"text":"CBN on behalf of the Federal Government","bold":true},{"text":"; sold at a "},{"text":"discount","bold":true},{"text":", redeemed at "},{"text":"face value","bold":true},{"text":". First issued "},{"text":"1960","bold":true},{"text":", ₦18 million. Standard tenors "},{"text":"91, 182, 364 days","bold":true},{"text":" (91 is the shortest). Sold by "},{"text":"auction","bold":true},{"text":": authorised dealers (banks) tender for themselves and customers."}]],[[{"text":"Treasury certificate (TC)","bold":true}],[{"text":"1968","bold":true},{"text":", ₦20 million; "},{"text":"1 to 2 years","bold":true},{"text":", so higher return than TBs. Widened instruments and financed the "},{"text":"civil war and post-war reconstruction","bold":true},{"text":". Discontinued by 1996."}]],[[{"text":"CBN certificate","bold":true}],[{"text":"February "},{"text":"2001","bold":true},{"text":"; 180 and 360 days; minimum ₦250,000."}]],[[{"text":"CBN bills","bold":true}],[{"text":"September "},{"text":"2005","bold":true},{"text":"; issued by the CBN for "},{"text":"monetary policy (to mop up excess liquidity)","bold":true},{"text":" in OMO; originally 14 to 182 days."}]],[[{"text":"Certificate of deposit (CD)","bold":true}],[{"text":"Bank receipt for a time deposit, "},{"text":"3 months to 3 years","bold":true},{"text":". Introduced "},{"text":"1975","bold":true},{"text":" as an "},{"text":"interbank","bold":true},{"text":" instrument channelling "},{"text":"commercial banks' surplus funds to merchant banks","bold":true},{"text":". "},{"text":"Negotiable","bold":true},{"text":" (rate negotiated; can be "},{"text":"sold in the secondary market","bold":true},{"text":" before maturity) or "},{"text":"non-negotiable","bold":true},{"text":" (rate fixed by CBN; held to maturity)."}]],[[{"text":"Commercial paper (CP)","bold":true}],[{"text":"Short-term unsecured promissory note","bold":true},{"text":" of a large, creditworthy (blue-chip) firm, sold at a discount; backed only by the "},{"text":"issuer's reputation","bold":true},{"text":"; up to 270 days."}]],[[{"text":"Bankers' acceptance (BA)","bold":true}],[{"text":"A "},{"text":"bill of exchange drawn on a bank and accepted by it","bold":true},{"text":": the bank writes "},{"text":"\"Accepted\"","bold":true},{"text":" with an authorised signature across the face; 30 to 270 days."}]],[[{"text":"Call money","bold":true}],[{"text":"Very short loans (overnight or a few days) "},{"text":"repayable on demand","bold":true},{"text":"."}]],[[{"text":"Repo","bold":true}],[{"text":"Sale of securities with an agreement to "},{"text":"buy them back","bold":true},{"text":" at a set price and date."}]],[[{"text":"Tenored deposits","bold":true}],[{"text":"Call deposit","bold":true},{"text":" (no fixed maturity; ended by notice of 24 hours, 7 days, 14 days, 1 month); "},{"text":"fixed deposit","bold":true},{"text":" (fixed period, fixed rate)."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Discontinued schemes:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Call Money Fund","bold":true},{"text":" (1962 to 1974): banks lent surplus clearing balances to the fund at a CBN-fixed rate (between 2% and 2.5%) for investment in TBs; abolished because "},{"text":"government's financial position had improved","bold":true},{"text":"."}]},{"text":[{"text":"Produce Bills Finance Scheme","bold":true},{"text":" (from 1962, in the 1960s): a consortium of financial houses "},{"text":"discounted marketing boards' export produce bills","bold":true},{"text":"."}]},{"text":[{"text":"Bankers' Unit Fund","bold":true},{"text":" (1976 to 1988): banks pooled surplus funds with the CBN for investment mainly in "},{"text":"Federal Government stocks","bold":true},{"text":"; counted as liquid assets."}]}]}]},{"text":[{"text":"Eligible development stocks","bold":true},{"text":" (1975): FG development loan stocks with "},{"text":"less than three years to maturity","bold":true},{"text":", counted as banks' "},{"text":"liquid assets","bold":true},{"text":" for the liquidity ratio."}]},{"text":[{"text":"Modern instruments:","bold":true},{"text":" "},{"text":"Electronic Funds Transfer","bold":true},{"text":" (via "},{"text":"SWIFT","bold":true},{"text":") and the "},{"text":"smart card","bold":true},{"text":" (\"cashless wallet\" with a memory chip)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"TBs and TCs are "},{"text":"primary sources of liquidity","bold":true},{"text":" for a bank. A TB investor's return is "},{"text":"face value minus price paid","bold":true},{"text":": no dividends, no coupons."}]},{"text":[{"text":"CP vs commercial (trade) bill:","bold":true},{"text":" a trade bill arises from "},{"text":"an actual sale of goods on credit","bold":true},{"text":"; CP is "},{"text":"not tied to any trade transaction","bold":true},{"text":". A highly rated food company needing ₦2 billion for 120 days, unsecured and cheaper than a bank loan, issues "},{"text":"CP","bold":true},{"text":"."}]},{"text":[{"text":"A BA is "},{"text":"safer than CP","bold":true},{"text":" of the same maturity because a "},{"text":"bank has undertaken to pay","bold":true},{"text":". BAs mainly finance "},{"text":"international trade","bold":true},{"text":" (an importer's draft accepted by a bank)."}]},{"text":[{"text":"CBN bills vs TBs:","bold":true},{"text":" CBN bills mop up liquidity; TBs raise short-term funds for the FG."}]},{"text":[{"text":"Call deposit example:","bold":true},{"text":" Mrs Adeyemi places ₦5 million with no fixed maturity, ended by seven days' notice: a "},{"text":"call deposit","bold":true},{"text":"."}]},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 32, $study_guide$[{"text":"Under the SLF the bank "},{"text":"borrows","bold":true},{"text":"; under the SDF it "},{"text":"deposits","bold":true},{"text":". Don't swap them."}]}]}]},{"number":"6.5","title":"Money market computations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount (bank discount method) = Face value x rate x days/365"}]},{"text":[{"text":"Price = Face value - Discount"}]},{"text":[{"text":"Simple yield = (Face value - Price) / Price x 365/days"}]},{"text":[{"text":"Interest (call money, interbank, deposits) = Principal x rate x days/365"}]},{"text":[{"text":"Repo rate = (Repurchase price - Sale price) / Sale price x 365/days"}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1: Treasury bill price.","bold":true},{"text":" ₦20,000,000 face value, 182 days, 11% discount rate."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = 20,000,000 x 0.11 x 182/365 = ₦1,096,986.30 (rounded to kobo)."}]},{"text":[{"text":"Price = 20,000,000 - 1,096,986.30 = "},{"text":"₦18,903,013.70","bold":true},{"text":"."}]},{"text":[{"text":"The same method prices commercial paper: the issuer receives the price."}]}]},{"type":"paragraph","text":[{"text":"Example 2: yield.","bold":true},{"text":" Holding the bill above to maturity:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gain = 20,000,000 - 18,903,013.70 = ₦1,096,986.30."}]},{"text":[{"text":"Yield = 1,096,986.30 / 18,903,013.70 x 365/182 = 0.058032 x 2.005495 = "},{"text":"11.64%","bold":true},{"text":" (2 d.p.)."}]},{"text":[{"text":"The yield is "},{"text":"above","bold":true},{"text":" the 11% discount rate, because the gain is measured on the smaller price. A ₦1,000,000 91-day bill bought for ₦975,000: 25,000/975,000 x 365/91 = "},{"text":"10.28%","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Example 3: interbank interest.","bold":true},{"text":" ₦30,000,000 lent for 3 days at 18%: 30,000,000 x 0.18 x 3/365 = "},{"text":"₦44,383.56","bold":true},{"text":". For overnight use days = 1."}]},{"type":"paragraph","text":[{"text":"Example 4: repo rate.","bold":true},{"text":" A bank sells TBs for ₦4,900,000 and buys them back for ₦5,000,000 after 30 days."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gain to the buyer = ₦100,000."}]},{"text":[{"text":"Rate = 100,000 / 4,900,000 x 365/30 = 0.020408 x 12.166667 = "},{"text":"24.83%","bold":true},{"text":" (2 d.p.)."}]}]},{"type":"paragraph","text":[{"text":"Traps: use 365, not 360 (360 gives wrong options); the discount is not the price; for a repo divide by the "},{"text":"amount received","bold":true},{"text":", not the buy-back price."}]}]},{"number":"6.6","title":"Growth, appraisal and challenges","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5 factors that helped growth:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Establishment and "},{"text":"enthusiasm of the CBN","bold":true},{"text":"."}]},{"text":[{"text":"Policy of "},{"text":"Nigerianising the credit base","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"teleprinter","bold":true},{"text":" service, which "},{"text":"speeded up transfers between CBN branches and its Lagos head office","bold":true},{"text":"."}]},{"text":[{"text":"Permissive legislation","bold":true},{"text":" allowing new and varied instruments."}]},{"text":[{"text":"Government's financial requirements","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Appraisal (how well it performed):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economic function (no idle funds): "},{"text":"deficient","bold":true},{"text":": excess liquidity remains."}]},{"text":[{"text":"Nigerianising credit: worked in the 1960s, weakened after the oil boom (capital flight, external borrowing)."}]},{"text":[{"text":"First line of defence: weak since the Call Money Fund ended in "},{"text":"1974","bold":true},{"text":"; the interbank market is smaller and dearer."}]},{"text":[{"text":"Second line of defence (bill discounting): partly met since discount houses came."}]},{"text":[{"text":"Channel for CBN cash and basis for "},{"text":"OMO","bold":true},{"text":": partly met; OMO is now a key tool."}]},{"text":[{"text":"Short-term funds for government: "},{"text":"most effective","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Challenges:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Dominance by government securities","bold":true},{"text":"."}]},{"text":[{"text":"Narrow range of instruments","bold":true},{"text":"."}]},{"text":[{"text":"Lack of "},{"text":"depth, breadth and resilience","bold":true},{"text":"."}]},{"text":[{"text":"Low "},{"text":"public awareness","bold":true},{"text":"."}]},{"text":[{"text":"Oligopolistic structure","bold":true},{"text":" dominated by big banks."}]},{"text":[{"text":"Weak "},{"text":"institutional framework for probity, integrity and accountability","bold":true},{"text":"."}]},{"text":[{"text":"Information asymmetry","bold":true},{"text":": unequal access to market information, weakening pricing."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Listing of Treasury bills on foreign stock exchanges\" was "},{"text":"never","bold":true},{"text":" a growth factor."}]},{"text":[{"text":"\"Lack of market space in some cities\" is "},{"text":"not","bold":true},{"text":" a challenge: the market needs no physical location."}]},{"text":[{"text":"An unregulated market, too many instruments or too many small investors are all wrong options; the real problems are government dominance and too few instruments."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money market = short-term (up to 1 year), liquid, low-risk, wholesale; CBN apex, banks dominate. Capital market = long-term; SEC apex, non-bank institutions dominate."}]},{"text":[{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 33, $study_guide$text":"No money market before the CBN; surplus funds went to London. Key aim: Nigerianise the credit base."}]},{"text":[{"text":"4 prerequisites end with a lender of last resort."}]},{"text":[{"text":"First line of defence: call money/interbank; second: discounting bills."}]},{"text":[{"text":"TBs 1960 (91/182/364 days); TCs 1968; Call Money Fund 1962-74; Produce Bills from 1962; CDs and eligible stocks 1975; BUF to 1988; CBN certificate 2001; CBN bills 2005; FSDH 1992."}]},{"text":[{"text":"CP is unsecured, backed by reputation; BA is a bill accepted by a bank."}]},{"text":[{"text":"OMO sale withdraws liquidity; SLF lends to banks, SDF takes their deposits."}]},{"text":[{"text":"Discount = FV x r x days/365; price = FV - discount."}]}]}],"theory":{"itemId":"79757ac4-9d38-5934-b193-781b9f2373f8","question":[{"type":"paragraph","text":[{"text":"A ₦10,000,000 91-day Treasury bill is issued at a 10% discount rate. Find the price and the investor's simple yield (365-day year)."}]}]},"practice":[{"topic":"The Nigerian Money Market","named":false}]}},{"kind":"note","itemId":"df6f8e7b-2c44-56c6-b389-8ec18be571e2","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Organisational Structure of Clearing Banks","body":"What a clearing bank is and its six characteristics; the three levels of structure (governance, management, operational); board committees and executive officers; front, middle and back office and support functions; the branch network; line and staff, centralisation and decentralisation; unit, branch, group, chain and correspondent banking; the clearing process and the history of cheque clearing in Nigeria (manual, MICR, NACS, the 2004 settlement framework, electronic systems).","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What a clearing bank is and its six characteristics; the three levels of structure (governance, management, operational); board committees and executive officers; front, middle and back office and support functions; the branch network; line and staff, centralisation and decentralisation; unit, branch, group, chain and correspondent banking; the clearing process and the history of cheque clearing in Nigeria (manual, MICR, NACS, the 2004 settlement framework, electronic systems)."}],"lessons":[{"number":"7.1","title":"Clearing banks and their characteristics","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clearing banks:","bold":true},{"text":" financial institutions that are "},{"text":"members of a clearing house","bold":true},{"text":", "},{"text":"maintain accounts with the Central Bank","bold":true},{"text":" and can "},{"text":"participate directly in the clearing and settlement","bold":true},{"text":" of cheques, payments and other payment instruments. In Nigeria they are "},{"text":"commercial banks licensed by the CBN","bold":true},{"text":" to take part in the national clearing and settlement system."}]},{"text":[{"text":"6 key characteristics:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Membership of the clearing house","bold":true},{"text":" run by or under the CBN."}]},{"text":[{"text":"Settlement account with the CBN","bold":true},{"text":", used to settle inter-bank fund transfers and net clearing positions."}]},{"text":[{"text":"Wide branch network","bold":true},{"text":" across the country."}]},{"text":[{"text":"Large capital base","bold":true},{"text":" (must meet CBN minimum capital)."}]},{"text":[{"text":"Advanced technology","bold":true},{"text":" for payment processing."}]},{"text":[{"text":"Regulatory compliance:","bold":true},{"text":" subject to strict CBN supervision."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Regulatory framework (6):","bold":true},{"text":" CBN (primary regulator: licences, examinations); "},{"text":"NDIC","bold":true},{"text":" ("},{"text":"insures deposits","bold":true},{"text":", supervises, "},{"text":"resolves failed banks","bold":true},{"text":"); "},{"text":"BOFIA 2020","bold":true},{"text":" (main banking law; replaced BOFIA 1991); CBN Prudential Guidelines (capital, liquidity, lending limits); AML/CFT regulations; Consumer Protection Framework."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A clearing bank is "},{"text":"not","bold":true},{"text":" restricted to a single office in one locality; that describes a unit bank (Lesson 7.4). The settlement account at the CBN is "},{"text":"not","bold":true},{"text":" for safe custody, deposit insurance premiums or issuing currency."}]},{"text":[{"text":"Commercial banks such as First Bank, Zenith, Access, UBA and GTBank are clearing banks; microfinance banks are not direct clearing house members."}]},{"text":[{"text":"Challenges (7):","bold":true},{"text":" cybersecurity; compliance costs; fintech disruption; cost of branch networks; credit risk (bad loans); customers' demand for 24/7 service; talent."}]},{"text":[{"text":"Future trends (7):","bold":true},{"text":" digital transformation; agility (flatter structures); "},{"text":"centralisation of operations","bold":true},{"text":" (back office consolidated into central processing centres and shared services, for "},{"text":"efficiency","bold":true},{"text":"); fintech partnerships and open banking; data analytics; ESG (green) banking; hybrid work."}]}]}]},{"number":"7.2","title":"Governance and management levels","mustKnow":[{"type":"paragraph","text":[{"text":"The structure is hierarchical and examined at "},{"text":"3 levels:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Governance level:","bold":true},{"text":" the Board of Directors."}]},{"text":[{"text":"Management level:","bold":true},{"text":" executive management."}]},{"text":[{"text":"Operational level:","bold":true},{"text":" departments and units."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Board of Directors:","bold":true},{"text":" sits at the "},{"text":"apex","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 34, $study_guide$ld":true},{"text":"; responsible for "},{"text":"overall strategic direction and governance","bold":true},{"text":"."}]},{"text":[{"text":"Board composition:","bold":true},{"text":" "},{"text":"Board Chairman (non-executive)","bold":true},{"text":"; MD/CEO; Executive Directors (typically 3 to 5); independent Non-Executive Directors; representative of major shareholders (where applicable)."}]},{"text":[{"text":"7 board functions:","bold":true},{"text":" formulating strategic policies and objectives; appointing and overseeing senior management; approving major capital expenditure and investments; ensuring regulatory compliance and corporate governance; risk oversight and approving the risk management framework; reviewing and approving annual budgets and financial statements; protecting shareholders' interests."}]}]},{"type":"table","header":[[{"text":"Board committee"}],[{"text":"Job"}]],"rows":[[[{"text":"Audit"}],[{"text":"Financial reporting, internal controls, external audit"}]],[[{"text":"Risk Management"}],[{"text":"Monitors and manages all categories of risk"}]],[[{"text":"Credit"}],[{"text":"Reviews and approves large credit facilities; sets credit policies"}]],[[{"text":"Governance and Nomination"}],[{"text":"Board appointments, succession planning, governance"}]],[[{"text":"Remuneration"}],[{"text":"Compensation packages for executive management"}]],[[{"text":"IT Governance"}],[{"text":"Technology strategy, cybersecurity, digital transformation"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Board vs executive management:","bold":true},{"text":" the board "},{"text":"sets strategy and oversees","bold":true},{"text":"; executive management "},{"text":"runs the bank day to day","bold":true},{"text":" and implements board policies."}]}]},{"type":"table","header":[[{"text":"Executive"}],[{"text":"Responsibility"}]],"rows":[[[{"text":"MD/CEO"}],[{"text":"Highest-ranking executive: implements board decisions, develops strategy, leads the management team, represents the bank externally, ensures profitability and growth"}]],[[{"text":"Deputy Managing Director (DMD)"}],[{"text":"Assists the MD/CEO and acts in his absence; often oversees strategic business units"}]],[[{"text":"ED, Commercial Banking"}],[{"text":"Commercial, corporate and SME banking"}]],[[{"text":"ED, Retail Banking"}],[{"text":"Retail operations, consumer lending, branch network"}]],[[{"text":"ED, Treasury and Financial Markets"}],[{"text":"Treasury, foreign exchange, investment portfolio, money market"}]],[[{"text":"Chief Financial Officer (CFO)"}],[{"text":"Financial planning, accounting, financial reporting, investor relations"}]],[[{"text":"Chief Risk Officer (CRO)"}],[{"text":"Enterprise risk management: credit, market, operational risk"}]],[[{"text":"Chief Compliance Officer (CCO)"}],[{"text":"Regulatory compliance, AML, KYC"}]],[[{"text":"CTO/CIO"}],[{"text":"IT infrastructure, digital banking platforms, technology strategy"}]],[[{"text":"Chief Operations Officer (COO)"}],[{"text":"Operations, service delivery, process optimisation, efficiency"}]],[[{"text":"Company Secretary/Legal Adviser"}],[{"text":"Legal counsel, corporate governance, regulatory filings"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" the Chairman is "},{"text":"not","bold":true},{"text":" the MD/CEO; CBN governance rules keep the roles separate. The board does "},{"text":"not","bold":true},{"text":" process account-opening forms. Shareholders, not depositors, meet at the AGM."}]},{"text":[{"text":"Scenario links: a ₦25 billion loan above management's limit goes to the "},{"text":"Credit Committee","bold":true},{"text":"; finding a successor to a retiring chairman is "},{"text":"Governance and Nomination","bold":true},{"text":"; overseeing external auditors is "},{"text":"Audit","bold":true},{"text":"; cybersecurity oversight is "},{"text":"IT Governance","bold":true},{"text":" (not Risk Management)."}]},{"text":[{"text":"Kemi, who heads AML and KYC, is the "},{"text":"CCO","bold":true},{"text":", not the CRO. The CRO handles risk, not compliance."}]}]}]},{"number":"7.3","title":"Operational level, branch network and authority","mustKnow":[{"type":"paragraph","text":[{"text":"A. Front office (revenue generating; deals directly with customers)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Retail Banking:","bold":true},{"text":" personal accounts, consumer loans, cards."}]},{"text":[{"text":"Corporate Banking:","bold":true},{"text":" large corporates, project and trade finance."}]},{"text":[{"text":"Commercial Banking:","bold":true},{"text":" medium-sized enterprises, working capital."}]},{"text":[{"text":"SME Banking:","bold":true},{"text":" small businesses, micro-finance."}]},{"text":[{"text":"Treasury:","bold":true},{"text":" FX, money market, investment securities, asset-liability management."}]},{"text":[{"text":"Investment Banking:","bold":true},{"text":" mergers and acquisitions advisory, capital raising, underwriting."}]},{"text":[{"text":"Private Banking/Wealth Management:","bold":true},{"text":" high net-worth individuals, investment advisory, estate planning."}]}]},{"type":"paragraph","text":[{"text":"B. Middle office (support and control)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Risk Management:","bold":true},{"text":" credit, market and operational risk."}]},{"text":[{"text":"Compliance:","bold":true},{"text":" AML/CFT, sanctions, regulatory reporting."}]},{"text":[{"text":"Internal Audit:","bold":true},{"text":" independent review of controls."}]},{"text":[{"text":"Credit Administration:","bold":true},{"text":" "},{"text":"credit appraisal, loan documentation, collateral management, credit monitoring","bold":true},{"text":"."}]},{"text":[{"text":"Finance and Planning:","bold":true},{"text":" budgeting, management reporting."}]},{"text":[{"text":"Legal:","bold":true},{"text":" c$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 35, $study_guide$ontracts, litigation, debt recovery."}]}]},{"type":"paragraph","text":[{"text":"C. Back office (processing and settlement)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Operations:","bold":true},{"text":" transaction processing, account opening, cheque clearing, funds transfer."}]},{"text":[{"text":"Payment and Settlement:","bold":true},{"text":" clearing house operations, RTGS, NEFT, inter-bank settlement."}]},{"text":[{"text":"Reconciliation Unit:","bold":true},{"text":" account reconciliation, "},{"text":"nostro/vostro","bold":true},{"text":" accounts, "},{"text":"suspense account","bold":true},{"text":" resolution."}]},{"text":[{"text":"Customer Service:","bold":true},{"text":" enquiries, complaints."}]},{"text":[{"text":"Cards and Electronic Banking:","bold":true},{"text":" ATMs, POS, mobile banking."}]},{"text":[{"text":"Trade Services:","bold":true},{"text":" "},{"text":"letters of credit","bold":true},{"text":", bills for collection, trade documents."}]}]},{"type":"paragraph","text":[{"text":"D. Support functions:","bold":true},{"text":" Human Resources; Information Technology; Procurement/General Services; Marketing and Corporate Communications; Business Development; Internal Control."}]},{"type":"paragraph","text":[{"text":"Branch network (top down):","bold":true},{"text":" "},{"text":"Head Office → Regional/Zonal Office → Area/Divisional Office → Branches","bold":true},{"text":", plus "},{"text":"Agency banking/agents","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Head office:","bold":true},{"text":" executive management and central departments. "},{"text":"Regional/Zonal office:","bold":true},{"text":" "},{"text":"oversees clusters of branches in a geographical zone","bold":true},{"text":" (e.g. Lagos Zone); reports to head office. "},{"text":"Area office:","bold":true},{"text":" smaller clusters within a region. "},{"text":"Branches:","bold":true},{"text":" outlets serving customers directly (flagship, commercial, retail, mini). The "},{"text":"branch manager","bold":true},{"text":" has overall responsibility: business development, customer relations, approving loans within delegated limits."}]},{"text":[{"text":"Agency banking:","bold":true},{"text":" third-party agents (e.g. a shop owner) offering basic deposit and withdrawal services in underserved areas."}]},{"text":[{"text":"Line authority:","bold":true},{"text":" direct authority passed down the chain of command over people who carry out the bank's main business (e.g. MD → regional manager → branch manager)."}]},{"text":[{"text":"Staff authority (staff function):","bold":true},{"text":" specialists who "},{"text":"advise","bold":true},{"text":" line managers but "},{"text":"cannot command","bold":true},{"text":" them (legal, research, HR training)."}]},{"text":[{"text":"Centralisation:","bold":true},{"text":" decision-making concentrated at head office; branches refer major decisions upward. "},{"text":"Decentralisation:","bold":true},{"text":" authority delegated to branch managers, who decide locally."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" Internal Audit is "},{"text":"middle office","bold":true},{"text":", not front office. Payment and Settlement is "},{"text":"back office","bold":true},{"text":", not a support function. Treasury and Private Banking "},{"text":"are","bold":true},{"text":" front office. Credit Administration is middle office, distinct from Corporate Banking which sells loans."}]},{"text":[{"text":"An importer in Kano wanting a letter of credit is served by "},{"text":"Trade Services","bold":true},{"text":" (back office). A unit matching nostro and vostro entries is the "},{"text":"Reconciliation Unit","bold":true},{"text":"."}]},{"text":[{"text":"A branch manager is a "},{"text":"line","bold":true},{"text":" officer; the head of legal advice, a research analyst and an HR training officer are "},{"text":"staff","bold":true},{"text":". When the Legal Department reviews a loan contract but cannot order the branch to lend, it is a staff function."}]},{"text":[{"text":"An Ibadan branch manager who must send every small loan to Lagos shows "},{"text":"excessive centralisation","bold":true},{"text":" (delay, frustrated customers). "},{"text":"Decentralisation","bold":true},{"text":" gives "},{"text":"faster decisions that respond to local needs","bold":true},{"text":"; centralisation gives tighter uniform control."}]}]}]},{"number":"7.4","title":"Types of banking systems","mustKnow":[{"type":"table","header":[[{"text":"System"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Unit banking"}],[{"text":"Each bank is a separate entity, usually a single office, with its own management; operations restricted to one locality (USA tradition)"}]],[[{"text":"Branch banking"}],[{"text":"One bank operates many branches across the country under one head office (Nigeria, UK)"}]],[[{"text":"Group banking"}],[{"text":"Two or more banks, each keeping its separate name, controlled by a "},{"text":"holding company","bold":true},{"text":"; the controlled banks are "},{"text":"operating banks","bold":true}]],[[{"text":"Chain banking"}],[{"text":"Control of several separate banks by an "},{"text":"individual or group of individuals","bold":true},{"text":" through share ownership, with "},{"text":"no holding company","bold":true}]],[[{"text":"Correspondent banking"}],[{"text":"Small ("},{"text":"respondent","bold":true},{"text":") banks keep deposits with large city ("},{"text":"correspondent","bold":true},{"text":") banks, which give them services; it knits unit banks together"}]]]},{"type":"paragraph","text":[{"text":"Unit banking: merits","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Prevents monopoly banking."}]},{"text":[{"text":"Close personal relationship with, and knowledge of, local customers."}]},{"text":[{"text":"Quick local decisions; efficie$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 36, $study_guide$nt management."}]},{"text":[{"text":"Funds are used locally for local development."}]}]},{"type":"paragraph","text":[{"text":"Unit banking: demerits","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cannot grant large loans (small resources)."}]},{"text":[{"text":"Risk is not spread geographically."}]},{"text":[{"text":"Difficulty meeting a sudden rush of withdrawals."}]},{"text":[{"text":"Dependence on correspondent banks for remittance of funds, which is costly."}]},{"text":[{"text":"No economies of scale; savings facilities limited to one locality."}]}]},{"type":"paragraph","text":[{"text":"Branch banking: merits","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economies of large-scale operation."}]},{"text":[{"text":"Geographical spreading of risk","bold":true},{"text":" (losses in one area covered by profits elsewhere)."}]},{"text":[{"text":"Small cash reserves at each branch: "},{"text":"cash can be mobilised quickly from sister branches","bold":true},{"text":"."}]},{"text":[{"text":"Wider mobilisation of savings, including rural areas."}]},{"text":[{"text":"Cheap and easy remittance of funds."}]},{"text":[{"text":"Easier and more efficient "},{"text":"central bank control","bold":true},{"text":" of a few large banks."}]}]},{"type":"paragraph","text":[{"text":"Branch banking: demerits","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Can create "},{"text":"monopolistic or oligopolistic and bureaucratic conditions","bold":true},{"text":"."}]},{"text":[{"text":"Delay and red tape: branch managers refer decisions to head office."}]},{"text":[{"text":"Lack of personal touch with local customers."}]},{"text":[{"text":"Funds drained from rural to urban areas."}]}]},{"type":"paragraph","text":[{"text":"Group banking:","bold":true},{"text":" merits: economies of scale, central management, operating banks can "},{"text":"pool resources to finance large borrowings","bold":true},{"text":". Demerits: may lead to "},{"text":"monopoly","bold":true},{"text":"; holding company may "},{"text":"divert surplus reserves to its non-banking interests","bold":true},{"text":"; "},{"text":"failure of one operating bank can affect others","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group vs chain:","bold":true},{"text":" group banking uses a "},{"text":"holding company","bold":true},{"text":"; chain banking is control by "},{"text":"individuals","bold":true},{"text":" through share ownership (Chief Okonkwo and his brothers owning controlling shares in three banks). In both, the banks keep separate names."}]},{"text":[{"text":"Correspondent vs respondent:","bold":true},{"text":" the large city bank is the correspondent; the small community bank that keeps deposits with it is the "},{"text":"respondent","bold":true},{"text":". The correspondent clears cheques, remits funds, gives investment advice and joins in large loans for the respondent. It does not replace the CBN as lender of last resort and does not put banks under one holding company."}]},{"text":[{"text":"Nigerian commercial banks with hundreds of outlets across the 36 states and the FCT under one head office practise "},{"text":"branch banking","bold":true},{"text":"; some also sit under holding companies (e.g. Access Holdings, First HoldCo, formerly FBN Holdings)."}]},{"text":[{"text":"\"Close personal relationship with local customers\" is a "},{"text":"merit","bold":true},{"text":" of unit banking, not a demerit."}]}]}]},{"number":"7.5","title":"The clearing function and its history in Nigeria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clearing system:","bold":true},{"text":" the process of "},{"text":"obtaining values for non-in-house cheques among deposit money banks","bold":true},{"text":", usually carried out at the "},{"text":"clearing house of the CBN or its designated branches","bold":true},{"text":". Put simply: banks exchange cheques drawn on one another and settle the "},{"text":"net","bold":true},{"text":" amounts owed."}]},{"text":[{"text":"Lagos Clearing House:","bold":true},{"text":" a "},{"text":"cheque sorting (exchange) centre","bold":true},{"text":", not a stock exchange or commodity market. The CBN set up the first bankers' clearing house in "},{"text":"1961","bold":true},{"text":" for the Lagos zone."}]}]},{"type":"paragraph","text":[{"text":"7 steps of cheque clearing (in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Collection:","bold":true},{"text":" branches collect cheques deposited by customers."}]},{"text":[{"text":"Sorting:","bold":true},{"text":" by paying bank into "},{"text":"on-us","bold":true},{"text":" (drawn on the same bank, settled internally) and "},{"text":"other-bank","bold":true},{"text":" items."}]},{"text":[{"text":"Presentation:","bold":true},{"text":" other-bank cheques are presented to the clearing house."}]},{"text":[{"text":"Clearing session:","bold":true},{"text":" the clearing house coordinates the exchange between banks."}]},{"text":[{"text":"Settlement:","bold":true},{"text":" "},{"text":"net positions settled through settlement accounts at the CBN","bold":true},{"text":" (debits and credits)."}]},{"text":[{"text":"Return items:","bold":true},{"text":" "},{"text":"unpaid cheques sent back through the clearing system with reasons","bold":true},{"text":"."}]},{"text":[{"text":"Customer notification","bold":true},{"text":" of cleared or returned items."}]}]},{"type":"paragraph","text":[{"text":"History (dates):","bold":true}]},{"type":"table","header":[[{"text":"Period"}],[{"text":"Key facts"}]],"rows":[[[{"text":"Manual (from 1961)"}],[{"text":"Bank representatives met physically to exchange cheques and present claims; up to 8 hours to know net positions; up to 27 days for customers to get value"}]],[[{"text":"MICR (from 1988)"}],[{"text":"Magnetic Ink Character Recognit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 37, $study_guide$ion, to speed machine processing and shorten clearing; phased from CBN in 1988; Lagos zone stopped conventional cheque exchange on 1 July 1994; reject rate about 30% for lack of cheque standards"}]],[[{"text":"NACS (2002)"}],[{"text":"Nigeria Automated Clearing System: automated clearing began in 2002 with 22 banks; NACS is a department of "},{"text":"NIBSS","bold":true},{"text":" (Nigeria Inter-Bank Settlement System)"}]],[[{"text":"New settlement framework (1 April 2004)"}],[{"text":"Banks split into settlement and non-settlement banks"}]],[[{"text":"Cheque truncation (2012)"}],[{"text":"Image-based clearing; less physical movement of cheques"}]]]},{"type":"paragraph","text":[{"text":"NACS: 4 core objectives","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Efficiently and cost-effectively process clearing items using electronic data presentation."}]},{"text":[{"text":"Significantly reduce the clearing float.","bold":true}]},{"text":[{"text":"Maintain and enforce standards for clearing procedures."}]},{"text":[{"text":"Encourage development and integration of other electronic payment products."}]}]},{"type":"paragraph","text":[{"text":"NACS participants (3):","bold":true},{"text":" "},{"text":"Zonal Clearing House","bold":true},{"text":" (centre: registers participants, processes data, determines settlement positions, manages NACS infrastructure); "},{"text":"Direct participating bank","bold":true},{"text":" (through its Participating Bank Clearing Centre, PBCC, sends data straight to the ZCH; 21 at inception); "},{"text":"Indirect participating bank","bold":true},{"text":" (clears "},{"text":"through a direct participating bank","bold":true},{"text":")."}]},{"type":"paragraph","text":[{"text":"2004 framework:","bold":true},{"text":" "},{"text":"settlement bank","bold":true},{"text":" = a bank that clears and settles cheques "},{"text":"on behalf of other banks","bold":true},{"text":"; only settlement banks keep "},{"text":"settlement accounts","bold":true},{"text":" with the CBN and deposit collateral with it. "},{"text":"Non-settlement banks","bold":true},{"text":" keep "},{"text":"only operations accounts","bold":true},{"text":" with the CBN (for FX, cash and cash reserve requirements, always in credit) and clear through an "},{"text":"agency arrangement","bold":true},{"text":" with a settlement bank, depositing at least ₦250 million collateral with it."}]},{"type":"paragraph","text":[{"text":"Electronic systems:","bold":true},{"text":" "},{"text":"NEFT","bold":true},{"text":" (NIBSS Electronic Funds Transfer: "},{"text":"batch","bold":true},{"text":" processing); "},{"text":"RTGS","bold":true},{"text":" (Real-Time Gross Settlement: "},{"text":"individual large-value payments in real time","bold":true},{"text":"); "},{"text":"NIP","bold":true},{"text":" (NIBSS Instant Payment: "},{"text":"instant","bold":true},{"text":" transfer to another bank); "},{"text":"Cheque Truncation System","bold":true},{"text":" (electronic image-based clearing)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why the 2004 framework:","bold":true},{"text":" by 1995 over thirty banks persistently overdrew their CBN accounts through clearing; suspending a bank from clearing was too damaging, so the framework imposed market discipline to end overdrawn accounts. Settlement banks needed ₦15 billion (later ₦16 billion) clearing collateral and branches in all 22 clearing zones; seven were named before the 2005 consolidation (including UBA, First Bank, Union Bank, GTBank and Zenith)."}]},{"text":[{"text":"Benefits of automation:","bold":true},{"text":" shorter clearing cycle and "},{"text":"smaller clearing float","bold":true},{"text":", so customers get value faster (5 days cut to 3, now shorter); less rowdiness and late balancing; less fraud. Automation did "},{"text":"not","bold":true},{"text":" abolish cheques and did "},{"text":"not","bold":true},{"text":" remove banks' CBN accounts or allow unlimited overdrawing."}]},{"text":[{"text":"Today:","bold":true},{"text":" NIBSS (owned by the CBN and the banks) runs NACS, NIP and NEFT; the CBN runs RTGS and holds banks' settlement accounts. With cheque truncation, cheques now clear on the next working day (T+1)."}]},{"text":[{"text":"Traps:","bold":true},{"text":" NACS is run by "},{"text":"NIBSS","bold":true},{"text":", not CIBN, SEC or NDIC; NDIC does not settle clearing balances. A cheque drawn on Bank B paid into Bank A is an "},{"text":"other-bank item","bold":true},{"text":" presented through the clearing house; a cheque drawn on Bank A itself is "},{"text":"on-us","bold":true},{"text":". RTGS is real-time and gross; NEFT is batch."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clearing bank = clearing house member + CBN settlement account + direct clearing. Three levels: governance (board), management (executives), operational (departments)."}]},{"text":[{"text":"Board at the apex; Chairman non-executive; six committees: Audit, Risk, Credit, Governance and Nomination, Remuneration, IT Governance."}]},{"text":[{"text":"MD/CEO leads; DMD acts in his absence; CRO risk; CCO compliance, AML, KYC."}]},{"text":[{"text":"Front office earns revenue; middle office controls (incl. Internal Audit, Credit Administration); back office processes (Operations, Payment and Settlement, Reconciliation, Trade Services)."}]},{"text":[{"text":"Branch network: head office → region/zone → area → branch, plus agents."}]},{"text":[{"text":"Line commands; staff advises. Excessive centralisation causes delay; decentralisation speeds local decisions."}]},{"text":[{"text":"Unit, branch (Nigeria), group (holding company, operating banks), chain (individuals), correspondent (respondent banks)."}]},{"text":[{"text":"Clearing: collect → sort → present → session → settle at CBN → returns → notify."}]},{"text":[{"text":"Manual 1961, MICR 1988, NACS 2002 (NIBSS), settlement banks 1 April 2004, truncation $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 38, $study_guide$2012; NIP instant, RTGS real-time large value, NEFT batch."}]}]}],"theory":{"itemId":"cf183a1a-405b-5437-b01b-151c2507c180","question":[{"type":"paragraph","text":[{"text":"Distinguish a settlement bank from a non-settlement bank under the CBN's April 2004 framework, and list the steps in clearing a cheque."}]}]},"practice":[{"topic":"Organizational Structure of Clearing Banks","named":false}]}},{"kind":"note","itemId":"7f9bf555-6a8e-5d21-9568-bac17ccfe251","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Bills of Exchange and Cheques","body":"Negotiable instruments; bills of exchange, promissory notes and IOUs; acceptance, maturity, days of grace and discounting; holders, endorsement and dishonour; cheques, their parties, types and crossings; when a bank must not pay; and cheque clearing in Nigeria.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"Negotiable instruments; bills of exchange, promissory notes and IOUs; acceptance, maturity, days of grace and discounting; holders, endorsement and dishonour; cheques, their parties, types and crossings; when a bank must not pay; and cheque clearing in Nigeria."}],"lessons":[{"number":"8.1","title":"Negotiable instruments, bills, notes and IOUs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Law:","bold":true},{"text":" the Bills of Exchange Act (Cap B8, Laws of the Federation of Nigeria 2004), modelled on the English Bills of Exchange Act 1882."}]},{"text":[{"text":"Negotiable instrument:","bold":true},{"text":" a written document that promises or orders payment of a sum of money, is transferable by delivery or by endorsement and delivery, and gives the holder in due course a good title free from defects in the title of prior parties."}]},{"text":[{"text":"6 characteristics:","bold":true},{"text":" (1) writing, (2) signature, (3) unconditional promise or order, (4) fixed sum (sum certain in money), (5) payable on demand or at a fixed or determinable future time, (6) transferability."}]},{"text":[{"text":"Bill of exchange:","bold":true},{"text":" an unconditional order in writing, addressed by one person to another, signed by the person giving it, requiring the person to whom it is addressed to pay on demand or at a fixed or determinable future time a sum certain in money to or to the order of a specified person or to bearer."}]},{"text":[{"text":"Cheque:","bold":true},{"text":" a bill of exchange drawn on a banker payable on demand."}]},{"text":[{"text":"Promissory note:","bold":true},{"text":" an unconditional promise in writing made by one person to another, signed by the maker, engaging to pay on demand or at a fixed or determinable future time a sum certain in money to, or to the order of, a specified person or to bearer."}]},{"text":[{"text":"IOU (\"I owe you\"):","bold":true},{"text":" an informal document acknowledging a debt owed by one person to another. It is "},{"text":"not","bold":true},{"text":" a negotiable instrument: it cannot be assigned, transferred or sold."}]}]},{"type":"paragraph","text":[{"text":"Parties","bold":true}]},{"type":"table","header":[[{"text":"Instrument"}],[{"text":"Parties"}]],"rows":[[[{"text":"Bill of exchange"}],[{"text":"Drawer","bold":true},{"text":" (gives the order), "},{"text":"drawee","bold":true},{"text":" (ordered to pay; becomes "},{"text":"acceptor","bold":true},{"text":" once he accepts), "},{"text":"payee","bold":true},{"text":" (to be paid)"}]],[[{"text":"Cheque"}],[{"text":"Drawer (customer who writes it), drawee (always a "},{"text":"bank","bold":true},{"text":"), payee"}]],[[{"text":"Promissory note"}],[{"text":"Maker","bold":true},{"text":" (signs and promises to pay), payee: only 2 parties"}]]]},{"type":"paragraph","text":[{"text":"Bill versus promissory note","bold":true}]},{"type":"table","header":[[{"text":"Bill of exchange"}],[{"text":"Promissory note"}]],"rows":[[[{"text":"An "},{"text":"order","bold":true},{"text":" to pay"}],[{"text":"A "},{"text":"promise","bold":true},{"text":" to pay"}]],[[{"text":"3 parties"}],[{"text":"2 parties"}]],[[{"text":"A time bill needs acceptance"}],[{"text":"No acceptance"}]],[[{"text":"Drawer liable only if the drawee fails to pay"}],[{"text":"Maker is primarily liable"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mr Bello, who banks with Zenith Bank, writes a ₦250,000 cheque to Mrs Adeyemi: Bello = drawer, "},{"text":"Zenith Bank = drawee","bold":true},{"text":", Adeyemi = payee. The Central Bank of Nigeria is never the drawee of an ordinary customer's cheque."}]},{"text":[{"text":"Trap: a bill or a note must be in writing, so \"need not be in writing\" is always false. A promissory note can be payable on demand."}]},{"text":[{"text":"Contents of an IOU (5):","bold":true},{"text":" parties' details; payment information (amount, due date, interest, method); signatures of both parties; termination date; involvement of a legal practitioner."}]}]}]},{"number":"8.2","title":"Bills in operation: acceptance, maturity, days of grace and discounting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Acceptance:","bold":true},{"text":" the signification by the drawee of his assent to the order of the drawer. It must be written on the bill and signed by the drawee. After accepting he is the "},{"text":"acceptor","bold":true},{"text":" and is primarily liable."}]},{"text":[{"text":"General acceptance:","bold":true},{"text":" assents without qualification. "},{"text":"Qualified acceptance:","bold":true},{"text":" varies the bill's effect, e.g. "},{"text":"partial","bold":true},{"text":" (\"Accepted for ₦300,000 only\" on a ₦500,000 bill), "},{"text":"conditional","bold":true},{"text":", "},{"text":"local","bold":true},{"text":" (one place only), qualified as to "},{"text":"time","bold":true},{"text":"."}]},{"text":[{"text":"When payable:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"On demand (sight bill):","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 39, $study_guide$e},{"text":" expressed \"on demand\", \"at sight\" or \"on presentation\", or no time stated. A cheque is always on demand."}]},{"text":[{"text":"Usance (time) bill:","bold":true},{"text":" \"X days after date\", \"X days after sight\", or after an event "},{"text":"certain","bold":true},{"text":" to happen (e.g. someone's death)."}]}]}]},{"text":[{"text":"Presentment for acceptance is necessary","bold":true},{"text":" for a bill payable "},{"text":"after sight","bold":true},{"text":" (to fix maturity), a bill that says so, and a bill payable away from the drawee's residence or place of business."}]},{"text":[{"text":"Days of grace:","bold":true},{"text":" "},{"text":"3 days","bold":true},{"text":" are added to a bill not payable on demand, unless the bill says otherwise. Cheques and demand bills get none."}]},{"text":[{"text":"Counting:","bold":true},{"text":" exclude the day of the date (or of sight), include the day of payment."}]},{"text":[{"text":"Inland bill:","bold":true},{"text":" drawn and payable within Nigeria (or drawn in Nigeria on a resident). "},{"text":"Foreign bill:","bold":true},{"text":" any other."}]},{"text":[{"text":"Accommodation party:","bold":true},{"text":" signs as drawer, acceptor or endorser "},{"text":"without receiving value","bold":true},{"text":", to lend his name to another."}]},{"text":[{"text":"Discounting:","bold":true},{"text":" a bank buys an "},{"text":"accepted usance bill","bold":true},{"text":" before maturity for less than its face value."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = Face value x Rate x Days / 365"}]},{"text":[{"text":"Proceeds = Face value - Discount"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contingency trap:","bold":true},{"text":" \"30 days after the death of Chief Ade\" is valid (death is certain; only its date is unknown). \"On the day she gets married\" is "},{"text":"not","bold":true},{"text":" a bill: marriage may never happen. Any condition (\"provided the receipt is signed\") also destroys a bill or cheque."}]},{"text":[{"text":"\"Ninety days after sight pay Chika Nwosu or order ₦1,200,000\" is a "},{"text":"usance bill","bold":true},{"text":" and must be presented for acceptance to fix its maturity. A bill drawn in Accra and payable in Lagos is a "},{"text":"foreign bill","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1 (maturity):","bold":true},{"text":" bill dated 15 January, payable 60 days after date (not a leap year)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Exclude 15 January. Days left in January: 31 - 15 = 16."}]},{"text":[{"text":"February: 28 more = 44. March: 60 - 44 = 16, so 16 March."}]},{"text":[{"text":"Add 3 days of grace: due "},{"text":"19 March","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Same method: dated 1 March, 30 days after date: 30 days to 31 March, plus 3 = "},{"text":"3 April","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (discounting):","bold":true},{"text":" Mrs Okon's accepted bill of ₦800,000 matures in 73 days; her bank discounts at 10% a year (365-day year)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Discount = 800,000 x 0.10 x 73/365 = ₦16,000."}]},{"text":[{"text":"Proceeds = 800,000 - 16,000 = "},{"text":"₦784,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Another: ₦1,460,000 at 15% for 60 days: discount = 1,460,000 x 0.15 x 60/365 = ₦36,000; proceeds = "},{"text":"₦1,424,000","bold":true},{"text":". The bank collects the full face value at maturity; the difference is its income. It discounts only for credible customers, with at least two parties (e.g. acceptor and customer) of good standing. Cheques are not discounted: they are already payable on demand."}]}]},{"number":"8.3","title":"Holders, endorsement and dishonour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Holder:","bold":true},{"text":" the payee or endorsee who is in possession of the bill, or the bearer of it."}]},{"text":[{"text":"Holder in due course:","bold":true},{"text":" a holder who took the bill:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"complete and regular on the face of it;"}]},{"text":[{"text":"before it was overdue, and without notice of any previous dishonour;"}]},{"text":[{"text":"in good faith and for value;"}]},{"text":[{"text":"without notice of any defect in the title of the person who negotiated it."}]}]}]},{"text":[{"text":"He need "},{"text":"not","bold":true},{"text":" be the original payee. "},{"text":"Advantage:","bold":true},{"text":" he takes a good title free from defects in the title of prior parties."}]},{"text":[{"text":"Endorsement:","bold":true},{"text":" the signature of the holder on the instrument (usually on the back) made to transfer it. "},{"text":"Delivery","bold":true},{"text":" is transfer of possession; endorsement plus delivery transfers an order instrument; a bearer instrument passes by delivery alone."}]},{"text":[{"text":"Valid endorsement:","bold":true},{"text":" written on the bill itself and signed by the endorser; it must cover the "},{"text":"whole","bold":true},{"text":" bill (no partial endorsement)."}]},{"text":[{"text":"Types of endorsement:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Blank:","bold":true},{"text":" signature only; makes the instrument payable to "},{"text":"bearer","bold":true},{"text":"."}]},{"text":[{"text":"Special:","bold":true},{"text":" names the endorsee (\"Pay Chinedu Okeke or order\")."}]},{"text":[{"text":"Restrictive:","bold":true},{"text":" stops further negotiation (\"Pay Musa Ibrahim only\")."}]},{"text":[{"text":"Conditional:","bold":true},{"text":" adds a condition, which the payer may disregard."}]}]}]},{"text":[{"text":"Dishonour","bold":true},{"text":" happens in 2 ways$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 40, $study_guide$: by "},{"text":"non-acceptance","bold":true},{"text":" and by "},{"text":"non-payment","bold":true},{"text":"."}]},{"text":[{"text":"Notice of dishonour:","bold":true},{"text":" given to the drawer and endorsers to "},{"text":"preserve the holder's right of recourse","bold":true},{"text":" against them."}]},{"text":[{"text":"Noting:","bold":true},{"text":" a notary public's minute on the bill. "},{"text":"Protest:","bold":true},{"text":" the formal notarial certificate attesting dishonour."}]},{"text":[{"text":"Foreign bill","bold":true},{"text":" dishonoured: protest is "},{"text":"compulsory","bold":true},{"text":", or the drawer and endorsers are "},{"text":"discharged","bold":true},{"text":". "},{"text":"Inland bill:","bold":true},{"text":" noting or protest is "},{"text":"optional","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fictitious or non-existing payee:","bold":true},{"text":" the bill may be treated as payable to bearer."}]},{"text":[{"text":"Bill prohibiting transfer","bold":true},{"text":" (\"Pay Ade only\"): valid between the parties but not negotiable."}]},{"text":[{"text":"Material alteration","bold":true},{"text":" (date, sum, time or place of payment) without the assent of all parties liable: the bill is "},{"text":"avoided","bold":true},{"text":", except against a party who made, authorised or assented to it, and later endorsers."}]},{"text":[{"text":"Liability:","bold":true},{"text":" the acceptor is primarily liable; the drawer and endorsers are liable if it is dishonoured. Until a cheque is endorsed, the "},{"text":"drawer","bold":true},{"text":" alone is liable on it: the drawee bank never accepts a cheque, so it owes nothing to the holder (it answers to its customer under their contract)."}]},{"text":[{"text":"Thief and holder in due course:","bold":true},{"text":" a thief steals an uncrossed bearer cheque and passes it to Ada for goods; she takes it in good faith, for value, before overdue, without notice, complete and regular. Ada is a "},{"text":"holder in due course with a good title","bold":true},{"text":". If the cheque was crossed "},{"text":"\"not negotiable\"","bold":true},{"text":", Ada gets "},{"text":"no better title than the thief had","bold":true},{"text":"."}]},{"text":[{"text":"Trap: noting, protest, crossing and countermand are not ways of dishonour."}]}]}]},{"number":"8.4","title":"Cheques: features, types, crossings and advantages","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Characteristics of a cheque (7):","bold":true},{"text":" (1) in writing; (2) unconditional order; (3) drawn on a specified banker; (4) signed by the drawer; (5) payable on demand; (6) sum certain in money (amount specified); (7) payable to a specified person or order, or to bearer. It needs "},{"text":"no acceptance","bold":true},{"text":"."}]},{"text":[{"text":"Face of a completed cheque:","bold":true},{"text":" bank and branch, date, payee, amount in words and in figures, drawer's signature, cheque number and MICR code line. There is no acceptance signature."}]}]},{"type":"paragraph","text":[{"text":"Cheque versus time bill","bold":true}]},{"type":"table","header":[[{"text":"Cheque"}],[{"text":"Bill of exchange"}]],"rows":[[[{"text":"Drawee is always a banker"}],[{"text":"Drawee may be any person, including a banker"}]],[[{"text":"Always payable on demand"}],[{"text":"On demand or at a future time"}]],[[{"text":"No acceptance"}],[{"text":"Time bill is presented for acceptance"}]],[[{"text":"No days of grace"}],[{"text":"3 days of grace on time bills"}]],[[{"text":"Can be crossed"}],[{"text":"Not crossed"}]]]},{"type":"paragraph","text":[{"text":"Similarities:","bold":true},{"text":" both are negotiable instruments, unconditional written orders, with three parties."}]},{"type":"paragraph","text":[{"text":"Types of cheque","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Open:","bold":true},{"text":" not crossed; can be cashed over the counter of the drawee bank."}]},{"text":[{"text":"Crossed:","bold":true},{"text":" two parallel transverse lines across the face; payable only through a bank account."}]},{"text":[{"text":"Bearer:","bold":true},{"text":" payable to whoever presents it, without endorsement."}]},{"text":[{"text":"Order:","bold":true},{"text":" payable to the named payee or as he directs by endorsement."}]},{"text":[{"text":"Stale:","bold":true},{"text":" in circulation unreasonably long; Nigerian banks refuse a cheque more than "},{"text":"6 months","bold":true},{"text":" old."}]},{"text":[{"text":"Post-dated:","bold":true},{"text":" bears a future date; not paid before that date."}]},{"text":[{"text":"Undated:","bold":true},{"text":" not invalid in law, but bankers by custom refuse it until dated."}]},{"text":[{"text":"Certified:","bold":true},{"text":" marked by the drawee bank to confirm the drawer has sufficient funds."}]}]},{"type":"paragraph","text":[{"text":"Crossings","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"General:","bold":true},{"text":" two parallel lines, with or without \"& Co\"; pay only to a banker."}]},{"text":[{"text":"Special:","bold":true},{"text":" a bank's name between the lines (e.g. \"Guaranty Trust Bank Plc\"); pay "},{"text":"only to that bank","bold":true},{"text":"."}]},{"text":[{"text":"\"Not negotiable\":","bold":true},{"text":" a transferee gets no better title than his transferor."}]},{"text":[{"text":"\"Account payee only\":","bold":true},{"text":" a direction to the "},{"text":"collecting","bold":true},{"text":" bank to credit the proceeds only to the payee's account."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Who may cross:","bold":true},{"text":" the "},{"text":"drawer or a holder","bold":true},{"text":"; a banker may also cross for collection. A crossing is a "},{"text":"material part","bold":true},{"text":" of the cheque and may not be unlawfully$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 41, $study_guide$ obliterated or altered."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Benefits of crossing:","bold":true},{"text":" payment goes through a bank account; protects the owner against theft; helps trace who received payment. It does "},{"text":"not","bold":true},{"text":" let the payee cash faster over the counter; it stops that."}]},{"text":[{"text":"Advantages of cheques:","bold":true},{"text":" economise currency notes and coins; safety (no carrying cash); proof of payment; payment can be stopped against fraud; convenient for large and distant payments. A cheque does "},{"text":"not","bold":true},{"text":" guarantee the drawer has funds; it can bounce. Issuing a cheque that bounces for lack of funds is a criminal offence under the Dishonoured Cheques (Offences) Act (Cap D11, LFN 2004)."}]},{"text":[{"text":"Precautions in drawing a cheque:","bold":true},{"text":" write the amount in words and figures, and make them agree; leave no spaces; sign every alteration in full; date it; fill in the payee (never leave it blank); cross cheques sent by post; keep the cheque book safe."}]},{"text":[{"text":"Ngozi's cheque dated 2 January, presented 10 August: over 6 months, "},{"text":"refused as stale","bold":true},{"text":". A cheque dated 30 November presented on 15 November: "},{"text":"post-dated","bold":true},{"text":", refused until 30 November."}]}]}]},{"number":"8.5","title":"Paying, collecting and clearing cheques","mustKnow":[{"type":"paragraph","text":[{"text":"When the bank's authority to pay ends (or it must not pay):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insufficient funds (no balance or overdraft limit to cover it)."}]},{"text":[{"text":"Countermand:","bold":true},{"text":" in writing, clear, signed in line with the mandate, "},{"text":"before","bold":true},{"text":" the cheque is paid."}]},{"text":[{"text":"Notice of the customer's "},{"text":"death","bold":true},{"text":" (express or constructive)."}]},{"text":[{"text":"Suspicion that the cheque was lost or stolen (investigate first)."}]},{"text":[{"text":"Assignment of the credit balance to a third party."}]},{"text":[{"text":"Court injunction or "},{"text":"garnishee order","bold":true},{"text":" (a court order attaching the balance to satisfy a judgment debt)."}]},{"text":[{"text":"Notice of a "},{"text":"bankruptcy petition","bold":true},{"text":" (or a company's winding-up)."}]},{"text":[{"text":"Forgery","bold":true},{"text":" of the drawer's signature."}]},{"text":[{"text":"Irregularly drawn cheque (e.g. words and figures differ)."}]},{"text":[{"text":"Presentation outside banking hours or at the wrong branch."}]},{"text":[{"text":"A lawful order freezing the account."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Forgery:","bold":true},{"text":" the cheque is wholly inoperative; the bank has "},{"text":"no mandate","bold":true},{"text":" and cannot debit the customer."}]},{"text":[{"text":"Wrongful dishonour:","bold":true},{"text":" the bank is liable to the customer in "},{"text":"damages for breach of contract","bold":true},{"text":"."}]},{"text":[{"text":"Paying banker protection:","bold":true},{"text":" paying a crossed cheque according to the crossing, "},{"text":"in good faith and without negligence","bold":true},{"text":"."}]},{"text":[{"text":"Collecting banker protection:","bold":true},{"text":" receiving payment for a "},{"text":"customer","bold":true},{"text":" in good faith and without negligence. Collecting for a non-customer, or without identity checks, loses protection; the bank becomes liable to the true owner."}]},{"text":[{"text":"Clearing:","bold":true},{"text":" the procedure by which a bank collects the proceeds of a cheque drawn on another bank for its own customer. An "},{"text":"in-house (on-us)","bold":true},{"text":" cheque, drawn on and paid into the same bank, needs no interbank clearing."}]},{"text":[{"text":"MICR:","bold":true},{"text":" Magnetic Ink Character Recognition."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A new cheque book does "},{"text":"not","bold":true},{"text":" end authority to pay. Notice of death on Monday: a cheque presented Tuesday must "},{"text":"not","bold":true},{"text":" be paid, even if signed earlier. Proper return reasons: \"insufficient funds\", \"refer to drawer\", \"payment stopped\", \"account closed\"; a large amount or the payee banking elsewhere is no reason."}]},{"text":[{"text":"Before paying cash, a cashier checks:","bold":true},{"text":" regular and complete; drawn on that branch; not crossed; not post-dated; not stale; not stopped; properly endorsed."}]},{"text":[{"text":"Clearing history in Nigeria:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1961: first bankers' clearing house, Lagos, run by the CBN (manual exchange)."}]},{"text":[{"text":"1988: MICR introduced in phases; conventional cheque exchange ended at the Lagos Clearing House on 1 July 1994."}]},{"text":[{"text":"2002: "},{"text":"Nigeria Automated Clearing System (NACS)","bold":true},{"text":", run by the Nigeria Inter-Bank Settlement System ("},{"text":"NIBSS","bold":true},{"text":")."}]},{"text":[{"text":"1 April 2004: new settlement framework (settlement and non-settlement banks)."}]}]}]},{"text":[{"text":"NACS participants:","bold":true},{"text":" the "},{"text":"Zonal Clearing House","bold":true},{"text":" (centre: registers participants, processes data, fixes settlement positions); "},{"text":"direct participating banks","bold":true},{"text":" (own clearing centre, the PBCC, with MICR reader/sorters, collateral in treasury bills); "},{"text":"indirect participating banks","bold":true},{"text":" (take part "},{"text":"through a direct participating bank","bold":true},{"text":")."}]},{"text":[{"text":"Current position:","bold":true},{"text":" the clearing cycle fell from 5 days to 3; cheque truncation (2012) then brought n$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 42, $study_guide$ationwide "},{"text":"T+1","bold":true},{"text":" (next-day) clearing from 2013, through NIBSS."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bill = unconditional written "},{"text":"order","bold":true},{"text":"; note = "},{"text":"promise","bold":true},{"text":" (maker); cheque = bill drawn on a banker payable on demand; IOU = not negotiable."}]},{"text":[{"text":"Drawer writes, drawee pays (the bank for a cheque), payee receives; an accepting drawee becomes the acceptor."}]},{"text":[{"text":"Time bills: acceptance (general or qualified), "},{"text":"3 days of grace","bold":true},{"text":"; after-sight bills must be presented for acceptance."}]},{"text":[{"text":"Discount = Face x Rate x Days/365; proceeds = face - discount."}]},{"text":[{"text":"Holder in due course: regular, not overdue, good faith, value, no notice; gets a title free of defects."}]},{"text":[{"text":"Endorsements: blank (bearer), special, restrictive, conditional. Dishonour by non-acceptance or non-payment; foreign bills must be protested."}]},{"text":[{"text":"Crossings: general, special, \"not negotiable\", \"account payee\"; drawer or holder may cross."}]},{"text":[{"text":"Stale after 6 months; post-dated not paid early; undated not invalid."}]},{"text":[{"text":"Death, countermand, garnishee, bankruptcy and forgery end authority to pay; wrongful dishonour = damages."}]},{"text":[{"text":"Clearing: Lagos 1961, MICR 1988, NACS (NIBSS) 2002, T+1 from 2013."}]}]}],"theory":{"itemId":"b18a4814-169e-5a94-bd65-42e2358ab6f6","question":[{"type":"paragraph","text":[{"text":"A bill of exchange for ₦3,650,000 dated 5 May is payable 90 days after date. The holder discounts it with her bank on 28 June at 10% per annum (365-day year). Find the due date and the proceeds."}]}]},"practice":[{"topic":"Bills of Exchange and Cheques","named":false}]}},{"kind":"note","itemId":"ede397d8-af01-5f95-a344-f31dc97cc099","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Methods of Payment through the Banking System","body":"Domestic methods; standing orders, direct debits and their computations; international methods and Nostro/Vostro; electronic banking, cards and Nigerian payment systems; the e-Naira.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"Domestic methods; standing orders, direct debits and their computations; international methods and Nostro/Vostro; electronic banking, cards and Nigerian payment systems; the e-Naira."}],"lessons":[{"number":"9.1","title":"Domestic methods of payment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Domestic methods to list:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Standing order","bold":true},{"text":" (Lesson 9.2)"}]},{"text":[{"text":"Direct debit","bold":true},{"text":" (Lesson 9.2)"}]},{"text":[{"text":"Mail and telegraphic transfers","bold":true}]},{"text":[{"text":"Bank drafts","bold":true}]},{"text":[{"text":"Bank cheques","bold":true}]},{"text":[{"text":"Intra-bank transfers","bold":true}]},{"text":[{"text":"Banker's payments","bold":true}]},{"text":[{"text":"Personal cheques","bold":true}]},{"text":[{"text":"Credit transfer (bank giro)","bold":true}]}]}]},{"text":[{"text":"Personal cheque:","bold":true},{"text":" the "},{"text":"simplest and most common","bold":true},{"text":" method of paying a debt within the economy. Its weakness: "},{"text":"fraud and dishonour","bold":true},{"text":", so many creditors prefer drafts or standing orders."}]},{"text":[{"text":"Bank draft:","bold":true},{"text":" a cheque "},{"text":"drawn by a branch of a bank on another branch or on the head office of the same bank","bold":true},{"text":", signed by the "},{"text":"bank's own authorised signatories","bold":true},{"text":". The issuing branch sends the paying branch an "},{"text":"advice","bold":true},{"text":" with the draft's particulars so the paying branch can "},{"text":"confirm the draft is genuine","bold":true},{"text":". Because it is a "},{"text":"bank's own instrument, it is not normally dishonoured","bold":true},{"text":". Used for large payments, locally and internationally."}]},{"text":[{"text":"Bank cheque","bold":true},{"text":" (also called a certified cheque): issued by the bank on the customer's written request (paid for in cash or by his own cheque) and cleared in the usual way. It is used "},{"text":"within the same clearing area only","bold":true},{"text":", while a "},{"text":"bank draft is used where other clearing areas are involved","bold":true},{"text":", so a bank cheque is of narrower use."}]},{"text":[{"text":"Mail transfer (MT) and telegraphic transfer (TT):","bold":true},{"text":" the customer gives written instructions stating the "},{"text":"beneficiary's name, the beneficiary's bank, the account number and the amount","bold":true},{"text":"; the bank debits him and pays. A "},{"text":"TT is faster","bold":true},{"text":" (cable, telex or electronic message) than an MT (post)."}]},{"text":[{"text":"Intra-bank transfer:","bold":true},{"text":" a customer with "},{"text":"several accounts at the same bank","bold":true},{"text":" moves funds between them, e.g. from savings to current so that a cheque already issued can be paid."}]},{"text":[{"text":"Banker's payment:","bold":true},{"text":" an instrument "},{"text":"banks use to pay each other","bold":true},{"text":", (1) for services between banks such as "},{"text":"cash supplied","bold":true},{"text":" by one bank to another, and (2) for the "},{"text":"proceeds of a cheque sent for special clearing","bold":true},{"text":". It passes through clearing: the issuing bank is debited, the receiving bank credited."}]},{"text":[{"text":"Credit transfer (bank giro):","bold":true},{"text":" the payer fills "},{"text":"credit (giro) slips","bold":true},{"text":" at his own bank, and the funds are credited directly to the payees' accounts at the same or other banks."}]}]}],"explainMore":[{"type":"list","o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 43, $study_guide$rdered":false,"items":[{"text":[{"text":"Trap: neither a bank cheque nor a draft is drawn by the customer on his own account or by the CBN; the tested difference is "},{"text":"same clearing area (bank cheque)","bold":true},{"text":" versus "},{"text":"other clearing areas (draft)","bold":true},{"text":"."}]},{"text":[{"text":"Example: after heavy withdrawals, Bank X asks Bank Y for ₦50 million cash and settles with a banker's payment in favour of Bank Y; through clearing, Bank X is debited and Bank Y credited. In special clearing, the paying bank sends a banker's payment for the cheque's proceeds."}]},{"text":[{"text":"Domestic settlement between banks is "},{"text":"direct","bold":true},{"text":" (cheques, drafts or banker's payments) or "},{"text":"through the clearing house","bold":true},{"text":" (cheques, or credit and debit vouchers)."}]}]}]},{"number":"9.2","title":"Standing orders and direct debits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standing order:","bold":true},{"text":" an instruction by a customer to his bank to make "},{"text":"regular payments of a fixed amount","bold":true},{"text":" at weekly, monthly or quarterly intervals, from his account (current or savings), to a "},{"text":"named third party","bold":true},{"text":" at the same or another bank. It is signed "},{"text":"in line with the account mandate","bold":true},{"text":"; the bank acts as "},{"text":"agent","bold":true},{"text":"."}]},{"text":[{"text":"Used for (6):","bold":true},{"text":" insurance premiums; regular subscriptions; house rents; hire purchase instalments; instalment loan repayments; school fees. (Not one-off payments.)"}]},{"text":[{"text":"Information the bank needs before opening one (11):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the customer's application"}]},{"text":[{"text":"name of the customer giving the order"}]},{"text":[{"text":"name of the beneficiary"}]},{"text":[{"text":"address of the beneficiary"}]},{"text":[{"text":"destination of the remittance"}]},{"text":[{"text":"mode of payment (air, sea, land, rail and so on)"}]},{"text":[{"text":"amount to be remitted"}]},{"text":[{"text":"intervals of payment"}]},{"text":[{"text":"customer's signature"}]},{"text":[{"text":"account number of the applicant"}]},{"text":[{"text":"account number of the beneficiary"}]}]}]},{"text":[{"text":"Customer's duties (4):","bold":true},{"text":" give accurate information; keep sufficient funds; pay the bank's charges; "},{"text":"notify the bank promptly when the order is to be discontinued","bold":true},{"text":"."}]},{"text":[{"text":"Banker's duties (4):","bold":true},{"text":" handle the order with "},{"text":"diligence and care","bold":true},{"text":"; remit strictly according to the mandate, provided funds are available; warn the customer not to cause delay or non-payment (the bank is not responsible for these); send "},{"text":"periodic statements","bold":true},{"text":" to the customer."}]},{"text":[{"text":"Banker's rights (2):","bold":true},{"text":" charge "},{"text":"commission","bold":true},{"text":"; "},{"text":"cancel","bold":true},{"text":" the order where the customer has caused non-payment on the due date "},{"text":"three consecutive times or more","bold":true},{"text":"."}]},{"text":[{"text":"Advantages to the bank (2):","bold":true},{"text":" commission income; widens the range of services offered."}]},{"text":[{"text":"Advantages to the customer (4):","bold":true},{"text":" pays recurring items; provides a record of payment; cheap transmission charges; "},{"text":"the onus of paying on the due dates rests with the banker","bold":true},{"text":"."}]},{"text":[{"text":"Bank's considerations:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insufficient funds:","bold":true},{"text":" the bank "},{"text":"is not obliged to pay and incurs no liability","bold":true},{"text":" for not paying."}]},{"text":[{"text":"Payee asks the bank to cancel:","bold":true},{"text":" "},{"text":"disregard it unless the customer confirms","bold":true},{"text":"."}]},{"text":[{"text":"Payee refuses the payments:","bold":true},{"text":" "},{"text":"continue to make each payment as it falls due and notify the customer of each refusal","bold":true},{"text":"."}]},{"text":[{"text":"Payee asks why a payment is late:","bold":true},{"text":" do not answer; "},{"text":"advise the payee to contact the customer","bold":true},{"text":" (secrecy)."}]}]}]},{"text":[{"text":"The bank's obligation to pay stops when (4):","bold":true},{"text":" funds are insufficient; the balance is insufficient and there is "},{"text":"no credit (overdraft) arrangement","bold":true},{"text":"; the customer "},{"text":"countermands","bold":true},{"text":"; a "},{"text":"garnishee order","bold":true},{"text":" stops payments out of the account."}]},{"text":[{"text":"Direct debit:","bold":true},{"text":" the "},{"text":"beneficiary (creditor) initiates","bold":true},{"text":" the payment. The paying customer endorses (authorises) the creditor's document, and the creditor then sends signed debit claims to the bank "},{"text":"from time to time","bold":true},{"text":". Used by "},{"text":"insurance companies and finance houses","bold":true},{"text":"; suits "},{"text":"variable amounts","bold":true},{"text":"; the customer can cancel the authority."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Standing order"}],[{"text":"Direct debit"}]],"rows":[[[{"text":"Started by"}],[{"text":"the customer (payer)"}],[{"text":"the beneficiary (creditor), with the payer's signed authority"}]],[[{"text":"Amount"}],[{"text":"fixed"}],[{"text":"fixed or variable"}]],[[{"text":"Typical user"}],[{"text":"individual paying rent, fees"}],[{"text":"insurers, finance houses, clubs"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paying ₦45,000 rent to a landlord on the first of every month \"unt$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 44, $study_guide$il further notice\" is a standing order. An insurer sending signed debit claims under a policyholder's endorsed authority uses a direct debit; so should a gym whose fees change monthly, because a standing order is for a fixed amount."}]},{"text":[{"text":"Traps: \"the beneficiary writes to cancel\" does "},{"text":"not","bold":true},{"text":" end the duty to pay (only the customer cancels); sending statements and taking care are the "},{"text":"bank's","bold":true},{"text":" duties, notifying discontinuance is the "},{"text":"customer's","bold":true},{"text":"; the beneficiary's income is never needed."}]}]}]},{"number":"9.3","title":"Standing order computations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total debit","bold":true},{"text":" = standing order amount + commission (rate × amount) + postage."}]},{"text":[{"text":"Balance before","bold":true},{"text":" = opening balance (CR +, DR −) + credits − debits. "},{"text":"Balance after","bold":true},{"text":" = balance before − total debit."}]},{"text":[{"text":"Decision rule:","bold":true},{"text":" pay if the balance after is CR or a DR "},{"text":"within the approved overdraft limit","bold":true},{"text":"; otherwise the bank "},{"text":"does not pay","bold":true},{"text":"."}]},{"text":[{"text":"Annual commission","bold":true},{"text":" = rate × amount × number of payments in the year."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (Mr Emeka).","bold":true},{"text":" Standing order ₦5,000 due at month end. Opening balance ₦1,000 DR; cheque paid in ₦8,000; cheque book ₦100; cheque issued to Ben ₦1,950; cash lodged ₦920. Charges: ½% commission and ₦50 postage. Overdraft limit ₦1,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Debits: ₦1,000 (opening DR) + ₦100 + ₦1,950 = ₦3,050. Credits: ₦8,000 + ₦920 = ₦8,920."}]},{"text":[{"text":"Balance before: ₦8,920 − ₦3,050 = "},{"text":"₦5,870 CR","bold":true},{"text":"."}]},{"text":[{"text":"Commission 0.5% × ₦5,000 = ₦25; total debit ₦5,000 + ₦25 + ₦50 = ₦5,075."}]},{"text":[{"text":"Balance after: ₦5,870 − ₦5,075 = "},{"text":"₦795 CR","bold":true},{"text":", so the bank "},{"text":"pays","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (total debit).","bold":true},{"text":" ₦12,000 at ½% plus ₦100 postage: commission 0.5% × ₦12,000 = ₦60; total debit ₦12,000 + ₦60 + ₦100 = "},{"text":"₦12,160","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (within the limit).","bold":true},{"text":" Balance ₦4,000 CR; order ₦4,500; ½% and ₦50; limit ₦1,000. Charges ₦22.50 + ₦50 = ₦72.50; total debit ₦4,572.50; balance after ₦4,000 − ₦4,572.50 = "},{"text":"₦572.50 DR","bold":true},{"text":", inside the limit, so the bank "},{"text":"pays","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (beyond the limit).","bold":true},{"text":" Balance ₦3,000 CR; order ₦5,000; ½% and ₦50; limit ₦1,500. Total debit ₦5,075; balance after ₦3,000 − ₦5,075 = "},{"text":"₦2,075 DR","bold":true},{"text":", beyond ₦1,500, so the bank "},{"text":"does not pay","bold":true},{"text":". (Forgetting charges gives ₦2,000 DR, the trap.)"}]},{"type":"paragraph","text":[{"text":"Worked example 5 (1% commission).","bold":true},{"text":" Opening ₦2,500 CR; in ₦15,000 and ₦1,800; out ₦6,200 and ₦200. Balance before ₦12,900 CR; total debit ₦10,000 + ₦100 + ₦50 = ₦10,150; after "},{"text":"₦2,750 CR","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 6 (annual commission).","bold":true},{"text":" ₦25,000 monthly at ½%: ₦125 per payment × 12 = "},{"text":"₦1,500","bold":true},{"text":" (₦125 is one month only)."}]}]},{"number":"9.4","title":"International methods of payment and settlement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International methods (6):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Payment in advance:","bold":true},{"text":" the importer pays before shipment (safest for the exporter)."}]},{"text":[{"text":"Open account:","bold":true},{"text":" the exporter sends the "},{"text":"documents of title direct to the importer","bold":true},{"text":", loses control of the goods, and relies on the importer's honesty to remit after selling. "},{"text":"Riskiest","bold":true},{"text":" for the exporter; discouraged."}]},{"text":[{"text":"Clean collection:","bold":true},{"text":" "},{"text":"only the bill of exchange","bold":true},{"text":" is sent to the bank for collection."}]},{"text":[{"text":"Documentary collection:","bold":true},{"text":" the bill is sent "},{"text":"with commercial documents","bold":true},{"text":" (bill of lading, insurance certificate or policy). Still not certain, because the importer may not pay."}]},{"text":[{"text":"Documentary letter of credit (LC):","bold":true},{"text":" the "},{"text":"surest","bold":true},{"text":" method; a "},{"text":"bank's undertaking to pay","bold":true},{"text":" the exporter "},{"text":"provided he complies with the terms","bold":true},{"text":" of the credit."}]},{"text":[{"text":"Bill negotiation:","bold":true},{"text":" the exporter needing cash now "},{"text":"endorses and delivers","bold":true},{"text":" the bill to his bank, which pays the "},{"text":"face value less a discount","bold":true},{"text":" for commission and interest and collects the full amount at maturity."}]}]}]},{"text":[{"text":"Parties to an LC:","bold":true},{"text":" "},{"text":"issuing bank","bold":true},{"text":" = the "},{"text":"importer's bank","bold":true},{"text":", which opens the credit in the exporter's favour; "},{"text":"advising bank","bold":true},{"text":" = the "},{"text":"exporter's bank","bold":true},{"text":", which tells the exporter the credit has been opened."}]},{"text":[{"text":"D/P (documents against payment):","bold":true},{"text":" documents of title released when the bill is "},{"text":"p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 45, $study_guide$aid","bold":true},{"text":". "},{"text":"D/A (documents against acceptance):","bold":true},{"text":" released when the bill is "},{"text":"accepted","bold":true},{"text":"."}]},{"text":[{"text":"In all these methods, the actual money moves by "},{"text":"mail transfer, telegraphic transfer or bank draft","bold":true},{"text":"."}]},{"text":[{"text":"Nostro","bold":true},{"text":" (\"our\" in Latin): an account a "},{"text":"Nigerian bank keeps with a correspondent bank abroad","bold":true},{"text":", in foreign currency, to receive export proceeds and make foreign payments."}]},{"text":[{"text":"Vostro","bold":true},{"text":" (\"your\" in Latin): an account a "},{"text":"foreign bank keeps with a Nigerian bank","bold":true},{"text":", in naira, to settle its obligations in Nigeria."}]},{"text":[{"text":"Bill negotiation:","bold":true},{"text":" amount received = face value − (discount rate × face value)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exporter's risk, least to most: payment in advance, letter of credit, documentary collection, clean collection, open account."}]},{"text":[{"text":"LC process: sale agreed; issuing bank opens the credit; advising bank informs the exporter; goods shipped; documents released only on payment or acceptance, so the exporter keeps control."}]},{"text":[{"text":"Point of view decides the name: a London bank's naira account with Zenith Bank in Lagos is a "},{"text":"Vostro","bold":true},{"text":" account to Zenith Bank (and a Nostro account to the London bank)."}]},{"text":[{"text":"Worked example (bill negotiation, bank figures).","bold":true},{"text":" Face value ₦800,000; discount 2.5%. Discount = 0.025 × ₦800,000 = ₦20,000. Exporter receives ₦800,000 − ₦20,000 = "},{"text":"₦780,000","bold":true},{"text":"."}]}]}]},{"number":"9.5","title":"Electronic banking, cards and the Nigerian payment system","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic banking:","bold":true},{"text":" delivering banking services through electronic channels: "},{"text":"payment cards","bold":true},{"text":" (credit, cheque, charge, debit and cash cards), "},{"text":"electronic funds transfer, ATMs, POS terminals, telephone and internet (home) banking","bold":true},{"text":". Over-the-counter cash withdrawal with a signed slip is "},{"text":"not","bold":true},{"text":" e-banking."}]},{"text":[{"text":"Problems with cash that pushed banks to alternatives (4):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the "},{"text":"falling value of the naira","bold":true},{"text":" means large sums must be carried"}]},{"text":[{"text":"single over-the-counter transactions can run into millions of naira"}]},{"text":[{"text":"carrying cash invites "},{"text":"robbery and loss of life","bold":true}]},{"text":[{"text":"banks spend heavily on "},{"text":"staff and note-counting machines","bold":true}]}]}]},{"text":[{"text":"E-banking products in Nigeria (4):","bold":true},{"text":" "},{"text":"electronic smart card; electronic funds transfer; telephone banking; internet banking.","bold":true}]},{"text":[{"text":"Smart card:","bold":true},{"text":" looks like a credit card but has an "},{"text":"intelligent memory chip","bold":true},{"text":" that stores value and keeps an "},{"text":"up-to-date record of the transactions","bold":true},{"text":" made with it. Called a "},{"text":"\"cashless wallet\"","bold":true},{"text":". Value can be loaded and withdrawn."}]},{"text":[{"text":"Electronic funds transfer (EFT):","bold":true},{"text":" "},{"text":"electronically recorded pre-authorised debits and credits","bold":true},{"text":" that "},{"text":"replace paper cheques","bold":true},{"text":". Three areas: between financial institutions; wholesale (corporate), e.g. the "},{"text":"direct deposit (payroll) programme","bold":true},{"text":" paying salaries straight into staff accounts; retail (consumer): electronic bill payment, "},{"text":"POS using a debit card","bold":true},{"text":", and cash-based money transfer (Western Union, MoneyGram)."}]},{"text":[{"text":"ATM services (5):","bold":true},{"text":" cash withdrawal; balance enquiry; statement request; cash deposit; "},{"text":"transfer between accounts","bold":true},{"text":". Operated with a card "},{"text":"plus a secret personal identification number (PIN)","bold":true},{"text":". Not done at an ATM: approving loans, opening fixed deposits, granting unapproved overdrafts."}]},{"text":[{"text":"ATM advantages:","bold":true},{"text":" cash outside banking hours; shorter queues in banking halls; time saved for customers' own business."}]},{"text":[{"text":"Cards:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Debit card:","bold":true},{"text":" payment taken "},{"text":"directly from the holder's own account","bold":true},{"text":" at the time of use."}]},{"text":[{"text":"Credit card:","bold":true},{"text":" a "},{"text":"revolving credit line","bold":true},{"text":"; pay a minimum and carry the rest with interest."}]},{"text":[{"text":"Charge card:","bold":true},{"text":" the "},{"text":"full balance must be settled at the end of each billing period","bold":true},{"text":"."}]}]}]},{"text":[{"text":"SWIFT = Society for Worldwide Interbank Financial Telecommunication:","bold":true},{"text":" a non-profit, cooperative message network "},{"text":"based in Belgium","bold":true},{"text":". It carries "},{"text":"secure payment instructions, not the funds","bold":true},{"text":"; money settles through correspondent (Nostro/Vostro) accounts. Its premium is "},{"text":"security","bold":true},{"text":", not speed."}]},{"text":[{"text":"NIBSS (Nigeria Inter-Bank Settlement System):","bold":true},{"text":" runs "},{"text":"NIP (NIBSS Instant Payment)","bold":true},{"text":", which credits beneficiaries "},{"text":"in real time","bold":true},{"text":", and "},{"text":"NEFT (Nigeria Electronic Funds Tra$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 46, $study_guide$nsfer)","bold":true},{"text":", which works in "},{"text":"batches","bold":true},{"text":" with a longer delay. NIBSS also runs automated cheque clearing."}]},{"text":[{"text":"RTGS (Real-Time Gross Settlement):","bold":true},{"text":" run by the "},{"text":"CBN","bold":true},{"text":"; "},{"text":"each payment is settled individually and immediately","bold":true},{"text":" across banks' accounts, mainly for "},{"text":"large-value","bold":true},{"text":" transfers."}]},{"text":[{"text":"Cashless policy:","bold":true},{"text":" the CBN policy to reduce cash in circulation. "},{"text":"First piloted in Lagos State from 1 January 2012.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internet banking:","bold":true},{"text":" the bank's website for balances, history and transfers from home or office. "},{"text":"USSD","bold":true},{"text":" (dial a short code such as *XYZ#) is popular in Nigeria because it "},{"text":"works on basic phones without internet data","bold":true},{"text":"; mobile apps need a smartphone."}]},{"text":[{"text":"Paying at a Shoprite till with a debit card and PIN uses a "},{"text":"POS terminal","bold":true},{"text":". The "},{"text":"BVN (Bank Verification Number)","bold":true},{"text":" identifies a customer across banks; it is not the PIN, and a "},{"text":"sort code","bold":true},{"text":" identifies a bank branch."}]},{"text":[{"text":"The cashless policy later went nationwide. "},{"text":"Current position (from 1 January 2026):","bold":true},{"text":" no cash-deposit limit; weekly cash withdrawals capped at "},{"text":"₦500,000 for individuals and ₦5 million for corporates","bold":true},{"text":", with "},{"text":"3% and 5%","bold":true},{"text":" charged on the excess."}]},{"text":[{"text":"Trap: \"cash leaves an electronic record\" and \"cash has no handling cost\" are false, so they are never problems of cash."}]}]}]},{"number":"9.6","title":"The e-Naira (central bank digital currency)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Central bank digital currency (CBDC):","bold":true},{"text":" an "},{"text":"electronic form of central bank money","bold":true},{"text":" that people use to make digital payments and which can also act as a "},{"text":"store of value","bold":true},{"text":"."}]},{"text":[{"text":"e-Naira:","bold":true},{"text":" Nigeria's CBDC, developed under "},{"text":"Project Giant","bold":true},{"text":"; the CBN announced its technical partner for the project on "},{"text":"30 August 2021","bold":true},{"text":"; officially "},{"text":"launched in October 2021","bold":true},{"text":" (25 October 2021), the first CBDC in Africa."}]},{"text":[{"text":"It is "},{"text":"legal tender","bold":true},{"text":", issued by the CBN, and "},{"text":"complements (does not replace) the cash naira","bold":true},{"text":" at "},{"text":"one e-Naira = one naira","bold":true},{"text":"."}]},{"text":[{"text":"Benefits:","bold":true},{"text":" digital-economy catalyst; better monetary policy (payment data); "},{"text":"financial inclusion","bold":true},{"text":"; safer payments; cheaper cross-border trade; banking stability; "},{"text":"lower naira printing cost","bold":true},{"text":"; less abuse of the naira, theft and disease from dirty notes."}]},{"text":[{"text":"CBDC versus cryptocurrency (4):","bold":true}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"CBDC (e-Naira)"}],[{"text":"Cryptocurrency (e.g. Bitcoin)"}]],"rows":[[[{"text":"Issuer"}],[{"text":"central bank"}],[{"text":"privately created by users"}]],[[{"text":"Legal tender"}],[{"text":"yes"}],[{"text":"no"}]],[[{"text":"Volatility"}],[{"text":"low (fixed 1:1 with the naira)"}],[{"text":"high"}]],[[{"text":"Legal backing"}],[{"text":"backed by law (state)"}],[{"text":"not backed by law"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Challenges: cyber fraud, a foreign technology provider, public enlightenment, teething problems."}]},{"text":[{"text":"Trap: making the naira "},{"text":"more volatile","bold":true},{"text":" for speculation is never a benefit; CBDCs are designed to avoid volatility."}]},{"text":[{"text":"Do not confuse dates: "},{"text":"January 2012","bold":true},{"text":" is the cashless pilot in Lagos; "},{"text":"October 2021","bold":true},{"text":" is the e-Naira launch."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personal cheque = simplest domestic method; draft = branch on branch/head office, rarely dishonoured; bank cheque = same clearing area only."}]},{"text":[{"text":"Banker's payment = bank pays bank; intra-bank transfer = between a customer's own accounts."}]},{"text":[{"text":"Standing order = customer starts, fixed amount; direct debit = beneficiary starts under the payer's authority, can be variable."}]},{"text":[{"text":"No funds, no overdraft, countermand or garnishee order ends the duty to pay; a payee cannot cancel."}]},{"text":[{"text":"Total debit = amount + commission + postage; pay only if the balance after stays CR or within the overdraft limit."}]},{"text":[{"text":"Open account riskiest; letter of credit surest; issuing = importer's bank, advising = exporter's bank; D/P against payment, D/A against acceptance."}]},{"text":[{"text":"Nostro = \"our\" account abroad; Vostro = \"your\" account with us. SWIFT sends messages, not money."}]},{"text":[{"text":"ATM = card + PIN; debit card = own account now; charge card = settle in full. NIP real time, NEFT batch, RTGS large-value; cashless pilot Lagos, 1 January 2012."}]},{"text":[{"text":"e-Naira launched October 2021, legal tender, 1:1 with the naira, complements cash."}]}]}],"theory":{"itemId":"2bb50407-c66f-50dc-bf77-5c088c5cd6e4","question":[{"type":"paragraph","text":[{"text":"Mrs Bello's account opened the month at ₦2,000 DR. She paid in a cheque of ₦9,500, issued a cheque of ₦4,800 and was charged ₦150 for a cheque book. Her standing order of ₦6,000 falls due at m$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 47, $study_guide$onth end; the bank charges ½% commission and ₦50 postage, and her overdraft limit is ₦2,000. Will the bank pay?"}]}]},"practice":[{"topic":"Methods of Payment through the Banking System","named":false}]}},{"kind":"note","itemId":"f4410e43-476b-545e-a3e0-76a6ef42b2bc","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Bank-Customer Relationship","body":"Who a banker and a customer are (definitions and cases); the relationships between them; the banker's rights (charges and COT, lien, set-off, appropriation and Clayton's Rule) with their computations; the banker's duties, secrecy and when authority to pay ends; the customer's duties and rights; garnishee and bankruptcy; types of account, KYC, opening, mandates, powers of attorney and closing; special services.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"Who a banker and a customer are (definitions and cases); the relationships between them; the banker's rights (charges and COT, lien, set-off, appropriation and Clayton's Rule) with their computations; the banker's duties, secrecy and when authority to pay ends; the customer's duties and rights; garnishee and bankruptcy; types of account, KYC, opening, mandates, powers of attorney and closing; special services."}],"lessons":[{"number":"10.1","title":"Who is a banker and who is a customer?","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"J.W. Gilbert:","bold":true},{"text":" a banker is \"a dealer in capital, or more properly a dealer in money. He is an intermediate party between the borrower and the lender. He borrows from one party and lends to another.\""}]},{"text":[{"text":"Hart:","bold":true},{"text":" a banker receives money and collects cheques for customers and honours cheques drawn on him by them, up to their current account balances."}]},{"text":[{"text":"Sir John Paget:","bold":true},{"text":" no one can be a banker who does not (1) take deposit accounts, (2) take current accounts, (3) issue and pay cheques, (4) collect cheques, crossed and uncrossed, for customers."}]},{"text":[{"text":"Halsbury's Laws of England:","bold":true},{"text":" a banker is an individual, partnership or corporation whose sole or predominant business is banking, that is, "},{"text":"the receipt of money on current or deposit account and the payment of cheques drawn by, and collection of cheques paid in by, a customer","bold":true},{"text":"."}]},{"text":[{"text":"Criticism of Hart, Paget and Halsbury:","bold":true},{"text":" they describe "},{"text":"deposit banking","bold":true},{"text":" well but are "},{"text":"not wide enough","bold":true},{"text":" to cover the other businesses banks now do."}]},{"text":[{"text":"United Dominions Trust v Kirkwood (1966):","bold":true},{"text":" the marks of a banker: accepting money from and collecting cheques for customers, and "},{"text":"honouring cheques or orders drawn on the bank","bold":true},{"text":", and keeping current (or similar) accounts."}]},{"text":[{"text":"Akwule and Others v The Queen (1963), Supreme Court of Nigeria:","bold":true},{"text":" \"banker\" means "},{"text":"the company carrying on banking business","bold":true},{"text":", not an employee of the bank."}]},{"text":[{"text":"Nigerian law today:","bold":true},{"text":" a bank is a company licensed by the CBN to carry on banking business under the "},{"text":"Banks and Other Financial Institutions Act (BOFIA) 2020","bold":true},{"text":" (which replaced BOFIA 1991)."}]},{"text":[{"text":"Customer:","bold":true},{"text":" there is "},{"text":"no statutory definition","bold":true},{"text":"; the courts supply the principles. A person, firm, society or company becomes a customer when he "},{"text":"offers","bold":true},{"text":" to open an account and the bank "},{"text":"accepts","bold":true},{"text":" (offer and acceptance, as in any contract)."}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Rule"}]],"rows":[[[{"text":"Great Western Railway v London and County Banking Co. (1901)"}],[{"text":"A man who "},{"text":"merely cashed cheques","bold":true},{"text":" for his employer for many years was "},{"text":"not","bold":true},{"text":" a customer"}]],[[{"text":"Commissioners of Taxation v English, Scottish and Australian Bank (1920)"}],[{"text":"Duration is not of the essence","bold":true},{"text":"; a person is a customer as soon as an account is opened"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Akwule in practice: if Mr Eze's funded cheque is wrongly returned at a Yaba branch, he sues "},{"text":"the bank","bold":true},{"text":", his banker and debtor, not the cashier, the branch manager or the CBN."}]},{"text":[{"text":"Duration and frequency of dealings are not decisive. Adaeze, whose account was opened yesterday with one ₦50,000 deposit, is already a customer. Tunde the messenger who cashed his employer's cheques weekly for ten years is not (GWR case)."}]},{"text":[{"text":"Trap: a customer does not need a loan, a cheque book or six months' operation. The relationship needs "},{"text":"both parties' intention","bold":true},{"text":", so it is "},{"text":"contractual","bold":true},{"text":"."}]}]}]},{"number":"10.2","title":"The relationships between banker and customer","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Debtor and creditor (the primary relationship):","bold":true},{"text":" customer in credit = "},{"text":"creditor","bold":true},{"text":", bank = "},{"text":"debtor","bold":true},{"text":". Customer overdrawn = "},{"text":"debtor","bold":true},{"text":", bank = "},{"text":"creditor","bold":true},{"text":"."}]},{"text":[{"text":"Principal and agent:","bold":true},{"text":" bank is "},{"text":"agent","bold":true},{"text":" when it collects cheques, makes payments (standing orders, premiums), buys or sells shares and securities, or does foreign exchange for the customer."}]},{"text":[{"text":"Bailor and bailee:","bold":true},{"text":" items left for "},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 48, $study_guide${"text":"safe custody","bold":true},{"text":"; customer = "},{"text":"bailor","bold":true},{"text":", bank = "},{"text":"bailee","bold":true},{"text":". The bank charges a fee, so it is a "},{"text":"bailee for reward","bold":true},{"text":" and its standard of care is "},{"text":"high","bold":true},{"text":"; lost items are paid for."}]},{"text":[{"text":"Mortgagor and mortgagee:","bold":true},{"text":" on a loan secured by property, customer = "},{"text":"mortgagor","bold":true},{"text":", bank = "},{"text":"mortgagee","bold":true},{"text":"."}]},{"text":[{"text":"Trustee and beneficiary:","bold":true},{"text":" where money is given to the bank for a "},{"text":"specific purpose","bold":true},{"text":" (held in a fiduciary capacity)."}]},{"text":[{"text":"Contractual:","bold":true},{"text":" the whole relationship rests on contract (offer and acceptance at account opening, plus terms and mandate)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Foley v Hill (1848):","bold":true},{"text":" money paid in "},{"text":"becomes the bank's money","bold":true},{"text":", to use as it pleases; the bank only owes an "},{"text":"equivalent sum","bold":true},{"text":". It is "},{"text":"not","bold":true},{"text":" held on trust and need not be kept separately."}]},{"text":[{"text":"Joachimson v Swiss Bank Corporation (1921):","bold":true},{"text":" the bank need not repay a current account balance "},{"text":"until the customer demands it","bold":true},{"text":". Repayment is on "},{"text":"written demand, at the branch where the account is kept, during banking hours","bold":true},{"text":"."}]},{"text":[{"text":"General relationship:","bold":true},{"text":" from ordinary business: deposits, withdrawals, cheques, statements. "},{"text":"Special relationship:","bold":true},{"text":" from extra services: safe custody, advice, guarantees, letters of credit, powers of attorney, standing orders, direct debits, trustee services. Special services may carry "},{"text":"higher","bold":true},{"text":" duties."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reversal of the ordinary rule: in law a debtor must seek out his creditor. In banking the "},{"text":"customer (creditor) must seek out the bank (debtor)","bold":true},{"text":" and demand payment."}]},{"text":[{"text":"Because the bank is a debtor, not a trustee, it may lend depositors' money to a manufacturer in Ikeja "},{"text":"without asking them","bold":true},{"text":"."}]},{"text":[{"text":"Matching scenarios: Halima with ₦300,000 in credit is creditor; Sola overdrawn by ₦150,000 is debtor. Kemi asking the bank to buy ₦500,000 of FGN bonds and collect a Kano cheque makes the bank her "},{"text":"agent","bold":true},{"text":". Chief Okonkwo leaving his C of O and jewellery for a fee is "},{"text":"bailor","bold":true},{"text":". Musa mortgaging his Lekki house for a ₦10 million loan is "},{"text":"mortgagor","bold":true},{"text":", the bank "},{"text":"mortgagee","bold":true},{"text":". Mrs Ade's ₦5 million held only for her late brother's children's school fees makes the bank a "},{"text":"trustee","bold":true},{"text":", the children "},{"text":"beneficiaries","bold":true},{"text":"."}]},{"text":[{"text":"Employer and employee","bold":true},{"text":" is never a banker-customer relationship."}]}]}]},{"number":"10.3","title":"Rights of the banker","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To charge "},{"text":"reasonable commission","bold":true},{"text":" for services and "},{"text":"interest","bold":true},{"text":" on advances."}]},{"text":[{"text":"Banker's lien.","bold":true}]},{"text":[{"text":"Set-off","bold":true},{"text":" (combination of accounts)."}]},{"text":[{"text":"Appropriation","bold":true},{"text":" of payments."}]},{"text":[{"text":"That the "},{"text":"customer seeks out the bank","bold":true},{"text":" for repayment."}]},{"text":[{"text":"To "},{"text":"return irregularly drawn","bold":true},{"text":" cheques."}]},{"text":[{"text":"To "},{"text":"return cheques that would create an unauthorised overdraft","bold":true},{"text":"."}]},{"text":[{"text":"To "},{"text":"recall an overdraft","bold":true},{"text":", which is repayable on demand."}]},{"text":[{"text":"To be "},{"text":"reimbursed","bold":true},{"text":" for expenses incurred on the customer's behalf."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Banker's lien:","bold":true},{"text":" a "},{"text":"general lien","bold":true},{"text":": the right to "},{"text":"retain","bold":true},{"text":" a customer's securities that come into the bank's hands "},{"text":"in the ordinary course of business","bold":true},{"text":" until his debt is paid. It carries an "},{"text":"implied power of sale","bold":true},{"text":" and is "},{"text":"lost if the bank voluntarily parts with possession","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" cover items left for safe custody or for a specific purpose, and does not apply where the parties agreed no lien."}]},{"text":[{"text":"Set-off:","bold":true},{"text":" combining a "},{"text":"credit balance on one account","bold":true},{"text":" with a "},{"text":"debit balance on another","bold":true},{"text":" of the same customer, using the credit to reduce the debt. Conditions: (1) accounts in the "},{"text":"same name and same right","bold":true},{"text":"; (2) the debt "},{"text":"due and payable","bold":true},{"text":"; (3) "},{"text":"no agreement excluding","bold":true},{"text":" set-off; (4) notice usually given as good practice. Personal and "},{"text":"trust","bold":true},{"text":" accounts cannot be combined."}]},{"text":[{"text":"Appropriation order:","bold":true},{"text":" the "},{"text":"customer","bold":true},{"text":" may appropriate first; if he does not, the "},{"text":"bank","bold":true},{"text":" may; if neither does, "},{"text":"Clayton's Rule","bold":true},{"text":" applies to a running account."}]},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 49, $study_guide$text":[{"text":"Clayton's Rule (Devaynes v Noble, 1816):","bold":true},{"text":" the "},{"text":"first item on the debit side is discharged by the first item on the credit side","bold":true},{"text":" (first in, first out)."}]},{"text":[{"text":"Commission on turnover (COT):","bold":true},{"text":" a charge on "},{"text":"current account","bold":true},{"text":" customers' "},{"text":"debit","bold":true},{"text":" entries for a period. "},{"text":"COT = periodic rate × total debit entries.","bold":true},{"text":" Savings accounts do "},{"text":"not","bold":true},{"text":" attract COT."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"COT (₦), bank-style.","bold":true},{"text":" Tola had ₦40,000 credit on 1 January; withdrew ₦50,000 (15 Jan), ₦30,000 (20 Feb), ₦10,000 (8 Mar). COT 15% per annum."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Quarterly rate = 15% ÷ 4 = 3.75% = 0.0375."}]},{"text":[{"text":"Total debits = 50,000 + 30,000 + 10,000 = ₦90,000. (The opening balance is not a debit entry.)"}]},{"text":[{"text":"COT = 0.0375 × 90,000 = "},{"text":"₦3,375","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Current position: the CBN phased COT down from 2013, abolished it from 2016 and replaced it with a capped "},{"text":"current account maintenance fee","bold":true},{"text":" charged "},{"text":"per mille","bold":true},{"text":" (per ₦1,000) of customer-induced debits (CBN Guide to Charges). Exam questions still compute COT as above."}]},{"text":[{"text":"Lien example.","bold":true},{"text":" Mr Bello owes ₦2 million. The bank holds share certificates received to collect his dividends (ordinary course of business) and a sealed jewellery box left for safe custody. Lien covers the "},{"text":"share certificates only","bold":true},{"text":". No court order or consent is needed."}]},{"text":[{"text":"Set-off example.","bold":true},{"text":" Chidi: savings ₦450,000 Cr; current ₦620,000 Dr (due); trustee account for his father's estate ₦300,000 Cr. The trust account is in a different right, so leave it out. ₦620,000 − ₦450,000 = "},{"text":"₦170,000","bold":true},{"text":" still owed."}]},{"text":[{"text":"Clayton's Rule, partner's death.","bold":true},{"text":" Firm overdrawn ₦800,000 when Bayo dies; account not stopped; ₦500,000 paid in, ₦300,000 withdrawn."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The ₦500,000 credit discharges the oldest debit first: ₦800,000 − ₦500,000 = "},{"text":"₦300,000","bold":true},{"text":" of the old debt left (Bayo's estate remains liable for this)."}]},{"text":[{"text":"The ₦300,000 withdrawal is a "},{"text":"new","bold":true},{"text":" debt, for which the estate is not liable."}]}]}]},{"text":[{"text":"Clayton's Rule, guarantee.","bold":true},{"text":" Mrs Ojo ends her guarantee at ₦1,200,000; Dapo pays in ₦700,000 and withdraws ₦900,000. Her liability = 1,200,000 − 700,000 = "},{"text":"₦500,000","bold":true},{"text":". The ₦900,000 is new borrowing she never guaranteed. To protect itself, a bank "},{"text":"stops (rules off) the account","bold":true},{"text":" and opens a new one when a guarantee ends or a partner dies."}]}]}]},{"number":"10.4","title":"Duties of the banker, secrecy, and when authority to pay ends","mustKnow":[{"type":"paragraph","text":[{"text":"Duties of the banker:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"honour cheques","bold":true},{"text":" when (a) there are sufficient funds or an agreed overdraft, (b) the cheque is properly drawn and presented, (c) there is no legal bar."}]},{"text":[{"text":"To "},{"text":"receive","bold":true},{"text":" money and "},{"text":"collect","bold":true},{"text":" cheques for the customer with care."}]},{"text":[{"text":"To give "},{"text":"reasonable notice before closing","bold":true},{"text":" an account in credit."}]},{"text":[{"text":"To "},{"text":"furnish statements","bold":true},{"text":" of account periodically."}]},{"text":[{"text":"Duty of care","bold":true},{"text":" (act in good faith, without negligence)."}]},{"text":[{"text":"To "},{"text":"pay agreed interest","bold":true},{"text":" on deposits."}]},{"text":[{"text":"To "},{"text":"alert the customer","bold":true},{"text":" to irregularities on his account."}]},{"text":[{"text":"Secrecy.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Wrongful dishonour:","bold":true},{"text":" a bank that wrongly returns a funded cheque is "},{"text":"liable in damages for breach of contract, including injury to the customer's credit","bold":true},{"text":"."}]},{"text":[{"text":"Tournier v National Provincial and Union Bank of England (1924):","bold":true},{"text":" secrecy is a "},{"text":"legal duty arising from contract","bold":true},{"text":", but "},{"text":"qualified","bold":true},{"text":" by "},{"text":"4 exceptions","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Compulsion by law","bold":true},{"text":" (court order, subpoena, statute)."}]},{"text":[{"text":"Duty to the public.","bold":true}]},{"text":[{"text":"Interest of the bank.","bold":true}]},{"text":[{"text":"Express or implied consent of the customer.","bold":true}]}]}]},{"text":[{"text":"Secrecy "},{"text":"continues after the account is closed","bold":true},{"text":". A spouse has no right to the other's account details without authority."}]}]},{"type":"paragraph","text":[{"text":"When the bank's authority to pay ends (12 cases):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Lack of funds. 2. Countermand (stop payment). 3. Notice of the customer's "},{"text":"death","bold":true},{"text":". 4. Notice of defect in the presenter's title (lost or stolen cheque). 5. Notice of the customer's "},{"text":"mental incapacity","bold":true},{"text":". 6. Assignment of the balance. 7. "},{"text":"Garnishee order","bold":true},{"text":" or cou$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 50, $study_guide$rt injunction. 8. "},{"text":"Bankruptcy","bold":true},{"text":" of the customer. 9. "},{"text":"Forged","bold":true},{"text":" drawer's signature. 10. Irregularly drawn cheque. 11. Demand outside banking hours or at the wrong branch. 12. A lawful order freezing the account."}]}]},{"type":"paragraph","text":[{"text":"Duties of the customer:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Draw cheques with "},{"text":"reasonable care","bold":true},{"text":" so as not to facilitate fraud."}]},{"text":[{"text":"Seek out","bold":true},{"text":" the bank and demand repayment."}]},{"text":[{"text":"Issue cheques only against "},{"text":"available funds","bold":true},{"text":" or an agreed overdraft."}]},{"text":[{"text":"Pay bank charges","bold":true},{"text":" as agreed."}]},{"text":[{"text":"Inform the bank promptly","bold":true},{"text":" of forgery, a lost cheque book or other suspicious dealings."}]}]},{"type":"paragraph","text":[{"text":"Rights of the customer: to know his balance; to "},{"text":"withdraw without notice","bold":true},{"text":" by cheque if the current account is in funds; to appropriate his payments; to receive statements; to confidentiality; to reasonable notice of closure; to "},{"text":"close the account","bold":true},{"text":" if not indebted."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Secrecy scenarios: a Federal High Court order for a fraud suspect's statements = "},{"text":"compulsion by law","bold":true},{"text":" (so are suspicious transaction reports to the NFIU under the Money Laundering (Prevention and Prohibition) Act 2022). Suing a guarantor and showing the principal debtor's balance, or briefing the bank's solicitor on a debt = "},{"text":"interest of the bank","bold":true},{"text":". Reporting a customer trading with an enemy in wartime, or a public officer looting public funds = "},{"text":"duty to the public","bold":true},{"text":". Kunle writing to let his auditors have his statements, or authorising a status report = "},{"text":"express consent","bold":true},{"text":". Funke closed her account in 2023; in 2026 the bank must still refuse a journalist."}]},{"text":[{"text":"Statements let the customer "},{"text":"reconcile","bold":true},{"text":" his records and detect errors."}]},{"text":[{"text":"Countermand","bold":true},{"text":" must be "},{"text":"in writing, clear and unambiguous, signed per the mandate, and received before the cheque is paid","bold":true},{"text":"."}]},{"text":[{"text":"A "},{"text":"forged","bold":true},{"text":" drawer's signature makes the cheque "},{"text":"wholly inoperative","bold":true},{"text":"; it carries no mandate, so the bank cannot debit the customer, however skilful the forgery."}]},{"text":[{"text":"Death","bold":true},{"text":" cancels all mandates: Mr Danjuma's cheques signed the week before must "},{"text":"not","bold":true},{"text":" be paid after notice of death. A customer travelling abroad on holiday does "},{"text":"not","bold":true},{"text":" end authority."}]},{"text":[{"text":"London Joint Stock Bank v Macmillan and Arthur (1918):","bold":true},{"text":" partners signed a cheque with blank spaces; a clerk raised the amount. The customer owes a duty to "},{"text":"draw cheques carefully so as not to facilitate fraud","bold":true},{"text":" and "},{"text":"bears the loss","bold":true},{"text":" of his carelessness."}]},{"text":[{"text":"Garnishee order:","bold":true},{"text":" a court order "},{"text":"attaching","bold":true},{"text":" funds in the customer's account to satisfy a "},{"text":"judgment debt","bold":true},{"text":" he owes a third party. Parties: judgment creditor (Mr Adamu), judgment debtor (Mrs Lawal), "},{"text":"garnishee = the bank","bold":true},{"text":" (Union Bank). On service of the "},{"text":"order nisi","bold":true},{"text":" the bank "},{"text":"freezes","bold":true},{"text":" the account and pays only when the order is made "},{"text":"absolute","bold":true},{"text":" or as the court directs."}]},{"text":[{"text":"Bankruptcy","bold":true},{"text":" (Bankruptcy Act): on notice of a bankruptcy order the customer's "},{"text":"authority to operate the account ceases","bold":true},{"text":", the bank freezes it, and the "},{"text":"trustee in bankruptcy steps into his shoes","bold":true},{"text":". For an unsecured debt the bank "},{"text":"proves in the bankruptcy","bold":true},{"text":" and shares with other creditors; a secured creditor may realise its security."}]}]}]},{"number":"10.5","title":"Accounts: types, opening, mandates and closing","mustKnow":[{"type":"paragraph","text":[{"text":"The 3 main types of deposit account (a "},{"text":"loan account","bold":true},{"text":" is not one):"}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Current"}],[{"text":"Savings"}],[{"text":"Fixed (time)"}]],"rows":[[[{"text":"Deposit type"}],[{"text":"Demand","bold":true},{"text":" deposit"}],[{"text":"Savings deposit"}],[{"text":"Time","bold":true},{"text":" deposit"}]],[[{"text":"Withdrawal"}],[{"text":"By "},{"text":"cheque","bold":true},{"text":", on demand, no notice"}],[{"text":"Withdrawal slip, by holder in person"}],[{"text":"Only at "},{"text":"maturity","bold":true},{"text":"; penalty if early"}]],[[{"text":"Interest"}],[{"text":"Little or none"}],[{"text":"Earns interest"}],[{"text":"Highest","bold":true}]],[[{"text":"References"}],[{"text":"Required (traditionally)"}],[{"text":"Not required"}],[{"text":"Not required"}]],[[{"text":"COT / overdraft"}],[{"text":"COT; overdraft possible"}],[{"text":"No COT; no overdraft"}],[{"text":"Deposit receipt issued"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Savings rule (traditional):","bold":true},{"text":" more than "},{"text":"3 withdrawals in a month","bold":true},{"text":" forfeits that month's interest."}]},{"text":[{"text":"Domiciliary account:","bold":true},{"text":" a "},{"text":"foreign-currency","bold":true},{"text":" account (e.g. US dolla$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 51, $study_guide$rs) for receiving remittances and holding foreign exchange, subject to CBN rules."}]},{"text":[{"text":"KYC (Know Your Customer):","bold":true},{"text":" verifying a customer's "},{"text":"identity, address and beneficial ownership","bold":true},{"text":" before and during the relationship. Documents: photograph, ID (NIN, passport, driver's licence, voter's card), proof of address, "},{"text":"BVN","bold":true},{"text":"; companies add CAC documents, TIN, board resolution. "},{"text":"Enhanced due diligence","bold":true},{"text":" for high-risk customers: "},{"text":"PEPs, non-residents","bold":true},{"text":", complex structures."}]},{"text":[{"text":"Mandate:","bold":true},{"text":" the customer's formal authority stating "},{"text":"who may sign cheques and operate the account","bold":true},{"text":". The bank must follow it strictly. Joint mandates: \"EITHER TO SIGN\", \"BOTH TO SIGN\", \"ANY TWO OF THE THREE TO SIGN\"."}]},{"text":[{"text":"Power of attorney:","bold":true},{"text":" a formal written authority, "},{"text":"signed and sealed","bold":true},{"text":", by which the "},{"text":"donor","bold":true},{"text":" empowers the "},{"text":"donee (attorney)","bold":true},{"text":" to act for him generally or in specified matters. "},{"text":"Specific","bold":true},{"text":" (one purpose) or "},{"text":"General","bold":true},{"text":" (anything the donor may lawfully do by an attorney)."}]}]},{"type":"paragraph","text":[{"text":"On receiving a power of attorney the bank must:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sight the original."}]},{"text":[{"text":"Keep a certified true copy in the customer's file."}]},{"text":[{"text":"Ensure it is stamped."}]},{"text":[{"text":"Operate strictly within the listed powers."}]},{"text":[{"text":"Follow the donor's instructions on revocation."}]}]},{"type":"paragraph","text":[{"text":"A power of attorney ends by:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Completion of its purpose. 2. Expiry of its time. 3. Death of donor or donee. 4. Mental incapacity of either. 5. Bankruptcy of either. 6. Express revocation by the donor. 7. Implication (the donor resumes operating the account)."}]}]},{"type":"paragraph","text":[{"text":"Documents for opening:"}]},{"type":"table","header":[[{"text":"Customer"}],[{"text":"Key documents"}]],"rows":[[[{"text":"Limited company"}],[{"text":"Board resolution and extract naming signatories, memorandum and articles, certificate of incorporation (plus CAC returns)"}]],[[{"text":"Partnership"}],[{"text":"Firm's name; application signed by all partners; business-name search; deed of partnership; mandate with "},{"text":"joint and several liability","bold":true},{"text":" clause"}]],[[{"text":"Club, union, association"}],[{"text":"Rules; resolution; "},{"text":"extract of minutes certified by Chairman/President and Secretary","bold":true},{"text":"; specimen signatures and photographs"}]],[[{"text":"Executor"}],[{"text":"Grant of probate","bold":true},{"text":" (administrator: letters of administration)"}]],[[{"text":"Government or agency"}],[{"text":"Gazette establishing it; authority from Accountant-General (federal or state) or council Chairman and Secretary"}]],[[{"text":"Minor"}],[{"text":"Titled guardian's name "},{"text":"\"IN RE\"","bold":true},{"text":" minor's name and date of birth; guardian operates until "},{"text":"18","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tope and Yemi's mandate says \"BOTH TO SIGN\"; a ₦80,000 cheque signed only by Tope must be "},{"text":"refused","bold":true},{"text":"."}]},{"text":[{"text":"On a joint account, the balance passes to the "},{"text":"survivor","bold":true},{"text":" (rule of survivorship) unless the terms say otherwise."}]},{"text":[{"text":"Delegation of mandate","bold":true},{"text":" rules: no delegation on "},{"text":"trust accounts","bold":true},{"text":" (all trustees must sign), so the Ibadan orphanage trustee cannot delegate to his secretary; minors are not accepted as agents; an agent who does not sign as agent is personally liable; joint holders must all authorise any delegation."}]},{"text":[{"text":"Alhaji Sani's power letting his son only withdraw for school fees is "},{"text":"specific","bold":true},{"text":". A salary credit never revokes a power of attorney."}]},{"text":[{"text":"Closing accounts.","bold":true},{"text":" A bank may close a "},{"text":"credit","bold":true},{"text":" account, after reasonable notice, for unreasonableness, frequent negligent operation, "},{"text":"habitual drawing on uncleared effects","bold":true},{"text":", fraud links or image risk. General procedure: (1) closing form completed, (2) unused cheques returned, (3) closing charges determined, (4) closing entries posted, (5) closing balance determined, (6) balance paid, (7) ledger marked "},{"text":"\"CLOSED\"","bold":true},{"text":", (8) entry in the opened and closed register. A new cheque book is never part of closing."}]}]}]},{"number":"10.6","title":"Special services that create special relationships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Safe custody:","bold":true},{"text":" items (title deeds, C of O, share certificates, wills, jewellery) taken in a sealed envelope or locked box "},{"text":"\"contents unknown\"","bold":true},{"text":" (or listed and signed for); the customer gets a "},{"text":"receipt that must be surrendered","bold":true},{"text":" to withdraw them. The bank does not open, value, lend or pay interest on them."}]},{"text":[{"text":"Status enquiry (banker's opinion):","bold":true},{"text":" a reply on a customer's creditworthiness, given "},{"text":"briefly, in general terms, in confidence and \"without responsibility\"","bold":true},{"text":", without disclosing balances; the bank must still take care it is "},{"text":"not misleading","bold":true},{"text":". It never makes the bank a guarantor."}]}]},{"type":"tab$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 52, $study_guide$le","header":[[{"text":"Reply"}],[{"text":"Meaning"}]],"rows":[[[{"text":"\"Undoubted for your figures\""}],[{"text":"Strongest","bold":true},{"text":": considerable strength"}]],[[{"text":"\"Considered good for your figures\""}],[{"text":"Satisfactory"}]],[[{"text":"\"Should be good for your figures\""}],[{"text":"Some doubt"}]],[[{"text":"\"We cannot speak for your figures\""}],[{"text":"Unfavourable"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Standing order:","bold":true},{"text":" customer instructs his bank to pay a "},{"text":"fixed","bold":true},{"text":" amount regularly to a named beneficiary. "},{"text":"Direct debit:","bold":true},{"text":" customer authorises a "},{"text":"third party (originator)","bold":true},{"text":" to collect "},{"text":"variable","bold":true},{"text":" amounts from his account."}]},{"text":[{"text":"Agency services:","bold":true},{"text":" collecting cheques and dividend warrants, paying premiums, rent and bills, buying and selling shares, acting as trustee or executor. Accepting fixed deposits is "},{"text":"deposit-taking","bold":true},{"text":", not agency."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bisi's phone company pulling a different amount monthly = "},{"text":"direct debit","bold":true},{"text":"; her bank paying a fixed ₦20,000 to her landlord = "},{"text":"standing order","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No statutory definition of customer: offer and acceptance; duration not essential (Taxation Commissioners 1920); mere cheque-cashing is not enough (GWR 1901)."}]},{"text":[{"text":"Akwule (1963): the banker is the bank, not its staff."}]},{"text":[{"text":"Customer in credit = creditor; overdrawn = debtor. Foley v Hill: deposit is the bank's money. Joachimson: written demand, at the branch, in banking hours."}]},{"text":[{"text":"Bailor-bailee (safe custody, bailee for reward), agent, mortgagor-mortgagee, trustee; employer-employee never."}]},{"text":[{"text":"Lien is general, with implied power of sale, not over safe custody. Set-off needs same name and same right."}]},{"text":[{"text":"Clayton's Rule: first debit cleared by first credit; stop the account on death or end of guarantee."}]},{"text":[{"text":"Tournier: 4 exceptions: law, public duty, bank's interest, consent; secrecy survives closure."}]},{"text":[{"text":"Death, countermand, garnishee, bankruptcy, forgery and mental incapacity end authority to pay; travel does not."}]},{"text":[{"text":"COT = periodic rate × total debits; current accounts only."}]},{"text":[{"text":"KYC with EDD for PEPs; executors need probate; minors \"IN RE\"; no delegation on trust accounts."}]}]}],"theory":{"itemId":"93b3314f-d916-555a-8263-c86999e9cc3f","question":[{"type":"paragraph","text":[{"text":"Ngozi guaranteed Ade's overdraft and gave notice ending her guarantee when the balance was ₦950,000 Dr. The bank did not stop the account. Ade then paid in ₦400,000 and ₦250,000 and withdrew ₦600,000. Using Clayton's Rule, find (a) Ngozi's remaining liability and (b) the total overdraft."}]}]},"practice":[{"topic":"Bank-Customer Relationship","named":false}]}},{"kind":"note","itemId":"ec17bbbb-a980-543d-b948-0b20447f2e84","sourceKey":"guide-topic:11","position":11,"payload":{"title":"Bank Account Services for Exporters and Importers","body":"How banks help foreign traders; the methods of receiving payment for exports and who bears the risk; documentary letters of credit (parties, UCP 600, types); collections (clean, documentary, D/P, D/A, URC 522); shipping documents; nostro, vostro and domiciliary accounts; Form M, Form NXP and Form A; spot and forward exchange; export finance (bill negotiation, pre- and post-shipment finance, forfaiting, factoring, export credit insurance); NEXIM; the trade roles of merchant and commercial banks.","noteType":"guide_topic","number":11,"mustKnow":[{"text":"How banks help foreign traders; the methods of receiving payment for exports and who bears the risk; documentary letters of credit (parties, UCP 600, types); collections (clean, documentary, D/P, D/A, URC 522); shipping documents; nostro, vostro and domiciliary accounts; Form M, Form NXP and Form A; spot and forward exchange; export finance (bill negotiation, pre- and post-shipment finance, forfaiting, factoring, export credit insurance); NEXIM; the trade roles of merchant and commercial banks."}],"lessons":[{"number":"11.1","title":"Banks in foreign trade and the methods of payment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Role of banks in international trade:","bold":true},{"text":" banks lend to traders for their overseas deals (overdraft and other lending facilities) and act as the "},{"text":"link between customers and their overseas trade partners","bold":true},{"text":", especially in collecting payment for exports."}]},{"text":[{"text":"Methods banks use to obtain payment for exports:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Open account:","bold":true},{"text":" the exporter sends the "},{"text":"documents of title direct to the importer","bold":true},{"text":" abroad, has "},{"text":"no control","bold":true},{"text":" of the goods and "},{"text":"relies completely on the importer's honesty","bold":true},{"text":" to remit the proceeds after receiving (and selling) the goods. Most risky; discouraged."}]},{"text":[{"text":"Payment by collection:","bold":true},{"text":" the exporter ships the goods and sends the bill of exchange (with or without documents) to "},{"text":"his banker for collection","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clean collection:","bold":true},{"text":" "},{"text":"only the bill","bold":true},{"text":" of exchange is sent, no shipping documents."}]},{"text":[{"text":"Documentary collection:","bold":true},{"text":" the bill is "},{"text":"acc$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 53, $study_guide$ompanied by commercial documents","bold":true},{"text":" (bill of lading, insurance certificate or policy, and others)."}]},{"text":[{"text":"Not fully safe: the exporter "},{"text":"cannot be 100% sure","bold":true},{"text":" the importer will pay."}]}]}]},{"text":[{"text":"Documentary letter of credit:","bold":true},{"text":" the "},{"text":"surest","bold":true},{"text":" method and the one most advised to customers; it gives a "},{"text":"guarantee of payment to the exporter provided he complies with the terms of the credit","bold":true},{"text":"."}]},{"text":[{"text":"Bill negotiation:","bold":true},{"text":" an exporter who needs funds and cannot wait "},{"text":"negotiates the bill to his bank by endorsement and delivery","bold":true},{"text":"; the bank pays "},{"text":"face value less a discount for commission and interest","bold":true},{"text":", then collects the full amount at maturity."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Payment in advance (cash in advance):","bold":true},{"text":" the importer pays before shipment. Safest for the exporter; "},{"text":"greatest risk for the importer","bold":true},{"text":"."}]},{"text":[{"text":"Exporter's risk, lowest to highest:","bold":true},{"text":" payment in advance, letter of credit, documentary collection, clean collection, "},{"text":"open account","bold":true},{"text":". The importer's risk runs the other way."}]},{"text":[{"text":"How the money actually moves:","bold":true},{"text":" by "},{"text":"mail transfer","bold":true},{"text":", "},{"text":"telegraphic (wire) transfer","bold":true},{"text":" or "},{"text":"bank draft","bold":true},{"text":". Banks actually remit abroad by "},{"text":"telegraphic (wire) transfer","bold":true},{"text":", sent over "},{"text":"SWIFT","bold":true},{"text":"; standing orders and direct debits are domestic."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Kano sesame exporter who hands his bank a bill drawn on a German buyer "},{"text":"with no shipping documents","bold":true},{"text":" is asking for a "},{"text":"clean collection","bold":true},{"text":". Add the bill of lading and insurance certificate and it becomes a "},{"text":"documentary collection","bold":true},{"text":"."}]},{"text":[{"text":"Open account = documents go "},{"text":"directly","bold":true},{"text":" to the buyer. Collection = documents go "},{"text":"through the banks","bold":true},{"text":". Do not confuse \"the importer's bank guarantees payment\" (a credit) with a collection, where no bank guarantees anything."}]}]}]},{"number":"11.2","title":"Documentary letters of credit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Documentary letter of credit (LC):","bold":true},{"text":" a written undertaking by a bank (the issuing bank), given at the importer's request, to pay the exporter a stated sum "},{"text":"against documents that comply exactly","bold":true},{"text":" with the terms of the credit."}]}]},{"type":"table","header":[[{"text":"Party"}],[{"text":"Who it is"}]],"rows":[[[{"text":"Applicant","bold":true}],[{"text":"the "},{"text":"importer","bold":true},{"text":", who asks his bank to open the credit"}]],[[{"text":"Beneficiary","bold":true}],[{"text":"the "},{"text":"exporter","bold":true},{"text":", in whose favour the credit is opened"}]],[[{"text":"Issuing (opening) bank","bold":true}],[{"text":"the "},{"text":"importer's bank","bold":true},{"text":", which opens the credit in favour of the exporter"}]],[[{"text":"Advising bank","bold":true}],[{"text":"a bank in the "},{"text":"exporter's country","bold":true},{"text":" (usually his bank) that "},{"text":"tells the exporter","bold":true},{"text":" the credit has been opened, without necessarily adding its own promise to pay"}]],[[{"text":"Confirming bank","bold":true}],[{"text":"a bank (usually in the exporter's country) that "},{"text":"adds its own definite undertaking to pay","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Process:","bold":true},{"text":" (1) exporter and importer sign a sales agreement with specific terms; (2) the "},{"text":"importer's bank (issuing bank) opens the credit","bold":true},{"text":" in favour of the exporter; (3) the "},{"text":"exporter's bank (advising bank)","bold":true},{"text":" is advised of it; (4) goods are shipped; (5) the exporter presents the documents; (6) "},{"text":"the documents of title are released to the importer only against payment (D/P) or acceptance (D/A) of the bill of exchange","bold":true},{"text":", so the exporter keeps control of the goods until then."}]},{"text":[{"text":"Rules:","bold":true},{"text":" "},{"text":"UCP 600","bold":true},{"text":" (Uniform Customs and Practice for Documentary Credits), published by the "},{"text":"International Chamber of Commerce (ICC)","bold":true},{"text":", in force since 1 July 2007."}]},{"text":[{"text":"3 key UCP 600 principles:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A credit is "},{"text":"irrevocable even if it does not say so","bold":true},{"text":"."}]},{"text":[{"text":"Irrevocable","bold":true},{"text":" = it "},{"text":"cannot be amended or cancelled without the agreement of the issuing bank, any confirming bank and the beneficiary","bold":true},{"text":"."}]},{"text":[{"text":"Banks deal with documents, not with goods.","bold":true},{"text":" Complying documents must be paid; "},{"text":"non-complying documents may be refused","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Types of credit:","bold":true}]}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Feature"}]],"rows":[[[{"text":"Confirmed","bold":true}],[{"text":"a second bank adds its own undertaking to pay"}]],[[{"text":"Sight","bold":true}],[{"text":"paid "},{"text":"when compliant documents are presented","bold":true}]],[[{"text":"Usance (term, deferred)","bold":true}],[{"text":"paid at a "$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 54, $study_guide$},{"text":"stated future date","bold":true}]],[[{"text":"Transferable","bold":true}],[{"text":"the beneficiary (a middleman) "},{"text":"transfers part or all of the credit to a second beneficiary","bold":true},{"text":", his supplier"}]],[[{"text":"Back-to-back","bold":true}],[{"text":"a middleman uses the credit from his buyer "},{"text":"as security for a second, new credit","bold":true},{"text":" opened in favour of his supplier"}]],[[{"text":"Red clause","bold":true}],[{"text":"lets the exporter "},{"text":"draw an advance before shipment","bold":true},{"text":" to buy and pack the goods"}]],[[{"text":"Revolving","bold":true}],[{"text":"the amount is "},{"text":"restored after each drawing","bold":true},{"text":" for an agreed period"}]],[[{"text":"Standby","bold":true}],[{"text":"works as a "},{"text":"guarantee","bold":true},{"text":", paid only if the applicant "},{"text":"fails to perform or pay","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"An Aba shoe exporter who doubts the overseas issuing bank asks a reputable Nigerian bank to add its promise: the credit is now "},{"text":"confirmed","bold":true},{"text":". Confirmation is optional; an irrevocable credit does "},{"text":"not","bold":true},{"text":" have to carry a second bank's guarantee."}]},{"text":[{"text":"A Port Harcourt importer whose documents comply cannot stop payment by complaining about goods still at sea. The bank "},{"text":"pays","bold":true},{"text":", because banks deal in documents. His remedy is against the seller under the sales contract."}]},{"text":[{"text":"Transferable vs back-to-back:","bold":true},{"text":" transferable = the "},{"text":"same","bold":true},{"text":" credit passed on (Mrs Ezenwa passing part of her Ghanaian buyer's credit to the Kano factory). Back-to-back = a "},{"text":"second, separate","bold":true},{"text":" credit backed by the first."}]},{"text":[{"text":"A Lagos manufacturer importing the same raw material from India every month uses a "},{"text":"revolving","bold":true},{"text":" credit instead of opening a new one each time."}]},{"text":[{"text":"Standby credits follow "},{"text":"ISP98","bold":true},{"text":" (or UCP 600); collections follow URC 522 (Lesson 11.3). Incoterms (CIF, FOB and so on) are delivery terms, not LC rules."}]}]}]},{"number":"11.3","title":"Documentary collections and shipping documents","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Documentary collection:","bold":true},{"text":" the exporter's bank sends the bill and shipping documents to a bank in the importer's country, which releases them to the importer on his paying or accepting. "},{"text":"Banks act only as agents and give no undertaking to pay.","bold":true}]},{"text":[{"text":"Rules:","bold":true},{"text":" "},{"text":"URC 522","bold":true},{"text":" (Uniform Rules for Collections, ICC)."}]},{"text":[{"text":"Parties:","bold":true},{"text":" "},{"text":"principal","bold":true},{"text":" (exporter, drawer); "},{"text":"remitting bank","bold":true},{"text":" (the "},{"text":"exporter's bank","bold":true},{"text":", which receives the documents and sends them abroad); "},{"text":"collecting bank","bold":true},{"text":" (any bank in the process other than the remitting bank); "},{"text":"presenting bank","bold":true},{"text":" (the collecting bank that presents the documents to the importer); "},{"text":"drawee","bold":true},{"text":" (importer)."}]}]},{"type":"table","header":[[],[{"text":"D/P (documents against payment)"}],[{"text":"D/A (documents against acceptance)"}]],"rows":[[[{"text":"Importer gets documents"}],[{"text":"only "},{"text":"on paying","bold":true}],[{"text":"on "},{"text":"accepting a bill payable later","bold":true},{"text":" (e.g. 90 days)"}]],[[{"text":"Bill"}],[{"text":"at sight"}],[{"text":"usance (term)"}]],[[{"text":"Exporter's risk"}],[{"text":"lower: no payment, no documents"}],[{"text":"higher: importer has the goods before he pays"}]]]},{"type":"table","header":[[{"text":"Collection"}],[{"text":"Letter of credit"}]],"rows":[[[{"text":"URC 522"}],[{"text":"UCP 600"}]],[[{"text":"Banks are agents only; "},{"text":"no bank undertaking","bold":true}],[{"text":"Issuing bank undertakes to pay","bold":true},{"text":" against compliant documents"}]],[[{"text":"Less safe, cheaper"}],[{"text":"Surest, dearer"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Shipping documents:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bill of lading (B/L):","bold":true},{"text":" issued by the shipping company. "},{"text":"3 functions:","bold":true},{"text":" (i) "},{"text":"receipt","bold":true},{"text":" for the goods, (ii) "},{"text":"evidence of the contract of carriage","bold":true},{"text":", (iii) "},{"text":"document of title","bold":true},{"text":", transferable by "},{"text":"endorsement","bold":true},{"text":"; the holder can take delivery."}]},{"text":[{"text":"Commercial invoice:","bold":true},{"text":" prepared by the "},{"text":"seller","bold":true},{"text":"; shows description, quantity, unit price and total value; used for "},{"text":"payment and customs valuation","bold":true},{"text":"."}]},{"text":[{"text":"Certificate of origin:","bold":true},{"text":" states the "},{"text":"country where the goods were produced or manufactured","bold":true},{"text":"."}]},{"text":[{"text":"Insurance policy or certificate:","bold":true},{"text":" proves the goods are covered against loss in transit; under "},{"text":"CIF","bold":true},{"text":" terms the buyer claims on it if goods are damaged at sea."}]},{"text":[{"text":"Air waybill:","bold":true},{"text":" the carrier's receipt for goods sent by air; "},{"text":"not a document of title","bold":true},{"text":", so goods are released to the "},{"text":"named consignee","bold":true},{"text":" without it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why prefer a collection to open $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 55, $study_guide$account even though neither has a bank guarantee? Because in a collection the "},{"text":"shipping documents stay under bank control until the buyer pays or accepts","bold":true},{"text":"."}]},{"text":[{"text":"The Onitsha importer who accepted a 90-day bill, took the documents, cleared the goods and then refused to pay: the exporter lost because the collection was on "},{"text":"D/A","bold":true},{"text":" terms."}]},{"text":[{"text":"Trap: a bill of lading does "},{"text":"not","bold":true},{"text":" certify the country of origin; that is the certificate of origin's job."}]}]}]},{"number":"11.4","title":"Foreign currency accounts, Nigerian trade forms and foreign exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade needs international settlements; two accounts are principally kept: "},{"text":"nostro","bold":true},{"text":" and "},{"text":"vostro","bold":true},{"text":"."}]},{"text":[{"text":"Nostro","bold":true},{"text":" (Latin \"our\"): accounts "},{"text":"maintained by Nigerian banks abroad","bold":true},{"text":", usually in foreign currency with a "},{"text":"correspondent bank","bold":true},{"text":", to "},{"text":"receive export proceeds","bold":true},{"text":" and "},{"text":"settle payments requiring foreign currency","bold":true},{"text":" overseas."}]},{"text":[{"text":"Vostro","bold":true},{"text":" (Latin \"your\"): accounts "},{"text":"kept by foreign commercial banks with Nigerian banks","bold":true},{"text":", into which payments in local currency are made and from which those banks "},{"text":"settle their obligations in Nigeria in naira","bold":true},{"text":"."}]},{"text":[{"text":"Loro","bold":true},{"text":" (\"their\"): an account of a third bank, referred to by two other banks."}]},{"text":[{"text":"One account, two names: a Nigerian bank's dollar account in New York is its "},{"text":"nostro","bold":true},{"text":"; the New York bank calls it a "},{"text":"vostro","bold":true},{"text":"."}]},{"text":[{"text":"Domiciliary account:","bold":true},{"text":" an account held in a "},{"text":"foreign currency","bold":true},{"text":" (USD, GBP, EUR and so on) in a "},{"text":"bank in Nigeria","bold":true},{"text":", by residents or non-residents, for foreign remittances, trade payments and holding forex. Since deregulation, exporters may keep their forex earnings in it. "},{"text":"2 types:","bold":true},{"text":" "},{"text":"Export Domiciliary Account","bold":true},{"text":" and "},{"text":"Ordinary Domiciliary Account","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian trade forms","bold":true},{"text":" (all processed through an "},{"text":"authorised dealer bank","bold":true},{"text":"):"}]}]},{"type":"table","header":[[{"text":"Form"}],[{"text":"Use"}]],"rows":[[[{"text":"Form M","bold":true}],[{"text":"statutory "},{"text":"import","bold":true},{"text":" document, completed and "},{"text":"registered electronically","bold":true},{"text":" through the authorised dealer bank, supported by a "},{"text":"proforma invoice","bold":true},{"text":", before importing"}]],[[{"text":"Form NXP","bold":true},{"text":" (Nigerian Export Proceeds Form)"}],[{"text":"statutory "},{"text":"export","bold":true},{"text":" form, so the export and the "},{"text":"repatriation of its proceeds","bold":true},{"text":" are documented and tracked"}]],[[{"text":"Form A","bold":true}],[{"text":"foreign exchange for "},{"text":"invisible","bold":true},{"text":" (service) payments, e.g. school fees, medical bills, travel"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Spot transaction:","bold":true},{"text":" settled almost immediately (normally within "},{"text":"2 business days","bold":true},{"text":") at "},{"text":"today's rate","bold":true},{"text":"."}]},{"text":[{"text":"Forward exchange contract:","bold":true},{"text":" fixes a rate "},{"text":"today","bold":true},{"text":" for exchange at a "},{"text":"future date","bold":true},{"text":"; removes exchange rate risk."}]},{"text":[{"text":"Formula:","bold":true},{"text":" Saving from forward = Foreign amount x (Spot rate on settlement day - Forward rate). A negative answer is an extra cost."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (forward saving):","bold":true},{"text":" an importer books a forward contract to buy USD 25,000 in 3 months at ₦1,520 per US dollar. On settlement day the spot rate is ₦1,560."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost at spot: 25,000 x 1,560 = ₦39,000,000."}]},{"text":[{"text":"Cost under forward: 25,000 x 1,520 = ₦38,000,000."}]},{"text":[{"text":"Saving: ₦39,000,000 - ₦38,000,000 = "},{"text":"₦1,000,000","bold":true},{"text":" (check: 25,000 x 40 = ₦1,000,000)."}]}]}]},{"text":[{"text":"If the naira had instead strengthened to ₦1,500, he would still pay ₦1,520: 25,000 x (1,500 - 1,520) = -₦500,000, an extra cost of ₦500,000 compared with spot. A forward removes uncertainty both ways; it is cover, not a bet."}]},{"text":[{"text":"A Lagos importer who owes USD 40,000 in three months and fears naira weakness should take a "},{"text":"forward exchange contract","bold":true},{"text":" now, not wait for a spot purchase in three months."}]},{"text":[{"text":"Traps: the account every bank keeps with the "},{"text":"CBN","bold":true},{"text":" for clearing is not a nostro; a customer's dollar account at a local branch is "},{"text":"domiciliary","bold":true},{"text":", not nostro. Form M is for "},{"text":"imports","bold":true},{"text":", NXP for "},{"text":"exports","bold":true},{"text":". Nostro and vostro work is done in a bank's "},{"text":"Reconciliation Unit","bold":true},{"text":"; LCs and collections in "},{"text":"Trade Services","bold":true},{"text":"."}]}]}]},{"number":"11.5","title":"Export finance, NEXIM and the trade roles of banks","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pre-shipment finance:","bold":true},{"text":" $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 56, $study_guide$money to "},{"text":"buy, process and pack","bold":true},{"text":" goods "},{"text":"before shipment","bold":true},{"text":" (e.g. packing credit, red clause credit)."}]},{"text":[{"text":"Post-shipment finance:","bold":true},{"text":" money "},{"text":"after shipment","bold":true},{"text":", e.g. "},{"text":"negotiating or discounting the export bill","bold":true},{"text":"."}]},{"text":[{"text":"Bill negotiation formula:","bold":true},{"text":" Amount credited = Face value - Interest - Commission, where Interest = Face value x Rate x (Months / 12) and Commission = Face value x Commission rate."}]},{"text":[{"text":"Factoring:","bold":true},{"text":" "},{"text":"sale of short-term book debts","bold":true},{"text":" (receivables) to a factor, who pays an agreed portion (often about 60% of book value) at once."}]},{"text":[{"text":"Forfaiting:","bold":true},{"text":" "},{"text":"purchase, without recourse, of medium-term export receivables","bold":true},{"text":" such as "},{"text":"avalised","bold":true},{"text":" (bank-guaranteed) bills or promissory notes."}]},{"text":[{"text":"Export credit insurance:","bold":true},{"text":" protects the exporter against "},{"text":"commercial risk","bold":true},{"text":" (buyer's default) "},{"text":"and political risk","bold":true},{"text":" (war, transfer bans) in the buyer's country."}]},{"text":[{"text":"NEXIM (Nigerian Export-Import Bank):","bold":true},{"text":" established by the "},{"text":"NEXIM Act No. 38 of 1991","bold":true},{"text":", "},{"text":"jointly owned by the Federal Government and the CBN","bold":true},{"text":", as Nigeria's "},{"text":"Export Credit Agency","bold":true},{"text":", with a share capital of ₦50 billion under the 1991 Act. "},{"text":"5 functions:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Export "},{"text":"credit guarantee and credit insurance","bold":true},{"text":" facilities to Nigerian exporters."}]},{"text":[{"text":"Domestic credit insurance","bold":true},{"text":" that assists exports."}]},{"text":[{"text":"A "},{"text":"foreign exchange revolving fund","bold":true},{"text":" lent to exporters to "},{"text":"import foreign inputs","bold":true},{"text":" for producing exportable goods."}]},{"text":[{"text":"Investment guarantee and investment insurance","bold":true},{"text":" facilities to exporters."}]},{"text":[{"text":"An adequate "},{"text":"information system","bold":true},{"text":" to support export business."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"NEXIM also gives "},{"text":"short- and medium-term loans","bold":true},{"text":" to exporters, short-term "},{"text":"guarantees for bank loans","bold":true},{"text":" to exporters, and cover against "},{"text":"political and commercial risks","bold":true},{"text":" of non-payment by foreign buyers. It does "},{"text":"not","bold":true},{"text":" grant mortgage loans."}]},{"text":[{"text":"Merchant banks' foreign exchange services","bold":true},{"text":" (wholesale, to corporates): "},{"text":"correspondent banking","bold":true},{"text":", where they "},{"text":"arrange the confirmation of letters of credit","bold":true},{"text":" for clients; and "},{"text":"operations","bold":true},{"text":": opening LCs, remitting export proceeds to clients' beneficiaries abroad, getting forex for clients' payments abroad. Their "},{"text":"traditional first function is acceptance","bold":true},{"text":": adding their name to bills of exchange to finance others' trade (hence \"accepting houses\")."}]},{"text":[{"text":"Commercial banks in international trade:","bold":true},{"text":" accepting and collecting foreign bills; discounting bills and documentary credits so sellers are paid at once; "},{"text":"confirming letters of credit","bold":true},{"text":"; buying and selling foreign currency; acting as "},{"text":"referees","bold":true},{"text":" (status opinions) on traders' creditworthiness. They do "},{"text":"not fix the official exchange rate","bold":true},{"text":"; that is the CBN's role."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (bill negotiation):","bold":true},{"text":" Chief Adebayo, a Lagos cocoa exporter, negotiates a ₦4,000,000 bill 3 months before maturity. Interest 12% p.a., commission 0.5% of face value."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interest: 4,000,000 x 0.12 x 3/12 = ₦120,000."}]},{"text":[{"text":"Commission: 4,000,000 x 0.005 = ₦20,000."}]},{"text":[{"text":"Credited: 4,000,000 - 120,000 - 20,000 = "},{"text":"₦3,860,000","bold":true},{"text":"."}]},{"text":[{"text":"Traps: ₦3,880,000 forgets the commission; ₦3,980,000 forgets the interest."}]}]}]},{"text":[{"text":"A Sapele timber exporter financed to process the timber and later having his bill discounted has received "},{"text":"pre-shipment then post-shipment","bold":true},{"text":" finance, in that order."}]},{"text":[{"text":"A cashew exporter fearing war or a currency transfer ban in the buyer's country needs "},{"text":"export credit insurance","bold":true},{"text":" such as NEXIM offers. Paying school fees abroad is a Form A matter, not a NEXIM fund."}]},{"text":[{"text":"Status opinion:","bold":true},{"text":" when a Ghanaian importer asks about a Nigerian exporter, the exporter's bank gives a confidential reply on his creditworthiness, acting as a "},{"text":"referee","bold":true},{"text":". It is given in confidence and without responsibility, but must not be misleading."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exporter's risk rises: advance payment, LC, documentary collection, clean collection, "},{"text":"open account","bold":true},{"text":" (riskiest). Advance payment is riskiest for the importer."}]},{"text":[{"text":"Clean collection = bill only; documentary = bill plus documents; banks are agents only, under "},{"text":"URC 522","bold":true},{"text":"."}]},{"text":[{"text":"LC: applicant =$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 57, $study_guide$ importer; beneficiary = exporter; issuing = importer's bank; advising = exporter's bank; confirming adds a promise. "},{"text":"UCP 600","bold":true},{"text":": irrevocable even if silent; documents, not goods."}]},{"text":[{"text":"D/P = documents on payment; D/A = documents on acceptance (riskier)."}]},{"text":[{"text":"Transferable, back-to-back, red clause (advance), revolving (reinstated), standby (guarantee)."}]},{"text":[{"text":"B/L = receipt, contract of carriage, document of title; air waybill is not a title document."}]},{"text":[{"text":"Nostro = ours abroad; vostro = theirs here in naira; domiciliary = forex account in Nigeria (export and ordinary)."}]},{"text":[{"text":"Form M imports, Form NXP exports, Form A invisibles. Forward fixes today's rate for a future date."}]},{"text":[{"text":"Bill negotiation: face value - interest - commission. NEXIM: Act 38 of 1991, FGN and CBN, export credit agency."}]},{"text":[{"text":"Merchant banks: acceptance, LC confirmation. Commercial banks act as referees; the CBN, not they, sets the official rate."}]}]}],"theory":{"itemId":"9437fe54-c183-5fea-93dc-a733022fb320","question":[{"type":"paragraph","text":[{"text":"An exporter negotiates a ₦6,000,000 export bill with his bank 2 months before maturity. The bank charges interest at 15% per annum and a commission of 0.25% of face value. How much does he receive?"}]}]},"practice":[{"topic":"Bank Account Services for Exporters and Importers","named":false}]}},{"kind":"note","itemId":"34973020-0754-559b-b52e-67d797deaced","sourceKey":"guide-topic:12","position":12,"payload":{"title":"Bank Lending","body":"Lending, borrowing, interest and risk assets; principles and objectives of lending; the 5 Cs and canons; security, its qualities and forms; loan procedure and agreement terms; loan versus overdraft; bad debts and recovery; loan computations.","noteType":"guide_topic","number":12,"mustKnow":[{"text":"Lending, borrowing, interest and risk assets; principles and objectives of lending; the 5 Cs and canons; security, its qualities and forms; loan procedure and agreement terms; loan versus overdraft; bad debts and recovery; loan computations."}],"lessons":[{"number":"12.1","title":"Meaning of lending and its principles","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bank lending:","bold":true},{"text":" the extension of a credit facility to an intending borrower on the understanding that the principal and the interest on it will be repaid at an agreed future date. Lending is the "},{"text":"most profitable","bold":true},{"text":" business of banks."}]},{"text":[{"text":"Borrowing:","bold":true},{"text":" the ability of a willing and creditworthy customer to obtain a credit facility from a bank or other loan provider, with a view to repaying the sum at an agreed future date (with or without interest)."}]},{"text":[{"text":"Interest:","bold":true},{"text":" the return paid by the borrower to the provider of funds, usually stated as a "},{"text":"percentage of the principal","bold":true},{"text":" per month or per annum. Banks charge a "},{"text":"higher rate","bold":true},{"text":" to compensate for the "},{"text":"risk that the borrower may default","bold":true},{"text":"."}]},{"text":[{"text":"Risk asset:","bold":true},{"text":" loans and advances are called risk assets because the "},{"text":"recovery of all the credit extended is uncertain","bold":true},{"text":"."}]},{"text":[{"text":"Three principles of lending (Mather, 1972):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Safety:","bold":true},{"text":" of "},{"text":"paramount importance","bold":true},{"text":". The borrower's character, integrity and reliability must be sound; the source of repayment must be probed and certain."}]},{"text":[{"text":"Suitability:","bold":true},{"text":" the purpose must not conflict with the government's economic and monetary policies. No lending for gambling, betting or other speculative activities."}]},{"text":[{"text":"Profitability:","bold":true},{"text":" banks are not charities; every advance must earn profit (interest)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Objectives banks seek when granting credit (4):","bold":true}]}]},{"type":"table","header":[[{"text":"Objective"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Profitability"}],[{"text":"loans, advances and investments yield good returns to shareholders"}]],[[{"text":"Liquidity"}],[{"text":"assets can quickly become cash to meet depositors' withdrawals and CBN requirements"}]],[[{"text":"Safety"}],[{"text":"depositors' funds are safeguarded so they can withdraw on demand without delay"}]],[[{"text":"Suitability"}],[{"text":"lending fits sound policy and regulators' rules; not all loans committed to long-term projects"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: "},{"text":"speculation","bold":true},{"text":" and "},{"text":"growth","bold":true},{"text":" are not lending objectives."}]},{"text":[{"text":"A bank that lends out almost all its deposits fails on "},{"text":"liquidity","bold":true},{"text":"; a bank that keeps everything as cash and lends nothing sacrifices "},{"text":"profitability","bold":true},{"text":"."}]},{"text":[{"text":"A customer with a good record and good security who wants money for football betting or a gambling business is refused on "},{"text":"suitability","bold":true},{"text":", not safety."}]},{"text":[{"text":"BOFIA 2020","bold":true},{"text":" (which replaced BOFIA 1991) requires that a bank manager or officer may grant an advance, loan or credit facility only if it is "},{"text":"authorised in accordance with the rules and regulations of the bank","bold":true},{"text":" and in line with the CBN's regulations on collateralisation (section 17)."}]}]}]},{"number":"12.2","title":"The 5 Cs and the canons of lending","mustKnow":[{"type":"paragraph","text":[{"text":"The 5 Cs of lending:","bold":true}]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 58, $study_guide$},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Character:","bold":true},{"text":" honesty, integrity, willingness to repay. The "},{"text":"first and best security","bold":true},{"text":"; \"the real security for any advance is the character of the borrower\". Checked by a "},{"text":"status enquiry","bold":true},{"text":"."}]},{"text":[{"text":"Capacity:","bold":true},{"text":" ability to repay; track record, technical and managerial know-how."}]},{"text":[{"text":"Capital:","bold":true},{"text":" the borrower's own contribution to the project."}]},{"text":[{"text":"Collateral:","bold":true},{"text":" security to fall back on. The "},{"text":"last and least","bold":true},{"text":" consideration, a residual matter not crucial to the decision."}]},{"text":[{"text":"Conditions:","bold":true},{"text":" the economic environment and the sector's prospects."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Status enquiry:","bold":true},{"text":" obtaining background information on a prospective borrower (from other banks and sources) to find out whether he is "},{"text":"prudent or prodigal","bold":true},{"text":" with borrowed funds."}]}]},{"type":"paragraph","text":[{"text":"The canons of lending: 7 questions on receiving a loan request","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"How much does the customer require? ("},{"text":"Amount","bold":true},{"text":")"}]},{"text":[{"text":"What does he want it for? ("},{"text":"Purpose","bold":true},{"text":")"}]},{"text":[{"text":"For how long? ("},{"text":"Duration","bold":true},{"text":")"}]},{"text":[{"text":"What is the source of repayment? ("},{"text":"Repayment","bold":true},{"text":")"}]},{"text":[{"text":"Is the business strong enough to keep going if plans suffer a setback? ("},{"text":"Strength of the business","bold":true},{"text":")"}]},{"text":[{"text":"What security can he offer? ("},{"text":"Security","bold":true},{"text":")"}]},{"text":[{"text":"What is your assessment of the customer? ("},{"text":"The borrower","bold":true},{"text":")"}]}]},{"type":"paragraph","text":[{"text":"Checklist for assessing proposals (9):","bold":true},{"text":" character, capacity, capital, purpose, amount, repayment, stability, security, monitoring."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital:","bold":true},{"text":" before a ₦50 million cassava-processing loan, the bank insists the promoters put in substantial money of their own. A borrower with little at stake may not be committed, leaving the risk mostly on the bank."}]},{"text":[{"text":"Conditions:","bold":true},{"text":" in a recession, a Lagos bank cuts new loans to hotels and event centres even for good customers."}]},{"text":[{"text":"Collateral","bold":true},{"text":" never replaces assessing ability to repay. A highly creditworthy borrower with a proven track record may get an advance "},{"text":"without collateral","bold":true},{"text":"."}]},{"text":[{"text":"Amount:","bold":true},{"text":" lend too little and the project may be "},{"text":"abandoned uncompleted","bold":true},{"text":", so repayment never comes; lend too much and the bank takes excess risk."}]},{"text":[{"text":"Purpose:","bold":true},{"text":" must be legal and outside banks' no-go areas. An illegal activity is the purpose a Nigerian banker is least willing to finance. Borrowing "},{"text":"short","bold":true},{"text":" to buy fixed assets such as a factory building means \"borrowing short and investing long\", which is risky because fixed assets are not quickly saleable."}]},{"text":[{"text":"Duration:","bold":true},{"text":" deposits are mostly "},{"text":"short-term","bold":true},{"text":", so commercial banks prefer short-term working-capital finance. Medium and long-term requests go to merchant banks and development institutions such as the "},{"text":"Bank of Industry (BOI)","bold":true},{"text":"."}]},{"text":[{"text":"Repayment:","bold":true},{"text":" a personal customer shows earnings and outgoings; a company submits a "},{"text":"cash budget, projected profit and loss account and projected balance sheet","bold":true},{"text":"."}]},{"text":[{"text":"Strength of the business:","bold":true},{"text":" balance sheets and profit and loss accounts for about "},{"text":"three years","bold":true},{"text":" show whether it can remain a going concern."}]}]}]},{"number":"12.3","title":"Security and its qualities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Security (collateral):","bold":true},{"text":" anything of value deposited or pledged as a guarantee of repayment of a loan, to be forfeited on default; an asset the bank can fall back on if the borrower fails to repay."}]},{"text":[{"text":"Security interest:","bold":true},{"text":" an enforceable legal claim on collateral pledged for a loan, giving the lender the right to repossess the property if the borrower fails to repay."}]},{"text":[{"text":"Margin:","bold":true},{"text":" the difference between the market value of the security and the loan granted against it."}]},{"text":[{"text":"Why banks take security:","bold":true},{"text":" a safety net if repayment fails; a customer who has deposited his property or title documents is more likely to "},{"text":"use the funds judiciously","bold":true},{"text":" for the agreed purpose."}]},{"text":[{"text":"Rule:","bold":true},{"text":" obtain and "},{"text":"perfect","bold":true},{"text":" the security "},{"text":"before disbursing","bold":true},{"text":" funds."}]}]},{"type":"paragraph","text":[{"text":"Qualities of good security (9):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Non-encumbrance:","bold":true},{"text":" free of disputes and of prior charges to other lenders."}]},{"text":[{"text":"Stability of price","bold":true},{"text":" and ease of valuation."}]},{"text":[{"text":"Legal acceptability.","bold":true}]},{"text":[{"text":"Adequacy:"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 59, $study_guide$,"bold":true},{"text":" covers the full loan plus a reasonable margin."}]},{"text":[{"text":"Proper documentation","bold":true},{"text":" (mortgage deed, pledge agreement)."}]},{"text":[{"text":"Ownership and possession","bold":true},{"text":" (undoubted title)."}]},{"text":[{"text":"Income generation / low maintenance cost.","bold":true}]},{"text":[{"text":"Marketability:","bold":true},{"text":" a ready, broad market."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" quickly convertible to cash at a known price."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mrs Bello's shop already charged to another bank lacks "},{"text":"non-encumbrance","bold":true},{"text":"."}]},{"text":[{"text":"Bankers dislike "},{"text":"luxury goods","bold":true},{"text":" as security because their prices swing with fashion and taste; necessities are more stable."}]},{"text":[{"text":"An illegal asset is hard to dispose of and exposes the bank to legal consequences."}]},{"text":[{"text":"A block of flats paying rent beats a vacant plot: "},{"text":"income generation","bold":true},{"text":"."}]},{"text":[{"text":"Mr Ojo's late father's house, not in his name and disputed by family, lacks "},{"text":"undoubted title","bold":true},{"text":"."}]},{"text":[{"text":"High maintenance cost","bold":true},{"text":" is never a quality of good security."}]}]}]},{"number":"12.4","title":"Forms of security","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personal security:","bold":true},{"text":" a guarantee by the borrower or a third party instead of a tangible asset (personal guarantee, life policy)."}]},{"text":[{"text":"Non-personal (tangible) security:","bold":true},{"text":" movable and immovable property: land (mortgage), debentures, shares, goods (lien, pledge, hypothecation). "},{"text":"Safer","bold":true},{"text":", because the property can be sold to recover the unpaid amount."}]},{"text":[{"text":"Freehold","bold":true},{"text":" land: absolute title, lasts indefinitely, higher value. "},{"text":"Leasehold:","bold":true},{"text":" title expires; value "},{"text":"falls","bold":true},{"text":" as the unexpired years reduce."}]},{"text":[{"text":"Mortgage:","bold":true},{"text":" a security created by contract giving the lender an interest in the borrower's property until a sum is repaid; written agreement registered at the land registry. Borrower = "},{"text":"mortgagor","bold":true},{"text":"; bank = "},{"text":"mortgagee","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Legal mortgage"}],[{"text":"Equitable mortgage"}]],"rows":[[[{"text":"Legal estate"}],[{"text":"vests in the mortgagee"}],[{"text":"stays with the mortgagor"}]],[[{"text":"Creation"}],[{"text":"mortgage deed, under seal"}],[{"text":"deposit of title deeds"}]],[[{"text":"Possession"}],[{"text":"immediate right for mortgagee"}],[{"text":"mortgagor keeps the property"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Guarantee:","bold":true},{"text":" a promise by one person ("},{"text":"guarantor / surety","bold":true},{"text":") to answer for the present or future debt of another ("},{"text":"principal debtor","bold":true},{"text":"), made to the creditor (the "},{"text":"bank","bold":true},{"text":"). "},{"text":"Specific","bold":true},{"text":" guarantee: one debt (e.g. a term loan). "},{"text":"Continuing","bold":true},{"text":" guarantee: a series of transactions, e.g. an overdraft, present and future balances."}]},{"text":[{"text":"Advantages of a guarantee:","bold":true},{"text":" easy to take (just sign); useful where the borrower has no property. "},{"text":"Disadvantages:","bold":true},{"text":" value depends "},{"text":"wholly on the guarantor's financial standing","bold":true},{"text":"; suing him is costly and slow; technical defects may free him."}]}]},{"type":"table","header":[[{"text":"Charge over goods"}],[{"text":"Ownership"}],[{"text":"Possession"}],[{"text":"Note"}]],"rows":[[[{"text":"Lien"}],[{"text":"borrower"}],[{"text":"lender"}],[{"text":"ordinary lien: retain only; "},{"text":"banker's lien: may sell after proper notice","bold":true}]],[[{"text":"Pledge"}],[{"text":"borrower"}],[{"text":"bank (actual or constructive delivery)"}],[{"text":"bailment of goods"}]],[[{"text":"Hypothecation"}],[{"text":"borrower"}],[{"text":"borrower"}],[{"text":"equitable charge; riskiest, because the goods stay in the borrower's possession"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed charge:","bold":true},{"text":" over specific assets (a particular machine or property). "},{"text":"Floating charge:","bold":true},{"text":" over a class of assets (stock, receivables) the company may deal in until "},{"text":"crystallisation","bold":true},{"text":" on default or liquidation. Created by a "},{"text":"debenture","bold":true},{"text":" and registered with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Constructive delivery:","bold":true},{"text":" the bank's padlock on the warehouse door holding a trader's rice, key kept by the bank, is a "},{"text":"pledge","bold":true},{"text":" although the rice never moves."}]},{"text":[{"text":"Hypothecation suits raw materials a business must keep using; the bank should inspect the goods regularly."}]},{"text":[{"text":"In Nigeria, since the "},{"text":"Land Use Act 1978","bold":true},{"text":", land in each state is vested in the state Governor and held under a "},{"text":"right of occupancy","bold":true},{"text":" (evidenced by a certificate of occupancy, usually for up to 99 years), so the leasehold point above (value falls as the unexpired term shortens) applies to Nigerian titles."}]}]},{"type":"paragraph","text":[{"text":"Procedure for taking security","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Savings account:","bold":true},{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 60, $study_guide$t":" letter of authority to transfer; surrender the "},{"text":"passbook","bold":true},{"text":"; a signed blank withdrawal form (no date or amount). A certificate of occupancy is "},{"text":"not","bold":true},{"text":" needed."}]},{"text":[{"text":"Current account:","bold":true},{"text":" letter of authority; signed blank cheque."}]},{"text":[{"text":"Fixed deposit:","bold":true},{"text":" letter of authority; surrender the receipt or certificate; renew and endorse it if it expires first."}]},{"text":[{"text":"Life policy:","bold":true},{"text":" check the insurer, beneficiary, surrender value and premiums; complete a "},{"text":"deed of assignment","bold":true},{"text":"; "},{"text":"give notice to the insurance company","bold":true},{"text":", which acknowledges it."}]},{"text":[{"text":"Stocks and shares:","bold":true},{"text":" customer signs a "},{"text":"memorandum of deposit","bold":true},{"text":" (rights including disposal on default); transfer by deed at the stock exchange (the traditional procedure; quoted shares are now held electronically in the Central Securities Clearing System, CSCS, where the bank's interest is recorded)."}]},{"text":[{"text":"Land:","bold":true},{"text":" deposit the title deed or "},{"text":"certificate of occupancy","bold":true},{"text":"; "},{"text":"search at the land registry (ministry of lands)","bold":true},{"text":" to verify authenticity and ownership; physical inspection; then a legal mortgage (Governor's consent under the Land Use Act)."}]}]}]},{"number":"12.5","title":"Procedure, facilities, agreements, bad debts and recovery","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Individual applicant:","bold":true},{"text":" current account; application; "},{"text":"statement of affairs","bold":true},{"text":"; securities; agreement."}]},{"text":[{"text":"Corporate applicant","bold":true},{"text":" adds: audited accounts and tax clearance for 3 years; Memorandum and Articles; "},{"text":"certificate of incorporation","bold":true},{"text":"; cash-flow projection."}]},{"text":[{"text":"Ways banks extend credit:","bold":true},{"text":" loans, overdrafts, discounting of bills of exchange (a "},{"text":"standing order","bold":true},{"text":" is a payment service, not credit)."}]},{"text":[{"text":"Overdraft:","bold":true},{"text":" an arrangement allowing a current account holder to withdraw more than his balance up to an agreed limit. "},{"text":"Conditions:","bold":true},{"text":" current account holder; evidence of honesty; account activity for at least "},{"text":"six months","bold":true},{"text":"; express approval of the manager."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Loan"}],[{"text":"Overdraft"}]],"rows":[[[{"text":"Account"}],[{"text":"separate loan account"}],[{"text":"runs on the current account"}]],[[{"text":"Interest"}],[{"text":"on the whole amount granted"}],[{"text":"only on the amount actually overdrawn, daily"}]],[[{"text":"Term"}],[{"text":"specific purpose, fixed repayment; ends at maturity"}],[{"text":"short-term, repayable "},{"text":"on demand","bold":true},{"text":", renewable"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Loan account entries:","bold":true},{"text":" "},{"text":"debit","bold":true},{"text":" a new loan account, "},{"text":"credit","bold":true},{"text":" the current account. Repayment and interest: "},{"text":"debit","bold":true},{"text":" current account, "},{"text":"credit","bold":true},{"text":" loan account."}]},{"text":[{"text":"Terms of loan agreements (5):","bold":true},{"text":" prohibition of further charges; bank approval of major management changes; rendering of financial returns; restriction of benefits to shareholders (dividends after repayments); insurance cover on mortgaged property kept in good repair. A share of the borrower's profits is "},{"text":"not","bold":true},{"text":" a usual term."}]},{"text":[{"text":"Monitoring (3):","bold":true},{"text":" regular demand for records; "},{"text":"physical inspection","bold":true},{"text":" of the project; watching the account for hard-core borrowing and missed reductions."}]},{"text":[{"text":"Bad debt:","bold":true},{"text":" a debt whose full or partial recovery is considered not possible."}]}]},{"type":"paragraph","text":[{"text":"Causes of bad debts (10):","bold":true},{"text":" lack of in-depth knowledge of the customer's operations; excessive dependence on the balance sheet; "},{"text":"connected lending","bold":true},{"text":" (loans to relations or related businesses without the basic principles); lending on "},{"text":"overvalued securities","bold":true},{"text":"; inadequate project monitoring; lack of appraisal skills; manipulation of account records; borrowers' misconception of loans as windfalls; "},{"text":"natural hazards","bold":true},{"text":" (drought, flood, war: worst for "},{"text":"agricultural loans","bold":true},{"text":"); changes in economic policies."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recovery:","bold":true},{"text":" amicable methods first (restructuring, rescheduling, negotiated settlement), which "},{"text":"preserve the relationship and avoid costly litigation","bold":true},{"text":"; then demand letters, writ of summons, garnishee, winding-up or bankruptcy; "},{"text":"realisation of security","bold":true},{"text":" (power of sale under a mortgage, a receiver under a debenture, enforcing a pledge or guarantee); reporting defaulters to licensed "},{"text":"credit bureaus","bold":true},{"text":" such as CRC Credit Bureau, which "},{"text":"affects their future access to credit","bold":true},{"text":"; and, for eligible assets, "},{"text":"AMCON","bold":true},{"text":"."}]},{"text":[{"text":"Amortisation:","bold":true},{"text":" retiring a loan gradually by periodic payments rather than all at maturity. For a specific asset such as a delivery truck, repayments should match the asset's "},{"text":"productive life","bold"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 61, $study_guide$:true},{"text":" and come from its cash flows."}]}]}]},{"number":"12.6","title":"Loan computations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Flat (simple) interest = P x R x T (T in years; months / 12; days / 365)"}]},{"text":[{"text":"Total repayable = P + interest; equal instalment = total repayable / number of instalments"}]},{"text":[{"text":"Annuity payment = loan / PVIFA, where PVIFA = [1 - (1 + i)^-n] / i; interest each period = rate x opening balance; principal repaid = payment - interest"}]},{"text":[{"text":"Overdraft interest = amount overdrawn x rate x days / 365, summed for each balance"}]},{"text":[{"text":"LTV = loan / value of security x 100; margin = value - loan; margin % = (value - loan) / value x 100"}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"1. Mr Eze's vehicle loan:","bold":true},{"text":" ₦200,000 on 1 January 1996, 2 years, 4 equal half-yearly instalments, 10% flat; current account ₦40,000 credit."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interest = 200,000 x 0.10 x 2 = ₦40,000; per half-year ₦10,000."}]},{"text":[{"text":"Principal per half-year = 200,000 / 4 = ₦50,000."}]},{"text":[{"text":"Debit each half-year = 50,000 + 10,000 = "},{"text":"₦60,000","bold":true},{"text":"."}]},{"text":[{"text":"Current account: 40,000 + 200,000 = 240,000; then 180,000; 120,000; 60,000; "},{"text":"nil","bold":true},{"text":" at 31/12/97."}]}]},{"type":"paragraph","text":[{"text":"2. Flat interest and instalments","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"₦500,000, 3 years, 18%: 500,000 x 0.18 x 3 = "},{"text":"₦270,000","bold":true},{"text":" (not ₦90,000, one year only)."}]},{"text":[{"text":"₦300,000, 9 months, 16%: 300,000 x 0.16 x 9/12 = "},{"text":"₦36,000","bold":true},{"text":"."}]},{"text":[{"text":"₦1,200,000, 12 months, 15%, 12 monthly instalments: interest 180,000; total 1,380,000; / 12 = "},{"text":"₦115,000","bold":true},{"text":"."}]},{"text":[{"text":"₦2,000,000, 2 years, 14%, 8 quarterly instalments: interest 560,000; total 2,560,000; / 8 = "},{"text":"₦320,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"3. Balances","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Mr Uche: ₦800,000 in 4 half-yearly principal instalments of 200,000. After the third: 800,000 - 600,000 = "},{"text":"₦200,000","bold":true},{"text":"."}]},{"text":[{"text":"Bisi: 150,000 + 600,000 = 750,000 credit. Year 1 debit = 600,000 / 3 + 600,000 x 0.10 = 200,000 + 60,000 = 260,000. Balance = "},{"text":"₦490,000 credit","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4. Amortisation:","bold":true},{"text":" ₦1,000,000, 10%, 3 equal year-end payments."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PVIFA = [1 - 1.1^-3] / 0.10 = 2.486852; payment = 1,000,000 / 2.486852 = "},{"text":"₦402,114.80","bold":true},{"text":" (to the nearest kobo)."}]}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening"}],[{"text":"Interest 10%"}],[{"text":"Principal"}],[{"text":"Closing"}]],"rows":[[[{"text":"1"}],[{"text":"1,000,000.00"}],[{"text":"100,000.00"}],[{"text":"302,114.80"}],[{"text":"697,885.20"}]],[[{"text":"2"}],[{"text":"697,885.20"}],[{"text":"69,788.52"}],[{"text":"332,326.28"}],[{"text":"365,558.92"}]],[[{"text":"3"}],[{"text":"365,558.92"}],[{"text":"36,555.89"}],[{"text":"365,558.91"}],[{"text":"0.01 (rounding)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"First year's principal reduction = 402,114.80 - 100,000 = "},{"text":"₦302,114.80","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5. Overdraft interest","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Kola: 400,000 x 0.20 x 73/365 = "},{"text":"₦16,000.00","bold":true},{"text":"."}]},{"text":[{"text":"Femi Stores (limit ₦1m, used ₦600,000): 600,000 x 0.24 x 30/365 = "},{"text":"₦11,835.62","bold":true},{"text":" (on the amount used, never the limit)."}]},{"text":[{"text":"Changing balance: 250,000 x 0.18 x 20/365 = 2,465.75; 450,000 x 0.18 x 10/365 = 2,219.18; total = "},{"text":"₦4,684.93","bold":true},{"text":" (rounded to kobo)."}]}]},{"type":"paragraph","text":[{"text":"6. LTV and margin","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"₦12m against ₦20m: 12 / 20 x 100 = "},{"text":"60%","bold":true},{"text":"."}]},{"text":[{"text":"Maximum LTV 70% on ₦15m: maximum loan 10,500,000; margin = 15,000,000 - 10,500,000 = "},{"text":"₦4,500,000","bold":true},{"text":"."}]},{"text":[{"text":"₦1.8m against shares worth ₦2.5m: (2,500,000 - 1,800,000) / 2,500,000 x 100 = "},{"text":"28%","bold":true},{"text":" (LTV is 72%)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lending = extending credit to be repaid with interest; loans are risk assets."}]},{"text":[{"text":"Mather's principles: safety (paramount), suitability, profitability; objectives add liquidity."}]},{"text":[{"text":"5 Cs: character (first and best security), capacity, capital, collateral (last and least), conditions."}]},{"text":[{"text":"Canons: amount, purpose, duration, repayment, strength of business, security, the borrower."}]},{"text":[{"text":"Legal mortgage vests the legal estate; equitable mortgage is by deposit of deeds. Pledge = bank holds; hypothecation = borrower holds."}]},{"text":[{"text":"Loan: separate account, interest on full amount. Overdraft: current account, interest on amount used, repayable on demand."}]},{"text":[{"text":"Flat interest = P x R x T; annuity payment = loan / PVIFA; LTV = loan / value."}]}]}],"theory":{"itemId":"18d4be41-705b-541c-a2ea-ecd36219fe1f","question":[{"type":"paragraph","text":[{"text":"Ada borrows ₦900,000 for 18 months at 12% per annum flat interest on the original principal, repaying principal and interest in 18 equal monthly instalments. Find the total interest and each instalment."}]}]},"practice":[{"topic":"Bank Lending","named":f$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 62, $study_guide$alse}]}},{"kind":"note","itemId":"00f013a5-ed76-555c-b667-452f9a34679e","sourceKey":"guide-topic:13","position":13,"payload":{"title":"Balance Sheet Structure and Interpreting Customers' Accounts","body":"Why bank accounts must be uniform and what SAS 10 covered; the bank's financial statements; every asset and liability item in order; statutory reserve rules under BOFIA 2020; deposit and non-deposit sources of funds and the uses of funds; bank ratios (liquidity, cash reserve, excess reserve, loan-to-deposit); and how a lending banker reads a customer's accounts: liquidity, gearing, profitability and activity ratios, window dressing, break-up value and overtrading.","noteType":"guide_topic","number":13,"mustKnow":[{"text":"Why bank accounts must be uniform and what SAS 10 covered; the bank's financial statements; every asset and liability item in order; statutory reserve rules under BOFIA 2020; deposit and non-deposit sources of funds and the uses of funds; bank ratios (liquidity, cash reserve, excess reserve, loan-to-deposit); and how a lending banker reads a customer's accounts: liquidity, gearing, profitability and activity ratios, window dressing, break-up value and overtrading."}],"lessons":[{"number":"13.1","title":"Bank financial statements and SAS 10","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why uniform bank accounts matter:","bold":true},{"text":" banks hold the public's savings, provide the means of payment and finance business and trade, so they must keep public confidence. Their statements must be "},{"text":"uniformly presented, reliable, factual and comparable","bold":true},{"text":", so users can judge performance and regulators (CBN, NDIC) can classify and supervise them."}]},{"text":[{"text":"Statement of Accounting Standard (SAS) 10","bold":true},{"text":" (accounting by banks) focused on "},{"text":"3 main areas:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Income recognition","bold":true}]},{"text":[{"text":"Loss recognition","bold":true}]},{"text":[{"text":"Balance sheet classification","bold":true}]}]}]},{"text":[{"text":"6 reasons a special standard was needed:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Importance of the banking sector to industrial and commercial development."}]},{"text":[{"text":"Allegedly overstated profits","bold":true},{"text":" reported by banks."}]},{"text":[{"text":"Inconsistent accounting policies","bold":true},{"text":" and reporting practices that made comparison of performance difficult."}]},{"text":[{"text":"The need to sustain public confidence in the banking sector."}]},{"text":[{"text":"Survival problems of troubled banks."}]},{"text":[{"text":"A probable \"shake-out\" ahead from increased competition."}]}]}]},{"text":[{"text":"2 major financial statements:","bold":true},{"text":" the "},{"text":"balance sheet","bold":true},{"text":" and the "},{"text":"income statement","bold":true},{"text":". Others: source and application of funds, notes to the accounts, five-year financial summary, statement of value added."}]},{"text":[{"text":"Balance sheet rule:","bold":true},{"text":" group assets and liabilities by "},{"text":"nature","bold":true},{"text":" and list them in "},{"text":"order of liquidity and maturity","bold":true},{"text":", starting with "},{"text":"cash","bold":true},{"text":". It shows the sources of funds and how much has gone into loans, securities and other uses "},{"text":"at one date","bold":true},{"text":"."}]},{"text":[{"text":"Income statement:","bold":true},{"text":" the cost of acquiring deposits and other funds (interest to depositors, staff, overheads, taxes) against revenue (interest on loans and advances, leases, fees), ending with "},{"text":"net earnings","bold":true},{"text":", part reinvested and part paid as dividends."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Foreign exchange rate determination, staff matters, branch hours and fixing savings rates were "},{"text":"not","bold":true},{"text":" SAS 10 areas."}]},{"text":[{"text":"SAS 10 is now history: Nigerian banks have reported under "},{"text":"IFRS","bold":true},{"text":" since 2012, where the balance sheet is called the "},{"text":"statement of financial position","bold":true},{"text":". The ordering and the items you learn here still describe a bank's position."}]},{"text":[{"text":"Bank versus trading company:","bold":true},{"text":" a trading company's balance sheet is mainly stock and fixed assets funded largely by owners' capital. A bank's is "},{"text":"mainly financial assets","bold":true},{"text":" (cash, bills, loans) "},{"text":"funded largely by deposits","bold":true},{"text":", with fixed assets a "},{"text":"small share","bold":true},{"text":"."}]},{"text":[{"text":"Off-balance-sheet (contingent) items:","bold":true},{"text":" guarantees (e.g. a performance guarantee for a contractor building a road for a state government), acceptances and letters of credit are "},{"text":"not","bold":true},{"text":" assets or liabilities until the customer defaults. They are "},{"text":"disclosed in the notes to the accounts","bold":true},{"text":"."}]}]}]},{"number":"13.2","title":"The asset side of a bank's balance sheet","mustKnow":[{"type":"paragraph","text":[{"text":"Assets, in order of liquidity (most liquid first):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cash and short-term funds:","bold":true},{"text":" notes and coins in the strong rooms of all branches, regional offices and head office; the most liquid asset. The bank fixes its cash ratio and keeps vault cash to the barest minimum. "},{"text":"Short-term funds","bold":true},{"text":" = sums due from other banks in Nigeria or abroad, e.g. cheques on other banks credited to customers before clearing. Balances with the CBN and with other banks are also assets."}]},{"text":[{"text":"Short-term investment:$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 63, $study_guide$","bold":true},{"text":" "},{"text":"Treasury bills","bold":true},{"text":", maturity within "},{"text":"91 days","bold":true},{"text":" (the shortest tenor; Nigerian Treasury bills are also issued for 182 and 364 days). Held because they are "},{"text":"safe (less risky), highly liquid and can be rediscounted with the CBN before maturity","bold":true},{"text":"."}]},{"text":[{"text":"Long-term investment:","bold":true},{"text":" longer maturities but solid, e.g. "},{"text":"development stocks and bonds","bold":true},{"text":"."}]},{"text":[{"text":"Bills discounted:","bold":true},{"text":" FGN Treasury bills, special bills, trade bills, bankers' acceptances, commercial papers, less provision for discount."}]},{"text":[{"text":"Loans and advances:","bold":true},{"text":" the "},{"text":"risk assets","bold":true},{"text":"; credit facilities to customers. "},{"text":"About 70% or more of revenue","bold":true},{"text":" comes from them. Except term loans, all are technically "},{"text":"repayable on demand","bold":true},{"text":". They earn "},{"text":"more interest than government securities","bold":true},{"text":" because they are riskier, so banks take "},{"text":"security (collateral)","bold":true},{"text":"."}]},{"text":[{"text":"Other assets:","bold":true},{"text":" accrued interest, prepayments, "},{"text":"accrued interest receivable","bold":true},{"text":"."}]},{"text":[{"text":"Fixed assets:","bold":true},{"text":" land and buildings, machinery, vehicles, fixtures and fittings, computers and other equipment, shown at "},{"text":"cost less depreciation","bold":true},{"text":" (net value) to give a true and fair view."}]},{"text":[{"text":"Equipment on lease:","bold":true},{"text":" machinery, vehicles and other fixed assets leased out."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: "},{"text":"deposits are never an asset","bold":true},{"text":" of the bank. Treasury bills do "},{"text":"not","bold":true},{"text":" earn the highest rate and are "},{"text":"not","bold":true},{"text":" secured on land; they mature, so they give no permanent income."}]},{"text":[{"text":"Least liquid items sit at the bottom (fixed assets). Most liquid: cash and short-term funds."}]},{"text":[{"text":"Accrued interest "},{"text":"receivable","bold":true},{"text":" is an asset (money owed to the bank); accrued interest "},{"text":"payable","bold":true},{"text":" to depositors is a liability."}]}]}]},{"number":"13.3","title":"The liability and capital side; statutory reserve","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Deposits:","bold":true},{"text":" the "},{"text":"largest liability","bold":true},{"text":" of any deposit money bank. Depositors are "},{"text":"creditors","bold":true},{"text":" of the bank who can call for most of their money "},{"text":"on demand or at short notice","bold":true},{"text":". They include personal and business customers and other banks."}]},{"text":[{"text":"Other liabilities:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"amount due to subsidiary companies"}]},{"text":[{"text":"provision for taxation","bold":true}]},{"text":[{"text":"proposed dividends","bold":true},{"text":" to shareholders"}]},{"text":[{"text":"cash security for letters of credit"}]},{"text":[{"text":"cash security for collection"}]},{"text":[{"text":"remittance deposits"}]},{"text":[{"text":"interest reserves: interest on deposits accrued but not yet paid"}]},{"text":[{"text":"bank drafts and certified cheques","bold":true},{"text":" (issued, not yet paid)"}]}]}]},{"text":[{"text":"Capital:","bold":true},{"text":" owners' contribution. "},{"text":"Paid-up capital","bold":true},{"text":" = the amount actually injected by shareholders. "},{"text":"Authorised capital","bold":true},{"text":" = the "},{"text":"maximum","bold":true},{"text":" shareholders may inject."}]},{"text":[{"text":"Statutory reserves:","bold":true},{"text":" a reserve fund every bank must keep by law, built from "},{"text":"net profit after tax, before any dividend is declared","bold":true},{"text":"."}]},{"text":[{"text":"Capital reserves:","bold":true},{"text":" not mandatory but a prop for growth."}]},{"text":[{"text":"Retained profits (retained earnings):","bold":true},{"text":" "},{"text":"undivided profits","bold":true},{"text":" left in the business "},{"text":"after dividends and all other appropriations","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Statutory reserve transfer (BOFIA 2020, section 15; formerly BOFIA 1991, section 16):","bold":true}]},{"type":"table","header":[[{"text":"Reserve fund compared with paid-up share capital"}],[{"text":"Minimum transfer"}]],"rows":[[[{"text":"Less than paid-up capital"}],[{"text":"30% of net profit after tax"}]],[[{"text":"Equal to or more than paid-up capital"}],[{"text":"15% of net profit after tax"}]]]},{"type":"paragraph","text":[{"text":"No transfer is made until all identifiable and accumulated losses have been made good."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer balances:","bold":true},{"text":" Mr Eze's ₦2,000,000 credit balance is a "},{"text":"liability","bold":true},{"text":" (the bank owes him). Mrs Musa's ₦500,000 overdraft is an "},{"text":"asset","bold":true},{"text":" (she owes the bank). Loans, advances and overdrafts are always assets."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" a bank earns net profit after tax of ₦10bn."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reserve fund below paid-up capital: 30% × ₦10bn = "},{"text":"₦3bn","bold":true},{"text":" to transfer."}]},{"text":[{"text":"Reserve fund already equal to or above paid-up capital: 15% × ₦10bn = "},{"text":"₦1.5bn","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Watch the word "},{"text":"nominal","bold":true},{"text":": in this course it is used for the amount already invested by ow$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 64, $study_guide$ners, though in company law nominal capital usually means authorised capital."}]},{"text":[{"text":"Not","bold":true},{"text":" liabilities: loans and advances, Treasury bills, bills discounted, accrued interest receivable."}]}]}]},{"number":"13.4","title":"Sources and uses of a bank's funds","mustKnow":[{"type":"paragraph","text":[{"text":"Deposit funds (4 types):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Current account:","bold":true},{"text":" "},{"text":"non-interest-bearing demand deposits","bold":true},{"text":", withdrawn at any time by cheque without notice, as long as the balance covers it."}]},{"text":[{"text":"Savings account:","bold":true},{"text":" the "},{"text":"lowest interest rate","bold":true},{"text":" offered; a "},{"text":"minimal amount","bold":true},{"text":" opens it."}]},{"text":[{"text":"Time or fixed deposit:","bold":true},{"text":" a "},{"text":"fixed maturity (term)","bold":true},{"text":" and a "},{"text":"stipulated interest rate","bold":true},{"text":"."}]},{"text":[{"text":"Short-term investors:","bold":true},{"text":" investors seeking money market yields."}]}]},{"type":"paragraph","text":[{"text":"Non-deposit funds:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment income:","bold":true},{"text":" from investments in other banks, government securities, subsidiaries, real estate."}]},{"text":[{"text":"Rental income:","bold":true},{"text":" from bank property let to others."}]},{"text":[{"text":"Borrowing:","bold":true},{"text":" "},{"text":"overnight call deposit","bold":true},{"text":" (arranged in minutes but at a "},{"text":"very high interest rate","bold":true},{"text":"), "},{"text":"interbank borrowing","bold":true},{"text":", "},{"text":"long-term debenture","bold":true},{"text":"."}]},{"text":[{"text":"Owners' capital:","bold":true},{"text":" founders' contribution or shares sold in the capital market."}]},{"text":[{"text":"Retained earnings:","bold":true},{"text":" accumulated net income left after dividends."}]},{"text":[{"text":"Interest income:","bold":true},{"text":" interest and fees on loans (the bulk of revenue), interest on placements and securities."}]},{"text":[{"text":"Fees earned:","bold":true},{"text":" trust services, issuing houses work, account maintenance, bank drafts, "},{"text":"letters of credit","bold":true},{"text":", cheque books, excess clearing charges."}]},{"text":[{"text":"Sale of assets:","bold":true},{"text":" real estate, a subsidiary, collateral property. "},{"text":"Extraordinary income","bold":true},{"text":" because it is "},{"text":"usually non-recurring","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Uses of funds:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Repayment of deposits on demand (current, savings, time)."}]},{"text":[{"text":"Payment of interest to depositors."}]},{"text":[{"text":"Salaries and wages."}]},{"text":[{"text":"Loan repayment (principal and interest to other banks or debenture holders)."}]},{"text":[{"text":"Investment in government securities and other approved investments."}]},{"text":[{"text":"Reserves required by regulators."}]},{"text":[{"text":"Fees and capital budget: new branches and information technology."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" fees earned from letters of credit are a "},{"text":"source","bold":true},{"text":", not a use."}]},{"text":[{"text":"Mrs Adeyemi's ₦5,000,000 for 180 days at 12% a year with an early-withdrawal penalty is a "},{"text":"fixed (time) deposit","bold":true},{"text":"."}]},{"text":[{"text":"Capital history:","bold":true},{"text":" under the 2010 licensing regime a bank needed paid-up capital of ₦10bn (regional), ₦15bn (merchant), ₦25bn (national) or ₦50bn (international). The "},{"text":"2024 recapitalisation","bold":true},{"text":" (deadline "},{"text":"31 March 2026","bold":true},{"text":") raised this to "},{"text":"₦500bn","bold":true},{"text":" (international commercial), "},{"text":"₦200bn","bold":true},{"text":" (national), "},{"text":"₦50bn","bold":true},{"text":" (regional and merchant), "},{"text":"₦20bn","bold":true},{"text":" and "},{"text":"₦10bn","bold":true},{"text":" (national and regional non-interest)."}]}]}]},{"number":"13.5","title":"Reading a bank's balance sheet: ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Liquidity ratio = Liquid assets ÷ Total deposit liabilities × 100"}]},{"text":[{"text":"Required liquid assets = Minimum liquidity ratio × Deposits; Shortfall = Required − Held"}]},{"text":[{"text":"Required cash reserve = Cash reserve ratio × Eligible deposits"}]},{"text":[{"text":"Excess reserve = Reserves actually held − Required reserve"}]},{"text":[{"text":"Loan-to-deposit ratio = Loans and advances ÷ Total deposits × 100; Maximum loans = Limit × Deposits"}]}]},{"type":"paragraph","text":[{"text":"Liquid assets here: cash, balances with the CBN, Treasury bills (and net interbank placements). "},{"text":"Never","bold":true},{"text":" loans or fixed assets. Current CBN position: liquidity ratio "},{"text":"30%","bold":true},{"text":"; cash reserve ratio "},{"text":"45%","bold":true},{"text":" for deposit money banks. Exam questions usually state an assumed figure: use the one given."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Surulere Bank: cash ₦6bn, CBN balances ₦15bn, Treasury bills ₦24bn, loans and advances ₦110bn, fixed assets ₦12bn; deposits ₦150bn."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Liquidity ratio:","bold":true},{"text":" liquid assets = 6 + 15 + 24 = ₦45bn. Ratio = 45 ÷ 150 × 100 = "},{"text":"30%","bold":true},{"text":". (Loans and fixed assets are left out.)"}]},{"text":[{"text":"Loan-to-deposit ratio:","bold":true},{"text":" 110 ÷ 150 × 100 = "},{"text":"73.33%","bold":true},{"text":" (2 d.p.)."}]},{"text":[{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 65, $study_guide$t":"Maximum loans","bold":true},{"text":" under a 65% internal limit: 0.65 × ₦150bn = "},{"text":"₦97.5bn","bold":true},{"text":"."}]},{"text":[{"text":"Shortfall:","bold":true},{"text":" minimum 30%, liquid assets held ₦40bn. Required = 0.30 × ₦150bn = ₦45bn. Shortfall = 45 − 40 = "},{"text":"₦5bn","bold":true},{"text":"."}]},{"text":[{"text":"Cash reserve and excess:","bold":true},{"text":" assume CRR 20% on ₦150bn: required = 0.20 × 150 = ₦30bn. If the bank holds ₦33bn with the CBN, excess reserve = 33 − 30 = "},{"text":"₦3bn","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Traps: liquidity ratio divides by "},{"text":"deposits","bold":true},{"text":", not total assets; excess reserve is held minus required, not the required amount itself."}]}]},{"number":"13.6","title":"Interpreting a customer's accounts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Purpose:","bold":true},{"text":" the banker analyses the customer's balance sheet and profit and loss account (usually for three years) to judge whether the business "},{"text":"can repay the advance and interest from its operations and assets","bold":true},{"text":", not to audit, set prices or compute tax."}]}]},{"type":"table","header":[[{"text":"Question"}],[{"text":"Ratios"}]],"rows":[[[{"text":"Can it meet short-term debts? (liquidity)"}],[{"text":"Current ratio, quick ratio, working capital"}]],[[{"text":"How much is borrowed? (gearing, solvency)"}],[{"text":"Gearing, debt-to-equity, interest cover"}]],[[{"text":"Is it profitable?"}],[{"text":"Net profit margin, ROCE"}]],[[{"text":"How efficiently does it use assets? (activity)"}],[{"text":"Stock days, stock turnover, debtor days"}]]]},{"type":"paragraph","text":[{"text":"Formulas:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Current ratio = Current assets ÷ Current liabilities"}]},{"text":[{"text":"Quick (acid-test) ratio = (Current assets − Stock) ÷ Current liabilities"}]},{"text":[{"text":"Working capital = Current assets − Current liabilities"}]},{"text":[{"text":"Gearing = Long-term debt ÷ (Long-term debt + Shareholders' funds) × 100"}]},{"text":[{"text":"Debt-to-equity = Long-term debt ÷ Shareholders' equity"}]},{"text":[{"text":"Interest cover = Profit before interest and tax ÷ Interest (times)"}]},{"text":[{"text":"Net profit margin = Net profit ÷ Sales × 100"}]},{"text":[{"text":"ROCE = Profit before interest and tax ÷ Capital employed × 100; Capital employed = Shareholders' funds + Long-term loans"}]},{"text":[{"text":"Stock days = Stock ÷ Cost of sales × 365"}]},{"text":[{"text":"Stock turnover = Cost of sales ÷ Average stock (times)"}]},{"text":[{"text":"Debtor collection period = Trade debtors ÷ Credit sales × 365"}]},{"text":[{"text":"Shareholders' funds = Share capital + Reserves (including retained profits)"}]}]},{"type":"paragraph","text":[{"text":"Key ideas:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Stock","bold":true},{"text":" is left out of the quick ratio because it is the "},{"text":"least liquid","bold":true},{"text":" current asset and may not turn into cash quickly at book value."}]},{"text":[{"text":"High gearing","bold":true},{"text":" = heavy reliance on borrowed funds relative to owners' funds: more risk to a new lender."}]},{"text":[{"text":"Break-up (forced-sale) basis:","bold":true},{"text":" a prudent banker values assets at what they would fetch if the business failed, not on a going-concern basis."}]},{"text":[{"text":"Tangible net worth","bold":true},{"text":" = Shareholders' funds − Intangibles; "},{"text":"goodwill is deducted","bold":true},{"text":" because it has little or no value if the business is wound up."}]},{"text":[{"text":"Window dressing:","bold":true},{"text":" arranging transactions just before the balance sheet date so the accounts look stronger than normal."}]},{"text":[{"text":"Overtrading:","bold":true},{"text":" sales growing faster than the working capital to support them: working capital falls, creditors and overdraft rise sharply, current ratio falls below 1."}]},{"text":[{"text":"Limitations of the balance sheet:","bold":true},{"text":" historical (possibly out-of-date) figures; position at "},{"text":"one date only","bold":true},{"text":"; open to window dressing. (Listing assets and liabilities is its purpose, not a limitation.)"}]},{"text":[{"text":"Cash flow forecast:","bold":true},{"text":" loans are repaid out of "},{"text":"cash","bold":true},{"text":"; a profitable business can still fail if it runs out of cash."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Ikeja Traders Ltd: stock ₦3,000,000, debtors ₦2,000,000, cash ₦1,000,000; trade creditors ₦2,500,000, overdraft ₦1,500,000; long-term loan ₦8,000,000; share capital ₦10,000,000, retained profits ₦6,000,000, goodwill ₦1,000,000; sales (all on credit) ₦36,500,000, cost of sales ₦21,900,000, net profit ₦2,920,000; profit before interest and tax ₦4,800,000, interest ₦800,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Current assets = 3,000,000 + 2,000,000 + 1,000,000 = ₦6,000,000. Current liabilities = 2,500,000 + 1,500,000 = ₦4,000,000 (the overdraft is a current liability)."}]},{"text":[{"text":"Current ratio","bold":true},{"text":" = 6,000,000 ÷ 4,000,000 = "},{"text":"1.5 : 1","bold":true},{"text":"."}]},{"text":[{"text":"Quick ratio","bold":true},{"text":" = (6,000,000 − 3,000,000) ÷ 4,000,000 = "},{"text":"0.75 : 1","bold":true},{"text":"."}]},{"text":[{"text":"Working capital","bold":true},{"text":" = 6,000,000 − 4,000,000 = "},{"text":"₦2,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Shareholders' funds = 10,000,000 + 6,000,000 = ₦16,000,000. "},{"text":"Gearing","bold":true},{"text":" = 8,000,000 ÷ (8,000,000 + 16,000,000) × 100 = "},{"text":"33.3%","bold":true},{"text":" (1 d.p.). "},{"text":"Debt-to-equity","bold":true},{"text":" = 8,000,000 ÷ 16,000,000 = "},{"text":"0.5 : 1","bold":true},{"text":".$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 66, $study_guide$"}]},{"text":[{"text":"Interest cover","bold":true},{"text":" = 4,800,000 ÷ 800,000 = "},{"text":"6 times","bold":true},{"text":". If you are given profit "},{"text":"before tax","bold":true},{"text":" after interest (say ₦4,000,000), add the interest back first: 4,000,000 + 800,000 = 4,800,000, then divide."}]},{"text":[{"text":"Net profit margin","bold":true},{"text":" = 2,920,000 ÷ 36,500,000 × 100 = "},{"text":"8%","bold":true},{"text":". If given gross profit and expenses (sales ₦50m, gross profit ₦15m, expenses ₦11m): net profit = 15 − 11 = ₦4m; margin = 4 ÷ 50 × 100 = "},{"text":"8%","bold":true},{"text":"."}]},{"text":[{"text":"ROCE","bold":true},{"text":" = 4,800,000 ÷ (16,000,000 + 8,000,000) × 100 = "},{"text":"20%","bold":true},{"text":"."}]},{"text":[{"text":"Stock days","bold":true},{"text":" = 3,000,000 ÷ 21,900,000 × 365 = "},{"text":"50 days","bold":true},{"text":". "},{"text":"Stock turnover","bold":true},{"text":" = 21,900,000 ÷ 3,000,000 = "},{"text":"7.3 times","bold":true},{"text":"."}]},{"text":[{"text":"Debtor days","bold":true},{"text":" = 2,000,000 ÷ 36,500,000 × 365 = "},{"text":"20 days","bold":true},{"text":"."}]},{"text":[{"text":"Tangible net worth","bold":true},{"text":" = 16,000,000 − 1,000,000 = "},{"text":"₦15,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Working backwards:","bold":true},{"text":" current ratio 1.5 : 1 with current liabilities ₦4,000,000 gives current assets = 1.5 × 4,000,000 = ₦6,000,000, so working capital = ₦2,000,000."}]}]},{"type":"paragraph","text":[{"text":"Reading the signs:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Current ratio 2.4 : 1 but quick ratio 0.4 : 1: most current assets are "},{"text":"tied up in stock","bold":true},{"text":"."}]},{"text":[{"text":"Debtor days rising from 35 to 80 with sales unchanged: "},{"text":"credit control is weakening","bold":true},{"text":", some debts may go bad, cash is squeezed."}]},{"text":[{"text":"Bisi Trading borrows ₦10m from a director on 30 December to clear its overdraft and redraws the overdraft on 3 January to repay him: "},{"text":"window dressing","bold":true},{"text":"."}]},{"text":[{"text":"Sales double, working capital falls, creditors and overdraft jump, current ratio below 1: "},{"text":"overtrading","bold":true},{"text":"."}]},{"text":[{"text":"Traps: use "},{"text":"cost of sales","bold":true},{"text":" (not sales) for stock days and stock turnover; use "},{"text":"credit sales","bold":true},{"text":" for debtor days; gearing divides by debt "},{"text":"plus","bold":true},{"text":" equity, debt-to-equity by equity alone."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SAS 10 covered income recognition, loss recognition and balance sheet classification; reasons include overstated profits and inconsistent policies. Banks now use IFRS."}]},{"text":[{"text":"Bank assets run in order of liquidity: cash and short-term funds, Treasury bills, long-term investments, bills discounted, loans and advances, other assets, fixed assets, equipment on lease."}]},{"text":[{"text":"Loans and advances are the risk assets earning about 70% or more of revenue; Treasury bills are safe, liquid and rediscountable."}]},{"text":[{"text":"Deposits are the largest liability; overdrafts and loans are assets; guarantees are off-balance-sheet."}]},{"text":[{"text":"Statutory reserve (BOFIA 2020): 30% of net profit after tax if the reserve is below paid-up capital, 15% if equal or above, before any dividend."}]},{"text":[{"text":"Deposit funds: current, savings, fixed, short-term investors. Non-deposit: investment and rental income, borrowing, capital, retained earnings, interest, fees, sale of assets (extraordinary)."}]},{"text":[{"text":"Liquidity ratio = liquid assets ÷ deposits; excess reserve = held − required; LDR = loans ÷ deposits."}]},{"text":[{"text":"Customer analysis: current, quick, working capital, gearing, interest cover, margin, ROCE, stock and debtor days."}]},{"text":[{"text":"Prudent bankers value on a break-up basis, deduct goodwill, watch for window dressing and overtrading, and check cash flow."}]}]}],"theory":{"itemId":"f637abb5-ecf7-5f70-8423-69c4aab9d5c0","question":[{"type":"paragraph","text":[{"text":"Oshodi Ventures Ltd asks for an overdraft. Current assets ₦9,000,000 (including stock ₦4,000,000); current liabilities ₦6,000,000; long-term loan ₦5,000,000; shareholders' funds ₦15,000,000; profit before interest and tax ₦3,000,000; loan interest ₦500,000. Compute the current ratio, quick ratio, working capital, gearing and interest cover, and comment."}]}]},"practice":[{"topic":"Balance Sheet Structure and Interpreting Customers' Accounts","named":false}]}},{"kind":"note","itemId":"1b7ae81f-9a5d-5cef-9085-5e49ce5db46c","sourceKey":"guide-topic:14","position":14,"payload":{"title":"Liability and Asset Portfolio Management 'Problem' of Banks","body":"The three goals (liquidity, profitability, solvency) and why they conflict; reasons for liquidity and for profitability; priorities in allocating funds; the four liquidity theories; asset, liability and asset-liability management and ALCO; liquidity ratio, cash reserve ratio, excess reserves and loans-to-deposits computations; maturity mismatch and gap analysis; capital adequacy, the Basel accords and CAMEL.","noteType":"guide_topic","number":14,"mustKnow":[{"text":"The three goals (liquidity, profitability, solvency) and why they conflict; reasons for liquidity and for profitability; priorities in allocating funds; the four liquidity theories; asset, liability and asset-liability management and ALCO; liquidity ratio, cash reserve ratio, excess reserves and loans-to-deposits computations; maturity mismatch and gap analysis; capital adequacy, the Basel accords and CAMEL."}],"lessons":[{"number":"14.1","title":"The three goals and the 'problem'","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 major goals of a deposit money bank (DMB):","bold":true},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 67, $study_guide$:" "},{"text":"liquidity, profitability and solvency","bold":true},{"text":" (not longevity or endurability)."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" the conversion of current assets into cash within a short period of time without appreciable loss of value. In banking: the ability of a bank to meet its customers' demands for cash and its other obligations as they fall due (to pay depositors on demand)."}]},{"text":[{"text":"Profitability:","bold":true},{"text":" earning a reasonable margin of income (interest on loans and investments) over costs (interest on deposits and other expenses)."}]},{"text":[{"text":"Solvency:","bold":true},{"text":" the ability to meet all obligations in the long run, with assets exceeding liabilities. To be solvent a bank must be both liquid and profitable."}]},{"text":[{"text":"The 'problem':","bold":true},{"text":" balancing the competing goals of liquidity, profitability and solvency. Loans earn interest but tie up cash; idle cash keeps the bank liquid but earns no income. "},{"text":"The more liquid a bank is, the less profitable it tends to be.","bold":true}]},{"text":[{"text":"Cash","bold":true},{"text":" (notes and coins) is the "},{"text":"most liquid asset","bold":true},{"text":" but earns "},{"text":"no income","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 reasons a bank keeps adequate liquidity:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To meet the cash demands (withdrawals) of customers; current account holders need give no notice."}]},{"text":[{"text":"To maintain the unshaken confidence of the public."}]},{"text":[{"text":"To meet the statutory liquidity requirements of the CBN (liquidity ratio, cash ratio)."}]},{"text":[{"text":"To meet cash expenses, such as petty cash expenses."}]}]},{"type":"paragraph","text":[{"text":"6 reasons a bank pursues profitability:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To satisfy the interest of shareholders (dividends)."}]},{"text":[{"text":"Evidence of strength and progress (radiates public confidence)."}]},{"text":[{"text":"To meet the obligations of lenders and creditors."}]},{"text":[{"text":"Index of performance and stability."}]},{"text":[{"text":"Source of capital: retained (ploughed-back) profit strengthens the bank."}]},{"text":[{"text":"Buffer for unexpected losses."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paying dividends is a reason for "},{"text":"profitability","bold":true},{"text":", not liquidity; maximising interest by lending out as much as possible is the opposite of a liquidity reason. Exams swap these."}]},{"text":[{"text":"The main cost of holding more cash than needed is the "},{"text":"opportunity cost","bold":true},{"text":": the interest or investment income the bank could have earned (from other banks or government securities). There is no CBN penalty for excess cash."}]},{"text":[{"text":"Solvent but illiquid:","bold":true},{"text":" assets comfortably exceed liabilities, but they are mostly long-term loans, so the bank cannot pay all the depositors who come today. Illiquidity can trigger a run that grounds even a solvent bank. "},{"text":"Insolvent:","bold":true},{"text":" liabilities exceed assets."}]},{"text":[{"text":"Nigerians have a high propensity to hold cash, so a Nigerian bank cannot neglect liquidity whatever the cost."}]}]}]},{"number":"14.2","title":"The balance sheet and the priorities for funds","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Assets","bold":true},{"text":" (from most to least liquid): cash; balances with the CBN and other banks; money at call and short notice; Treasury bills and other government securities; loans and advances; long-term investments; premises and equipment."}]},{"text":[{"text":"Liabilities:","bold":true},{"text":" capital (shareholders' funds: share capital and reserves); deposits (current, savings, fixed); borrowings from the CBN and other banks; balances held for other banks."}]},{"text":[{"text":"Loans and advances:","bold":true},{"text":" the bank's "},{"text":"risk assets","bold":true},{"text":"; they generate most of its revenue and earn more than government securities."}]}]},{"type":"paragraph","text":[{"text":"Traditional priorities in allocating a commercial bank's funds","bold":true},{"text":" (in order):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Primary reserves","bold":true},{"text":" (first claim): cash in vault, balances with the CBN (including the cash reserve requirement), balances with other banks, cheques in course of collection. For liquidity, not income."}]},{"text":[{"text":"Secondary reserves:","bold":true},{"text":" short-term, marketable, interest-earning assets, mainly "},{"text":"Treasury bills","bold":true},{"text":", Treasury certificates and call money. Some income, quickly turned into cash."}]},{"text":[{"text":"Loans and advances","bold":true},{"text":" to customers: the main source of profit."}]},{"text":[{"text":"Investments for income:","bold":true},{"text":" longer-term securities bought with what is left."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moving ₦20 billion from Treasury bills into three-year corporate loans makes a bank "},{"text":"more profitable but less liquid and more exposed to credit risk","bold":true},{"text":". Moving the other way makes it more liquid and less profitable. The rule: higher return comes with lower liquidity and higher risk."}]},{"text":[{"text":"Land and buildings and long-term mortgages are "},{"text":"not","bold":true},{"text":" secondary reserves; vault cash is a "},{"text":"primary","bold":true},{"text":" reserve."}]}]}]},{"number":"14.3","title":"Liquidity theories and management approaches","mustKnow":[{"type":"table","header":[[{"text":"Theory"}],[{"text":"Key idea"}],[{"text":"Weakness"}]],"rows":[[[{"text":"Commer$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 68, $study_guide$cial loan (real bills) theory","bold":true}],[{"text":"Grant only short-term, self-liquidating loans that finance goods in production or trade and are repaid when the goods are sold. Linked to Adam Smith (1776)."}],[{"text":"Ignores that a stable core of deposits can safely support some longer-term lending; goods may not sell in a slump."}]],[[{"text":"Shiftability theory","bold":true},{"text":" (H. G. Moulton, 1918)"}],[{"text":"Stay liquid by holding assets that can be sold or shifted to other investors or to the central bank before maturity without significant loss (e.g. Treasury bills)."}],[{"text":"In a general crisis all banks sell at once, so assets may not be shiftable without heavy loss."}]],[[{"text":"Anticipated income theory","bold":true},{"text":" (H. V. Prochnow)"}],[{"text":"A loan is liquid if it is repaid from the borrower's expected future income, usually in regular instalments."}],[{"text":"Depends on the borrower's income actually arriving."}]],[[{"text":"Liability management theory","bold":true},{"text":" (1960s)"}],[{"text":"Liquidity comes from the "},{"text":"liability side","bold":true},{"text":": borrow (interbank, certificates of deposit, central bank) when cash is needed."}],[{"text":"Borrowing costs rise and funds may dry up in a crisis."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Asset management:","bold":true},{"text":" treats deposits and other liabilities as largely given and concentrates on choosing the mix of cash, securities and loans to meet liquidity and profit goals."}]},{"text":[{"text":"Liability management:","bold":true},{"text":" actively raising funds (interbank borrowing, certificates of deposit) to meet loan demand or withdrawals instead of selling assets."}]},{"text":[{"text":"Asset-liability management (ALM):","bold":true},{"text":" coordinated management of both sides of the balance sheet so that the mix, maturity and pricing of assets and liabilities together achieve liquidity, profitability and risk targets."}]},{"text":[{"text":"ALCO (Asset and Liability Committee):","bold":true},{"text":" a committee of senior management (executive directors) that sets and monitors balance sheet strategy: liquidity, maturity profile, interest rate gaps and the pricing of loans and deposits. Not a CBN or NDIC body, not a shareholders' committee."}]}]},{"type":"paragraph","text":[{"text":"Sources of liquidity at short notice:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Asset side:","bold":true},{"text":" sell or rediscount Treasury bills; let maturing Treasury bills run off; collect maturing loans."}]},{"text":[{"text":"Liability side:","bold":true},{"text":" borrow in the interbank market; issue certificates of deposit; borrow from the CBN through its Standing Lending Facility; attract new deposits."}]},{"text":[{"text":"Granting a new five-year loan "},{"text":"uses","bold":true},{"text":" liquidity; it is never a source."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Balogun Market textile trader borrowing ₦3 million for 90 days to buy stock, repaid when the fabric is sold, is the classic "},{"text":"commercial loan","bold":true},{"text":" case."}]},{"text":[{"text":"A civil servant's three-year car loan repaid by monthly salary deductions is the "},{"text":"anticipated income","bold":true},{"text":" case."}]},{"text":[{"text":"A bank that borrows ₦15 billion overnight in the interbank market and issues certificates of deposit, instead of selling its investments, is practising "},{"text":"liability management","bold":true},{"text":"."}]},{"text":[{"text":"A monthly meeting of executive directors that reviews the deposit maturity profile, sets fixed deposit rates and decides to cut the negative gap is the "},{"text":"ALCO","bold":true},{"text":", not the audit, credit or remuneration committee."}]}]}]},{"number":"14.4","title":"Regulatory liquidity ratios and computations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Liquidity ratio:","bold":true},{"text":" the minimum percentage of deposit liabilities a DMB must hold in specified liquid assets (cash, balances with the CBN, Treasury bills, net interbank placements). Current minimum for DMBs: "},{"text":"30%","bold":true},{"text":"."}]},{"text":[{"text":"Cash reserve ratio (CRR):","bold":true},{"text":" the percentage of deposits a bank is legally required to keep as cash reserves with the CBN. Since September 2025 (retained at the September 2026 MPC): "},{"text":"45%","bold":true},{"text":" for DMBs, 16% for merchant banks, 75% on non-TSA public sector deposits."}]},{"text":[{"text":"Loans-to-deposits ratio (LDR):","bold":true},{"text":" CBN minimum "},{"text":"50%","bold":true},{"text":" since April 2024 (was 65%)."}]},{"text":[{"text":"Formulas:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Liquidity ratio = Liquid assets ÷ Deposit liabilities × 100"}]},{"text":[{"text":"Required liquid assets = Required ratio × Deposits; shortfall = Required − Actual"}]},{"text":[{"text":"Liquid assets switchable to loans = Actual liquid assets − Required liquid assets"}]},{"text":[{"text":"Required reserves = Reserve ratio × Deposits"}]},{"text":[{"text":"Excess reserves = Total reserves − Required reserves"}]},{"text":[{"text":"New loans one bank can safely grant from a fresh deposit = Deposit × (1 − Reserve ratio)"}]},{"text":[{"text":"LDR = Loans and advances ÷ Total deposits × 100"}]}]}]}]}],"explainMore":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Liquidity ratio.","bold":true},{"text":" Deposits ₦120bn; cash ₦8bn, Treasury bills ₦25bn, net interbank placements ₦5bn. Liquid assets = 8 + 25 + 5 = ₦38bn. Ratio = 38 ÷ 120 × 100 = 31.67% (2 d.p.)."}]},{"text":[{"text":"Switchable surplus.","bold":true},{"text":" Required = 30% × 120 = ₦36bn. Surplus = 38 − 36 = ₦2bn can go into new loans."}]},{"text":[{"text":"Shortfall.","bold":true},{"text":" S$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 69, $study_guide$ame bank with liquid assets of only ₦30bn: shortfall = 36 − 30 = ₦6bn."}]},{"text":[{"text":"CRR.","bold":true},{"text":" Assume a 45% CRR on eligible deposits of ₦60bn: reserves = 0.45 × 60 = ₦27bn."}]},{"text":[{"text":"Excess reserves.","bold":true},{"text":" Deposits ₦800m, reserves ₦200m, ratio 20%. Required = 0.20 × 800 = ₦160m. Excess = 200 − 160 = ₦40m."}]},{"text":[{"text":"Single-bank lending.","bold":true},{"text":" Fresh deposit ₦20m, ratio 20%, no prior excess: keep 0.20 × 20 = ₦4m; lend 20 − 4 = ₦16m. Do not multiply by 1 ÷ 0.20; that is the whole system's money multiplier, not one bank."}]},{"text":[{"text":"Reserve deficiency after a withdrawal.","bold":true},{"text":" Deposits ₦500m, reserves exactly ₦50m (10%). A ₦30m cash withdrawal cuts both: deposits = ₦470m, reserves = ₦20m. Required = 0.10 × 470 = ₦47m. Deficiency = 47 − 20 = ₦27m. Required reserves fall only by 10% of the withdrawal, so a deficiency appears."}]},{"text":[{"text":"LDR.","bold":true},{"text":" Loans ₦330bn, deposits ₦500bn: 330 ÷ 500 × 100 = 66%. Do not divide deposits by loans."}]}]}]},{"number":"14.5","title":"Maturity mismatch and gap analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maturity mismatch:","bold":true},{"text":" financing long-term loans with deposits that can be withdrawn on demand or at short notice. Creates liquidity risk and interest rate risk."}]},{"text":[{"text":"Rate-sensitive assets (RSA) and liabilities (RSL):","bold":true},{"text":" those that reprice within a given period (e.g. 12 months)."}]},{"text":[{"text":"Repricing (funding) gap","bold":true},{"text":" = RSA − RSL."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positive gap","bold":true},{"text":" (RSA > RSL): "},{"text":"asset-sensitive","bold":true},{"text":"; net interest income (NII) "},{"text":"rises when rates rise","bold":true},{"text":", falls when rates fall."}]},{"text":[{"text":"Negative gap","bold":true},{"text":" (RSL > RSA): "},{"text":"liability-sensitive","bold":true},{"text":"; NII falls when rates rise, rises when rates fall."}]}]}]},{"text":[{"text":"Change in NII = Gap × Change in interest rate.","bold":true}]},{"text":[{"text":"Expect rates to fall: a "},{"text":"negative","bold":true},{"text":" gap benefits most. Expect rates to rise: a "},{"text":"positive","bold":true},{"text":" gap."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positive gap.","bold":true},{"text":" RSA ₦450bn, RSL ₦400bn: gap = 450 − 400 = +₦50bn (asset-sensitive). Rates fall 3 percentage points: ΔNII = 50bn × (−0.03) = −₦1.5bn."}]},{"text":[{"text":"Negative gap.","bold":true},{"text":" RSA ₦200bn, RSL ₦260bn: gap = 200 − 260 = −₦60bn (liability-sensitive). Rates rise 2 points: ΔNII = −60bn × 0.02 = −₦1.2bn."}]},{"text":[{"text":"Convert percentage points to decimals (2 points = 0.02). ₦50bn × 0.02 = ₦1bn, not ₦100m or ₦10bn."}]},{"text":[{"text":"Mismatch trap:","bold":true},{"text":" 10-year fixed-rate mortgages funded by 90-day fixed deposits. When rates rise sharply, deposit costs reprice upward quickly while mortgage income stays fixed, so the bank suffers."}]}]}]},{"number":"14.6","title":"Capital adequacy, Basel and CAMEL","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital adequacy ratio (CAR)","bold":true},{"text":" = Capital ÷ Risk-weighted assets × 100. RWA = sum of (each asset × its risk weight)."}]},{"text":[{"text":"Basel Committee on Banking Supervision (BCBS):","bold":true},{"text":" set up by the G10 central banks in Basel, Switzerland, after banking crises of the 1970s; works under the "},{"text":"Bank for International Settlements (BIS)","bold":true},{"text":"."}]},{"text":[{"text":"Basel I (July 1988):","bold":true},{"text":" capital of at least "},{"text":"8% of risk-weighted assets","bold":true},{"text":"; credit risk only. Risk weights: "},{"text":"0%","bold":true},{"text":" claims on government; "},{"text":"20%","bold":true},{"text":" claims on banks; "},{"text":"50%","bold":true},{"text":" residential mortgages; "},{"text":"100%","bold":true},{"text":" corporate and consumer loans."}]},{"text":[{"text":"Basel II (2004)","bold":true},{"text":", 3 pillars:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Minimum capital requirements (credit, market and operational risk)."}]},{"text":[{"text":"Supervisory review process."}]},{"text":[{"text":"Market discipline through effective public disclosure."}]}]},{"type":"paragraph","text":[{"text":"Deposit insurance is "},{"text":"not","bold":true},{"text":" a pillar."}]}]},{"text":[{"text":"Basel III (December 2010, finalised 2017):","bold":true},{"text":" stronger common equity (4.5% of RWA), 2.5% capital conservation buffer, countercyclical buffer, leverage ratio, and two liquidity ratios: "},{"text":"Liquidity Coverage Ratio (LCR):","bold":true},{"text":" enough high-quality liquid assets to cover net cash outflows over a "},{"text":"30-day stress period","bold":true},{"text":"; "},{"text":"Net Stable Funding Ratio (NSFR):","bold":true},{"text":" stable long-term funding for the whole balance sheet."}]},{"text":[{"text":"CAMEL","bold":true},{"text":" (rating used by CBN and NDIC): "},{"text":"C","bold":true},{"text":"apital adequacy, "},{"text":"A","bold":true},{"text":"sset quality, "},{"text":"M","bold":true},{"text":"anagement, "},{"text":"E","bold":true},{"text":"arnings, "},{"text":"L","bold":true},{"text":"iquidity. (CAMELS adds "},{"text":"S","bold":true},{"text":"ensitivity to market risk.)"}]},{"text":[{"text":"Nigerian CAR minimums: "},{"text":"15%","bold":true},{"text":" for banks with international authorisation, "},{"text":"10%","bold":true},{"text":" for national and regional banks."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CAR worked.","bold":true},{"text":" Capital ₦18bn. Government securities ₦50bn (0%), interbank claims ₦30bn (20%), residential mortgages ₦40bn$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 70, $study_guide$ (50%), corporate loans ₦100bn (100%)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"RWA = 0 + (30 × 0.2) + (40 × 0.5) + (100 × 1) = 0 + 6 + 20 + 100 = ₦126bn."}]},{"text":[{"text":"CAR = 18 ÷ 126 × 100 = 14.29% (2 d.p.)."}]},{"text":[{"text":"Against 15%: required capital = 0.15 × 126 = ₦18.9bn; shortfall = ₦0.9bn."}]}]}]},{"text":[{"text":"A bank at exactly its minimum CAR that wants many more corporate loans must "},{"text":"raise more capital or retain more profit","bold":true},{"text":" first. More deposits do not help (they are not capital), and cutting zero-weight government securities does not reduce RWA."}]},{"text":[{"text":"Basel I's weakness: one measure (credit risk capital) using book values, ignoring operational risk; Basel II followed, then the 2007-2008 crisis led to Basel III."}]},{"text":[{"text":"Bank recapitalisation (₦500bn international, ₦200bn national, ₦50bn regional; deadline 31 March 2026) is about minimum capital, a separate rule from the CAR ratio."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Three goals: liquidity, profitability, solvency; balancing them is the portfolio 'problem'."}]},{"text":[{"text":"More liquid means less profitable; cash is the most liquid asset and earns nothing."}]},{"text":[{"text":"4 liquidity reasons (withdrawals, confidence, CBN rules, cash expenses); 6 profitability reasons (dividends, strength, creditors, performance, capital, buffer)."}]},{"text":[{"text":"Fund priorities: primary reserves, secondary reserves (Treasury bills), loans and advances, investments for income."}]},{"text":[{"text":"Theories: commercial loan (self-liquidating), shiftability (sell before maturity), anticipated income (instalments), liability management (borrow)."}]},{"text":[{"text":"ALCO sets balance sheet strategy; ALM manages both sides together."}]},{"text":[{"text":"Liquidity ratio 30%; CRR 45% for DMBs; LDR 50%; excess reserves = actual − required."}]},{"text":[{"text":"Gap = RSA − RSL; ΔNII = gap × Δrate; positive gap gains when rates rise."}]},{"text":[{"text":"CAR = capital ÷ RWA; Basel I 8% (1988); Basel II three pillars; Basel III LCR (30 days) and NSFR; under BIS."}]},{"text":[{"text":"CAMEL: capital, asset quality, management, earnings, liquidity."}]}]}],"theory":{"itemId":"f20cc198-5ebe-5c43-b2da-99b9171910d2","question":[{"type":"paragraph","text":[{"text":"Agege Bank has deposit liabilities of ₦300bn and qualifying liquid assets of ₦100bn. The minimum liquidity ratio is 30%. (a) What is its liquidity ratio? (b) What is the largest amount of liquid assets it can switch into loans and still comply? (c) What happens to its liquidity and profitability after the switch?"}]}]},"practice":[{"topic":"Liability and Asset Portfolio Management","named":false}]}},{"kind":"note","itemId":"2e9a2b1f-a7ee-595f-94d3-cb027a593b41","sourceKey":"guide-topic:15","position":15,"payload":{"title":"The Chartered Institute of Bankers of Nigeria (CIBN)","body":"What the CIBN is and how it grew from a 1963 local centre to a chartered body; the laws behind it (Decree No. 12 of 1990, now the CIBN Act, 2007); its objectives and functions, and what it does NOT do; its Governing Council, Registrar and disciplinary system; membership categories, grades and letters; the offence of practising without membership; its link with the Bankers' Committee.","noteType":"guide_topic","number":15,"mustKnow":[{"text":"What the CIBN is and how it grew from a 1963 local centre to a chartered body; the laws behind it (Decree No. 12 of 1990, now the CIBN Act, 2007); its objectives and functions, and what it does NOT do; its Governing Council, Registrar and disciplinary system; membership categories, grades and letters; the offence of practising without membership; its link with the Bankers' Committee."}],"lessons":[{"number":"15.1","title":"What the CIBN is and how it began","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CIBN:","bold":true},{"text":" the "},{"text":"professional body for banking practitioners","bold":true},{"text":" in Nigeria. It sets the standards of knowledge and skill for persons entering the banking profession, conducts professional banking examinations and promotes ethics among bankers. It is "},{"text":"not","bold":true},{"text":" a regulator, a deposit insurer or a bank."}]},{"text":[{"text":"It was "},{"text":"primarily established by its own members","bold":true},{"text":", then backed by law."}]}]},{"type":"paragraph","text":[{"text":"Path of development (learn the order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"1963:","bold":true},{"text":" bankers in Lagos set up a "},{"text":"local centre of the Institute of Bankers, London","bold":true},{"text":" (the Lagos Local Centre, resolved by 124 bankers on 28 November 1963)."}]},{"text":[{"text":"1973:","bold":true},{"text":" the "},{"text":"Nigerian Institute of Bankers","bold":true},{"text":" was established; on 15 December "},{"text":"1976","bold":true},{"text":" it was incorporated as a "},{"text":"company limited by guarantee","bold":true},{"text":"."}]},{"text":[{"text":"1990:","bold":true},{"text":" it obtained "},{"text":"chartered status","bold":true},{"text":" by "},{"text":"Act (Decree) No. 12 of 1990","bold":true},{"text":" and became the "},{"text":"Chartered Institute of Bankers of Nigeria","bold":true},{"text":"."}]},{"text":[{"text":"2007:","bold":true},{"text":" the 1990 law was "},{"text":"repealed and replaced","bold":true},{"text":" by the "},{"text":"Chartered Institute of Bankers of Nigeria Act, 2007","bold":true},{"text":" (signed 11 April 2007). This is the law that governs the CIBN today."}]}]},{"type":"paragraph","text":[{"text":"Short form: "},{"text":"Local centre of the Institute of Bankers, London -> Nigerian Institute of Bankers -> CIBN.","bold":true}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: chartered status did "},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 71, $study_guide$:"not","bold":true},{"text":" come from the CBN Act 1958, the Banking Ordinance 1952 or BOFIA 1991; it came from "},{"text":"Decree No. 12 of 1990","bold":true},{"text":". The current law is the "},{"text":"CIBN Act, 2007","bold":true},{"text":", not the NDIC Act 2023, CAMA 2020 or BOFIA 2020 (BOFIA 2020 governs the licensing and regulation of banks, which is the CBN's job)."}]},{"text":[{"text":"Before 1990 the body was the "},{"text":"Nigerian Institute of Bankers","bold":true},{"text":", not the \"Institute of Banking and Finance\", the \"Nigerian Bankers' Association\" or a \"Banking Council\". It was a "},{"text":"company limited by guarantee","bold":true},{"text":", not a public limited company, a cooperative or a CBN corporation."}]},{"text":[{"text":"The 1963 body was a "},{"text":"local centre of the London Institute","bold":true},{"text":", not a chapter of the American Bankers Association, a CBN branch or the clearing house."}]},{"text":[{"text":"The Institute's home is "},{"text":"Bankers House, Victoria Island, Lagos","bold":true},{"text":"."}]}]}]},{"number":"15.2","title":"Objectives, functions and what the CIBN does not do","mustKnow":[{"type":"paragraph","text":[{"text":"3 objectives","bold":true},{"text":" for which the CIBN was set up and backed by the 1990 Act:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Promote banking education","bold":true},{"text":" in Nigeria."}]},{"text":[{"text":"Uphold and ensure the observance of professional ethics and tradition","bold":true},{"text":" in the banking industry."}]},{"text":[{"text":"Promote the general advancement of banking practice","bold":true},{"text":" in its branches, facilitate good rapport between bankers on matters of common interest, keep abreast of the latest developments in banking, and "},{"text":"liaise with government in promoting and regulating the banking industry","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 functions under the CIBN Act, 2007 (section 3):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Determine the standards of knowledge and skill","bold":true},{"text":" to be attained by persons seeking to become members of the banking profession."}]},{"text":[{"text":"Maintain registers","bold":true},{"text":" of members and of corporate members."}]},{"text":[{"text":"Conduct professional examinations","bold":true},{"text":" and award certificates."}]},{"text":[{"text":"Promote and ensure the observance of ethical standards and professionalism","bold":true},{"text":" among banking practitioners."}]}]},{"type":"paragraph","text":[{"text":"4 features","bold":true},{"text":" through which it promotes professionalism among its members:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Professional qualifications","bold":true},{"text":" through curriculum-based, rigorous training and skills development (examinations)."}]},{"text":[{"text":"High ethical standards","bold":true},{"text":", integrity and objectivity."}]},{"text":[{"text":"Codes of conduct","bold":true},{"text":" (rules and regulations) designed to "},{"text":"enforce self-regulation and compliance","bold":true},{"text":"."}]},{"text":[{"text":"A system of recognition for merit:","bold":true},{"text":" honorary awards for distinguished service or outstanding contributions to banking knowledge."}]}]},{"type":"paragraph","text":[{"text":"What the CIBN does NOT do","bold":true},{"text":" (each belongs to another body):"}]},{"type":"table","header":[[{"text":"Activity"}],[{"text":"Who does it"}]],"rows":[[[{"text":"Granting banking licences; supervising banks"}],[{"text":"CBN (under BOFIA 2020)"}]],[[{"text":"Issuing currency; fixing the Monetary Policy Rate"}],[{"text":"CBN"}]],[[{"text":"Open market operations; dealing in treasury bills"}],[{"text":"CBN"}]],[[{"text":"Insuring bank deposits"}],[{"text":"NDIC"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"NOT a role\" questions: the odd one out is always a "},{"text":"regulatory or central-bank power","bold":true},{"text":" (licensing banks, open market operations, MPR, currency) or "},{"text":"deposit insurance","bold":true},{"text":". Liaising with government on regulation "},{"text":"is","bold":true},{"text":" an objective; actually licensing banks is "},{"text":"not","bold":true},{"text":"."}]},{"text":[{"text":"How does the CIBN mainly promote professionalism? Through "},{"text":"rigorous professional examinations and training, codes of conduct, and recognition of distinguished members","bold":true},{"text":"."}]},{"text":[{"text":"Codes of conduct do not guarantee profits, fix interest rates or replace CBN supervision; their benefit is "},{"text":"self-regulation and compliance","bold":true},{"text":"."}]},{"text":[{"text":"Example: Chiamaka, a graduate trainee in a Lagos bank, who wants professional banking examinations leading to a recognised qualification registers with the "},{"text":"CIBN","bold":true},{"text":", not the Nigerian Exchange, SEC or NDIC."}]},{"text":[{"text":"Bankers' Committee:","bold":true},{"text":" the regular meeting of the CBN with the chief executives of banks, "},{"text":"presided over (chaired) by the Governor of the CBN","bold":true},{"text":". It is the apex of the banking profession. The CIBN and the "},{"text":"Financial Institutions Training Centre (FITC)","bold":true},{"text":" are its \"twin institutions\"; the CBN contributes "},{"text":"50%","bold":true},{"text":" of their budgets. The FITC is a training centre; it does not conduct the professional examinations."}]}]}]},{"number":"15.3","title":"Governance and discipline","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Governing Council:","bold":true},{"text":" responsible for the "},{"text":"administration and general management","bold":true},{"text":" of the Institute's affairs and its policy. Chaired by the "},{"text":"President","bold":true},{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 72, $study_guide$"text":". Members include the CBN Governor or his representative, bank chief executives, elected members, past Presidents and government and education representatives; the "},{"text":"Registrar is its Secretary","bold":true},{"text":". Members serve two-year terms."}]},{"text":[{"text":"President:","bold":true},{"text":" a Fellow elected at the annual general meeting for "},{"text":"two years","bold":true},{"text":"; chairs the Council; deputised by the First Vice-President."}]},{"text":[{"text":"Registrar:","bold":true},{"text":" appointed by the Council; the "},{"text":"Chief Executive","bold":true},{"text":" of the Institute; "},{"text":"keeps the registers","bold":true},{"text":"; "},{"text":"Secretary to the Governing Council","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Disciplinary system (3 steps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investigating Panel:","bold":true},{"text":" conducts the "},{"text":"preliminary investigation","bold":true},{"text":" of an alleged breach of the code of conduct and decides whether the case should go to the Tribunal. It has 5 members."}]},{"text":[{"text":"Disciplinary Tribunal:","bold":true},{"text":" "},{"text":"hears the case","bold":true},{"text":" and decides whether the member is guilty of unprofessional conduct. Chaired by the "},{"text":"Second Vice-President","bold":true},{"text":"."}]},{"text":[{"text":"Council confirmation:","bold":true},{"text":" the Tribunal's direction takes effect only when "},{"text":"confirmed by the Council","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Order: "},{"text":"Investigating Panel -> Disciplinary Tribunal -> confirmation by the Council.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sanctions:","bold":true},{"text":" a "},{"text":"reprimand","bold":true},{"text":", or an order to the Registrar to "},{"text":"strike the member's name off the register","bold":true},{"text":". "},{"text":"Striking off is the maximum sanction.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A member may be sanctioned for unprofessional conduct, for a conviction the Tribunal finds incompatible with being a banker, or for registration obtained by fraud."}]},{"text":[{"text":"The member may appeal to the "},{"text":"Federal High Court","bold":true},{"text":" within 28 days. The court is an appeal route, not the first step."}]},{"text":[{"text":"Traps: the Tribunal cannot imprison anyone or revoke a bank's licence (licences are the CBN's). The Bankers' Committee and the CBN board play no part in CIBN discipline. The Registrar (not the President or Governor) is the Chief Executive."}]}]}]},{"number":"15.4","title":"Membership, grades and the law on practising","mustKnow":[{"type":"paragraph","text":[{"text":"2 broad categories of membership:","bold":true},{"text":" "},{"text":"corporate members","bold":true},{"text":" and "},{"text":"individual members","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate members:","bold":true},{"text":" institutions such as the "},{"text":"CBN, NDIC, banks","bold":true},{"text":" (including "},{"text":"microfinance banks","bold":true},{"text":", mortgage banks and development banks) and discount houses. Corporate members must get their staff registered."}]},{"text":[{"text":"Individual grades:","bold":true},{"text":" Ordinary, Student, Graduate, "},{"text":"Associate","bold":true},{"text":", "},{"text":"Honorary Senior Member","bold":true},{"text":", Honorary Fellow, "},{"text":"Fellow","bold":true},{"text":". There is "},{"text":"no \"Principal Member\"","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Letters"}],[{"text":"Grade"}]],"rows":[[[{"text":"ACIB"}],[{"text":"Associate"}]],[[{"text":"FCIB"}],[{"text":"Fellow"}]],[[{"text":"HCIB"}],[{"text":"Honorary Senior Member"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Chartered banker:","bold":true},{"text":" a person who has "},{"text":"passed the professional examinations and been elected an Associate or Fellow","bold":true},{"text":" of the Institute."}]},{"text":[{"text":"Technical heads:","bold":true},{"text":" nobody may be employed or appointed to "},{"text":"head a technical department of a bank","bold":true},{"text":" (e.g. Treasury) unless he is a "},{"text":"member of the CIBN with valid, current registration","bold":true},{"text":"."}]},{"text":[{"text":"Offence:","bold":true},{"text":" a non-member who "},{"text":"practises or holds himself out as a professional banker for reward commits an offence","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A microfinance bank can be a "},{"text":"corporate","bold":true},{"text":" member; a retired manager, a new cashier or a banking student would be an "},{"text":"individual","bold":true},{"text":" member, never a corporate one."}]},{"text":[{"text":"ACIB is the Associate (the professional qualification earned by examination); FCIB is the senior Fellow grade; HCIB is honorary, not a \"Holder of a Certificate in Banking\"."}]},{"text":[{"text":"Being a chartered banker depends on "},{"text":"examinations plus election","bold":true},{"text":", not on years of service, a directorship or a degree alone."}]},{"text":[{"text":"Penalties: an individual offender faces up to "},{"text":"two years' imprisonment","bold":true},{"text":", a fine of not less than "},{"text":"₦20,000","bold":true},{"text":", or both; a body corporate faces a fine of not less than "},{"text":"₦200,000","bold":true},{"text":". Making false statements to obtain registration is also an offence."}]},{"text":[{"text":"The Registrar may remove a member who has not paid subscriptions for over one year."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CIBN = professional body for bankers: standards, examinations, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 73, $study_guide$ethics. Not a regulator, insurer or bank."}]},{"text":[{"text":"History: 1963 local centre of the Institute of Bankers, London -> Nigerian Institute of Bankers (company limited by guarantee, 1976) -> chartered by Decree No. 12 of 1990 -> now the CIBN Act, 2007."}]},{"text":[{"text":"3 objectives: banking education; professional ethics and tradition; advancement of banking practice and liaison with government."}]},{"text":[{"text":"4 Act functions: standards of knowledge and skill; registers; examinations and certificates; ethics and professionalism."}]},{"text":[{"text":"Licensing banks, OMO, MPR, currency = CBN; deposit insurance = NDIC."}]},{"text":[{"text":"Governing Council manages; Registrar = Chief Executive and Council Secretary."}]},{"text":[{"text":"Discipline: Investigating Panel -> Disciplinary Tribunal -> Council confirmation; maximum sanction = striking off."}]},{"text":[{"text":"Members: corporate and individual; ACIB Associate, FCIB Fellow, HCIB Honorary Senior Member."}]},{"text":[{"text":"Technical department heads must be registered members; holding out as a banker without membership is an offence."}]},{"text":[{"text":"Bankers' Committee is chaired by the CBN Governor."}]}]}],"theory":{"itemId":"b628bd1f-2f6b-5a85-9381-1c61cfc36600","question":[{"type":"paragraph","text":[{"text":"Discuss the role of the Chartered Institute of Bankers of Nigeria in promoting professionalism in the Nigerian banking sector."}]}]},"practice":[{"topic":"The Chartered Institute of Bankers of Nigeria (CIBN)","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"dbe954f3-3729-5b02-be2c-8358c1436612","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"A bank receives a fresh cash deposit of ₦4,000,000. The cash reserve ratio is 20%. Find (a) the excess reserve of the first bank, (b) the money multiplier, (c) the total deposits the banking system can create, and (d) the total if the reserve ratio is increased by 25%."},"answer":{"kind":"model_answer","itemId":"172eacd8-50f3-5bd7-961c-df8da2dd0ff7","sourceKey":"guide-answer:1","payload":{"body":"(a) Required reserve = 0.20 × ₦4,000,000 = ₦800,000; excess reserve = ₦4,000,000 − ₦800,000 = ₦3,200,000.\n(b) k = 1 ÷ 0.20 = 5.\n(c) Total = ₦4,000,000 × 5 = ₦20,000,000 (new deposits ₦16,000,000).\n(d) New r = 20% × 1.25 = 25%; total = ₦4,000,000 ÷ 0.25 = ₦16,000,000."}}},{"kind":"theory_question","itemId":"e3c86c07-6a9b-5074-9b35-8a144da2c912","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"An economy's banks create total deposits of ₦500 million from an initial deposit of ₦50 million. (a) Find the money multiplier and the reserve ratio. (b) The reserve requirement is then raised by 100% and the initial deposit by 40%. Find the new total deposits."},"answer":{"kind":"model_answer","itemId":"eab0e214-caf7-5bbb-8aa3-70efbb6fa155","sourceKey":"guide-answer:2","payload":{"body":"• (a) k = 500 / 50 = 10. Since k = 1 / r, r = 1 / 10 = 10%.\n• (b) New r = 10% × 2 = 20%. New initial deposit = ₦50m × 1.4 = ₦70m. New k = 1 / 0.20 = 5. Total deposits = ₦70m × 5 = ₦350 million. The doubled reserve ratio outweighs the larger deposit."}}},{"kind":"theory_question","itemId":"b51b3be2-8fb2-5fba-b04b-741e9d970e39","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"In the 2004 consolidation, a bank had a capital base of ₦2 billion. (a) How much extra capital did it need, how many times did the requirement rise, and by what percentage? (b) By what percentage did the number of banks fall when 89 became 25?"},"answer":{"kind":"model_answer","itemId":"52fc979d-2b73-5a30-b041-862f78cd78b9","sourceKey":"guide-answer:3","payload":{"body":"(a) Extra capital = ₦25 billion - ₦2 billion = ₦23 billion. Times = 25 ÷ 2 = 12.5 times. Percentage rise = (23 ÷ 2) × 100 = 1,150%.\n(b) Fall = 89 - 25 = 64 banks. Percentage = (64 ÷ 89) × 100 = 71.91, so about 71.9% (rounded to one decimal place)."}}},{"kind":"theory_question","itemId":"04394be6-b73b-50c1-b2b9-761e7cb01a71","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Lekki Bank has deposit liabilities of ₦800 billion. The CRR is 45% and the liquidity ratio 30%. (a) How much must it keep with the CBN as cash reserve? (b) What minimum liquid assets must it hold? (c) If the CBN cuts the CRR to 40%, how much is released for lending?"},"answer":{"kind":"model_answer","itemId":"bd428785-2412-5646-a93c-51d9c99377ab","sourceKey":"guide-answer:4","payload":{"body":"(a) 45% × ₦800bn = ₦360bn kept with the CBN.\n(b) 30% × ₦800bn = ₦240bn in liquid assets (cash, balances with the CBN, Treasury Bills).\n(c) New CRR: 40% × ₦800bn = ₦320bn. Released = ₦360bn − ₦320bn = ₦40bn. A lower CRR is expansionary: lending capacity and money supply rise."}}},{"kind":"theory_question","itemId":"b7457b9f-2007-595e-b06a-17c072779a6e","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"A deposit money bank had total deposit liabilities of ₦48 billion. (a) What annual premium did it pay at 15/16 of 1%? (b) It later fails. A depositor holds ₦9 million. Using the ₦5 million cover, how is she paid?"},"answer":{"kind":"model_answer","itemId":"c9da02ca-99ec-5a46-b081-f79252f5f5c9","sourceKey":"guide-answer:5","payload":{"body":"(a) 48,000,000,000 × 15/16 × 1/100 = ₦450,000,000. (b) The NDIC pays the insured ₦5,000,000; the remaining 9,000,000 − 5,000,000 = ₦4,000,000 is claimed pro rata from liquidation dividends. Her claim passes to the NDIC for the ₦5m paid (subrogation)."}}},{"kind":"theory_question","itemId":"79757ac4-9d38-5934-b193-781b9f2373f8","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A ₦10,000,000 91-day Treasury bill is issued at a 10% discount rate. Find the price and the investor's simple yield (365-day year)."},"answer":{"kind":"model_answer","itemId":"de9bcb00-7957-5508-845f-e25765590d77","sourceKey":"guide-answer:6","payload":{"body":"• Discount = 10,000,000 x 0.10 x 91/365 = ₦249,315.07.\n• Price = 10,000,000 - 249,315.07 = ₦9,750,684.93.\n• Yield = 249,315.07 / $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 74, $study_guide$9,750,684.93 x 365/91 = 10.26% (2 d.p.)."}}},{"kind":"theory_question","itemId":"cf183a1a-405b-5437-b01b-151c2507c180","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Distinguish a settlement bank from a non-settlement bank under the CBN's April 2004 framework, and list the steps in clearing a cheque."},"answer":{"kind":"model_answer","itemId":"426e2daf-0657-5940-a5b0-42a445c6eb33","sourceKey":"guide-answer:7","payload":{"body":"A settlement bank clears and settles cheques on behalf of other banks, keeps a settlement account with the CBN and deposits clearing collateral directly with it. A non-settlement bank keeps only an operations account with the CBN (always in credit), and clears through an agency arrangement with a settlement bank, depositing at least ₦250 million collateral with that bank. Steps: collection, sorting (on-us or other-bank), presentation, clearing session, settlement of net positions through CBN settlement accounts, return of unpaid items with reasons, customer notification."}}},{"kind":"theory_question","itemId":"b18a4814-169e-5a94-bd65-42e2358ab6f6","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"A bill of exchange for ₦3,650,000 dated 5 May is payable 90 days after date. The holder discounts it with her bank on 28 June at 10% per annum (365-day year). Find the due date and the proceeds."},"answer":{"kind":"model_answer","itemId":"2a9a3647-98a2-583b-a89d-910a458f4f0f","sourceKey":"guide-answer:8","payload":{"body":"1. 90 days after 5 May (excluding 5 May): May 26 days, June 30 (56), July 31 (87), August 3 (90): 3 August.\n2. Add 3 days of grace: due 6 August.\n3. Days from 28 June to 6 August: 2 (June) + 31 (July) + 6 (August) = 39 days.\n4. Discount = 3,650,000 x 0.10 x 39/365 = ₦39,000.\n5. Proceeds = 3,650,000 - 39,000 = ₦3,611,000."}}},{"kind":"theory_question","itemId":"2bb50407-c66f-50dc-bf77-5c088c5cd6e4","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"Mrs Bello's account opened the month at ₦2,000 DR. She paid in a cheque of ₦9,500, issued a cheque of ₦4,800 and was charged ₦150 for a cheque book. Her standing order of ₦6,000 falls due at month end; the bank charges ½% commission and ₦50 postage, and her overdraft limit is ₦2,000. Will the bank pay?"},"answer":{"kind":"model_answer","itemId":"3dedfe38-c67d-5fb0-ad7f-f59324deb709","sourceKey":"guide-answer:9","payload":{"body":"1. Balance before the order: −₦2,000 + ₦9,500 − ₦4,800 − ₦150 = ₦2,550 CR.\n2. Commission: 0.5% × ₦6,000 = ₦30. Charges: ₦30 + ₦50 = ₦80.\n3. Total debit: ₦6,000 + ₦80 = ₦6,080.\n4. Balance after: ₦2,550 − ₦6,080 = ₦3,530 DR.\n5. ₦3,530 DR is beyond the ₦2,000 limit, so the bank will not pay and incurs no liability for not paying."}}},{"kind":"theory_question","itemId":"93b3314f-d916-555a-8263-c86999e9cc3f","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"Ngozi guaranteed Ade's overdraft and gave notice ending her guarantee when the balance was ₦950,000 Dr. The bank did not stop the account. Ade then paid in ₦400,000 and ₦250,000 and withdrew ₦600,000. Using Clayton's Rule, find (a) Ngozi's remaining liability and (b) the total overdraft."},"answer":{"kind":"model_answer","itemId":"af3b4982-d256-51f6-920c-5ec56b555c25","sourceKey":"guide-answer:10","payload":{"body":"1. Under Clayton's Rule the credits clear the oldest debit first: 950,000 − 400,000 − 250,000 = ₦300,000. This is all Ngozi still owes under her guarantee.\n2. The ₦600,000 withdrawal is new borrowing after the guarantee ended; she is not liable for it.\n3. Total overdraft = 300,000 + 600,000 = ₦900,000 Dr."}}},{"kind":"theory_question","itemId":"9437fe54-c183-5fea-93dc-a733022fb320","sourceKey":"guide-theory:11","position":11,"payload":{"prompt":"An exporter negotiates a ₦6,000,000 export bill with his bank 2 months before maturity. The bank charges interest at 15% per annum and a commission of 0.25% of face value. How much does he receive?"},"answer":{"kind":"model_answer","itemId":"51edd875-6303-593d-9fbe-a269490bee06","sourceKey":"guide-answer:11","payload":{"body":"Interest = 6,000,000 x 0.15 x 2/12 = ₦150,000. Commission = 6,000,000 x 0.0025 = ₦15,000. Amount credited = 6,000,000 - 150,000 - 15,000 = ₦5,835,000."}}},{"kind":"theory_question","itemId":"18d4be41-705b-541c-a2ea-ecd36219fe1f","sourceKey":"guide-theory:12","position":12,"payload":{"prompt":"Ada borrows ₦900,000 for 18 months at 12% per annum flat interest on the original principal, repaying principal and interest in 18 equal monthly instalments. Find the total interest and each instalment."},"answer":{"kind":"model_answer","itemId":"15f264a4-b3ce-552d-b4bd-f8e3ccc0c89b","sourceKey":"guide-answer:12","payload":{"body":"Interest = 900,000 x 0.12 x 18/12 = ₦162,000. Total repayable = 900,000 + 162,000 = ₦1,062,000. Monthly instalment = 1,062,000 / 18 = ₦59,000."}}},{"kind":"theory_question","itemId":"f637abb5-ecf7-5f70-8423-69c4aab9d5c0","sourceKey":"guide-theory:13","position":13,"payload":{"prompt":"Oshodi Ventures Ltd asks for an overdraft. Current assets ₦9,000,000 (including stock ₦4,000,000); current liabilities ₦6,000,000; long-term loan ₦5,000,000; shareholders' funds ₦15,000,000; profit before interest and tax ₦3,000,000; loan interest ₦500,000. Compute the current ratio, quick ratio, working capital, gearing and interest cover, and comment."},"answer":{"kind":"model_answer","itemId":"0b7a4630-5937-58a1-a521-4c8ff09bd0cf","sourceKey":"guide-answer:13","payload":{"body":"• Current ratio = 9,000,000 ÷ 6,000,000 = 1.5 : 1.\n• Quick ratio = (9,000,000 − 4,000,000) ÷ 6,000,000 = 5,000,000 ÷ 6,000,000 = 0.83 : 1 (2 d.p.).\n• Working capital = 9,000,000 − 6,000,000 = ₦3,000,000.\n• Gearing = 5,000,000 ÷ (5,000,000 + 15,000,000) × 100 = 25%.\n• Interest cover = 3,000,000 ÷ 500,000 = 6 times.\n• Comment: liquidity is adequate on the current ratio, but the quick ratio below 1 shows reliance on selling stock to pay short-term debts. Gearing is low and interest is well covered, so the business can ca$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin_cm209', 75, $study_guide$rry more debt; the banker should still check the cash flow forecast and value security on a break-up basis."}}},{"kind":"theory_question","itemId":"f20cc198-5ebe-5c43-b2da-99b9171910d2","sourceKey":"guide-theory:14","position":14,"payload":{"prompt":"Agege Bank has deposit liabilities of ₦300bn and qualifying liquid assets of ₦100bn. The minimum liquidity ratio is 30%. (a) What is its liquidity ratio? (b) What is the largest amount of liquid assets it can switch into loans and still comply? (c) What happens to its liquidity and profitability after the switch?"},"answer":{"kind":"model_answer","itemId":"6ca0fedd-0a34-5e75-9b72-2b55a7bdab5c","sourceKey":"guide-answer:14","payload":{"body":"• (a) 100 ÷ 300 × 100 = 33.33% (2 d.p.).\n• (b) Required = 0.30 × 300 = ₦90bn. Switchable = 100 − 90 = ₦10bn.\n• (c) Its liquidity ratio falls to exactly 30% (less liquid), but the ₦10bn now earns loan interest, so it becomes more profitable, with more credit risk."}}},{"kind":"theory_question","itemId":"b628bd1f-2f6b-5a85-9381-1c61cfc36600","sourceKey":"guide-theory:15","position":15,"payload":{"prompt":"Discuss the role of the Chartered Institute of Bankers of Nigeria in promoting professionalism in the Nigerian banking sector."},"answer":{"kind":"model_answer","itemId":"98196b70-c55a-5564-9970-fab28ff69d7f","sourceKey":"guide-answer:15","payload":{"body":"Define the CIBN as the professional body for bankers, chartered in 1990 and now governed by the CIBN Act, 2007. State its objectives: banking education, professional ethics and tradition, advancement of banking practice and liaison with government. Then explain how it promotes professionalism: (1) rigorous examinations and training leading to qualifications such as ACIB; (2) high ethical standards, integrity and objectivity; (3) codes of conduct enforcing self-regulation, backed by the Investigating Panel, Disciplinary Tribunal and striking off; (4) recognition of merit through honorary awards. Add the legal backing: heads of technical departments must be members, and non-members holding themselves out as bankers commit an offence."}}}]}$study_guide$);
